        std::size_t parseScheduleBatchesPerCpp(const EmitOptions &options)
        {
            auto it = options.attributes.find("sched_batches_per_cpp");
            if (it == options.attributes.end())
            {
                return 1;
            }
            try
            {
                return std::max<std::size_t>(1, static_cast<std::size_t>(std::stoull(it->second)));
            }
            catch (const std::exception &)
            {
                return 1;
            }
        }

        std::size_t parseEmitParallelism(const EmitOptions &options)
        {
            auto fallback = []() -> std::size_t
            {
                const unsigned value = std::thread::hardware_concurrency();
                return value == 0 ? 1u : static_cast<std::size_t>(value);
            };

            auto it = options.attributes.find("emit_parallelism");
            if (it == options.attributes.end())
            {
                return fallback();
            }
            try
            {
                const std::size_t parsed = static_cast<std::size_t>(std::stoull(it->second));
                return parsed == 0 ? fallback() : parsed;
            }
            catch (const std::exception &)
            {
                return fallback();
            }
        }

        bool parseBooleanEmitOption(const EmitOptions &options,
                                    std::string_view attributeName,
                                    const char *envName,
                                    bool defaultValue = false)
        {
            auto parse = [](std::string_view text, bool fallback) {
                if (text.empty())
                {
                    return fallback;
                }
                if (text == "0" || text == "false" || text == "False" || text == "FALSE" ||
                    text == "off" || text == "Off" || text == "OFF" ||
                    text == "no" || text == "No" || text == "NO")
                {
                    return false;
                }
                return true;
            };

            if (auto it = options.attributes.find(std::string(attributeName)); it != options.attributes.end())
            {
                return parse(it->second, defaultValue);
            }
            if (const char *env = std::getenv(envName))
            {
                return parse(env, defaultValue);
            }
            return defaultValue;
        }

        enum class PureEventWordPackPolicy
        {
            kOff,
            kProbe,
            kTargeted,
        };

        std::string_view pureEventWordPackPolicyName(PureEventWordPackPolicy policy) noexcept
        {
            switch (policy)
            {
            case PureEventWordPackPolicy::kOff:
                return "off";
            case PureEventWordPackPolicy::kProbe:
                return "probe";
            case PureEventWordPackPolicy::kTargeted:
                return "targeted";
            }
            return "off";
        }

        std::optional<PureEventWordPackPolicy> parsePureEventWordPackPolicy(
            const EmitOptions &options,
            std::string &invalidValue)
        {
            std::string value = "off";
            if (const auto it = options.attributes.find("pure_event_word_pack_policy");
                it != options.attributes.end())
            {
                value = it->second;
            }
            else if (const char *env = std::getenv("WOLVRIX_GRHSIM_PURE_EVENT_WORD_PACK_POLICY"))
            {
                value = env;
            }

            if (value.empty() || value == "off")
            {
                return PureEventWordPackPolicy::kOff;
            }
            if (value == "probe")
            {
                return PureEventWordPackPolicy::kProbe;
            }
            if (value == "targeted")
            {
                return PureEventWordPackPolicy::kTargeted;
            }
            invalidValue = std::move(value);
            return std::nullopt;
        }

        std::optional<std::size_t> parseUnsignedEmitOption(const EmitOptions &options,
                                                           std::string_view attributeName,
                                                           const char *envName,
                                                           std::size_t defaultValue,
                                                           std::string &invalidValue)
        {
            std::string value;
            if (const auto it = options.attributes.find(std::string(attributeName));
                it != options.attributes.end())
            {
                value = it->second;
            }
            else if (const char *env = std::getenv(envName))
            {
                value = env;
            }
            else
            {
                return defaultValue;
            }
            if (value.empty() ||
                !std::all_of(value.begin(),
                             value.end(),
                             [](unsigned char ch) { return std::isdigit(ch) != 0; }))
            {
                invalidValue = std::move(value);
                return std::nullopt;
            }
            try
            {
                std::size_t consumed = 0u;
                const unsigned long long parsed = std::stoull(value, &consumed);
                if (consumed != value.size() ||
                    parsed > static_cast<unsigned long long>(std::numeric_limits<std::size_t>::max()))
                {
                    invalidValue = std::move(value);
                    return std::nullopt;
                }
                return static_cast<std::size_t>(parsed);
            }
            catch (const std::exception &)
            {
                invalidValue = std::move(value);
                return std::nullopt;
            }
        }

