        ValueId canonicalMaterializedStorageValue(const EmitModel &model, ValueId value) noexcept
        {
            const auto aliasIt = model.materializedValueAliasByValue.find(value);
            return aliasIt == model.materializedValueAliasByValue.end() ? value : aliasIt->second;
        }

        const MemoryRowReaderActivationDecl *memoryRowReaderActivationForSymbol(
            const EmitModel &model,
            std::string_view symbol) noexcept
        {
            const auto indexIt = model.memoryRowReaderActivationBySymbol.find(std::string(symbol));
            if (indexIt == model.memoryRowReaderActivationBySymbol.end() ||
                indexIt->second >= model.memoryRowReaderActivations.size())
            {
                return nullptr;
            }
            return &model.memoryRowReaderActivations[indexIt->second];
        }

        void emitStateReaderActivationStatements(
            std::ostream &stream,
            const EmitModel &model,
            std::string_view symbol,
            std::string_view indent,
            const ActivationEmitContext *context = nullptr,
            std::optional<std::string_view> memoryRowExpr = std::nullopt)
        {
            if (memoryRowExpr)
            {
                if (const auto *activation = memoryRowReaderActivationForSymbol(model, symbol))
                {
                    emitActivationStatements(stream,
                                             "supernode_active_curr_",
                                             "active_count_",
                                             activation->dynamicReaderActiveIds,
                                             indent,
                                             context);

                    std::size_t localWordIndex = 0;
                    std::uint8_t localLaterMask = UINT8_C(0);
                    std::string localActiveExpr = "nullptr";
                    if (context != nullptr && !context->localActiveExpr.empty() &&
                        context->currentActiveId != kInvalidIndex)
                    {
                        localWordIndex = context->currentWordIndex;
                        const std::size_t currentBit = context->currentActiveId % kActiveFlagBitsPerWord;
                        if (currentBit + 1u < kActiveFlagBitsPerWord)
                        {
                            localLaterMask = static_cast<std::uint8_t>(
                                UINT8_C(0xff) << static_cast<unsigned>(currentBit + 1u));
                        }
                        localActiveExpr = "&" + std::string(context->localActiveExpr);
                    }
                    stream << indent << activation->methodName << "(" << *memoryRowExpr << ", "
                           << localWordIndex << "u, UINT8_C(" << static_cast<unsigned>(localLaterMask)
                           << "), " << localActiveExpr << ");\n";
                    return;
                }
            }

            const auto headIt = model.stateHeadSupernodesBySymbol.find(std::string(symbol));
            if (headIt == model.stateHeadSupernodesBySymbol.end())
            {
                return;
            }
            emitActivationStatements(stream,
                                     "supernode_active_curr_",
                                     "active_count_",
                                     headIt->second,
                                     indent,
                                     context);
        }

        bool isStoredValue(const EmitModel &model, ValueId value) noexcept
        {
            return model.inputFieldByValue.find(value) != model.inputFieldByValue.end() ||
                   model.materializedValues.find(value) != model.materializedValues.end();
        }

        bool isComputeSupernode(const EmitModel &model, uint32_t supernodeId) noexcept
        {
            return supernodeId < model.supernodeHasComputePart.size() &&
                   model.supernodeHasComputePart[supernodeId] != 0U;
        }

        bool isCommitSupernode(const EmitModel &model, uint32_t supernodeId) noexcept
        {
            return supernodeId < model.supernodeHasCommitPart.size() &&
                   model.supernodeHasCommitPart[supernodeId] != 0U;
        }

        std::vector<ActiveMaskEntry> buildComputeSupernodeActiveMaskEntries(const EmitModel &model)
        {
            std::vector<uint32_t> activeIds;
            activeIds.reserve(model.computeSupernodeIds.size());
            for (uint32_t supernodeId : model.computeSupernodeIds)
            {
                if (supernodeId >= model.activeIdBySupernode.size())
                {
                    continue;
                }
                const std::size_t activeId = model.activeIdBySupernode[supernodeId];
                if (activeId == kInvalidIndex)
                {
                    continue;
                }
                activeIds.push_back(static_cast<uint32_t>(activeId));
            }
            sortUniqueVector(activeIds);
            return buildActiveMaskEntries(activeIds);
        }

        std::uint8_t scheduleBatchWordDispatchMask(const EmitModel &model,
                                                   const ScheduleBatch::Word &word) noexcept
        {
            std::uint8_t dispatchMask = UINT8_C(0);
            for (uint32_t supernodeId : word.supernodeIds)
            {
                const std::size_t activeId =
                    supernodeId < model.activeIdBySupernode.size() ? model.activeIdBySupernode[supernodeId]
                                                                   : kInvalidIndex;
                if (activeId == kInvalidIndex)
                {
                    continue;
                }
                const std::uint8_t bit =
                    static_cast<std::uint8_t>(UINT8_C(1) << (activeId % kActiveFlagBitsPerWord));
                dispatchMask = static_cast<std::uint8_t>(dispatchMask | bit);
            }
            return dispatchMask;
        }

        std::uint8_t scheduleBatchWordClearMask(const EmitModel &model,
                                                const ScheduleBatch &batch,
                                                const ScheduleBatch::Word &word) noexcept
        {
            std::uint8_t clearMask = UINT8_C(0);
            for (uint32_t supernodeId : word.supernodeIds)
            {
                const std::size_t activeId =
                    supernodeId < model.activeIdBySupernode.size() ? model.activeIdBySupernode[supernodeId]
                                                                   : kInvalidIndex;
                if (activeId == kInvalidIndex)
                {
                    continue;
                }
                const std::uint8_t bit =
                    static_cast<std::uint8_t>(UINT8_C(1) << (activeId % kActiveFlagBitsPerWord));
                if (batch.phase == ScheduleBatch::Phase::kCommit ||
                    supernodeId >= model.supernodeHasCommitPart.size() ||
                    model.supernodeHasCommitPart[supernodeId] == 0U)
                {
                    clearMask = static_cast<std::uint8_t>(clearMask | bit);
                }
            }
            return clearMask;
        }

        void emitPerfCounterIncrement(std::ostream &stream,
                                      const EmitModel &model,
                                      std::string_view indent,
                                      std::string_view field)
        {
            if (!model.emitPerf)
            {
                return;
            }
            stream << indent << "++perf_counters_." << field << ";\n";
        }

        void emitPerfCounterReset(std::ostream &stream, const EmitModel &model, std::string_view indent)
        {
            if (!model.emitPerf)
            {
                return;
            }
            stream << indent << "perf_counters_ = PerfCounters{};\n";
        }

        enum class RuntimeProfileOpClass
        {
            Source,
            Const,
            Compute,
            Sink,
            Ignored,
        };

        RuntimeProfileOpClass classifyRuntimeProfileOp(OperationKind kind) noexcept
        {
            switch (kind)
            {
            case OperationKind::kConstant:
                return RuntimeProfileOpClass::Const;
            case OperationKind::kRegisterReadPort:
            case OperationKind::kLatchReadPort:
            case OperationKind::kMemoryReadPort:
                return RuntimeProfileOpClass::Source;
            case OperationKind::kRegisterWritePort:
            case OperationKind::kLatchWritePort:
            case OperationKind::kMemoryWritePort:
            case OperationKind::kMemoryFillPort:
                return RuntimeProfileOpClass::Sink;
            case OperationKind::kRegister:
            case OperationKind::kMemory:
            case OperationKind::kLatch:
            case OperationKind::kDpicImport:
            case OperationKind::kInstance:
            case OperationKind::kBlackbox:
            case OperationKind::kXMRRead:
            case OperationKind::kXMRWrite:
                return RuntimeProfileOpClass::Ignored;
            default:
                return RuntimeProfileOpClass::Compute;
            }
        }

        void buildRuntimeProfileWeights(const Graph &graph,
                                        const ScheduleRefs &schedule,
                                        EmitModel &model)
        {
            const std::size_t supernodeCount = schedule.supernodeToOps.size();
            model.runtimeProfileSourceOpsBySupernode.assign(supernodeCount, 0);
            model.runtimeProfileComputeOpsBySupernode.assign(supernodeCount, 0);
            model.runtimeProfileSinkOpsBySupernode.assign(supernodeCount, 0);
            model.runtimeProfileConstOpsBySupernode.assign(supernodeCount, 0);
            model.runtimeProfileASuccBySupernode.assign(supernodeCount, 0);
            for (std::size_t supernodeId = 0; supernodeId < supernodeCount; ++supernodeId)
            {
                for (OperationId opId : schedule.supernodeToOps[supernodeId])
                {
                    const Operation op = graph.getOperation(opId);
                    const OperationKind kind = op.kind();
                    const bool directStateRead =
                        kind == OperationKind::kRegisterReadPort && op.results().size() == 1 &&
                        model.directStateReadSymbolByValue.contains(op.results().front());
                    if (!directStateRead)
                    {
                        switch (classifyRuntimeProfileOp(kind))
                        {
                        case RuntimeProfileOpClass::Source:
                            ++model.runtimeProfileSourceOpsBySupernode[supernodeId];
                            break;
                        case RuntimeProfileOpClass::Const:
                            ++model.runtimeProfileConstOpsBySupernode[supernodeId];
                            break;
                        case RuntimeProfileOpClass::Compute:
                            ++model.runtimeProfileComputeOpsBySupernode[supernodeId];
                            break;
                        case RuntimeProfileOpClass::Sink:
                            ++model.runtimeProfileSinkOpsBySupernode[supernodeId];
                            break;
                        case RuntimeProfileOpClass::Ignored:
                            break;
                        }
                    }
                    if (!directStateRead)
                    {
                        for (ValueId result : op.results())
                        {
                            const auto fanoutIt = model.boundaryFanoutByValue.find(result);
                            if (fanoutIt != model.boundaryFanoutByValue.end() && !fanoutIt->second.empty())
                            {
                                ++model.runtimeProfileASuccBySupernode[supernodeId];
                            }
                        }
                    }
                    if (isWritePortKind(kind))
                    {
                        const auto writeIt = model.writeByOp.find(opId);
                        if (writeIt != model.writeByOp.end())
                        {
                            const auto headIt = model.stateHeadSupernodesBySymbol.find(writeIt->second.symbol);
                            if (headIt != model.stateHeadSupernodesBySymbol.end() && !headIt->second.empty())
                            {
                                ++model.runtimeProfileASuccBySupernode[supernodeId];
                            }
                        }
                    }
                }
            }
        }

        std::optional<std::string> staticConstStringExpr(const Graph &graph, ValueId valueId)
        {
            if (graph.valueType(valueId) != ValueType::String)
            {
                return std::nullopt;
            }
            const OperationId defOpId = graph.valueDef(valueId);
            if (!defOpId.valid())
            {
                return std::nullopt;
            }
            const Operation defOp = graph.getOperation(defOpId);
            if (defOp.kind() != OperationKind::kConstant)
            {
                return std::nullopt;
            }
            return constantExpr(graph, defOp, valueId);
        }

        bool isStaticConstStringValue(const EmitModel &model, ValueId value) noexcept
        {
            return model.staticConstStringFieldByValue.find(value) != model.staticConstStringFieldByValue.end();
        }

