        std::optional<OperationId> singleAssignWrapperConsumer(const Graph &graph, ValueId value)
        {
            std::optional<OperationId> assignOpId;
            const Value valueInfo = graph.getValue(value);
            for (const auto &user : valueInfo.users())
            {
                if (!user.operation.valid())
                {
                    return std::nullopt;
                }
                if (assignOpId && user.operation != *assignOpId)
                {
                    return std::nullopt;
                }
                assignOpId = user.operation;
            }
            if (!assignOpId)
            {
                return std::nullopt;
            }
            const Operation assignOp = graph.getOperation(*assignOpId);
            if (assignOp.kind() != OperationKind::kAssign ||
                assignOp.operands().size() != 1 ||
                assignOp.results().size() != 1 ||
                assignOp.operands().front() != value)
            {
                return std::nullopt;
            }
            return assignOpId;
        }

        std::optional<PackedArrayLaneView> buildPackedArrayLaneViewFromConcat(const Graph &graph,
                                                                              ValueId value,
                                                                              ValueId sourceValue,
                                                                              OperationId defOpId,
                                                                              OperationId concatOpId,
                                                                              const Operation &concatOp)
        {
            if (!value.valid() || !sourceValue.valid() || concatOp.kind() != OperationKind::kConcat)
            {
                return std::nullopt;
            }
            const auto version = getAttribute<int64_t>(concatOp, "svPackedArray.version").value_or(0);
            const auto elementWidth = getAttribute<int64_t>(concatOp, "svPackedArray.elementWidth");
            const auto elementCount = getAttribute<int64_t>(concatOp, "svPackedArray.elementCount");
            const auto operand0Index = getAttribute<int64_t>(concatOp, "svPackedArray.concat.operand0Index");
            const auto operandStride = getAttribute<int64_t>(concatOp, "svPackedArray.concat.operandStride");
            const auto indexLow = getAttribute<int64_t>(concatOp, "svPackedArray.indexLow");
            const auto indexHigh = getAttribute<int64_t>(concatOp, "svPackedArray.indexHigh");
            const auto laneOrder = getAttribute<std::string>(concatOp, "svPackedArray.laneOrder");
            if (version != 1 || !elementWidth || !elementCount || !operand0Index || !operandStride ||
                !indexLow || !indexHigh || !laneOrder)
            {
                return std::nullopt;
            }
            if (*elementWidth <= 0 || *elementWidth > 64 || *elementCount <= 1 ||
                (*operandStride != 1 && *operandStride != -1) ||
                *indexLow > *indexHigh || (*laneOrder != "lsb_index_low" && *laneOrder != "lsb_index_high"))
            {
                return std::nullopt;
            }
            if (static_cast<std::size_t>(*elementCount) != concatOp.operands().size())
            {
                return std::nullopt;
            }
            if ((*indexHigh - *indexLow + 1) != *elementCount)
            {
                return std::nullopt;
            }
            const int64_t expectedWidth = (*elementWidth) * (*elementCount);
            if (expectedWidth <= 0 || graph.valueWidth(sourceValue) != expectedWidth || graph.valueWidth(value) != expectedWidth)
            {
                return std::nullopt;
            }

            PackedArrayLaneView view;
            view.value = value;
            view.sourceValue = sourceValue;
            view.concatOp = concatOpId;
            view.defOp = defOpId;
            view.elementWidth = static_cast<int32_t>(*elementWidth);
            view.elementCount = static_cast<std::size_t>(*elementCount);
            view.laneByOperand.reserve(concatOp.operands().size());
            for (std::size_t operandIndex = 0; operandIndex < concatOp.operands().size(); ++operandIndex)
            {
                const ValueId operand = concatOp.operands()[operandIndex];
                if (!operand.valid() || graph.valueWidth(operand) != view.elementWidth)
                {
                    return std::nullopt;
                }
                const int64_t svIndex =
                    *operand0Index + static_cast<int64_t>(operandIndex) * (*operandStride);
                const int64_t lane = *laneOrder == "lsb_index_low"
                                         ? svIndex - *indexLow
                                         : *indexHigh - svIndex;
                if (lane < 0 || lane >= *elementCount)
                {
                    return std::nullopt;
                }
                const int64_t expectedLane = *elementCount - 1 - static_cast<int64_t>(operandIndex);
                if (lane != expectedLane)
                {
                    return std::nullopt;
                }
                view.laneByOperand.push_back(static_cast<std::size_t>(lane));
            }
            return view;
        }

        std::optional<PackedArrayLaneView> buildPackedArrayLaneViewForValue(const Graph &graph, ValueId value)
        {
            const OperationId defOpId = graph.valueDef(value);
            if (!defOpId.valid() || graph.valueType(value) != ValueType::Logic || !isWideLogicValue(graph, value))
            {
                return std::nullopt;
            }
            const Operation defOp = graph.getOperation(defOpId);
            if (defOp.kind() == OperationKind::kConcat)
            {
                return buildPackedArrayLaneViewFromConcat(graph, value, value, defOpId, defOpId, defOp);
            }
            if (defOp.kind() == OperationKind::kAssign &&
                defOp.operands().size() == 1 &&
                defOp.results().size() == 1)
            {
                const ValueId sourceValue = defOp.operands().front();
                const auto wrapperOpId = singleAssignWrapperConsumer(graph, sourceValue);
                if (!wrapperOpId || *wrapperOpId != defOpId)
                {
                    return std::nullopt;
                }
                const OperationId sourceOpId = graph.valueDef(sourceValue);
                if (!sourceOpId.valid())
                {
                    return std::nullopt;
                }
                const Operation sourceOp = graph.getOperation(sourceOpId);
                return buildPackedArrayLaneViewFromConcat(graph, value, sourceValue, defOpId, sourceOpId, sourceOp);
            }
            return std::nullopt;
        }

        bool sliceArrayUsesPackedArrayLaneView(const Graph &graph,
                                               const PackedArrayLaneView &view,
                                               const Operation &op)
        {
            if (op.kind() != OperationKind::kSliceArray || op.operands().size() != 2 || op.results().size() != 1)
            {
                return false;
            }
            if (op.operands().front() != view.value)
            {
                return false;
            }
            const ValueId indexValue = op.operands()[1];
            if (graph.valueType(indexValue) != ValueType::Logic || graph.valueWidth(indexValue) > 64)
            {
                return false;
            }
            const auto sliceWidth = getAttribute<int64_t>(op, "sliceWidth");
            return sliceWidth && *sliceWidth == view.elementWidth &&
                   graph.valueWidth(op.results().front()) == view.elementWidth;
        }

        bool packedArrayLaneViewHasOnlySupportedConsumers(const Graph &graph,
                                                          const PackedArrayLaneView &view)
        {
            const Value valueInfo = graph.getValue(view.value);
            for (const auto &user : valueInfo.users())
            {
                if (!user.operation.valid())
                {
                    return false;
                }
                const Operation userOp = graph.getOperation(user.operation);
                if (sliceArrayUsesPackedArrayLaneView(graph, view, userOp))
                {
                    continue;
                }
                return false;
            }
            return true;
        }

        std::size_t countPackedArrayLaneSliceUsers(const Graph &graph,
                                                   const PackedArrayLaneView &view)
        {
            std::size_t count = 0;
            const Value valueInfo = graph.getValue(view.value);
            for (const auto &user : valueInfo.users())
            {
                if (!user.operation.valid())
                {
                    continue;
                }
                if (sliceArrayUsesPackedArrayLaneView(graph, view, graph.getOperation(user.operation)))
                {
                    ++count;
                }
            }
            return count;
        }

        void discoverPackedArrayLaneViews(const Graph &graph,
                                          const std::unordered_set<ValueId, ValueIdHash> &waveformValueIds,
                                          EmitModel &model)
        {
            model.packedArrayLaneViewByValue.clear();
            model.packedArrayLaneTargetBySourceValue.clear();
            model.packedArrayLaneEmitStats = PackedArrayLaneEmitStats{};
            std::unordered_set<ValueId, ValueIdHash> publicReadValues;
            publicReadValues.reserve(graph.outputPorts().size() + graph.inoutPorts().size() * 2u);
            for (const auto &port : graph.outputPorts())
            {
                publicReadValues.insert(port.value);
            }
            for (const auto &port : graph.inoutPorts())
            {
                publicReadValues.insert(port.out);
                publicReadValues.insert(port.oe);
            }
            for (OperationId opId : graph.operations())
            {
                const Operation op = graph.getOperation(opId);
                const auto version = getAttribute<int64_t>(op, "svPackedArray.version").value_or(0);
                if (version != 1)
                {
                    continue;
                }
                ++model.packedArrayLaneEmitStats.svPackedArrayAttrDefops;
                if (op.kind() == OperationKind::kConcat)
                {
                    ++model.packedArrayLaneEmitStats.svPackedArrayAttrConcatDefops;
                }
            }
            for (ValueId valueId : graph.values())
            {
                if (waveformValueIds.contains(valueId) || publicReadValues.contains(valueId))
                {
                    continue;
                }
                auto view = buildPackedArrayLaneViewForValue(graph, valueId);
                if (!view)
                {
                    const OperationId defOpId = graph.valueDef(valueId);
                    if (defOpId.valid())
                    {
                        const Operation defOp = graph.getOperation(defOpId);
                        const bool hasDirectPackedArrayAttr =
                            getAttribute<int64_t>(defOp, "svPackedArray.version").value_or(0) == 1;
                        const bool hasAssignWrappedPackedArrayAttr =
                            defOp.kind() == OperationKind::kAssign && defOp.operands().size() == 1 &&
                            [&]() {
                                const OperationId sourceOpId = graph.valueDef(defOp.operands().front());
                                if (!sourceOpId.valid())
                                {
                                    return false;
                                }
                                return getAttribute<int64_t>(graph.getOperation(sourceOpId), "svPackedArray.version")
                                           .value_or(0) == 1;
                            }();
                        if (hasDirectPackedArrayAttr || hasAssignWrappedPackedArrayAttr)
                        {
                            ++model.packedArrayLaneEmitStats.packedArrayLaneEmitFallbackInvalidShape;
                        }
                    }
                    continue;
                }
                if (view->value == view->sourceValue && singleAssignWrapperConsumer(graph, valueId))
                {
                    continue;
                }
                const Value valueInfo = graph.getValue(view->value);
                for (const auto &user : valueInfo.users())
                {
                    if (!user.operation.valid())
                    {
                        continue;
                    }
                    const Operation userOp = graph.getOperation(user.operation);
                    if (userOp.kind() == OperationKind::kSliceArray)
                    {
                        ++model.packedArrayLaneEmitStats.packedArraySliceArrayUsers;
                    }
                    else if (userOp.kind() == OperationKind::kSliceDynamic)
                    {
                        ++model.packedArrayLaneEmitStats.packedArraySliceDynamicLegacyUsers;
                    }
                }
                if (!packedArrayLaneViewHasOnlySupportedConsumers(graph, *view))
                {
                    ++model.packedArrayLaneEmitStats.packedArrayLaneEmitFallbackMixedUser;
                    continue;
                }
                if (view->sourceValue != valueId && model.boundaryFanoutByValue.contains(view->sourceValue))
                {
                    ++model.packedArrayLaneEmitStats.packedArrayLaneEmitFallbackInvalidShape;
                    continue;
                }
                model.packedArrayLaneTargetBySourceValue.emplace(view->sourceValue, valueId);
                model.packedArrayLaneEmitStats.packedArrayLaneEmitSelects +=
                    countPackedArrayLaneSliceUsers(graph, *view);
                model.packedArrayLaneViewByValue.emplace(valueId, std::move(*view));
            }
            model.packedArrayLaneEmitStats.packedArrayLaneEmitValues =
                model.packedArrayLaneViewByValue.size();
        }

        bool isPackedArrayLaneValue(const EmitModel &model, ValueId value) noexcept
        {
            return model.packedArrayLaneViewByValue.find(value) != model.packedArrayLaneViewByValue.end();
        }

        const PackedArrayLaneView *packedArrayLaneViewForValue(const EmitModel &model, ValueId value) noexcept
        {
            const auto it = model.packedArrayLaneViewByValue.find(value);
            if (it == model.packedArrayLaneViewByValue.end())
            {
                return nullptr;
            }
            return &it->second;
        }

        const PackedArrayLaneView *packedArrayLaneViewForSourceValue(const EmitModel &model, ValueId sourceValue) noexcept
        {
            const auto targetIt = model.packedArrayLaneTargetBySourceValue.find(sourceValue);
            if (targetIt == model.packedArrayLaneTargetBySourceValue.end())
            {
                return nullptr;
            }
            return packedArrayLaneViewForValue(model, targetIt->second);
        }

        struct LogicStorageReadOrder
        {
            std::size_t firstBatch = kInvalidIndex;
            std::size_t firstReadSequence = kInvalidIndex;
            std::size_t totalReads = 0;
            std::size_t graphOrder = kInvalidIndex;
        };

        struct OrderedLogicStorageEntry
        {
            enum class Kind
            {
                kState,
                kValue,
            };

            Kind kind = Kind::kState;
            std::string stateSymbol;
            ValueId valueId{};
            LogicStorageReadOrder order;
        };

        std::vector<OrderedLogicStorageEntry> buildGraphOrderLogicStorageOrder(const Graph &graph,
                                                                               const EmitModel &model,
                                                                               std::span<const ValueId> orderedValues)
        {
            std::vector<OrderedLogicStorageEntry> orderedEntries;
            orderedEntries.reserve(model.stateOrder.size() + orderedValues.size());

            std::size_t graphOrder = 0;
            for (const std::string &stateSymbol : model.stateOrder)
            {
                const auto stateIt = model.stateBySymbol.find(stateSymbol);
                if (stateIt == model.stateBySymbol.end() || stateIt->second.kind == StateDecl::Kind::Memory)
                {
                    continue;
                }
                if (stateIt->second.regToMemIntentStorage)
                {
                    continue;
                }
                orderedEntries.push_back(OrderedLogicStorageEntry{
                    .kind = OrderedLogicStorageEntry::Kind::kState,
                    .stateSymbol = stateSymbol,
                    .valueId = {},
                    .order =
                        LogicStorageReadOrder{
                            .firstBatch = kInvalidIndex,
                            .firstReadSequence = kInvalidIndex,
                            .totalReads = 0,
                            .graphOrder = graphOrder++,
                        },
                });
            }
            for (ValueId valueId : orderedValues)
            {
                if (!model.materializedValues.contains(valueId) || graph.valueType(valueId) != ValueType::Logic)
                {
                    continue;
                }
                orderedEntries.push_back(OrderedLogicStorageEntry{
                    .kind = OrderedLogicStorageEntry::Kind::kValue,
                    .stateSymbol = {},
                    .valueId = valueId,
                    .order =
                        LogicStorageReadOrder{
                            .firstBatch = kInvalidIndex,
                            .firstReadSequence = kInvalidIndex,
                            .totalReads = 0,
                            .graphOrder = graphOrder++,
                        },
                });
            }
            return orderedEntries;
        }

        std::vector<OrderedLogicStorageEntry> buildBatchReadLocalityLogicStorageOrder(
            const Graph &graph,
            const EmitModel &model,
            std::span<const ScheduleBatch> scheduleBatches,
            const ActivityScheduleSupernodeToOps &supernodeToOps)
        {
            std::unordered_map<std::string, LogicStorageReadOrder> orderByState;
            std::unordered_map<ValueId, LogicStorageReadOrder, ValueIdHash> orderByValue;
            orderByState.reserve(model.stateOrder.size());
            orderByValue.reserve(model.materializedValues.size());

            std::size_t graphOrder = 0;
            for (const std::string &stateSymbol : model.stateOrder)
            {
                const auto stateIt = model.stateBySymbol.find(stateSymbol);
                if (stateIt == model.stateBySymbol.end() || stateIt->second.kind == StateDecl::Kind::Memory)
                {
                    continue;
                }
                if (stateIt->second.regToMemIntentStorage)
                {
                    continue;
                }
                orderByState.emplace(stateSymbol,
                                     LogicStorageReadOrder{
                                         .firstBatch = kInvalidIndex,
                                         .firstReadSequence = kInvalidIndex,
                                         .totalReads = 0,
                                         .graphOrder = graphOrder++,
                                     });
            }
            for (ValueId valueId : graph.values())
            {
                if (!model.materializedValues.contains(valueId) || graph.valueType(valueId) != ValueType::Logic)
                {
                    continue;
                }
                orderByValue.emplace(valueId,
                                     LogicStorageReadOrder{
                                         .firstBatch = kInvalidIndex,
                                         .firstReadSequence = kInvalidIndex,
                                         .totalReads = 0,
                                         .graphOrder = graphOrder++,
                                     });
            }

            std::size_t readSequence = 0;
            const auto noteRead = [&](LogicStorageReadOrder &order, std::size_t batchIndex) {
                if (order.firstReadSequence == kInvalidIndex)
                {
                    order.firstBatch = batchIndex;
                    order.firstReadSequence = readSequence++;
                }
                ++order.totalReads;
            };

            for (std::size_t batchIndex = 0; batchIndex < scheduleBatches.size(); ++batchIndex)
            {
                const ScheduleBatch &batch = scheduleBatches[batchIndex];
                for (uint32_t supernodeId : batch.supernodeIds)
                {
                    if (supernodeId >= supernodeToOps.size())
                    {
                        continue;
                    }
                    for (const OperationId opId : supernodeToOps[supernodeId])
                    {
                        const Operation op = graph.getOperation(opId);
                        if (op.kind() == OperationKind::kRegisterReadPort || op.kind() == OperationKind::kLatchReadPort)
                        {
                            const std::string attrName =
                                op.kind() == OperationKind::kRegisterReadPort ? "regSymbol" : "latchSymbol";
                            if (const auto symbol = getAttribute<std::string>(op, attrName))
                            {
                                if (auto stateIt = orderByState.find(*symbol); stateIt != orderByState.end())
                                {
                                    noteRead(stateIt->second, batchIndex);
                                }
                            }
                        }
                        else if (isWritePortKind(op.kind()))
                        {
                            if (const auto writeIt = model.writeByOp.find(opId); writeIt != model.writeByOp.end())
                            {
                                if (auto stateIt = orderByState.find(writeIt->second.symbol);
                                    stateIt != orderByState.end())
                                {
                                    noteRead(stateIt->second, batchIndex);
                                }
                            }
                        }
                        for (ValueId operand : op.operands())
                        {
                            if (auto valueIt = orderByValue.find(operand); valueIt != orderByValue.end())
                            {
                                noteRead(valueIt->second, batchIndex);
                            }
                        }
                    }
                }
            }

            std::vector<OrderedLogicStorageEntry> orderedEntries;
            orderedEntries.reserve(orderByState.size() + orderByValue.size());
            for (const auto &[stateSymbol, order] : orderByState)
            {
                orderedEntries.push_back(OrderedLogicStorageEntry{
                    .kind = OrderedLogicStorageEntry::Kind::kState,
                    .stateSymbol = stateSymbol,
                    .valueId = {},
                    .order = order,
                });
            }
            for (const auto &[valueId, order] : orderByValue)
            {
                orderedEntries.push_back(OrderedLogicStorageEntry{
                    .kind = OrderedLogicStorageEntry::Kind::kValue,
                    .stateSymbol = {},
                    .valueId = valueId,
                    .order = order,
                });
            }

            std::sort(orderedEntries.begin(),
                      orderedEntries.end(),
                      [](const OrderedLogicStorageEntry &lhs, const OrderedLogicStorageEntry &rhs)
                      {
                          if (lhs.order.firstBatch != rhs.order.firstBatch)
                          {
                              return lhs.order.firstBatch < rhs.order.firstBatch;
                          }
                          if (lhs.order.firstReadSequence != rhs.order.firstReadSequence)
                          {
                              return lhs.order.firstReadSequence < rhs.order.firstReadSequence;
                          }
                          if (lhs.order.totalReads != rhs.order.totalReads)
                          {
                              return lhs.order.totalReads > rhs.order.totalReads;
                          }
                          return lhs.order.graphOrder < rhs.order.graphOrder;
                      });
            return orderedEntries;
        }

        void rebuildMixedLogicStorage(const Graph &graph,
                                      std::span<const OrderedLogicStorageEntry> orderedEntries,
                                      EmitModel &model)
        {
            model.valueFieldByValue.clear();
            model.staticConstStringFieldByValue.clear();
            model.packedArrayLaneFieldByValue.clear();
            model.staticConstStringDecls.clear();
            model.staticConstStringDefs.clear();
            model.valueFieldDecls.clear();
            model.valueScalarSlotByValue.clear();
            model.valueWideSlotByValue.clear();
            model.valueRealSlotByValue.clear();
            model.valueStringSlotByValue.clear();
            model.valueScalarSlotCounts = {};
            model.valueWideSlotCountsByWords.clear();
            model.valueRealSlotCount = 0;
            model.valueStringSlotCount = 0;
            model.stateLogicScalarSlotCounts = {};
            model.stateLogicWideSlotCountsByWords.clear();

            std::size_t stateLogicStorageOffset = 0;
            for (const OrderedLogicStorageEntry &entry : orderedEntries)
            {
                if (entry.kind == OrderedLogicStorageEntry::Kind::kState)
                {
                    StateDecl &state = model.stateBySymbol.at(entry.stateSymbol);
                    if (state.kind == StateDecl::Kind::Memory)
                    {
                        continue;
                    }
                    if (state.regToMemIntentStorage)
                    {
                        state.slotIndex = kInvalidIndex;
                        continue;
                    }
                    if (isWideLogicWidth(state.width))
                    {
                        stateLogicStorageOffset = alignTo(stateLogicStorageOffset, alignof(std::uint64_t));
                        state.slotIndex = stateLogicStorageOffset;
                        model.stateLogicWideSlotCountsByWords[state.wordCount]++;
                        stateLogicStorageOffset += state.wordCount * sizeof(std::uint64_t);
                    }
                    else
                    {
                        stateLogicStorageOffset =
                            alignTo(stateLogicStorageOffset, valuePackedScalarSlotAlignment(state.scalarKind));
                        state.slotIndex = stateLogicStorageOffset;
                        model.stateLogicScalarSlotCounts[static_cast<std::size_t>(state.scalarKind)]++;
                        stateLogicStorageOffset += valuePackedScalarSlotByteSize(state.scalarKind);
                    }
                    continue;
                }

                const ValueId valueId = entry.valueId;
                if (!model.materializedValues.contains(valueId) || graph.valueType(valueId) != ValueType::Logic)
                {
                    continue;
                }
                if (const auto *view = packedArrayLaneViewForValue(model, valueId))
                {
                    const std::string fieldName = packedArrayLaneFieldName(graph, valueId);
                    model.packedArrayLaneFieldByValue.emplace(valueId, fieldName);
                    model.valueFieldDecls.push_back("    " + packedArrayLaneStorageType(*view) + " " +
                                                    fieldName + "{};");
                    continue;
                }
                if (isWideLogicValue(graph, valueId))
                {
                    const std::size_t wordCount = logicWordCount(graph.valueWidth(valueId));
                    const std::size_t slotIndex = model.valueWideSlotCountsByWords[wordCount]++;
                    model.valueWideSlotByValue.emplace(valueId,
                                                       ValueWideSlotRef{.wordCount = wordCount, .slotIndex = slotIndex});
                    model.valueFieldByValue.emplace(valueId,
                                                    valueWideSlotRefExpr(wordCount, std::to_string(slotIndex)));
                }
                else
                {
                    const ValueSlotScalarKind slotKind = valueScalarSlotKindForWidth(graph.valueWidth(valueId));
                    const std::size_t kindIndex = static_cast<std::size_t>(slotKind);
                    const std::size_t slotIndex = model.valueScalarSlotCounts[kindIndex]++;
                    model.valueScalarSlotByValue.emplace(valueId,
                                                         ValueScalarSlotRef{.kind = slotKind, .slotIndex = slotIndex});
                    model.valueFieldByValue.emplace(valueId,
                                                    valueScalarSlotRefExpr(slotKind, std::to_string(slotIndex)));
                }
            }

            for (ValueId valueId : graph.values())
            {
                if (!model.materializedValues.contains(valueId) || graph.valueType(valueId) == ValueType::Logic)
                {
                    continue;
                }
                if (const auto staticExpr = staticConstStringExpr(graph, valueId))
                {
                    model.staticConstStringFieldByValue.emplace(valueId, *staticExpr);
                    continue;
                }
                switch (graph.valueType(valueId))
                {
                case ValueType::Real:
                {
                    const std::size_t slotIndex = model.valueRealSlotCount++;
                    model.valueRealSlotByValue.emplace(valueId, slotIndex);
                    model.valueFieldByValue.emplace(valueId,
                                                    "value_real_slots_[" + std::to_string(slotIndex) + "]");
                    break;
                }
                case ValueType::String:
                {
                    const std::size_t slotIndex = model.valueStringSlotCount++;
                    model.valueStringSlotByValue.emplace(valueId, slotIndex);
                    model.valueFieldByValue.emplace(valueId,
                                                    "value_string_slots_[" + std::to_string(slotIndex) + "]");
                    break;
                }
                case ValueType::Logic:
                default:
                    break;
                }
            }

            model.stateLogicStorageBytes = stateLogicStorageOffset;
            for (std::size_t kindIndex = 0; kindIndex < static_cast<std::size_t>(ValueSlotScalarKind::kCount); ++kindIndex)
            {
                const auto kind = static_cast<ValueSlotScalarKind>(kindIndex);
                const std::size_t slotCount = model.valueScalarSlotCounts[kindIndex];
                if (slotCount == 0)
                {
                    continue;
                }
                model.valueFieldDecls.push_back("    std::array<" + scalarLogicSlotCppType(kind) + ", " +
                                                std::to_string(slotCount) + "> " +
                                                scalarLogicSlotFieldName("value_", kind) + "{};");
            }
            for (const auto &[wordCount, slotCount] : model.valueWideSlotCountsByWords)
            {
                if (slotCount == 0)
                {
                    continue;
                }
                model.valueFieldDecls.push_back("    std::array<" +
                                                fixedArrayType("std::uint64_t", wordCount) + ", " +
                                                std::to_string(slotCount) + "> " +
                                                wideLogicSlotFieldName("value_", wordCount) + "{};");
            }
            if (model.valueRealSlotCount != 0)
            {
                model.valueFieldDecls.push_back("    std::array<double, " + std::to_string(model.valueRealSlotCount) +
                                                "> value_real_slots_{};");
            }
            if (model.valueStringSlotCount != 0)
            {
                model.valueFieldDecls.push_back("    std::array<std::string, " +
                                                std::to_string(model.valueStringSlotCount) +
                                                "> value_string_slots_{};");
            }
        }

        void rebuildMaterializedValueStorage(const Graph &graph,
                                             std::span<const ValueId> orderedValues,
                                             EmitModel &model)
        {
            model.valueFieldByValue.clear();
            model.staticConstStringFieldByValue.clear();
            model.packedArrayLaneFieldByValue.clear();
            model.staticConstStringDecls.clear();
            model.staticConstStringDefs.clear();
            model.valueFieldDecls.clear();
            model.valueScalarSlotByValue.clear();
            model.valueWideSlotByValue.clear();
            model.valueRealSlotByValue.clear();
            model.valueStringSlotByValue.clear();
            model.valueScalarSlotCounts = {};
            model.valueWideSlotCountsByWords.clear();
            model.valueRealSlotCount = 0;
            model.valueStringSlotCount = 0;

            for (ValueId valueId : orderedValues)
            {
                if (!model.materializedValues.contains(valueId))
                {
                    continue;
                }
                if (model.materializedValueAliasByValue.contains(valueId))
                {
                    continue;
                }
                if (const auto staticExpr = staticConstStringExpr(graph, valueId))
                {
                    model.staticConstStringFieldByValue.emplace(valueId, *staticExpr);
                    continue;
                }
                if (const auto *view = packedArrayLaneViewForValue(model, valueId))
                {
                    const std::string fieldName = packedArrayLaneFieldName(graph, valueId);
                    model.packedArrayLaneFieldByValue.emplace(valueId, fieldName);
                    model.valueFieldDecls.push_back("    " + packedArrayLaneStorageType(*view) + " " +
                                                    fieldName + "{};");
                    continue;
                }
                switch (graph.valueType(valueId))
                {
                case ValueType::Real:
                {
                    const std::size_t slotIndex = model.valueRealSlotCount++;
                    model.valueRealSlotByValue.emplace(valueId, slotIndex);
                    model.valueFieldByValue.emplace(valueId,
                                                    "value_real_slots_[" + std::to_string(slotIndex) + "]");
                    break;
                }
                case ValueType::String:
                {
                    const std::size_t slotIndex = model.valueStringSlotCount++;
                    model.valueStringSlotByValue.emplace(valueId, slotIndex);
                    model.valueFieldByValue.emplace(valueId,
                                                    "value_string_slots_[" + std::to_string(slotIndex) + "]");
                    break;
                }
                case ValueType::Logic:
                default:
                {
                    if (isWideLogicValue(graph, valueId))
                    {
                        const std::size_t wordCount = logicWordCount(graph.valueWidth(valueId));
                        const std::size_t slotIndex = model.valueWideSlotCountsByWords[wordCount]++;
                        model.valueWideSlotByValue.emplace(
                            valueId,
                            ValueWideSlotRef{.wordCount = wordCount, .slotIndex = slotIndex});
                        model.valueFieldByValue.emplace(valueId,
                                                        valueWideSlotRefExpr(wordCount, std::to_string(slotIndex)));
                    }
                    else
                    {
                        const ValueSlotScalarKind slotKind = valueScalarSlotKindForWidth(graph.valueWidth(valueId));
                        const std::size_t kindIndex = static_cast<std::size_t>(slotKind);
                        const std::size_t slotIndex = model.valueScalarSlotCounts[kindIndex]++;
                        model.valueScalarSlotByValue.emplace(
                            valueId,
                            ValueScalarSlotRef{.kind = slotKind, .slotIndex = slotIndex});
                        model.valueFieldByValue.emplace(valueId,
                                                        valueScalarSlotRefExpr(slotKind, std::to_string(slotIndex)));
                    }
                    break;
                }
                }
            }

            std::vector<ValueId> unresolvedAliases;
            for (const auto &[aliasValue, canonicalValue] : model.materializedValueAliasByValue)
            {
                const auto scalarIt = model.valueScalarSlotByValue.find(canonicalValue);
                const auto fieldIt = model.valueFieldByValue.find(canonicalValue);
                if (scalarIt == model.valueScalarSlotByValue.end() || fieldIt == model.valueFieldByValue.end())
                {
                    unresolvedAliases.push_back(aliasValue);
                    continue;
                }
                model.valueScalarSlotByValue.emplace(aliasValue, scalarIt->second);
                model.valueFieldByValue.emplace(aliasValue, fieldIt->second);
            }
            for (ValueId aliasValue : unresolvedAliases)
            {
                model.materializedValueAliasByValue.erase(aliasValue);
                const ValueSlotScalarKind slotKind = valueScalarSlotKindForWidth(graph.valueWidth(aliasValue));
                const std::size_t kindIndex = static_cast<std::size_t>(slotKind);
                const std::size_t slotIndex = model.valueScalarSlotCounts[kindIndex]++;
                model.valueScalarSlotByValue.emplace(
                    aliasValue,
                    ValueScalarSlotRef{.kind = slotKind, .slotIndex = slotIndex});
                model.valueFieldByValue.emplace(aliasValue,
                                                valueScalarSlotRefExpr(slotKind, std::to_string(slotIndex)));
            }
            for (std::size_t kindIndex = 0; kindIndex < static_cast<std::size_t>(ValueSlotScalarKind::kCount); ++kindIndex)
            {
                const auto kind = static_cast<ValueSlotScalarKind>(kindIndex);
                const std::size_t slotCount = model.valueScalarSlotCounts[kindIndex];
                if (slotCount == 0)
                {
                    continue;
                }
                model.valueFieldDecls.push_back("    std::array<" + scalarLogicSlotCppType(kind) + ", " +
                                                std::to_string(slotCount) + "> " +
                                                scalarLogicSlotFieldName("value_", kind) + "{};");
            }
            for (const auto &[wordCount, slotCount] : model.valueWideSlotCountsByWords)
            {
                if (slotCount == 0)
                {
                    continue;
                }
                model.valueFieldDecls.push_back("    std::array<" +
                                                fixedArrayType("std::uint64_t", wordCount) + ", " +
                                                std::to_string(slotCount) + "> " +
                                                wideLogicSlotFieldName("value_", wordCount) + "{};");
            }
            if (model.valueRealSlotCount != 0)
            {
                model.valueFieldDecls.push_back("    std::array<double, " + std::to_string(model.valueRealSlotCount) +
                                                "> value_real_slots_{};");
            }
            if (model.valueStringSlotCount != 0)
            {
                model.valueFieldDecls.push_back("    std::array<std::string, " +
                                                std::to_string(model.valueStringSlotCount) +
                                                "> value_string_slots_{};");
            }
        }

        std::vector<ValueId> buildStateAnchoredValueOrder(const Graph &graph,
                                                          const EmitModel &model,
                                                          std::span<const ScheduleBatch> scheduleBatches,
                                                          const ActivityScheduleSupernodeToOps &supernodeToOps,
                                                          const ActivityScheduleCommitLocalityGroupByOp *
                                                              commitLocalityGroupByOp,
                                                          const ActivityScheduleCommitLocalityGroupOrder *
                                                              commitLocalityGroupOrder)
        {
            struct ValueReadOrder
            {
                std::size_t stateAnchor = kInvalidIndex;
                std::size_t firstReadSequence = kInvalidIndex;
                std::size_t totalReads = 0;
                std::size_t graphOrder = kInvalidIndex;
            };

            std::unordered_map<ValueId, ValueReadOrder, ValueIdHash> orderByValue;
            orderByValue.reserve(model.materializedValues.size());
            std::vector<std::size_t> stateAnchorBySupernode(supernodeToOps.size(), kInvalidIndex);

            std::size_t graphOrder = 0;
            for (ValueId valueId : graph.values())
            {
                if (!model.materializedValues.contains(valueId))
                {
                    ++graphOrder;
                    continue;
                }
                orderByValue.emplace(valueId,
                                     ValueReadOrder{
                                         .stateAnchor = kInvalidIndex,
                                         .firstReadSequence = kInvalidIndex,
                                         .totalReads = 0,
                                         .graphOrder = graphOrder,
                                     });
                ++graphOrder;
            }

            const auto noteStateAnchor = [&](std::size_t &anchor, const StateDecl &state) {
                if (state.kind == StateDecl::Kind::Memory || state.regToMemIntentStorage)
                {
                    return;
                }
                anchor = anchor == kInvalidIndex ? state.slotIndex : std::max(anchor, state.slotIndex);
            };
            for (std::size_t supernodeId = 0; supernodeId < supernodeToOps.size(); ++supernodeId)
            {
                std::size_t stateAnchor = kInvalidIndex;
                for (const OperationId opId : supernodeToOps[supernodeId])
                {
                    const Operation op = graph.getOperation(opId);
                    if (op.kind() == OperationKind::kRegisterReadPort || op.kind() == OperationKind::kLatchReadPort)
                    {
                        const std::string attrName =
                            op.kind() == OperationKind::kRegisterReadPort ? "regSymbol" : "latchSymbol";
                        if (const auto symbol = getAttribute<std::string>(op, attrName))
                        {
                            if (const auto stateIt = model.stateBySymbol.find(*symbol);
                                stateIt != model.stateBySymbol.end())
                            {
                                noteStateAnchor(stateAnchor, stateIt->second);
                            }
                        }
                        continue;
                    }
                    if (!isWritePortKind(op.kind()))
                    {
                        continue;
                    }
                    if (const auto writeIt = model.writeByOp.find(opId); writeIt != model.writeByOp.end())
                    {
                        if (const auto stateIt = model.stateBySymbol.find(writeIt->second.symbol);
                            stateIt != model.stateBySymbol.end())
                        {
                            noteStateAnchor(stateAnchor, stateIt->second);
                        }
                    }
                }
                stateAnchorBySupernode[supernodeId] = stateAnchor;
            }

            bool useCommitLocalityGroups =
                commitLocalityGroupByOp != nullptr && commitLocalityGroupOrder != nullptr;
            std::size_t commitOpCount = 0;
            uint32_t maxCommitLocalityGroup = 0;
            bool haveCommitLocalityGroup = false;
            if (useCommitLocalityGroups)
            {
                for (const OperationId opId : graph.operations())
                {
                    if (opId.index == 0 || opId.index > commitLocalityGroupByOp->size())
                    {
                        useCommitLocalityGroups = false;
                        break;
                    }
                    const uint32_t group = (*commitLocalityGroupByOp)[opId.index - 1];
                    if (!isCommitPhaseOp(graph.getOperation(opId)))
                    {
                        if (group != wolvrix::lib::transform::kInvalidActivitySupernodeId)
                        {
                            useCommitLocalityGroups = false;
                            break;
                        }
                        continue;
                    }
                    if (group == wolvrix::lib::transform::kInvalidActivitySupernodeId)
                    {
                        useCommitLocalityGroups = false;
                        break;
                    }
                    ++commitOpCount;
                    maxCommitLocalityGroup = haveCommitLocalityGroup
                                                 ? std::max(maxCommitLocalityGroup, group)
                                                 : group;
                    haveCommitLocalityGroup = true;
                }
            }

            std::size_t commitLocalityGroupCount = 0;
            if (useCommitLocalityGroups && haveCommitLocalityGroup)
            {
                const uint64_t candidateGroupCount =
                    static_cast<uint64_t>(maxCommitLocalityGroup) + UINT64_C(1);
                if (candidateGroupCount > static_cast<uint64_t>(commitOpCount) ||
                    candidateGroupCount >
                        static_cast<uint64_t>(std::numeric_limits<std::size_t>::max()))
                {
                    useCommitLocalityGroups = false;
                }
                else
                {
                    commitLocalityGroupCount =
                        static_cast<std::size_t>(candidateGroupCount);
                }
            }
            std::vector<uint8_t> seenCommitLocalityGroups(commitLocalityGroupCount, 0U);
            if (useCommitLocalityGroups)
            {
                if (commitLocalityGroupOrder->size() != commitLocalityGroupCount)
                {
                    useCommitLocalityGroups = false;
                }
                for (const OperationId opId : graph.operations())
                {
                    if (!useCommitLocalityGroups ||
                        !isCommitPhaseOp(graph.getOperation(opId)))
                    {
                        continue;
                    }
                    const uint32_t group = (*commitLocalityGroupByOp)[opId.index - 1];
                    if (group >= seenCommitLocalityGroups.size())
                    {
                        useCommitLocalityGroups = false;
                        break;
                    }
                    seenCommitLocalityGroups[group] = 1U;
                }
                if (useCommitLocalityGroups &&
                    std::find(seenCommitLocalityGroups.begin(),
                              seenCommitLocalityGroups.end(),
                              uint8_t{0}) != seenCommitLocalityGroups.end())
                {
                    useCommitLocalityGroups = false;
                }
                std::fill(seenCommitLocalityGroups.begin(),
                          seenCommitLocalityGroups.end(),
                          uint8_t{0});
                for (const uint32_t group : *commitLocalityGroupOrder)
                {
                    if (!useCommitLocalityGroups ||
                        group >= seenCommitLocalityGroups.size() ||
                        seenCommitLocalityGroups[group] != 0U)
                    {
                        useCommitLocalityGroups = false;
                        break;
                    }
                    seenCommitLocalityGroups[group] = 1U;
                }
            }

            std::vector<std::size_t> stateAnchorByCommitLocalityGroup(
                commitLocalityGroupCount,
                kInvalidIndex);
            std::vector<std::vector<OperationId>> commitOpsByLocalityGroup(
                commitLocalityGroupCount);
            std::unordered_set<OperationId, OperationIdHash> seenCommitOps;
            if (useCommitLocalityGroups)
            {
                seenCommitOps.reserve(commitOpCount);
                for (const ScheduleBatch &batch : scheduleBatches)
                {
                    for (const uint32_t supernodeId : batch.supernodeIds)
                    {
                        if (supernodeId >= supernodeToOps.size() ||
                            !isCommitSupernode(model, supernodeId))
                        {
                            continue;
                        }
                        for (const OperationId opId : supernodeToOps[supernodeId])
                        {
                            if (!isCommitPhaseOp(graph.getOperation(opId)) ||
                                !seenCommitOps.insert(opId).second)
                            {
                                useCommitLocalityGroups = false;
                                break;
                            }
                            const uint32_t group = (*commitLocalityGroupByOp)[opId.index - 1];
                            if (group >= commitOpsByLocalityGroup.size())
                            {
                                useCommitLocalityGroups = false;
                                break;
                            }
                            commitOpsByLocalityGroup[group].push_back(opId);
                            const auto writeIt = model.writeByOp.find(opId);
                            if (writeIt != model.writeByOp.end())
                            {
                                const auto stateIt = model.stateBySymbol.find(writeIt->second.symbol);
                                if (stateIt != model.stateBySymbol.end())
                                {
                                    noteStateAnchor(stateAnchorByCommitLocalityGroup[group],
                                                    stateIt->second);
                                }
                            }
                        }
                        if (!useCommitLocalityGroups)
                        {
                            break;
                        }
                    }
                    if (!useCommitLocalityGroups)
                    {
                        break;
                    }
                }
                if (seenCommitOps.size() != commitOpCount)
                {
                    useCommitLocalityGroups = false;
                }
            }

            std::size_t readSequence = 0;
            const auto noteOperationReads = [&](OperationId opId, std::size_t stateAnchor)
            {
                const Operation op = graph.getOperation(opId);
                for (ValueId operand : op.operands())
                {
                    auto it = orderByValue.find(operand);
                    if (it == orderByValue.end())
                    {
                        continue;
                    }
                    if (it->second.firstReadSequence == kInvalidIndex)
                    {
                        it->second.firstReadSequence = readSequence++;
                    }
                    if (stateAnchor != kInvalidIndex)
                    {
                        it->second.stateAnchor = it->second.stateAnchor == kInvalidIndex
                                                    ? stateAnchor
                                                    : std::max(it->second.stateAnchor, stateAnchor);
                    }
                    ++it->second.totalReads;
                }
            };
            if (useCommitLocalityGroups)
            {
                for (const ScheduleBatch &batch : scheduleBatches)
                {
                    for (const uint32_t supernodeId : batch.supernodeIds)
                    {
                        if (supernodeId >= supernodeToOps.size() ||
                            isCommitSupernode(model, supernodeId))
                        {
                            continue;
                        }
                        for (const OperationId opId : supernodeToOps[supernodeId])
                        {
                            noteOperationReads(opId, stateAnchorBySupernode[supernodeId]);
                        }
                    }
                }
                for (const uint32_t group : *commitLocalityGroupOrder)
                {
                    for (const OperationId opId : commitOpsByLocalityGroup[group])
                    {
                        noteOperationReads(opId,
                                           stateAnchorByCommitLocalityGroup[group]);
                    }
                }
            }
            else
            {
                for (const ScheduleBatch &batch : scheduleBatches)
                {
                    for (const uint32_t supernodeId : batch.supernodeIds)
                    {
                        if (supernodeId >= supernodeToOps.size())
                        {
                            continue;
                        }
                        for (const OperationId opId : supernodeToOps[supernodeId])
                        {
                            noteOperationReads(opId, stateAnchorBySupernode[supernodeId]);
                        }
                    }
                }
            }

            std::vector<ValueId> orderedValues;
            orderedValues.reserve(model.materializedValues.size());
            for (const auto &[valueId, _] : orderByValue)
            {
                (void)_;
                orderedValues.push_back(valueId);
            }

            std::sort(orderedValues.begin(),
                      orderedValues.end(),
                      [&](ValueId lhs, ValueId rhs)
                      {
                          const ValueReadOrder &lhsInfo = orderByValue.at(lhs);
                          const ValueReadOrder &rhsInfo = orderByValue.at(rhs);
                          if (lhsInfo.stateAnchor != rhsInfo.stateAnchor)
                          {
                              if (lhsInfo.stateAnchor == kInvalidIndex)
                              {
                                  return false;
                              }
                              if (rhsInfo.stateAnchor == kInvalidIndex)
                              {
                                  return true;
                              }
                              return lhsInfo.stateAnchor > rhsInfo.stateAnchor;
                          }
                          if (lhsInfo.firstReadSequence != rhsInfo.firstReadSequence)
                          {
                              return lhsInfo.firstReadSequence < rhsInfo.firstReadSequence;
                          }
                          if (lhsInfo.totalReads != rhsInfo.totalReads)
                          {
                              return lhsInfo.totalReads > rhsInfo.totalReads;
                          }
                          return lhsInfo.graphOrder < rhsInfo.graphOrder;
                      });
            return orderedValues;
        }

        bool emitMaterializedConstantInit(std::ostream &stream,
                                          const Graph &graph,
                                          const EmitModel &model,
                                          ValueId valueId,
                                          std::string_view indent,
                                          std::string &error)
        {
            if (!model.materializedValues.contains(valueId))
            {
                return true;
            }
            const OperationId defOpId = graph.valueDef(valueId);
            if (!defOpId.valid())
            {
                return true;
            }
            const Operation defOp = graph.getOperation(defOpId);
            if (defOp.kind() != OperationKind::kConstant)
            {
                return true;
            }

            const auto expr = constantExpr(graph, defOp, valueId);
            if (!expr)
            {
                error = "unsupported constant emit";
                return false;
            }

            const auto valueFieldIt = model.valueFieldByValue.find(valueId);
            if (valueFieldIt == model.valueFieldByValue.end())
            {
                error = "materialized constant missing storage slot";
                return false;
            }
            const std::string &lhs = valueFieldIt->second;
            switch (graph.valueType(valueId))
            {
            case ValueType::Logic:
                if (isWideLogicValue(graph, valueId))
                {
                    stream << indent << lhs << " = " << *expr << ";\n";
                }
                else
                {
                    stream << indent << lhs << " = static_cast<" << cppTypeForValue(graph, valueId)
                           << ">(grhsim_trunc_u64(static_cast<std::uint64_t>(" << *expr << "), "
                           << graph.valueWidth(valueId) << "));\n";
                }
                break;
            case ValueType::Real:
            case ValueType::String:
                stream << indent << lhs << " = " << *expr << ";\n";
                break;
            }
            return true;
        }

        ValueSlotScalarKind valueScalarSlotKindForWidth(int32_t width)
        {
            if (width <= 1)
            {
                return ValueSlotScalarKind::kBool;
            }
            if (width <= 8)
            {
                return ValueSlotScalarKind::kU8;
            }
            if (width <= 16)
            {
                return ValueSlotScalarKind::kU16;
            }
            if (width <= 32)
            {
                return ValueSlotScalarKind::kU32;
            }
            return ValueSlotScalarKind::kU64;
        }

        std::size_t valueScalarSlotByteSize(ValueSlotScalarKind kind)
        {
            switch (kind)
            {
            case ValueSlotScalarKind::kBool:
            case ValueSlotScalarKind::kU8:
                return sizeof(std::uint8_t);
            case ValueSlotScalarKind::kU16:
                return sizeof(std::uint16_t);
            case ValueSlotScalarKind::kU32:
                return sizeof(std::uint32_t);
            case ValueSlotScalarKind::kU64:
                return sizeof(std::uint64_t);
            case ValueSlotScalarKind::kCount:
                break;
            }
            return sizeof(std::uint64_t);
        }

        std::size_t valuePackedScalarSlotByteSize(ValueSlotScalarKind kind)
        {
            switch (kind)
            {
            case ValueSlotScalarKind::kBool:
            case ValueSlotScalarKind::kU8:
            case ValueSlotScalarKind::kU16:
            case ValueSlotScalarKind::kU32:
                return sizeof(std::uint32_t);
            case ValueSlotScalarKind::kU64:
                return sizeof(std::uint64_t);
            case ValueSlotScalarKind::kCount:
                break;
            }
            return sizeof(std::uint64_t);
        }

        std::size_t valuePackedScalarSlotAlignment(ValueSlotScalarKind kind)
        {
            switch (kind)
            {
            case ValueSlotScalarKind::kBool:
            case ValueSlotScalarKind::kU8:
            case ValueSlotScalarKind::kU16:
            case ValueSlotScalarKind::kU32:
                return alignof(std::uint32_t);
            case ValueSlotScalarKind::kU64:
                return alignof(std::uint64_t);
            case ValueSlotScalarKind::kCount:
                break;
            }
            return alignof(std::uint64_t);
        }

        std::size_t alignTo(std::size_t offset, std::size_t alignment)
        {
            if (alignment <= 1)
            {
                return offset;
            }
            const std::size_t mask = alignment - 1;
            return (offset + mask) & ~mask;
        }

