        std::string stateRef(const StateDecl &state)
        {
            if (state.regToMemIntentStorage)
            {
                return state.regToMemIntentFieldName + "[" + std::to_string(state.regToMemIntentRow) + "]";
            }
            if (state.kind == StateDecl::Kind::Memory)
            {
                return state.fieldName;
            }
            if (isWideLogicWidth(state.width))
            {
                return stateWideStorageRefExpr(state.wordCount, std::to_string(state.slotIndex));
            }
            return stateScalarStorageRefExpr(state.scalarKind, std::to_string(state.slotIndex));
        }

        std::string resolvedStateRefExpr(const StateDecl &state,
                                         const SupernodeLocalExprContext *context = nullptr)
        {
            if (context != nullptr)
            {
                const auto it = context->stateRefBySymbol.find(state.symbol);
                if (it != context->stateRefBySymbol.end())
                {
                    return it->second;
                }
            }
            return stateRef(state);
        }

        struct SupernodeStorageRefAliasDecl
        {
            std::string aliasName;
            std::string initExpr;
            std::optional<ValueId> value;
            std::string stateSymbol;
            std::size_t firstTouchOrder = kInvalidIndex;
        };

        std::vector<SupernodeStorageRefAliasDecl>
        collectSupernodeStorageRefAliases(const Graph &graph,
                                          const EmitModel &model,
                                          std::span<const OperationId> supernodeOps,
                                          ScheduleBatch::Phase phase)
        {
            struct TouchInfo
            {
                std::size_t count = 0;
                std::size_t firstTouchOrder = kInvalidIndex;
            };

            std::unordered_map<ValueId, TouchInfo, ValueIdHash> valueTouches;
            std::unordered_map<std::string, TouchInfo> stateTouches;
            std::size_t nextTouchOrder = 0;

            const auto noteValue = [&](ValueId value, std::size_t weight = 1) {
                if (model.directStateReadSymbolByValue.contains(value))
                {
                    return;
                }
                value = canonicalMaterializedStorageValue(model, value);
                if (!model.valueScalarSlotByValue.contains(value) && !model.valueWideSlotByValue.contains(value))
                {
                    return;
                }
                TouchInfo &touch = valueTouches[value];
                if (touch.firstTouchOrder == kInvalidIndex)
                {
                    touch.firstTouchOrder = nextTouchOrder++;
                }
                touch.count += weight;
            };
            const auto noteState = [&](const StateDecl &state, std::size_t weight = 1) {
                if (state.kind == StateDecl::Kind::Memory)
                {
                    return;
                }
                TouchInfo &touch = stateTouches[state.symbol];
                if (touch.firstTouchOrder == kInvalidIndex)
                {
                    touch.firstTouchOrder = nextTouchOrder++;
                }
                touch.count += weight;
            };

            for (const OperationId opId : supernodeOps)
            {
                const Operation op = graph.getOperation(opId);
                const bool commitPhaseOp = isCommitPhaseOp(op);
                if ((phase == ScheduleBatch::Phase::kCompute && commitPhaseOp) ||
                    (phase == ScheduleBatch::Phase::kCommit && !commitPhaseOp))
                {
                    continue;
                }
                if (isRegToMemIntentBypassOp(model, opId))
                {
                    continue;
                }
                if (op.kind() == OperationKind::kRegisterReadPort && op.results().size() == 1 &&
                    model.directStateReadSymbolByValue.contains(op.results().front()))
                {
                    continue;
                }

                for (ValueId operand : op.operands())
                {
                    noteValue(operand);
                }
                for (ValueId result : op.results())
                {
                    noteValue(result, valueNeedsTrackedChange(model, result) ? 3u : 1u);
                }

                if (op.kind() == OperationKind::kRegisterReadPort || op.kind() == OperationKind::kLatchReadPort)
                {
                    const std::string attrName =
                        op.kind() == OperationKind::kRegisterReadPort ? "regSymbol" : "latchSymbol";
                    if (const auto symbol = getAttribute<std::string>(op, attrName))
                    {
                        const auto stateIt = model.stateBySymbol.find(*symbol);
                        if (stateIt != model.stateBySymbol.end())
                        {
                            noteState(stateIt->second, 2u);
                        }
                    }
                    continue;
                }

                if (!isWritePortKind(op.kind()))
                {
                    continue;
                }
                const auto writeIt = model.writeByOp.find(opId);
                if (writeIt == model.writeByOp.end())
                {
                    continue;
                }
                const auto stateIt = model.stateBySymbol.find(writeIt->second.symbol);
                if (stateIt != model.stateBySymbol.end())
                {
                    noteState(stateIt->second, 3u);
                }
            }

            std::vector<SupernodeStorageRefAliasDecl> aliases;
            aliases.reserve(valueTouches.size() + stateTouches.size());
            for (const auto &[value, touch] : valueTouches)
            {
                if (touch.count < 2)
                {
                    continue;
                }
                if (const auto scalarIt = model.valueScalarSlotByValue.find(value);
                    scalarIt != model.valueScalarSlotByValue.end())
                {
                    aliases.push_back(SupernodeStorageRefAliasDecl{
                        .aliasName = "grhsim_value_" + std::to_string(value.index) + "_" +
                                     std::to_string(value.generation) + "_slot",
                        .initExpr = valueScalarSlotRefExpr(scalarIt->second.kind,
                                                           std::to_string(scalarIt->second.slotIndex)),
                        .value = value,
                        .stateSymbol = {},
                        .firstTouchOrder = touch.firstTouchOrder,
                    });
                    continue;
                }
                if (const auto wideIt = model.valueWideSlotByValue.find(value);
                    wideIt != model.valueWideSlotByValue.end())
                {
                    aliases.push_back(SupernodeStorageRefAliasDecl{
                        .aliasName = "grhsim_value_" + std::to_string(value.index) + "_" +
                                     std::to_string(value.generation) + "_slot",
                        .initExpr = valueWideSlotRefExpr(wideIt->second.wordCount,
                                                         std::to_string(wideIt->second.slotIndex)),
                        .value = value,
                        .stateSymbol = {},
                        .firstTouchOrder = touch.firstTouchOrder,
                    });
                }
            }
            for (const auto &[symbol, touch] : stateTouches)
            {
                if (touch.count < 2)
                {
                    continue;
                }
                const auto stateIt = model.stateBySymbol.find(symbol);
                if (stateIt == model.stateBySymbol.end() || stateIt->second.kind == StateDecl::Kind::Memory)
                {
                    continue;
                }
                const std::string aliasName =
                    stateIt->second.regToMemIntentStorage
                        ? ("grhsim_state_reg_to_mem_" + sanitizeIdentifier(stateIt->second.regToMemIntentGroup) +
                           "_row_" + std::to_string(stateIt->second.regToMemIntentRow))
                        : (isWideLogicWidth(stateIt->second.width)
                               ? ("grhsim_state_words_" + std::to_string(stateIt->second.wordCount) + "_slot_" +
                                  std::to_string(stateIt->second.slotIndex))
                               : ("grhsim_state_scalar_" +
                                  std::to_string(static_cast<std::size_t>(stateIt->second.scalarKind)) + "_slot_" +
                                  std::to_string(stateIt->second.slotIndex)));
                aliases.push_back(SupernodeStorageRefAliasDecl{
                    .aliasName = aliasName,
                    .initExpr = stateRef(stateIt->second),
                    .value = std::nullopt,
                    .stateSymbol = symbol,
                    .firstTouchOrder = touch.firstTouchOrder,
                });
            }

            std::sort(aliases.begin(),
                      aliases.end(),
                      [](const SupernodeStorageRefAliasDecl &lhs, const SupernodeStorageRefAliasDecl &rhs) {
                          if (lhs.firstTouchOrder != rhs.firstTouchOrder)
                          {
                              return lhs.firstTouchOrder < rhs.firstTouchOrder;
                          }
                          return lhs.aliasName < rhs.aliasName;
                      });
            return aliases;
        }

        void emitSupernodeStorageRefAliases(std::ostream &stream,
                                            const std::vector<SupernodeStorageRefAliasDecl> &aliases,
                                            std::string_view indent,
                                            SupernodeLocalExprContext &context)
        {
            if (!emitStorageRefAliasesEnabled())
            {
                return;
            }
            for (const auto &alias : aliases)
            {
                stream << indent << "auto &" << alias.aliasName << " = " << alias.initExpr << ";\n";
                if (alias.value.has_value())
                {
                    context.storedValueRefByValue.emplace(*alias.value, alias.aliasName);
                }
                if (!alias.stateSymbol.empty())
                {
                    context.stateRefBySymbol.emplace(alias.stateSymbol, alias.aliasName);
                }
            }
        }

        void emitChangedValuePropagation(std::ostream &stream,
                                         const EmitModel &model,
                                         ValueId resultValue,
                                         std::string_view indent,
                                         const ActivationEmitContext *context)
        {
            const auto it = model.boundaryFanoutByValue.find(resultValue);
            if (it == model.boundaryFanoutByValue.end())
            {
                return;
            }
            emitActivationStatements(
                stream,
                "supernode_active_curr_",
                "active_count_",
                it->second,
                indent,
                context);
        }

        void emitOpComment(std::ostream &stream,
                           const Operation &op,
                           std::string_view indent)
        {
            stream << indent << "// op " << op.symbolText() << " [" << toString(op.kind()) << "]";
            auto emitTargetAttr = [&](std::string_view label, std::string_view attrName)
            {
                if (const auto target = getAttribute<std::string>(op, attrName))
                {
                    stream << " " << label << "=" << *target;
                }
            };
            switch (op.kind())
            {
            case OperationKind::kRegisterReadPort:
            case OperationKind::kRegisterWritePort:
                emitTargetAttr("reg", "regSymbol");
                break;
            case OperationKind::kLatchReadPort:
            case OperationKind::kLatchWritePort:
                emitTargetAttr("latch", "latchSymbol");
                break;
            case OperationKind::kMemoryReadPort:
            case OperationKind::kMemoryWritePort:
            case OperationKind::kMemoryFillPort:
                emitTargetAttr("mem", "memSymbol");
                break;
            default:
                break;
            }
            stream << "\n";
        }

        bool shouldEmitScheduleOpComment(const Graph &graph, const EmitModel &model, const Operation &op)
        {
            switch (op.kind())
            {
            case OperationKind::kRegisterReadPort:
            case OperationKind::kLatchReadPort:
            case OperationKind::kMemoryReadPort:
            case OperationKind::kRegisterWritePort:
            case OperationKind::kLatchWritePort:
            case OperationKind::kMemoryWritePort:
            case OperationKind::kMemoryFillPort:
            case OperationKind::kDpicCall:
            case OperationKind::kSystemTask:
                return true;
            default:
                break;
            }
            for (ValueId result : op.results())
            {
                if (isMaterializedValue(model, result) || valueNeedsTrackedChange(model, result))
                {
                    return true;
                }
            }
            (void)graph;
            return false;
        }

        std::string renderScalarLogicExpr(const Graph &graph, ValueId resultValue, const ScalarLogicExpr &rhs)
        {
            if (rhs.byteBitResult)
            {
                return "static_cast<std::uint8_t>(" + rhs.expr + ")";
            }
            const std::string cppType = cppTypeForValue(graph, resultValue);
            const std::size_t width = static_cast<std::size_t>(graph.valueWidth(resultValue));
            if (cppType == "std::uint64_t" && (rhs.alreadyBoundedToResultWidth || width >= 64u))
            {
                return "(" + rhs.expr + ")";
            }
            if (rhs.alreadyBoundedToResultWidth)
            {
                return "static_cast<" + cppType + ">(" + rhs.expr + ")";
            }
            return "static_cast<" + cppType + ">(" + scalarTruncExpr(rhs.expr, width) + ")";
        }

        std::string renderScalarAssignedExpr(const Graph &graph,
                                             ValueId resultValue,
                                             const std::string &expr,
                                             bool alreadyBoundedToResultWidth,
                                             bool byteBitResult = false)
        {
            return renderScalarLogicExpr(
                graph,
                resultValue,
                ScalarLogicExpr{
                    .expr = expr,
                    .alreadyBoundedToResultWidth = alreadyBoundedToResultWidth,
                    .byteBitResult = byteBitResult,
                });
        }

        std::string stripOuterCastToType(std::string expr, const std::string &cppType)
        {
            expr = stripRedundantOuterParens(std::move(expr));
            const std::string prefix = "static_cast<" + cppType + ">(";
            if (isWholeOuterCastToType(expr, cppType))
            {
                return expr.substr(prefix.size(), expr.size() - prefix.size() - 1u);
            }
            return expr;
        }

        bool isScalarCppType(std::string_view cppType) noexcept
        {
            return cppType == "bool" ||
                   cppType == "std::uint8_t" ||
                   cppType == "std::uint16_t" ||
                   cppType == "std::uint32_t" ||
                   cppType == "std::uint64_t";
        }

        std::string stripOuterCastToTypeIfWidthBounded(std::string expr,
                                                       const std::string &cppType,
                                                       std::size_t width)
        {
            expr = stripRedundantOuterParens(std::move(expr));
            const std::string prefix = "static_cast<" + cppType + ">(";
            if (!isWholeOuterCastToType(expr, cppType))
            {
                return expr;
            }
            std::string inner = expr.substr(prefix.size(), expr.size() - prefix.size() - 1u);
            inner = stripRedundantOuterParens(std::move(inner));
            if (isScalarZeroLiteral(inner) || scalarExprAlreadyMaskedToWidth(inner, width))
            {
                return inner;
            }
            return expr;
        }

        std::string scalarTypedInitializerExpr(const Graph &graph, ValueId resultValue, const std::string &assignedExpr)
        {
            const std::string cppType = cppTypeForValue(graph, resultValue);
            if (!isScalarCppType(cppType))
            {
                return stripOuterCastToType(assignedExpr, cppType);
            }

            std::string expr = stripOuterCastToType(assignedExpr, cppType);
            while (true)
            {
                const std::string uncast = stripRedundantUint64Cast(expr);
                if (uncast == expr)
                {
                    return expr;
                }
                expr = stripOuterCastToType(uncast, cppType);
            }
        }

        std::string scalarCastOperandExpr(const std::string &expr)
        {
            const std::string compact = stripRedundantOuterParens(expr);
            constexpr std::string_view prefix = "static_cast<std::uint64_t>(";
            if (isWholeOuterCastToType(compact, "std::uint64_t"))
            {
                return compact;
            }
            if (compact.starts_with("UINT64_C(") && compact.ends_with(")"))
            {
                return compact;
            }
            return "static_cast<std::uint64_t>(" + compact + ")";
        }

        std::string scalarValueBitsExpr(const Graph &graph, ValueId value, const std::string &expr)
        {
            const std::string cppType = cppTypeForValue(graph, value);
            if (cppType == "std::uint64_t")
            {
                return expr;
            }
            return scalarCastOperandExpr(stripOuterCastToTypeIfWidthBounded(
                expr,
                cppType,
                static_cast<std::size_t>(graph.valueWidth(value))));
        }

        std::string stripOuterScalarCastForMaskedBits(std::string expr)
        {
            while (true)
            {
                expr = stripRedundantOuterParens(std::move(expr));
                constexpr std::string_view prefix = "static_cast<";
                if (!expr.starts_with(prefix) || !expr.ends_with(")"))
                {
                    return expr;
                }
                const std::size_t closeType = expr.find(">(");
                if (closeType == std::string::npos)
                {
                    return expr;
                }
                if (!outerCallCoversWholeExpr(expr, closeType + 1u))
                {
                    return expr;
                }
                const std::string_view type(expr.data() + prefix.size(), closeType - prefix.size());
                if (type != "bool" &&
                    type != "std::uint8_t" &&
                    type != "std::uint16_t" &&
                    type != "std::uint32_t" &&
                    type != "std::uint64_t")
                {
                    return expr;
                }
                expr = expr.substr(closeType + 2u, expr.size() - closeType - 3u);
            }
        }

        std::string stripRedundantUint64Cast(std::string expr)
        {
            while (true)
            {
                expr = stripRedundantOuterParens(std::move(expr));
                constexpr std::string_view prefix = "static_cast<std::uint64_t>(";
                if (!isWholeOuterCastToType(expr, "std::uint64_t"))
                {
                    return expr;
                }
                expr = expr.substr(prefix.size(), expr.size() - prefix.size() - 1u);
            }
        }

        std::string maskedScalarBitsExpr(const std::string &expr)
        {
            return stripOuterScalarCastForMaskedBits(expr);
        }

        bool valueNeedsChangeDetect(const EmitModel &model, ValueId resultValue)
        {
            const auto it = model.boundaryFanoutByValue.find(resultValue);
            return it != model.boundaryFanoutByValue.end() && !it->second.empty();
        }

        bool isEventValue(const EmitModel &model, ValueId value)
        {
            return model.eventEdgeFieldByValue.find(value) != model.eventEdgeFieldByValue.end();
        }

        std::string eventClassifyExpr(std::string_view oldExpr, std::string_view newExpr)
        {
            return "event_baseline_initialized_ ? grhsim_classify_edge(" + std::string(oldExpr) + ", " +
                   std::string(newExpr) + ") : grhsim_event_edge_kind::none";
        }

        bool valueNeedsTrackedChange(const EmitModel &model, ValueId resultValue)
        {
            return valueNeedsChangeDetect(model, resultValue) || isEventValue(model, resultValue);
        }

        bool isMaterializedValue(const EmitModel &model, ValueId value);
        std::string valueRef(const EmitModel &model, ValueId value);
        std::string waveformWideExprForSignal(const Graph &graph,
                                              const EmitModel &model,
                                              const WaveformSignalDecl &signal);

        void emitChangedValueEffects(std::ostream &stream,
                                     const EmitModel &model,
                                     ValueId resultValue,
                                     std::string_view oldExpr,
                                     std::string_view newExpr,
                                     std::string_view indent,
                                     const ActivationEmitContext *context = nullptr)
        {
            if (const auto eventIt = model.eventEdgeFieldByValue.find(resultValue);
                eventIt != model.eventEdgeFieldByValue.end())
            {
                stream << indent << eventIt->second << " = " << eventClassifyExpr(oldExpr, newExpr) << ";\n";
            }
            emitChangedValuePropagation(stream, model, resultValue, indent, context);
        }

        void emitChangedValueEffectsForCondition(std::ostream &stream,
                                                 const EmitModel &model,
                                                 ValueId resultValue,
                                                 std::string_view oldExpr,
                                                 std::string_view newExpr,
                                                 std::string_view conditionExpr,
                                                 std::string_view indent,
                                                 const ActivationEmitContext *context = nullptr,
                                                 DeferredActivationEmitContext *deferredContext = nullptr)
        {
            if (const auto eventIt = model.eventEdgeFieldByValue.find(resultValue);
                eventIt != model.eventEdgeFieldByValue.end())
            {
                stream << indent << eventIt->second << " = " << eventClassifyExpr(oldExpr, newExpr) << ";\n";
                deferredContext = nullptr;
            }
            if (context != nullptr && context->suppressComputePropagation)
            {
                return;
            }
            const auto fanoutIt = model.boundaryFanoutByValue.find(resultValue);
            if (fanoutIt == model.boundaryFanoutByValue.end())
            {
                return;
            }
            if (deferredContext != nullptr && deferredContext->groups != nullptr)
            {
                std::vector<uint32_t> directActiveIds = fanoutIt->second;
                for (auto &group : *deferredContext->groups)
                {
                    if (!containsValueId(group.sourceValues, resultValue))
                    {
                        continue;
                    }
                    stream << indent << group.changedExpr << " = static_cast<bool>(" << group.changedExpr
                           << " | " << conditionExpr << ");\n";
                    std::vector<uint32_t> remaining;
                    remaining.reserve(directActiveIds.size());
                    std::set_difference(directActiveIds.begin(),
                                        directActiveIds.end(),
                                        group.activeIds.begin(),
                                        group.activeIds.end(),
                                        std::back_inserter(remaining));
                    directActiveIds = std::move(remaining);
                    if (directActiveIds.empty())
                    {
                        return;
                    }
                }
                if (directActiveIds.size() != fanoutIt->second.size())
                {
                    emitConditionalActivationStatements(stream,
                                                        "supernode_active_curr_",
                                                        "active_count_",
                                                        directActiveIds,
                                                        conditionExpr,
                                                        indent,
                                                        context);
                    return;
                }
            }
            emitConditionalActivationStatements(stream,
                                                "supernode_active_curr_",
                                                "active_count_",
                                                fanoutIt->second,
                                                conditionExpr,
                                                indent,
                                                context);
        }

        DeferredActivationGroups buildDeferredActivationGroups(const Graph &graph,
                                                               const EmitModel &model,
                                                               const ActivityScheduleSupernodeToOps &supernodeToOps,
                                                               uint32_t supernodeId)
        {
            constexpr std::size_t kMinDeferredGroupValues = 2;
            constexpr std::size_t kMaxDeferredGroupsPerSupernode = 16;

            DeferredActivationGroups groups;
            if (supernodeId >= supernodeToOps.size())
            {
                return groups;
            }

            struct ValueFanout
            {
                ValueId value;
                std::vector<uint32_t> activeIds;
            };

            std::vector<ValueFanout> valueFanouts;
            for (OperationId opId : supernodeToOps[supernodeId])
            {
                const Operation op = graph.getOperation(opId);
                if (op.results().empty())
                {
                    continue;
                }
                for (ValueId resultValue : op.results())
                {
                    if (isEventValue(model, resultValue) ||
                        model.directStateReadSymbolByValue.contains(resultValue))
                    {
                        continue;
                    }
                    const auto fanoutIt = model.boundaryFanoutByValue.find(resultValue);
                    if (fanoutIt == model.boundaryFanoutByValue.end() || fanoutIt->second.empty())
                    {
                        continue;
                    }
                    valueFanouts.push_back(ValueFanout{.value = resultValue, .activeIds = fanoutIt->second});
                }
            }
            if (valueFanouts.size() < kMinDeferredGroupValues)
            {
                return groups;
            }

            std::unordered_map<uint32_t, std::vector<ValueId>> sourceValuesByActiveId;
            for (const auto &fanout : valueFanouts)
            {
                for (uint32_t activeId : fanout.activeIds)
                {
                    sourceValuesByActiveId[activeId].push_back(fanout.value);
                }
            }

            struct Candidate
            {
                std::vector<uint32_t> activeIds;
                std::vector<ValueId> sourceValues;
            };

            std::unordered_map<std::string, Candidate> candidates;
            for (auto &[activeId, sourceValues] : sourceValuesByActiveId)
            {
                sortUniqueValueIds(sourceValues);
                if (sourceValues.size() < kMinDeferredGroupValues)
                {
                    continue;
                }
                const std::string key = valueIdGroupKey(sourceValues);
                auto &candidate = candidates[key];
                if (candidate.sourceValues.empty())
                {
                    candidate.sourceValues = std::move(sourceValues);
                }
                candidate.activeIds.push_back(activeId);
            }

            groups.reserve(candidates.size());
            for (auto &[_, candidate] : candidates)
            {
                sortUniqueVector(candidate.activeIds);
                if (candidate.sourceValues.size() >= kMinDeferredGroupValues)
                {
                    groups.push_back(DeferredActivationGroup{.activeIds = std::move(candidate.activeIds),
                                                             .sourceValues = std::move(candidate.sourceValues)});
                }
            }
            std::sort(groups.begin(),
                      groups.end(),
                      [](const DeferredActivationGroup &lhs, const DeferredActivationGroup &rhs)
                      {
                          if (lhs.activeIds.size() != rhs.activeIds.size())
                          {
                              return lhs.activeIds.size() > rhs.activeIds.size();
                          }
                          if (lhs.sourceValues.size() != rhs.sourceValues.size())
                          {
                              return lhs.sourceValues.size() > rhs.sourceValues.size();
                          }
                          return lhs.activeIds < rhs.activeIds;
                      });
            if (groups.size() > kMaxDeferredGroupsPerSupernode)
            {
                groups.resize(kMaxDeferredGroupsPerSupernode);
            }
            for (std::size_t i = 0; i < groups.size(); ++i)
            {
                groups[i].changedExpr = "grhsim_any_changed_" + std::to_string(supernodeId) + "_" + std::to_string(i);
            }
            return groups;
        }

        void emitScalarChangedValueAssign(std::ostream &stream,
                                          const EmitModel &model,
                                          ValueId resultValue,
                                          std::string_view lhs,
                                          std::string_view nextExpr,
                                          std::string_view indent,
                                          const ActivationEmitContext *context = nullptr,
                                          DeferredActivationEmitContext *deferredContext = nullptr)
        {
            const std::string changedName = "grhsim_changed_" + std::to_string(resultValue.index);
            stream << indent << "const bool " << changedName << " = (" << lhs << " != " << nextExpr << ");\n";
            emitChangedValueEffectsForCondition(
                stream, model, resultValue, lhs, nextExpr, changedName, indent, context, deferredContext);
            stream << indent << lhs << " = " << nextExpr << ";\n";
        }

        bool isMaterializedValue(const EmitModel &model, ValueId value)
        {
            return isStoredValue(model, value);
        }

        std::optional<std::string> regToMemIntentGroupForRole(const Operation &op, std::string_view role);
        bool hasRegToMemIntentShape(const Operation &op,
                                    std::string_view group,
                                    int64_t elementWidth,
                                    int64_t elementCount);
        std::optional<ValueId> regToMemIntentSliceIndexValue(const Graph &graph, const Operation &op);

        bool isRegToMemIntentBypassOp(const EmitModel &model, OperationId opId) noexcept
        {
            return model.regToMemIntentBypassOps.contains(opId);
        }

        struct RegToMemIntentConcatInfo
        {
            std::string group;
            std::string storageGroup;
            int64_t elementWidth = 0;
            int64_t elementCount = 0;
            int64_t storageElementCount = 0;
            int64_t storageRowOffset = 0;
        };

        std::optional<RegToMemIntentConcatInfo>
        regToMemIntentConcatInfo(const Graph &graph,
                                 const EmitModel &model,
                                 const Operation &op)
        {
            const auto group = regToMemIntentGroupForRole(op, "concat");
            const auto elementWidth = getAttribute<int64_t>(op, "regToMem.intent.elementWidth");
            const auto elementCount = getAttribute<int64_t>(op, "regToMem.intent.elementCount");
            const auto storageGroupAttr = getAttribute<std::string>(op, "regToMem.intent.storageGroup");
            const auto storageElementCountAttr = getAttribute<int64_t>(op, "regToMem.intent.storageElementCount");
            const auto storageRowOffsetAttr = getAttribute<int64_t>(op, "regToMem.intent.storageRowOffset");
            const auto regSymbols = getAttribute<std::vector<std::string>>(op, "regToMem.intent.regSymbols");
            const auto operandRows = getAttribute<std::vector<int64_t>>(op, "regToMem.intent.operandRows");
            if (op.kind() != OperationKind::kConcat || op.results().size() != 1 ||
                !group || !elementWidth || !elementCount || !regSymbols || !operandRows ||
                *elementWidth <= 0 || *elementCount <= 0 ||
                op.operands().size() != static_cast<std::size_t>(*elementCount) ||
                operandRows->size() != op.operands().size() ||
                regSymbols->size() != static_cast<std::size_t>(*elementCount))
            {
                return std::nullopt;
            }
            if (*elementCount > std::numeric_limits<int64_t>::max() / *elementWidth ||
                graph.valueWidth(op.results().front()) != (*elementWidth * *elementCount))
            {
                return std::nullopt;
            }
            const std::string storageGroup = storageGroupAttr.value_or(*group);
            const int64_t storageElementCount = storageElementCountAttr.value_or(*elementCount);
            const int64_t storageRowOffset = storageRowOffsetAttr.value_or(0);
            if (storageGroup.empty() ||
                storageElementCount < *elementCount ||
                storageRowOffset < 0 ||
                storageRowOffset > storageElementCount ||
                storageElementCount - storageRowOffset < *elementCount)
            {
                return std::nullopt;
            }
            const auto storageIt = model.regToMemIntentStorageByGroup.find(storageGroup);
            if (storageIt == model.regToMemIntentStorageByGroup.end() ||
                storageIt->second.elementWidth != *elementWidth ||
                storageIt->second.elementCount != static_cast<std::size_t>(storageElementCount))
            {
                return std::nullopt;
            }

            for (std::size_t operandIndex = 0; operandIndex < op.operands().size(); ++operandIndex)
            {
                const ValueId operand = op.operands()[operandIndex];
                const int64_t row = (*operandRows)[operandIndex];
                if (row < 0 || row >= *elementCount || graph.valueWidth(operand) != *elementWidth)
                {
                    return std::nullopt;
                }
                const OperationId readOpId = graph.valueDef(operand);
                if (!readOpId.valid())
                {
                    return std::nullopt;
                }
                const Operation readOp = graph.getOperation(readOpId);
                const auto readGroup = regToMemIntentGroupForRole(readOp, "read");
                const auto readRow = getAttribute<int64_t>(readOp, "regToMem.intent.row");
                const auto readStorageGroup = getAttribute<std::string>(readOp, "regToMem.intent.storageGroup");
                const auto readStorageRow = getAttribute<int64_t>(readOp, "regToMem.intent.storageRow");
                const bool readLocalMatch = readGroup && *readGroup == *group && readRow && *readRow == row;
                const bool readStorageMatch = readStorageGroup && *readStorageGroup == storageGroup &&
                                              readStorageRow &&
                                              *readStorageRow == row + storageRowOffset;
                const auto regSymbol = getAttribute<std::string>(readOp, "regSymbol");
                if (readOp.kind() != OperationKind::kRegisterReadPort ||
                    (!readLocalMatch && !readStorageMatch) || !regSymbol ||
                    (*regSymbols)[static_cast<std::size_t>(row)] != *regSymbol)
                {
                    return std::nullopt;
                }
                const auto stateIt = model.stateBySymbol.find(*regSymbol);
                if (stateIt == model.stateBySymbol.end() ||
                    !stateIt->second.regToMemIntentStorage ||
                    stateIt->second.regToMemIntentGroup != storageGroup ||
                    stateIt->second.regToMemIntentRow != static_cast<std::size_t>(row + storageRowOffset) ||
                    stateIt->second.width != *elementWidth)
                {
                    return std::nullopt;
                }
            }

            return RegToMemIntentConcatInfo{
                .group = *group,
                .storageGroup = storageGroup,
                .elementWidth = *elementWidth,
                .elementCount = *elementCount,
                .storageElementCount = storageElementCount,
                .storageRowOffset = storageRowOffset,
            };
        }

        bool isRegToMemIntentSliceOfConcat(const Graph &graph,
                                           const Operation &op,
                                           ValueId concatValue,
                                           const RegToMemIntentConcatInfo &concatInfo)
        {
            if ((op.kind() != OperationKind::kSliceArray && op.kind() != OperationKind::kSliceDynamic) ||
                op.operands().size() != 2 || op.results().size() != 1 ||
                op.operands().front() != concatValue ||
                !regToMemIntentGroupForRole(op, "slice") ||
                !hasRegToMemIntentShape(op,
                                        concatInfo.group,
                                        concatInfo.elementWidth,
                                        concatInfo.elementCount) ||
                !regToMemIntentSliceIndexValue(graph, op))
            {
                return false;
            }
            const auto storageGroup = getAttribute<std::string>(op, "regToMem.intent.storageGroup");
            const auto storageElementCount = getAttribute<int64_t>(op, "regToMem.intent.storageElementCount");
            const auto storageRowOffset = getAttribute<int64_t>(op, "regToMem.intent.storageRowOffset");
            if (storageGroup.value_or(concatInfo.group) != concatInfo.storageGroup ||
                storageElementCount.value_or(concatInfo.elementCount) != concatInfo.storageElementCount ||
                storageRowOffset.value_or(0) != concatInfo.storageRowOffset)
            {
                return false;
            }
            const auto sliceWidth = getAttribute<int64_t>(op, "sliceWidth");
            return sliceWidth && *sliceWidth == concatInfo.elementWidth &&
                   graph.valueWidth(op.results().front()) == concatInfo.elementWidth;
        }

        bool regToMemIntentValueCanBypass(const EmitModel &model, ValueId value)
        {
            return value.valid() && !isMaterializedValue(model, value) && !valueNeedsTrackedChange(model, value);
        }

        void collectRegToMemIntentBypassOps(const Graph &graph, EmitModel &model)
        {
            model.regToMemIntentSliceGroupByOp.clear();
            model.regToMemIntentConcatGroupByOp.clear();
            model.regToMemIntentReadGroupByOp.clear();
            model.regToMemIntentBypassOps.clear();

            std::unordered_map<OperationId, RegToMemIntentConcatInfo, OperationIdHash> concatInfoByOp;
            for (OperationId opId : graph.operations())
            {
                const Operation op = graph.getOperation(opId);
                if (auto concatInfo = regToMemIntentConcatInfo(graph, model, op))
                {
                    concatInfoByOp.emplace(opId, *concatInfo);
                    model.regToMemIntentConcatGroupByOp.emplace(opId, concatInfo->group);
                }
            }

            for (const auto &[concatOpId, concatInfo] : concatInfoByOp)
            {
                const Operation concatOp = graph.getOperation(concatOpId);
                const ValueId concatValue = concatOp.results().front();
                bool hasSliceUser = false;
                bool allUsersAreIntentSlices = true;
                const Value concatValueInfo = graph.getValue(concatValue);
                for (const auto &user : concatValueInfo.users())
                {
                    if (!user.operation.valid())
                    {
                        allUsersAreIntentSlices = false;
                        break;
                    }
                    const Operation userOp = graph.getOperation(user.operation);
                    if (!isRegToMemIntentSliceOfConcat(graph, userOp, concatValue, concatInfo))
                    {
                        allUsersAreIntentSlices = false;
                        break;
                    }
                    hasSliceUser = true;
                    model.regToMemIntentSliceGroupByOp.insert_or_assign(user.operation, concatInfo.group);
                }
                if (hasSliceUser && allUsersAreIntentSlices && regToMemIntentValueCanBypass(model, concatValue))
                {
                    model.regToMemIntentBypassOps.insert(concatOpId);
                }
            }

            for (const auto &[concatOpId, concatInfo] : concatInfoByOp)
            {
                if (!model.regToMemIntentBypassOps.contains(concatOpId))
                {
                    continue;
                }
                const Operation concatOp = graph.getOperation(concatOpId);
                for (ValueId operand : concatOp.operands())
                {
                    const OperationId readOpId = graph.valueDef(operand);
                    if (!readOpId.valid() || !regToMemIntentValueCanBypass(model, operand))
                    {
                        continue;
                    }
                    const Operation readOp = graph.getOperation(readOpId);
                    const auto readGroup = regToMemIntentGroupForRole(readOp, "read");
                    if (!readGroup || *readGroup != concatInfo.group)
                    {
                        continue;
                    }
                    bool onlyBypassConcatUsers = true;
                    const Value operandInfo = graph.getValue(operand);
                    for (const auto &user : operandInfo.users())
                    {
                        if (!user.operation.valid() ||
                            !model.regToMemIntentBypassOps.contains(user.operation))
                        {
                            onlyBypassConcatUsers = false;
                            break;
                        }
                        const auto concatGroupIt = model.regToMemIntentConcatGroupByOp.find(user.operation);
                        if (concatGroupIt == model.regToMemIntentConcatGroupByOp.end() ||
                            concatGroupIt->second != concatInfo.group)
                        {
                            onlyBypassConcatUsers = false;
                            break;
                        }
                    }
                    if (onlyBypassConcatUsers)
                    {
                        model.regToMemIntentBypassOps.insert(readOpId);
                        model.regToMemIntentReadGroupByOp.insert_or_assign(readOpId, concatInfo.group);
                    }
                }
            }
        }

        bool opNeedsWordLogicEmit(const Graph &graph, const Operation &op) noexcept;
        std::string valueRef(const EmitModel &model, ValueId value);

        std::optional<slang::SVInt> constLogicValue(const Graph &graph, ValueId value, int32_t width)
        {
            if (graph.valueType(value) != ValueType::Logic || width <= 0)
            {
                return std::nullopt;
            }
            const OperationId defOpId = graph.valueDef(value);
            if (!defOpId.valid())
            {
                return std::nullopt;
            }
            const Operation defOp = graph.getOperation(defOpId);
            if (defOp.kind() != OperationKind::kConstant)
            {
                return std::nullopt;
            }
            auto literal = getAttribute<std::string>(defOp, "constValue");
            if (!literal)
            {
                return std::nullopt;
            }
            auto parsed = parseConstLiteral(*literal);
            if (!parsed)
            {
                return std::nullopt;
            }
            parsed = parsed->resize(static_cast<slang::bitwidth_t>(width));
            if (parsed->hasUnknown())
            {
                return std::nullopt;
            }
            return parsed;
        }

        std::optional<std::size_t> constLogicIndexValue(const Graph &graph, ValueId value, std::size_t cap)
        {
            const int32_t width = graph.valueWidth(value);
            auto parsed = constLogicValue(graph, value, width);
            if (!parsed)
            {
                return std::nullopt;
            }
            const std::uint64_t *rawWords = parsed->getRawPtr();
            const std::size_t words = logicWordCount(width);
            std::uint64_t raw = words == 0 ? UINT64_C(0) : rawWords[0];
            for (std::size_t i = 1; i < words; ++i)
            {
                if (rawWords[i] != UINT64_C(0))
                {
                    return cap;
                }
            }
            if (raw > static_cast<std::uint64_t>(std::numeric_limits<std::size_t>::max()))
            {
                return cap;
            }
            const std::size_t index = static_cast<std::size_t>(raw);
            return std::min(index, cap);
        }

        bool isConstLogicAllZero(const Graph &graph, ValueId value, int32_t width)
        {
            auto parsed = constLogicValue(graph, value, width);
            if (!parsed)
            {
                return false;
            }
            const std::size_t words = logicWordCount(width);
            const std::uint64_t *rawWords = parsed->getRawPtr();
            for (std::size_t i = 0; i < words; ++i)
            {
                if (rawWords[i] != 0)
                {
                    return false;
                }
            }
            return true;
        }

        std::optional<std::string> regToMemIntentGroupForRole(const Operation &op, std::string_view role)
        {
            const auto group = getAttribute<std::string>(op, "regToMem.intent.group");
            if (!group || group->empty() ||
                getAttribute<std::string>(op, "regToMem.intent.role").value_or(std::string()) != role ||
                getAttribute<std::string>(op, "regToMem.intent.mode").value_or(std::string()) != "array-index")
            {
                return std::nullopt;
            }
            return group;
        }

        bool hasRegToMemIntentShape(const Operation &op,
                                    std::string_view group,
                                    int64_t elementWidth,
                                    int64_t elementCount)
        {
            const auto opGroup = getAttribute<std::string>(op, "regToMem.intent.group");
            const auto opElementWidth = getAttribute<int64_t>(op, "regToMem.intent.elementWidth");
            const auto opElementCount = getAttribute<int64_t>(op, "regToMem.intent.elementCount");
            return opGroup && *opGroup == group &&
                   opElementWidth && *opElementWidth == elementWidth &&
                   opElementCount && *opElementCount == elementCount;
        }

        std::optional<ValueId> regToMemIntentSliceIndexValue(const Graph &graph, const Operation &op)
        {
            if ((op.kind() != OperationKind::kSliceArray && op.kind() != OperationKind::kSliceDynamic) ||
                op.operands().size() != 2 ||
                !regToMemIntentGroupForRole(op, "slice"))
            {
                return std::nullopt;
            }
            if (op.kind() == OperationKind::kSliceArray)
            {
                return op.operands()[1];
            }

            const auto elementWidth = getAttribute<int64_t>(op, "regToMem.intent.elementWidth");
            if (!elementWidth || *elementWidth <= 0)
            {
                return std::nullopt;
            }
            if (*elementWidth == 1)
            {
                return op.operands()[1];
            }
            const OperationId startDefId = graph.valueDef(op.operands()[1]);
            if (!startDefId.valid())
            {
                return std::nullopt;
            }
            const Operation startDef = graph.getOperation(startDefId);
            if (startDef.kind() != OperationKind::kMul || startDef.operands().size() != 2)
            {
                return std::nullopt;
            }
            const std::size_t width = static_cast<std::size_t>(*elementWidth);
            const auto lhsConst = constLogicIndexValue(graph, startDef.operands()[0], width + 1u);
            if (lhsConst && *lhsConst == width)
            {
                return startDef.operands()[1];
            }
            const auto rhsConst = constLogicIndexValue(graph, startDef.operands()[1], width + 1u);
            if (rhsConst && *rhsConst == width)
            {
                return startDef.operands()[0];
            }
            return std::nullopt;
        }

        bool isConstLogicAllOnes(const Graph &graph, ValueId value, int32_t width)
        {
            auto parsed = constLogicValue(graph, value, width);
            if (!parsed)
            {
                return false;
            }
            const std::size_t words = logicWordCount(width);
            const std::uint64_t *rawWords = parsed->getRawPtr();
            for (std::size_t i = 0; i < words; ++i)
            {
                const std::size_t wordWidth =
                    (i + 1u == words) ? (static_cast<std::size_t>(width) - i * 64u) : 64u;
                const std::uint64_t expected = wordWidth >= 64u ? ~UINT64_C(0) : ((UINT64_C(1) << wordWidth) - 1u);
                if (rawWords[i] != expected)
                {
                    return false;
                }
            }
            return true;
        }

        bool isPowerOfTwoU64(std::uint64_t value) noexcept
        {
            return value != 0 && (value & (value - 1u)) == 0;
        }

        std::size_t minUnsignedBitsForRange(std::uint64_t exclusiveUpperBound) noexcept
        {
            std::size_t bits = 0;
            std::uint64_t limit = 1;
            while (limit < exclusiveUpperBound)
            {
                limit <<= 1u;
                ++bits;
            }
            return bits;
        }

        bool validateRegisterWritePort(const Graph &graph,
                                       const Operation &op,
                                       const StateDecl &state,
                                       std::string &error)
        {
            const auto operands = op.operands();
            const std::string opName = std::string(op.symbolText());
            if (!op.results().empty())
            {
                error = "kRegisterWritePort must not have results: " + opName;
                return false;
            }
            if (operands.size() < 4)
            {
                error = "kRegisterWritePort missing operands: " + opName;
                return false;
            }
            if (!isValidLogicConditionValue(graph, operands[0]))
            {
                error = "kRegisterWritePort updateCond must be logic: " + opName;
                return false;
            }
            if (graph.valueType(operands[1]) != ValueType::Logic || graph.valueWidth(operands[1]) != state.width)
            {
                error = "kRegisterWritePort nextValue width/type mismatch: " + opName;
                return false;
            }
            if (graph.valueType(operands[2]) != ValueType::Logic || graph.valueWidth(operands[2]) != state.width)
            {
                error = "kRegisterWritePort mask width/type mismatch: " + opName;
                return false;
            }
            auto eventEdges = getAttribute<std::vector<std::string>>(op, "eventEdge");
            if (!eventEdges)
            {
                error = "kRegisterWritePort missing eventEdge: " + opName;
                return false;
            }
            const std::size_t eventCount = operands.size() - 3;
            if (eventEdges->size() != eventCount)
            {
                error = "kRegisterWritePort eventEdge size mismatch: " + opName;
                return false;
            }
            for (std::size_t i = 0; i < eventCount; ++i)
            {
                const ValueId eventValue = operands[3 + i];
                if (graph.valueType(eventValue) != ValueType::Logic || graph.valueWidth(eventValue) != 1)
                {
                    error = "kRegisterWritePort event operand must be 1-bit logic: " + opName;
                    return false;
                }
            }
            return true;
        }

        bool validateMemoryWritePort(const Graph &graph,
                                     const Operation &op,
                                     const StateDecl &state,
                                     std::string &error)
        {
            const auto operands = op.operands();
            const std::string opName = std::string(op.symbolText());
            if (!op.results().empty())
            {
                error = "kMemoryWritePort must not have results: " + opName;
                return false;
            }
            if (operands.size() < 5)
            {
                error = "kMemoryWritePort missing operands: " + opName;
                return false;
            }
            if (!isValidLogicConditionValue(graph, operands[0]))
            {
                error = "kMemoryWritePort updateCond must be logic: " + opName;
                return false;
            }
            if (graph.valueType(operands[1]) != ValueType::Logic || graph.valueWidth(operands[1]) <= 0)
            {
                error = "kMemoryWritePort addr must be logic: " + opName;
                return false;
            }
            if (graph.valueType(operands[2]) != ValueType::Logic || graph.valueWidth(operands[2]) != state.width)
            {
                error = "kMemoryWritePort data width/type mismatch: " + opName;
                return false;
            }
            if (graph.valueType(operands[3]) != ValueType::Logic || graph.valueWidth(operands[3]) != state.width)
            {
                error = "kMemoryWritePort mask width/type mismatch: " + opName;
                return false;
            }
            auto eventEdges = getAttribute<std::vector<std::string>>(op, "eventEdge");
            if (!eventEdges)
            {
                error = "kMemoryWritePort missing eventEdge: " + opName;
                return false;
            }
            const std::size_t eventCount = operands.size() - 4;
            if (eventEdges->size() != eventCount)
            {
                error = "kMemoryWritePort eventEdge size mismatch: " + opName;
                return false;
            }
            for (std::size_t i = 0; i < eventCount; ++i)
            {
                const ValueId eventValue = operands[4 + i];
                if (graph.valueType(eventValue) != ValueType::Logic || graph.valueWidth(eventValue) != 1)
                {
                    error = "kMemoryWritePort event operand must be 1-bit logic: " + opName;
                    return false;
                }
            }
            return true;
        }

        bool validateMemoryFillPort(const Graph &graph,
                                    const Operation &op,
                                    const StateDecl &state,
                                    std::string &error)
        {
            const auto operands = op.operands();
            const std::string opName = std::string(op.symbolText());
            if (!op.results().empty())
            {
                error = "kMemoryFillPort must not have results: " + opName;
                return false;
            }
            if (operands.size() < 3)
            {
                error = "kMemoryFillPort missing operands: " + opName;
                return false;
            }
            if (!isValidLogicConditionValue(graph, operands[0]))
            {
                error = "kMemoryFillPort updateCond must be logic: " + opName;
                return false;
            }
            const int32_t dataWidth = graph.valueWidth(operands[1]);
            const int64_t packedWidth =
                state.rowCount > 0 ? static_cast<int64_t>(state.width) * state.rowCount : 0;
            if (graph.valueType(operands[1]) != ValueType::Logic ||
                (dataWidth != state.width && dataWidth != packedWidth))
            {
                error = "kMemoryFillPort data width/type mismatch: " + opName;
                return false;
            }
            auto eventEdges = getAttribute<std::vector<std::string>>(op, "eventEdge");
            if (!eventEdges)
            {
                error = "kMemoryFillPort missing eventEdge: " + opName;
                return false;
            }
            const std::size_t eventCount = operands.size() - 2;
            if (eventEdges->size() != eventCount)
            {
                error = "kMemoryFillPort eventEdge size mismatch: " + opName;
                return false;
            }
            for (std::size_t i = 0; i < eventCount; ++i)
            {
                const ValueId eventValue = operands[2 + i];
                if (graph.valueType(eventValue) != ValueType::Logic || graph.valueWidth(eventValue) != 1)
                {
                    error = "kMemoryFillPort event operand must be 1-bit logic: " + opName;
                    return false;
                }
            }
            return true;
        }

        bool validateSystemTask(const Graph &graph,
                                const Operation &op,
                                std::string &error)
        {
            const auto operands = op.operands();
            const std::string opName = std::string(op.symbolText());
            if (!op.results().empty())
            {
                error = "kSystemTask must not have results: " + opName;
                return false;
            }
            if (operands.empty())
            {
                error = "kSystemTask missing callCond operand: " + opName;
                return false;
            }
            if (!isValidLogicConditionValue(graph, operands[0]))
            {
                error = "kSystemTask callCond must be logic: " + opName;
                return false;
            }
            auto name = getAttribute<std::string>(op, "name");
            if (!name || name->empty())
            {
                error = "kSystemTask missing name: " + opName;
                return false;
            }
            auto eventEdges = getAttribute<std::vector<std::string>>(op, "eventEdge");
            const std::size_t eventCount = eventEdges ? eventEdges->size() : 0;
            if (operands.size() < 1 + eventCount)
            {
                error = "kSystemTask eventEdge size mismatch: " + opName;
                return false;
            }
            for (std::size_t i = 0; i < eventCount; ++i)
            {
                const ValueId eventValue = operands[operands.size() - eventCount + i];
                if (graph.valueType(eventValue) != ValueType::Logic || graph.valueWidth(eventValue) != 1)
                {
                    error = "kSystemTask event operand must be 1-bit logic: " + opName;
                    return false;
                }
            }
            return true;
        }

        bool systemTaskIsFinal(const Operation &op)
        {
            return getAttribute<std::string>(op, "procKind").value_or(std::string()) == "final";
        }

        bool systemTaskRunsOnlyOnInitialEval(const Operation &op)
        {
            const std::string procKind = getAttribute<std::string>(op, "procKind").value_or(std::string());
            const bool hasTiming = getAttribute<bool>(op, "hasTiming").value_or(false);
            return procKind == "initial" && !hasTiming;
        }

        bool systemTaskRunsOnceAfterTimedTrigger(const Operation &op)
        {
            const std::string procKind = getAttribute<std::string>(op, "procKind").value_or(std::string());
            const bool hasTiming = getAttribute<bool>(op, "hasTiming").value_or(false);
            return procKind == "initial" && hasTiming;
        }

        bool systemFunctionRunsOnlyOnInitialEval(const Operation &op)
        {
            const std::string procKind = getAttribute<std::string>(op, "procKind").value_or(std::string());
            const bool hasTiming = getAttribute<bool>(op, "hasTiming").value_or(false);
            return procKind == "initial" && !hasTiming;
        }

        std::string systemTaskArgExpr(const Graph &graph,
                                      const EmitModel &model,
                                      ValueId value,
                                      const SupernodeLocalExprContext *context)
        {
            auto ref = [&]() -> std::string
            {
                if (auto it = model.inputFieldByValue.find(value); it != model.inputFieldByValue.end())
                {
                    return it->second;
                }
                return resolvedScheduleValueExpr(model, value, context);
            };
            const std::string signedText = graph.valueSigned(value) ? "true" : "false";
            switch (graph.valueType(value))
            {
            case ValueType::String:
                return "grhsim_make_task_arg(" + ref() + ")";
            case ValueType::Real:
                return "grhsim_make_task_arg(static_cast<double>(" + ref() + "))";
            case ValueType::Logic:
            default:
                break;
            }
            if (isWideLogicValue(graph, value))
            {
                std::ostringstream out;
                out << "grhsim_make_task_arg(" << resolvedScheduleValueExpr(model, value, context) << ", "
                    << graph.valueWidth(value) << ", "
                    << signedText << ")";
                return out.str();
            }
            std::ostringstream out;
            out << "grhsim_make_task_arg(static_cast<std::uint64_t>(" << ref() << "), "
                << graph.valueWidth(value) << ", "
                << signedText << ")";
            return out.str();
        }

        std::string systemTaskArgExpr(const Graph &graph,
                                      const EmitModel &model,
                                      ValueId value)
        {
            return systemTaskArgExpr(graph, model, value, nullptr);
        }

        std::string scalarSystemTaskArgExpr(const Graph &graph,
                                            const EmitModel &model,
                                            ValueId value,
                                            const SupernodeLocalExprContext *context)
        {
            const std::string ref =
                (model.inputFieldByValue.find(value) != model.inputFieldByValue.end())
                    ? model.inputFieldByValue.at(value)
                    : resolvedScheduleValueExpr(model, value, context);
            std::ostringstream out;
            out << "grhsim_scalar_task_arg{static_cast<std::uint64_t>(" << ref << "), "
                << graph.valueWidth(value) << "u, "
                << (graph.valueSigned(value) ? "true" : "false") << "}";
            return out.str();
        }

        std::string scalarSystemTaskDirectArgExpr(const Graph &graph,
                                                  const EmitModel &model,
                                                  ValueId value,
                                                  const SupernodeLocalExprContext *context)
        {
            const std::string ref =
                (model.inputFieldByValue.find(value) != model.inputFieldByValue.end())
                    ? model.inputFieldByValue.at(value)
                    : resolvedScheduleValueExpr(model, value, context);
            std::ostringstream out;
            out << "static_cast<unsigned>(" << graph.valueWidth(value) << "u"
                << (graph.valueSigned(value) ? " | 0x80000000u" : "") << "), "
                << "static_cast<std::uint64_t>(" << ref << ")";
            return out.str();
        }

        bool canUseScalarFormatSystemTask(const Graph &graph,
                                          const EmitModel &model,
                                          std::string_view name,
                                          std::span<const ValueId> args,
                                          bool requireStableValues)
        {
            const bool usesHandle = name == "fdisplay" || name == "fwrite";
            const bool supportedName =
                name == "display" || name == "write" || name == "strobe" || usesHandle;
            if (!supportedName)
            {
                return false;
            }
            const std::size_t formatIndex = usesHandle ? 1u : 0u;
            if (args.size() <= formatIndex)
            {
                return false;
            }
            if (usesHandle && !isScalarLogicValue(graph, args.front()))
            {
                return false;
            }
            if (graph.valueType(args[formatIndex]) != ValueType::String ||
                !isStaticConstStringValue(model, args[formatIndex]))
            {
                return false;
            }
            for (std::size_t i = formatIndex + 1u; i < args.size(); ++i)
            {
                if (!isScalarLogicValue(graph, args[i]))
                {
                    return false;
                }
                if (requireStableValues && !stableValueExpr(graph, model, args[i]).has_value())
                {
                    return false;
                }
            }
            return !requireStableValues ||
                   (!usesHandle || stableValueExpr(graph, model, args.front()).has_value());
        }

        bool canUseDirectScalarFormatSystemTask(const Graph &graph,
                                                const EmitModel &model,
                                                std::string_view name,
                                                std::span<const ValueId> args,
                                                bool requireStableValues)
        {
            if (name == "strobe")
            {
                return false;
            }
            return canUseScalarFormatSystemTask(graph, model, name, args, requireStableValues);
        }

        void emitScalarFormatSystemTaskCall(std::ostream &stream,
                                            const Graph &graph,
                                            const EmitModel &model,
                                            std::string_view indent,
                                            std::string_view name,
                                            std::span<const ValueId> args,
                                            const SupernodeLocalExprContext *context)
        {
            const bool usesHandle = name == "fdisplay" || name == "fwrite";
            const std::size_t formatIndex = usesHandle ? 1u : 0u;
            const std::string handleExpr =
                usesHandle
                    ? ("static_cast<std::uint64_t>(" + resolvedScheduleValueExpr(model, args.front(), context) + ")")
                    : "UINT64_C(0)";
            const std::string formatExpr = model.staticConstStringFieldByValue.at(args[formatIndex]);
            emitScalarFormatSystemTaskCall(stream,
                                           indent,
                                           name,
                                           handleExpr,
                                           formatExpr,
                                           args.size() - formatIndex - 1u,
                                           [&](std::size_t argIndex)
                                           {
                                               return scalarSystemTaskArgExpr(graph,
                                                                              model,
                                                                              args[formatIndex + 1u + argIndex],
                                                                              context);
                                           });
        }

        void emitDirectScalarFormatSystemTaskCall(std::ostream &stream,
                                                  const Graph &graph,
                                                  const EmitModel &model,
                                                  std::string_view indent,
                                                  std::string_view name,
                                                  std::span<const ValueId> args,
                                                  const SupernodeLocalExprContext *context)
        {
            const bool usesHandle = name == "fdisplay" || name == "fwrite";
            const bool newline = name == "display" || name == "fdisplay";
            const std::size_t formatIndex = usesHandle ? 1u : 0u;
            const std::string handleExpr =
                usesHandle
                    ? ("static_cast<std::uint64_t>(" + resolvedScheduleValueExpr(model, args.front(), context) + ")")
                    : "UINT64_C(0)";
            const std::string formatExpr = model.staticConstStringFieldByValue.at(args[formatIndex]);
            emitDirectScalarFormatSystemTaskCall(stream,
                                                 indent,
                                                 usesHandle,
                                                 newline,
                                                 handleExpr,
                                                 formatExpr,
                                                 args.size() - formatIndex - 1u,
                                                 [&](std::size_t argIndex)
                                                 {
                                                     return scalarSystemTaskDirectArgExpr(
                                                         graph,
                                                         model,
                                                         args[formatIndex + 1u + argIndex],
                                                         context);
                                                 });
        }

        std::string stableSystemTaskArgExpr(const Graph &graph,
                                            const EmitModel &model,
                                            ValueId value);

        std::string dpiLoweredTypeName(std::string_view typeName)
        {
            std::string lowered;
            lowered.reserve(typeName.size());
            for (unsigned char ch : typeName)
            {
                lowered.push_back(static_cast<char>(std::tolower(ch)));
            }
            return lowered;
        }

        bool dpiTypeIsString(std::string_view typeName)
        {
            return dpiLoweredTypeName(typeName) == "string";
        }

        bool dpiTypeIsReal(std::string_view typeName)
        {
            const std::string lowered = dpiLoweredTypeName(typeName);
            return lowered == "real" || lowered == "shortreal";
        }

        bool dpiTypeIsShortReal(std::string_view typeName)
        {
            return dpiLoweredTypeName(typeName) == "shortreal";
        }

        bool dpiTypeIsLogicLike(std::string_view typeName)
        {
            return !dpiTypeIsString(typeName) && !dpiTypeIsReal(typeName);
        }

        int64_t dpiEffectiveWidth(std::string_view typeName, int64_t width)
        {
            const std::string lowered = dpiLoweredTypeName(typeName);
            if (lowered == "byte")
            {
                return 8;
            }
            if (lowered == "shortint")
            {
                return 16;
            }
            if (lowered == "int" || lowered == "integer")
            {
                return 32;
            }
            if (lowered == "longint" || lowered == "time")
            {
                return 64;
            }
            return width > 0 ? width : 1;
        }

        std::string dpiScalarLogicCppType(int64_t width, bool isSigned)
        {
            if (width <= 1)
            {
                return "bool";
            }
            if (width <= 8)
            {
                return isSigned ? "std::int8_t" : "std::uint8_t";
            }
            if (width <= 16)
            {
                return isSigned ? "std::int16_t" : "std::uint16_t";
            }
            if (width <= 32)
            {
                return isSigned ? "std::int32_t" : "std::uint32_t";
            }
            return isSigned ? "std::int64_t" : "std::uint64_t";
        }

        std::string dpiBaseCppType(std::string_view typeName, int64_t width, bool isSigned)
        {
            const std::string lowered = dpiLoweredTypeName(typeName);
            if (dpiTypeIsShortReal(typeName))
            {
                return "float";
            }
            if (lowered == "real" || lowered == "shortreal")
            {
                return "double";
            }
            if (lowered == "string")
            {
                return "std::string";
            }
            const int64_t effectiveWidth = dpiEffectiveWidth(typeName, width);
            if (effectiveWidth <= 64)
            {
                return dpiScalarLogicCppType(effectiveWidth, isSigned);
            }
            return logicCppType(static_cast<int32_t>(effectiveWidth));
        }

        std::string dpiDeclArgCppType(std::string_view typeName,
                                      int64_t width,
                                      bool isSigned,
                                      std::string_view direction)
        {
            const std::string baseType = dpiBaseCppType(typeName, width, isSigned);
            if (direction == "output" || direction == "inout")
            {
                return baseType + " *";
            }
            if (dpiTypeIsString(typeName))
            {
                return "const char *";
            }
            if (dpiEffectiveWidth(typeName, width) > 64)
            {
                return "const " + baseType + " &";
            }
            return baseType;
        }

        int findNameIndex(const std::vector<std::string> &names, std::string_view needle)
        {
            for (std::size_t i = 0; i < names.size(); ++i)
            {
                if (names[i] == needle)
                {
                    return static_cast<int>(i);
                }
            }
            return -1;
        }

        ValueType dpiExpectedValueType(std::string_view typeName)
        {
            if (dpiTypeIsString(typeName))
            {
                return ValueType::String;
            }
            if (dpiTypeIsReal(typeName))
            {
                return ValueType::Real;
            }
            return ValueType::Logic;
        }

        bool validateDpiValueType(const Graph &graph,
                                  ValueId value,
                                  std::string_view typeName,
                                  int64_t width,
                                  std::string_view context,
                                  std::string &error)
        {
            const ValueType expectedType = dpiExpectedValueType(typeName);
            if (graph.valueType(value) != expectedType)
            {
                error = std::string(context) + " value type mismatch";
                return false;
            }
            if (expectedType == ValueType::Logic)
            {
                const int64_t expectedWidth = dpiEffectiveWidth(typeName, width);
                if (graph.valueWidth(value) != expectedWidth)
                {
                    error = std::string(context) + " width mismatch";
                    return false;
                }
            }
            return true;
        }

        std::string dpiValueExpr(const Graph &graph,
                                 const EmitModel &model,
                                 ValueId value,
                                 std::string_view typeName,
                                 int64_t width,
                                 bool isSigned,
                                 const SupernodeLocalExprContext *context)
        {
            const std::string ref = resolvedScheduleValueExpr(model, value, context);
            if (dpiTypeIsString(typeName))
            {
                if (isStaticConstStringValue(model, value))
                {
                    return ref;
                }
                return ref + ".c_str()";
            }
            if (dpiTypeIsShortReal(typeName))
            {
                return "static_cast<float>(" + ref + ")";
            }
            if (dpiTypeIsReal(typeName))
            {
                return ref;
            }
            const int64_t effectiveWidth = dpiEffectiveWidth(typeName, width);
            if (effectiveWidth > 64)
            {
                return castWordsExprForValue(
                    graph, value, resolvedScheduleValueExpr(model, value, context), static_cast<int32_t>(effectiveWidth));
            }
            return "static_cast<" + dpiBaseCppType(typeName, width, isSigned) + ">(" + ref + ")";
        }

        std::string dpiValueExpr(const Graph &graph,
                                 const EmitModel &model,
                                 ValueId value,
                                 std::string_view typeName,
                                 int64_t width,
                                 bool isSigned)
        {
            return dpiValueExpr(graph, model, value, typeName, width, isSigned, nullptr);
        }

        bool validateDpicCall(const Graph &graph,
                              const Operation &op,
                              const EmitModel &model,
                              std::string &error)
        {
            const std::string opName = std::string(op.symbolText());
            const auto operands = op.operands();
            if (operands.empty())
            {
                error = "kDpicCall missing callCond operand: " + opName;
                return false;
            }
            if (!isValidLogicConditionValue(graph, operands[0]))
            {
                error = "kDpicCall callCond must be logic: " + opName;
                return false;
            }

            const auto targetImport = getAttribute<std::string>(op, "targetImportSymbol");
            if (!targetImport)
            {
                error = "kDpicCall missing targetImportSymbol: " + opName;
                return false;
            }
            auto importIt = model.dpiImportBySymbol.find(*targetImport);
            if (importIt == model.dpiImportBySymbol.end())
            {
                error = "kDpicCall target import not found: " + *targetImport;
                return false;
            }
            const DpiImportDecl &decl = importIt->second;

            const std::vector<std::string> inArgName =
                getAttribute<std::vector<std::string>>(op, "inArgName").value_or(std::vector<std::string>{});
            const std::vector<std::string> outArgName =
                getAttribute<std::vector<std::string>>(op, "outArgName").value_or(std::vector<std::string>{});
            const std::vector<std::string> inoutArgName =
                getAttribute<std::vector<std::string>>(op, "inoutArgName").value_or(std::vector<std::string>{});
            const std::vector<std::string> eventEdges =
                getAttribute<std::vector<std::string>>(op, "eventEdge").value_or(std::vector<std::string>{});
            const bool hasReturn = getAttribute<bool>(op, "hasReturn").value_or(false);

            if (!inoutArgName.empty())
            {
                error = "kDpicCall inout args are not supported in grhsim-cpp emit: " + opName;
                return false;
            }
            for (const std::string &direction : decl.argsDirection)
            {
                if (direction == "inout")
                {
                    error = "kDpicImport with inout args is not supported in grhsim-cpp emit: " + decl.symbol;
                    return false;
                }
            }
            if (hasReturn != decl.hasReturn)
            {
                error = "kDpicCall hasReturn mismatch: " + opName;
                return false;
            }
            if (operands.size() != 1 + inArgName.size() + eventEdges.size())
            {
                error = "kDpicCall operand count mismatch: " + opName;
                return false;
            }
            const std::size_t expectedResults = (hasReturn ? 1u : 0u) + outArgName.size();
            if (op.results().size() != expectedResults)
            {
                error = "kDpicCall result count mismatch: " + opName;
                return false;
            }
            for (std::size_t i = 0; i < eventEdges.size(); ++i)
            {
                const ValueId eventValue = operands[1 + inArgName.size() + i];
                if (graph.valueType(eventValue) != ValueType::Logic || graph.valueWidth(eventValue) != 1)
                {
                    error = "kDpicCall event operand must be 1-bit logic: " + opName;
                    return false;
                }
            }

            auto validateUniqueNames = [&](const std::vector<std::string> &names, std::string_view kind) -> bool
            {
                std::unordered_set<std::string> seen;
                for (const std::string &name : names)
                {
                    if (!seen.insert(name).second)
                    {
                        error = "kDpicCall duplicate " + std::string(kind) + " name: " + opName;
                        return false;
                    }
                }
                return true;
            };
            if (!validateUniqueNames(inArgName, "input arg") || !validateUniqueNames(outArgName, "output arg"))
            {
                return false;
            }

            std::size_t importInputCount = 0;
            std::size_t importOutputCount = 0;
            for (const std::string &direction : decl.argsDirection)
            {
                if (direction == "input")
                {
                    ++importInputCount;
                }
                else if (direction == "output")
                {
                    ++importOutputCount;
                }
            }
            if (inArgName.size() != importInputCount || outArgName.size() != importOutputCount)
            {
                error = "kDpicCall arg group size mismatch: " + opName;
                return false;
            }

            std::size_t resultBase = 0;
            if (hasReturn)
            {
                if (!validateDpiValueType(graph,
                                          op.results()[0],
                                          decl.returnType,
                                          decl.returnWidth,
                                          "kDpicCall return",
                                          error))
                {
                    error += ": " + opName;
                    return false;
                }
                resultBase = 1;
            }

            for (std::size_t i = 0; i < decl.argsDirection.size(); ++i)
            {
                const std::string &direction = decl.argsDirection[i];
                const std::string formalName =
                    i < decl.argsName.size() ? decl.argsName[i] : ("arg" + std::to_string(i));
                const std::string_view typeName =
                    i < decl.argsType.size() ? std::string_view(decl.argsType[i]) : std::string_view("logic");
                const int64_t width = i < decl.argsWidth.size() ? decl.argsWidth[i] : 1;
                if (direction == "input")
                {
                    const int inputIndex = findNameIndex(inArgName, formalName);
                    if (inputIndex < 0)
                    {
                        error = "kDpicCall missing matching input arg " + formalName + ": " + opName;
                        return false;
                    }
                    if (!validateDpiValueType(graph,
                                              operands[1 + static_cast<std::size_t>(inputIndex)],
                                              typeName,
                                              width,
                                              "kDpicCall input arg",
                                              error))
                    {
                        error += ": " + opName + " formal=" + formalName;
                        return false;
                    }
                }
                else if (direction == "output")
                {
                    const int outputIndex = findNameIndex(outArgName, formalName);
                    if (outputIndex < 0)
                    {
                        error = "kDpicCall missing matching output arg " + formalName + ": " + opName;
                        return false;
                    }
                    if (!validateDpiValueType(graph,
                                              op.results()[resultBase + static_cast<std::size_t>(outputIndex)],
                                              typeName,
                                              width,
                                              "kDpicCall output arg",
                                              error))
                    {
                        error += ": " + opName + " formal=" + formalName;
                        return false;
                    }
                }
                else
                {
                    error = "kDpicImport has unsupported arg direction for grhsim-cpp emit: " + decl.symbol;
                    return false;
                }
            }
            return true;
        }

        void buildSameSupernodeStateReadSlotAliases(
            const Graph &graph,
            const ScheduleRefs &schedule,
            const std::unordered_set<ValueId, ValueIdHash> &waveformValueIds,
            EmitModel &model)
        {
            model.materializedValueAliasByValue.clear();
            model.sameSupernodeStateReadSlotAliasCount = 0;
            model.sameSupernodeStateReadSlotAliasGroupCount = 0;
            if (!emitSameSupernodeStateReadSlotAliasesEnabled())
            {
                return;
            }

            std::unordered_set<ValueId, ValueIdHash> protectedValues = waveformValueIds;
            for (const auto &port : graph.outputPorts())
            {
                protectedValues.insert(port.value);
            }
            for (const auto &port : graph.inoutPorts())
            {
                protectedValues.insert(port.out);
                protectedValues.insert(port.oe);
            }
            for (const auto &[value, _] : model.eventEdgeFieldByValue)
            {
                (void)_;
                protectedValues.insert(value);
            }

            std::unordered_set<ValueId, ValueIdHash> aliasedCanonicalValues;
            for (uint32_t supernodeId : model.computeSupernodeIds)
            {
                if (supernodeId >= schedule.supernodeToOps.size())
                {
                    continue;
                }
                std::unordered_map<std::string, ValueId> canonicalValueByState;
                for (OperationId opId : schedule.supernodeToOps[supernodeId])
                {
                    const Operation op = graph.getOperation(opId);
                    if ((op.kind() != OperationKind::kRegisterReadPort &&
                         op.kind() != OperationKind::kLatchReadPort) ||
                        op.results().size() != 1 || isRegToMemIntentBypassOp(model, opId))
                    {
                        continue;
                    }

                    const ValueId resultValue = op.results().front();
                    if (!model.materializedValues.contains(resultValue) ||
                        graph.valueType(resultValue) != ValueType::Logic ||
                        isWideLogicValue(graph, resultValue) ||
                        !valueNeedsChangeDetect(model, resultValue) ||
                        protectedValues.contains(resultValue) ||
                        model.packedArrayLaneViewByValue.contains(resultValue))
                    {
                        continue;
                    }

                    const char *symbolAttr =
                        op.kind() == OperationKind::kRegisterReadPort ? "regSymbol" : "latchSymbol";
                    const auto targetSymbol = getAttribute<std::string>(op, symbolAttr);
                    if (!targetSymbol)
                    {
                        continue;
                    }
                    const auto stateIt = model.stateBySymbol.find(*targetSymbol);
                    if (stateIt == model.stateBySymbol.end() ||
                        stateIt->second.kind == StateDecl::Kind::Memory ||
                        isWideLogicWidth(stateIt->second.width) ||
                        graph.valueWidth(resultValue) != stateIt->second.width ||
                        graph.valueSigned(resultValue) != stateIt->second.isSigned)
                    {
                        continue;
                    }

                    const auto [canonicalIt, inserted] =
                        canonicalValueByState.emplace(*targetSymbol, resultValue);
                    if (inserted || canonicalIt->second == resultValue)
                    {
                        continue;
                    }
                    model.materializedValueAliasByValue.emplace(resultValue, canonicalIt->second);
                    aliasedCanonicalValues.insert(canonicalIt->second);
                }
            }
            model.sameSupernodeStateReadSlotAliasCount = model.materializedValueAliasByValue.size();
            model.sameSupernodeStateReadSlotAliasGroupCount = aliasedCanonicalValues.size();
        }

        void buildDirectSingleWriterStateReads(
            const Graph &graph,
            const ScheduleRefs &schedule,
            const std::unordered_set<ValueId, ValueIdHash> &waveformValueIds,
            EmitModel &model)
        {
            model.directStateReadSymbolByValue.clear();
            model.directStateReadCount = 0;
            model.directStateReadCanonicalCount = 0;
            model.directStateReadAliasCount = 0;
            model.directStateReadGroupCount = 0;
            model.directStateReadSourceGroupCount = 0;
            model.directStateReadRemovedSourceHeadCount = 0;
            model.directStateReadConsumerHeadCount = 0;
            if (!model.directSingleWriterStateReads)
            {
                return;
            }

            constexpr uint32_t kNoSupernode = std::numeric_limits<uint32_t>::max();
            std::vector<uint32_t> supernodeByOp;
            if (!graph.operations().empty())
            {
                supernodeByOp.assign(graph.operations().back().index + 1u, kNoSupernode);
            }
            for (uint32_t supernodeId = 0; supernodeId < schedule.supernodeToOps.size(); ++supernodeId)
            {
                for (OperationId opId : schedule.supernodeToOps[supernodeId])
                {
                    if (opId.index >= supernodeByOp.size())
                    {
                        supernodeByOp.resize(opId.index + 1u, kNoSupernode);
                    }
                    supernodeByOp[opId.index] = supernodeId;
                }
            }

            std::unordered_map<std::string, std::size_t> registerWriteCountBySymbol;
            for (const WriteDecl &write : model.writes)
            {
                if (write.kind == StateDecl::Kind::Register)
                {
                    ++registerWriteCountBySymbol[write.symbol];
                }
            }

            std::unordered_set<ValueId, ValueIdHash> protectedValues = waveformValueIds;
            for (const auto &port : graph.outputPorts())
            {
                protectedValues.insert(port.value);
            }
            for (const auto &port : graph.inoutPorts())
            {
                protectedValues.insert(port.out);
                protectedValues.insert(port.oe);
            }
            for (const auto &[value, _] : model.eventEdgeFieldByValue)
            {
                (void)_;
                protectedValues.insert(value);
            }

            struct CandidateRead
            {
                ValueId value;
                const StateDecl *state = nullptr;
                uint32_t sourceSupernode = kNoSupernode;
                ValueId canonicalValue;
                bool rawEligible = false;
            };
            struct SourceReadGroup
            {
                std::size_t readCount = 0;
                std::size_t directCount = 0;
            };

            std::vector<CandidateRead> reads;
            reads.reserve(model.materializedValues.size());
            std::unordered_map<std::string, std::unordered_map<uint32_t, SourceReadGroup>> sourceGroupsByState;
            std::unordered_map<ValueId, bool, ValueIdHash> aliasGroupEligible;

            for (uint32_t supernodeId : model.computeSupernodeIds)
            {
                if (supernodeId >= schedule.supernodeToOps.size())
                {
                    continue;
                }
                for (OperationId opId : schedule.supernodeToOps[supernodeId])
                {
                    const Operation op = graph.getOperation(opId);
                    if (op.kind() != OperationKind::kRegisterReadPort)
                    {
                        continue;
                    }
                    const auto targetSymbol = getAttribute<std::string>(op, "regSymbol");
                    if (!targetSymbol)
                    {
                        continue;
                    }
                    const auto stateIt = model.stateBySymbol.find(*targetSymbol);
                    if (stateIt == model.stateBySymbol.end())
                    {
                        continue;
                    }
                    ++sourceGroupsByState[*targetSymbol][supernodeId].readCount;
                    if (op.results().size() != 1)
                    {
                        continue;
                    }

                    const ValueId resultValue = op.results().front();
                    const StateDecl &state = stateIt->second;
                    bool rawEligible =
                        state.kind == StateDecl::Kind::Register &&
                        !state.regToMemIntentStorage &&
                        !isWideLogicWidth(state.width) &&
                        registerWriteCountBySymbol[*targetSymbol] == 1u &&
                        model.materializedValues.contains(resultValue) &&
                        graph.valueType(resultValue) == ValueType::Logic &&
                        !isWideLogicValue(graph, resultValue) &&
                        graph.valueWidth(resultValue) == state.width &&
                        graph.valueSigned(resultValue) == state.isSigned &&
                        valueNeedsTrackedChange(model, resultValue) &&
                        !protectedValues.contains(resultValue) &&
                        !model.packedArrayLaneViewByValue.contains(resultValue) &&
                        !isRegToMemIntentBypassOp(model, opId);

                    const auto boundaryIt = model.boundaryFanoutByValue.find(resultValue);
                    rawEligible = rawEligible &&
                                  boundaryIt != model.boundaryFanoutByValue.end() &&
                                  !boundaryIt->second.empty();
                    if (rawEligible)
                    {
                        std::vector<uint32_t> userActiveIds;
                        for (const auto &user : graph.getValue(resultValue).users())
                        {
                            const OperationId userOpId = user.operation;
                            const uint32_t userSupernode =
                                userOpId.valid() && userOpId.index < supernodeByOp.size()
                                    ? supernodeByOp[userOpId.index]
                                    : kNoSupernode;
                            if (userSupernode == kNoSupernode || userSupernode == supernodeId ||
                                !isComputeSupernode(model, userSupernode) ||
                                userSupernode >= model.activeIdBySupernode.size() ||
                                model.activeIdBySupernode[userSupernode] == kInvalidIndex)
                            {
                                rawEligible = false;
                                break;
                            }
                            userActiveIds.push_back(
                                static_cast<uint32_t>(model.activeIdBySupernode[userSupernode]));
                        }
                        if (rawEligible)
                        {
                            sortUniqueVector(userActiveIds);
                            rawEligible = userActiveIds == boundaryIt->second;
                        }
                    }

                    const ValueId canonicalValue = canonicalMaterializedStorageValue(model, resultValue);
                    auto [eligibleIt, inserted] = aliasGroupEligible.emplace(canonicalValue, rawEligible);
                    if (!inserted)
                    {
                        eligibleIt->second = eligibleIt->second && rawEligible;
                    }
                    reads.push_back(CandidateRead{
                        .value = resultValue,
                        .state = &state,
                        .sourceSupernode = supernodeId,
                        .canonicalValue = canonicalValue,
                        .rawEligible = rawEligible,
                    });
                }
            }

            std::unordered_map<std::string, std::vector<uint32_t>> directConsumerActiveIdsByState;
            std::unordered_set<ValueId, ValueIdHash> directCanonicalGroups;
            for (const CandidateRead &read : reads)
            {
                const auto groupIt = aliasGroupEligible.find(read.canonicalValue);
                if (!read.rawEligible || groupIt == aliasGroupEligible.end() || !groupIt->second)
                {
                    continue;
                }
                model.directStateReadSymbolByValue.emplace(read.value, read.state->symbol);
                ++sourceGroupsByState[read.state->symbol][read.sourceSupernode].directCount;
                const auto boundaryIt = model.boundaryFanoutByValue.find(read.value);
                if (boundaryIt != model.boundaryFanoutByValue.end())
                {
                    auto &consumers = directConsumerActiveIdsByState[read.state->symbol];
                    consumers.insert(consumers.end(), boundaryIt->second.begin(), boundaryIt->second.end());
                }
                directCanonicalGroups.insert(read.canonicalValue);
                ++model.directStateReadCount;
                if (model.materializedValueAliasByValue.contains(read.value))
                {
                    ++model.directStateReadAliasCount;
                }
                else
                {
                    ++model.directStateReadCanonicalCount;
                }
            }
            model.directStateReadGroupCount = directCanonicalGroups.size();

            for (auto &[stateSymbol, sourceGroups] : sourceGroupsByState)
            {
                auto &frontier = model.stateHeadSupernodesBySymbol[stateSymbol];
                for (const auto &[sourceSupernode, group] : sourceGroups)
                {
                    if (group.directCount == 0)
                    {
                        continue;
                    }
                    ++model.directStateReadSourceGroupCount;
                    if (group.directCount != group.readCount ||
                        sourceSupernode >= model.activeIdBySupernode.size() ||
                        model.activeIdBySupernode[sourceSupernode] == kInvalidIndex)
                    {
                        continue;
                    }
                    const uint32_t sourceActiveId =
                        static_cast<uint32_t>(model.activeIdBySupernode[sourceSupernode]);
                    const std::size_t oldSize = frontier.size();
                    frontier.erase(std::remove(frontier.begin(), frontier.end(), sourceActiveId), frontier.end());
                    model.directStateReadRemovedSourceHeadCount += oldSize - frontier.size();
                }
            }

            for (auto &[stateSymbol, consumers] : directConsumerActiveIdsByState)
            {
                sortUniqueVector(consumers);
                model.directStateReadConsumerHeadCount += consumers.size();
                auto &frontier = model.stateHeadSupernodesBySymbol[stateSymbol];
                frontier.insert(frontier.end(), consumers.begin(), consumers.end());
                sortUniqueVector(frontier);
            }

            std::fprintf(stderr,
                         "[GRHSIM_DIRECT_STATE_READ] enabled=1 reads=%zu canonical=%zu aliases=%zu groups=%zu source_groups=%zu removed_source_heads=%zu consumer_heads=%zu\n",
                         model.directStateReadCount,
                         model.directStateReadCanonicalCount,
                         model.directStateReadAliasCount,
                         model.directStateReadGroupCount,
                         model.directStateReadSourceGroupCount,
                         model.directStateReadRemovedSourceHeadCount,
                         model.directStateReadConsumerHeadCount);
        }

        bool buildModel(const Graph &graph,
                        const ScheduleRefs &schedule,
                        const std::vector<ScheduleBatch> &scheduleBatches,
                        const std::unordered_set<ValueId, ValueIdHash> &waveformValueIds,
                        EmitModel &model,
                        std::string &error)
        {
            (void)scheduleBatches;
            model.stateBySymbol.clear();
            model.stateOrder.clear();
            model.stateFieldDecls.clear();
            model.regToMemIntentStorageByGroup.clear();
            model.regToMemIntentSliceGroupByOp.clear();
            model.regToMemIntentConcatGroupByOp.clear();
            model.regToMemIntentReadGroupByOp.clear();
            model.regToMemIntentBypassOps.clear();
            model.stateHeadSupernodesBySymbol.clear();
            model.memoryRowReaderActivationBySymbol.clear();
            model.memoryRowReaderActivations.clear();
            model.stateLogicScalarSlotCounts = {};
            model.stateLogicWideSlotCountsByWords.clear();
            model.packedArrayLaneViewByValue.clear();
            model.packedArrayLaneTargetBySourceValue.clear();
            model.packedArrayLaneFieldByValue.clear();
            model.localPackedArrayLaneNameByValue.clear();
            model.boundaryFanoutByValue.clear();
            model.inputHeadSupernodesByValue.clear();
            model.commitInputValues.clear();
            model.localValueNameByValue.clear();
            model.materializedValues.clear();
            model.materializedValueAliasByValue.clear();
            model.directStateReadSymbolByValue.clear();
            model.sameSupernodeStateReadSlotAliasCount = 0;
            model.sameSupernodeStateReadSlotAliasGroupCount = 0;
            model.eventEdgeFieldByValue.clear();
            model.allEventValues.clear();
            model.inputEventValues.clear();
            std::size_t stateLogicStorageOffset = 0;
            auto registerInputEndpoint = [&](ValueId valueId, const std::string &fieldStem, const std::string &apiStem) {
                if (model.inputFieldByValue.find(valueId) != model.inputFieldByValue.end())
                {
                    return;
                }
                const std::string typeName = cppTypeForValue(graph, valueId);
                model.inputFieldByValue.emplace(valueId, apiStem);
                model.prevInputFieldByValue.emplace(valueId, "prev_" + fieldStem);
                model.inputFieldDecls.push_back("    " + typeName + " prev_" + fieldStem + " = " + defaultInitExpr(graph, valueId) + ";");
                model.publicPortDecls.push_back("    " + typeName + " " + apiStem + " = " + defaultInitExpr(graph, valueId) + ";");
            };

            auto registerReadableEndpoint =
                [&](ValueId valueId, const std::string &fieldStem, const std::string &apiStem, bool initializeField) {
                    const std::string typeName = cppTypeForValue(graph, valueId);
                    const std::string initExpr = initializeField ? defaultInitExpr(graph, valueId) : typeName + "{}";
                    (void)fieldStem;
                    model.publicPortDecls.push_back("    " + typeName + " " + apiStem + " = " + initExpr + ";");
                };

            for (const auto &port : graph.inputPorts())
            {
                const std::string name = sanitizeIdentifier(port.name);
                registerInputEndpoint(port.value, "in_" + name, name);
            }

            for (const auto &port : graph.outputPorts())
            {
                const std::string name = sanitizeIdentifier(port.name);
                registerReadableEndpoint(port.value, "out_" + name, name, true);
            }

            for (const auto &port : graph.inoutPorts())
            {
                const std::string name = sanitizeIdentifier(port.name);
                const std::string inType = cppTypeForValue(graph, port.in);
                const std::string outType = cppTypeForValue(graph, port.out);
                const std::string oeType = cppTypeForValue(graph, port.oe);
                model.inputFieldByValue.emplace(port.in, name + ".in");
                model.prevInputFieldByValue.emplace(port.in, "prev_inout_" + name + "_in");
                model.inputFieldDecls.push_back("    " + inType + " prev_inout_" + name + "_in = " + defaultInitExpr(graph, port.in) + ";");
                model.publicPortDecls.push_back("    struct Inout_" + name + " {\n"
                                                "        " + inType + " in = " + defaultInitExpr(graph, port.in) + ";\n"
                                                "        " + outType + " out = " + defaultInitExpr(graph, port.out) + ";\n"
                                                "        " + oeType + " oe = " + defaultInitExpr(graph, port.oe) + ";\n"
                                                "    } " + name + ";");
            }

            for (OperationId opId : graph.operations())
            {
                const Operation op = graph.getOperation(opId);
                switch (op.kind())
                {
                case OperationKind::kRegister:
                case OperationKind::kLatch:
                case OperationKind::kMemory:
                {
                    auto width = getAttribute<int64_t>(op, "width");
                    auto isSigned = getAttribute<bool>(op, "isSigned");
                    if (!width || !isSigned)
                    {
                        error = "storage declaration missing width/isSigned: " + std::string(op.symbolText());
                        return false;
                    }
                    StateDecl state;
                    state.kind = op.kind() == OperationKind::kRegister
                                     ? StateDecl::Kind::Register
                                     : (op.kind() == OperationKind::kLatch ? StateDecl::Kind::Latch : StateDecl::Kind::Memory);
                    state.symbol = std::string(op.symbolText());
                    state.width = static_cast<int32_t>(*width);
                    state.isSigned = *isSigned;
                    if (state.kind == StateDecl::Kind::Memory)
                    {
                        state.fieldName = stateStorageFieldName(state.kind, state.symbol, opId.index);
                        auto row = getAttribute<int64_t>(op, "row");
                        if (!row || *row <= 0)
                        {
                            error = "memory declaration missing row: " + state.symbol;
                            return false;
                        }
                        state.rowCount = *row;
                        const std::string elemType = logicCppType(state.width);
                        state.cppType = fixedArrayType(elemType, static_cast<std::size_t>(state.rowCount));
                        if (isWideLogicWidth(state.width))
                        {
                            state.wordCount = logicWordCount(state.width);
                        }
                        else
                        {
                            state.scalarKind = valueScalarSlotKindForWidth(state.width);
                        }
                        if (!buildMemoryInitRowExprs(op, state.width, state.rowCount, state.memoryInitRowExprs, error))
                        {
                            return false;
                        }
                    }
                    else
                    {
                        if (state.width <= 0)
                        {
                            error = "storage width must be positive: " + state.symbol;
                            return false;
                        }
                        if (state.kind == StateDecl::Kind::Register)
                        {
                            const auto intentGroup = getAttribute<std::string>(op, "regToMem.intent.group");
                            const auto intentMode = getAttribute<std::string>(op, "regToMem.intent.mode");
                            const auto intentRow = getAttribute<int64_t>(op, "regToMem.intent.row");
                            const auto intentElementWidth =
                                getAttribute<int64_t>(op, "regToMem.intent.elementWidth");
                            const auto intentElementCount =
                                getAttribute<int64_t>(op, "regToMem.intent.elementCount");
                            if (intentGroup || intentRow || intentElementWidth || intentElementCount)
                            {
                                if (!intentGroup || !intentRow || !intentElementWidth || !intentElementCount ||
                                    intentMode.value_or(std::string()) != "array-index")
                                {
                                    error = "incomplete reg-to-mem intent attrs on register: " + state.symbol;
                                    return false;
                                }
                                if (*intentElementWidth != state.width)
                                {
                                    error = "reg-to-mem intent width mismatch on register: " + state.symbol;
                                    return false;
                                }
                                if (*intentElementCount <= 0 || *intentRow < 0 || *intentRow >= *intentElementCount)
                                {
                                    error = "reg-to-mem intent row out of range on register: " + state.symbol;
                                    return false;
                                }

                                state.regToMemIntentStorage = true;
                                state.regToMemIntentGroup = *intentGroup;
                                state.regToMemIntentRow = static_cast<std::size_t>(*intentRow);
                                state.regToMemIntentElementCount =
                                    static_cast<std::size_t>(*intentElementCount);
                                state.regToMemIntentFieldName =
                                    regToMemIntentStorageFieldName(*intentGroup);
                                state.cppType = logicCppType(state.width);
                                if (isWideLogicWidth(state.width))
                                {
                                    state.wordCount = logicWordCount(state.width);
                                }
                                else
                                {
                                    state.scalarKind = valueScalarSlotKindForWidth(state.width);
                                }

                                auto storageIt = model.regToMemIntentStorageByGroup.find(*intentGroup);
                                if (storageIt == model.regToMemIntentStorageByGroup.end())
                                {
                                    RegToMemIntentStorageDecl storage;
                                    storage.group = *intentGroup;
                                    storage.fieldName = state.regToMemIntentFieldName;
                                    storage.elementWidth = state.width;
                                    storage.isSigned = state.isSigned;
                                    storage.elementCount = state.regToMemIntentElementCount;
                                    storage.cppType =
                                        fixedArrayType(logicCppType(state.width), storage.elementCount);
                                    model.regToMemIntentStorageByGroup.emplace(*intentGroup, std::move(storage));
                                }
                                else
                                {
                                    const RegToMemIntentStorageDecl &storage = storageIt->second;
                                    if (storage.elementWidth != state.width ||
                                        storage.isSigned != state.isSigned ||
                                        storage.elementCount != state.regToMemIntentElementCount ||
                                        storage.fieldName != state.regToMemIntentFieldName)
                                    {
                                        error = "reg-to-mem intent group mismatch on register: " + state.symbol;
                                        return false;
                                    }
                                }
                            }
                        }
                        const std::string cppType =
                            isWideLogicWidth(state.width)
                                ? logicCppType(state.width)
                                : scalarLogicSlotCppType(valueScalarSlotKindForWidth(state.width));
                        if (!state.regToMemIntentStorage)
                        {
                            state.cppType = cppType;
                            if (isWideLogicWidth(state.width))
                            {
                                state.wordCount = logicWordCount(state.width);
                                model.stateLogicWideSlotCountsByWords[state.wordCount]++;
                                stateLogicStorageOffset = alignTo(stateLogicStorageOffset, alignof(std::uint64_t));
                                state.slotIndex = stateLogicStorageOffset;
                                stateLogicStorageOffset += state.wordCount * sizeof(std::uint64_t);
                            }
                            else
                            {
                                state.scalarKind = valueScalarSlotKindForWidth(state.width);
                                stateLogicStorageOffset =
                                    alignTo(stateLogicStorageOffset, valuePackedScalarSlotAlignment(state.scalarKind));
                                state.slotIndex = stateLogicStorageOffset;
                                model.stateLogicScalarSlotCounts[static_cast<std::size_t>(state.scalarKind)]++;
                                stateLogicStorageOffset += valuePackedScalarSlotByteSize(state.scalarKind);
                            }
                        }
                        if (auto initValue = getAttribute<std::string>(op, "initValue"))
                        {
                            if (*initValue == "$random")
                            {
                                state.initExpr = randomInitExprForWidth(state.width);
                            }
                            else if (auto expr = logicLiteralToCppExpr(*initValue, state.width))
                            {
                                state.initExpr = InitExprCode{.expr = *expr, .requiresRuntime = false};
                            }
                            else
                            {
                                error = "storage initValue is not statically evaluable: " + state.symbol;
                                return false;
                            }
                        }
                    }
                    if (state.kind == StateDecl::Kind::Memory)
                    {
                        model.stateFieldDecls.push_back("    " + state.cppType + " " + state.fieldName + " = " +
                                                        state.cppType + "{};");
                    }
                    model.stateOrder.push_back(state.symbol);
                    model.stateBySymbol.insert_or_assign(state.symbol, state);
                    break;
                }
                case OperationKind::kDpicImport:
                {
                    DpiImportDecl decl;
                    decl.symbol = std::string(op.symbolText());
                    decl.argsDirection = getAttribute<std::vector<std::string>>(op, "argsDirection").value_or(std::vector<std::string>{});
                    decl.argsWidth = getAttribute<std::vector<int64_t>>(op, "argsWidth").value_or(std::vector<int64_t>{});
                    decl.argsName = getAttribute<std::vector<std::string>>(op, "argsName").value_or(std::vector<std::string>{});
                    decl.argsSigned = getAttribute<std::vector<bool>>(op, "argsSigned").value_or(std::vector<bool>{});
                    decl.argsType = getAttribute<std::vector<std::string>>(op, "argsType").value_or(std::vector<std::string>{});
                    decl.hasReturn = getAttribute<bool>(op, "hasReturn").value_or(false);
                    decl.returnWidth = getAttribute<int64_t>(op, "returnWidth").value_or(64);
                    decl.returnSigned = getAttribute<bool>(op, "returnSigned").value_or(false);
                    decl.returnType = getAttribute<std::string>(op, "returnType").value_or(std::string("logic"));
                    decl.argsName.resize(decl.argsDirection.size());
                    decl.argsWidth.resize(decl.argsDirection.size(), 1);
                    decl.argsSigned.resize(decl.argsDirection.size(), false);
                    decl.argsType.resize(decl.argsDirection.size(), std::string("logic"));
                    for (std::size_t i = 0; i < decl.argsDirection.size(); ++i)
                    {
                        if (decl.argsName[i].empty())
                        {
                            decl.argsName[i] = "arg" + std::to_string(i);
                        }
                        decl.argsWidth[i] = dpiEffectiveWidth(decl.argsType[i], decl.argsWidth[i]);
                    }
                    decl.returnWidth = dpiEffectiveWidth(decl.returnType, decl.returnWidth);
                    model.dpiImportBySymbol.insert_or_assign(decl.symbol, decl);
                    model.dpiImports.push_back(decl);
                    break;
                }
                default:
                    break;
                }
            }

            std::vector<std::string> regToMemIntentGroups;
            regToMemIntentGroups.reserve(model.regToMemIntentStorageByGroup.size());
            for (const auto &[group, _] : model.regToMemIntentStorageByGroup)
            {
                (void)_;
                regToMemIntentGroups.push_back(group);
            }
            std::sort(regToMemIntentGroups.begin(), regToMemIntentGroups.end());
            for (const std::string &group : regToMemIntentGroups)
            {
                const RegToMemIntentStorageDecl &storage = model.regToMemIntentStorageByGroup.at(group);
                model.stateFieldDecls.push_back("    " + storage.cppType + " " + storage.fieldName + " = " +
                                                storage.cppType + "{};");
            }

            model.stateLogicStorageBytes = stateLogicStorageOffset;
            model.stateLogicScalarBaseOffsets = {};
            model.stateLogicWideBaseOffsetsByWords.clear();

            model.stateShadowTouchedBaseOffset = 0;
            model.stateShadowScalarBaseOffsets = {};
            model.stateShadowWideBaseOffsetsByWords.clear();
            model.stateShadowStorageBytes = 0;
            if (model.stateShadowTouchedCount != 0)
            {
                model.stateShadowStorageBytes = alignTo(model.stateShadowStorageBytes, alignof(std::uint8_t));
                model.stateShadowTouchedBaseOffset = model.stateShadowStorageBytes;
                model.stateShadowStorageBytes += model.stateShadowTouchedCount * sizeof(std::uint8_t);
            }
            for (std::size_t kindIndex = 0; kindIndex < static_cast<std::size_t>(ValueSlotScalarKind::kCount); ++kindIndex)
            {
                const auto kind = static_cast<ValueSlotScalarKind>(kindIndex);
                const std::size_t slotCount = model.stateShadowScalarSlotCounts[kindIndex];
                if (slotCount == 0)
                {
                    continue;
                }
                const std::size_t slotBytes = valueScalarSlotByteSize(kind);
                model.stateShadowStorageBytes = alignTo(model.stateShadowStorageBytes, slotBytes);
                model.stateShadowScalarBaseOffsets[kindIndex] = model.stateShadowStorageBytes;
                model.stateShadowStorageBytes += slotCount * slotBytes;
            }
            for (const auto &[wordCount, slotCount] : model.stateShadowWideSlotCountsByWords)
            {
                if (slotCount == 0)
                {
                    continue;
                }
                model.stateShadowStorageBytes = alignTo(model.stateShadowStorageBytes, alignof(std::uint64_t));
                model.stateShadowWideBaseOffsetsByWords.emplace(wordCount, model.stateShadowStorageBytes);
                model.stateShadowStorageBytes += slotCount * wordCount * sizeof(std::uint64_t);
            }

            model.memoryWriteTouchedBaseOffset = 0;
            model.memoryWriteAddrBaseOffset = 0;
            model.memoryWriteDataScalarBaseOffsets = {};
            model.memoryWriteDataWideBaseOffsetsByWords.clear();
            model.memoryWriteMaskScalarBaseOffsets = {};
            model.memoryWriteMaskWideBaseOffsetsByWords.clear();
            model.memoryWriteStorageBytes = 0;
            if (model.memoryWriteTouchedCount != 0)
            {
                model.memoryWriteStorageBytes = alignTo(model.memoryWriteStorageBytes, alignof(std::uint8_t));
                model.memoryWriteTouchedBaseOffset = model.memoryWriteStorageBytes;
                model.memoryWriteStorageBytes += model.memoryWriteTouchedCount * sizeof(std::uint8_t);
            }
            if (model.memoryWriteAddrCount != 0)
            {
                model.memoryWriteStorageBytes = alignTo(model.memoryWriteStorageBytes, alignof(std::size_t));
                model.memoryWriteAddrBaseOffset = model.memoryWriteStorageBytes;
                model.memoryWriteStorageBytes += model.memoryWriteAddrCount * sizeof(std::size_t);
            }
            for (std::size_t kindIndex = 0; kindIndex < static_cast<std::size_t>(ValueSlotScalarKind::kCount); ++kindIndex)
            {
                const auto kind = static_cast<ValueSlotScalarKind>(kindIndex);
                const std::size_t dataCount = model.memoryWriteDataScalarSlotCounts[kindIndex];
                if (dataCount != 0)
                {
                    const std::size_t slotBytes = valueScalarSlotByteSize(kind);
                    model.memoryWriteStorageBytes = alignTo(model.memoryWriteStorageBytes, slotBytes);
                    model.memoryWriteDataScalarBaseOffsets[kindIndex] = model.memoryWriteStorageBytes;
                    model.memoryWriteStorageBytes += dataCount * slotBytes;
                }
                const std::size_t maskCount = model.memoryWriteMaskScalarSlotCounts[kindIndex];
                if (maskCount != 0)
                {
                    const std::size_t slotBytes = valueScalarSlotByteSize(kind);
                    model.memoryWriteStorageBytes = alignTo(model.memoryWriteStorageBytes, slotBytes);
                    model.memoryWriteMaskScalarBaseOffsets[kindIndex] = model.memoryWriteStorageBytes;
                    model.memoryWriteStorageBytes += maskCount * slotBytes;
                }
            }
            for (const auto &[wordCount, slotCount] : model.memoryWriteDataWideSlotCountsByWords)
            {
                if (slotCount == 0)
                {
                    continue;
                }
                model.memoryWriteStorageBytes = alignTo(model.memoryWriteStorageBytes, alignof(std::uint64_t));
                model.memoryWriteDataWideBaseOffsetsByWords.emplace(wordCount, model.memoryWriteStorageBytes);
                model.memoryWriteStorageBytes += slotCount * wordCount * sizeof(std::uint64_t);
            }
            for (const auto &[wordCount, slotCount] : model.memoryWriteMaskWideSlotCountsByWords)
            {
                if (slotCount == 0)
                {
                    continue;
                }
                model.memoryWriteStorageBytes = alignTo(model.memoryWriteStorageBytes, alignof(std::uint64_t));
                model.memoryWriteMaskWideBaseOffsetsByWords.emplace(wordCount, model.memoryWriteStorageBytes);
                model.memoryWriteStorageBytes += slotCount * wordCount * sizeof(std::uint64_t);
            }

            for (OperationId opId : graph.operations())
            {
                const Operation op = graph.getOperation(opId);
                if (op.kind() == OperationKind::kSystemTask)
                {
                    model.needsSystemTaskRuntime = true;
                    if (!validateSystemTask(graph, op, error))
                    {
                        return false;
                    }
                    continue;
                }
                if (op.kind() == OperationKind::kSystemFunction)
                {
                    const std::string name = getAttribute<std::string>(op, "name").value_or(std::string());
                    if (name == "fopen" || name == "ferror")
                    {
                        model.needsSystemTaskRuntime = true;
                    }
                    continue;
                }
                if (op.kind() == OperationKind::kDpicCall)
                {
                    if (!validateDpicCall(graph, op, model, error))
                    {
                        return false;
                    }
                    continue;
                }
                if (op.kind() == OperationKind::kRegisterWritePort ||
                    op.kind() == OperationKind::kLatchWritePort ||
                    op.kind() == OperationKind::kMemoryWritePort ||
                    op.kind() == OperationKind::kMemoryFillPort)
                {
                    WriteDecl write;
                    write.opId = opId;
                    write.kind = op.kind() == OperationKind::kRegisterWritePort
                                     ? StateDecl::Kind::Register
                                     : (op.kind() == OperationKind::kLatchWritePort ? StateDecl::Kind::Latch : StateDecl::Kind::Memory);
                    write.isMemoryFill = op.kind() == OperationKind::kMemoryFillPort;
                    const char *symbolAttr = write.kind == StateDecl::Kind::Memory ? "memSymbol"
                                                                                    : (write.kind == StateDecl::Kind::Register ? "regSymbol" : "latchSymbol");
                    auto targetSymbol = getAttribute<std::string>(op, symbolAttr);
                    if (!targetSymbol)
                    {
                        error = std::string(symbolAttr) + " missing on write op: " + std::string(op.symbolText());
                        return false;
                    }
                    if (model.stateBySymbol.find(*targetSymbol) == model.stateBySymbol.end())
                    {
                        error = "write target declaration missing: " + *targetSymbol;
                        return false;
                    }
                    write.symbol = *targetSymbol;
                    const StateDecl &state = model.stateBySymbol.find(write.symbol)->second;
                    if (write.kind == StateDecl::Kind::Register)
                    {
                        if (state.kind != StateDecl::Kind::Register)
                        {
                            error = "kRegisterWritePort target is not a register: " + write.symbol;
                            return false;
                        }
                        if (!validateRegisterWritePort(graph, op, state, error))
                        {
                            return false;
                        }
                    }
                    else if (write.kind == StateDecl::Kind::Memory)
                    {
                        if (state.kind != StateDecl::Kind::Memory)
                        {
                            error = std::string(write.isMemoryFill ? "kMemoryFillPort" : "kMemoryWritePort") +
                                    " target is not a memory: " + write.symbol;
                            return false;
                        }
                        if (write.isMemoryFill)
                        {
                            if (!validateMemoryFillPort(graph, op, state, error))
                            {
                                return false;
                            }
                        }
                        else if (!validateMemoryWritePort(graph, op, state, error))
                        {
                            return false;
                        }
                        if (!write.isMemoryFill)
                        {
                            const auto operands = op.operands();
                            const ValueId addrValue = operands[1];
                            const ValueId maskValue = operands[3];
                            if (isConstLogicAllZero(graph, maskValue, state.width))
                            {
                                write.memoryMaskMode = WriteDecl::MemoryMaskMode::kConstZero;
                            }
                            else if (isConstLogicAllOnes(graph, maskValue, state.width))
                            {
                                write.memoryMaskMode = WriteDecl::MemoryMaskMode::kConstAllOnes;
                            }
                            if (state.rowCount > 0)
                            {
                                const std::uint64_t rowCount = static_cast<std::uint64_t>(state.rowCount);
                                if (isPowerOfTwoU64(rowCount))
                                {
                                    write.memoryAddrMode = WriteDecl::MemoryAddrMode::kPow2Wrap;
                                    write.memoryRowMask = static_cast<std::size_t>(rowCount - 1u);
                                }
                                else
                                {
                                    const int32_t addrWidth = graph.valueWidth(addrValue);
                                    if (addrWidth > 0 && addrWidth < 64 &&
                                        (UINT64_C(1) << static_cast<std::size_t>(addrWidth)) <= rowCount)
                                    {
                                        write.memoryAddrMode = WriteDecl::MemoryAddrMode::kInRange;
                                    }
                                }
                            }
                        }
                    }
                    if (write.kind == StateDecl::Kind::Register || write.kind == StateDecl::Kind::Latch)
                    {
                        if (isWideLogicWidth(state.width))
                        {
                            write.shadowWordCount = logicWordCount(state.width);
                        }
                        else
                        {
                            write.shadowScalarKind = valueScalarSlotKindForWidth(state.width);
                        }
                    }
                    else
                    {
                        if (isWideLogicWidth(state.width))
                        {
                            write.shadowWordCount = logicWordCount(state.width);
                        }
                        else
                        {
                            write.shadowScalarKind = valueScalarSlotKindForWidth(state.width);
                        }
                    }
                    model.writeByOp.emplace(opId, write);
                    model.writes.push_back(write);
                }
            }

            auto registerEventSamples = [&](OperationId opId, const Operation &op) {
                EventOperandInfo info = collectEventOperands(op);
                if (info.values.empty())
                {
                    return;
                }
                EventSampleDecl samples;
                samples.values = std::move(info.values);
                samples.edges = std::move(info.edges);
                for (std::size_t i = 0; i < samples.values.size(); ++i)
                {
                    const ValueId value = samples.values[i];
                    if (model.eventEdgeFieldByValue.find(value) != model.eventEdgeFieldByValue.end())
                    {
                        continue;
                    }
                    const std::size_t slotIndex = model.eventEdgeSlotCount++;
                    const std::string fieldName = "event_edge_slots_[" + std::to_string(slotIndex) + "]";
                    model.eventEdgeFieldByValue.emplace(value, fieldName);
                    model.allEventValues.push_back(value);
                    if (model.inputFieldByValue.find(value) != model.inputFieldByValue.end())
                    {
                        model.inputEventValues.push_back(value);
                    }
                }
                if (op.kind() == OperationKind::kSystemTask && systemTaskRunsOnceAfterTimedTrigger(op))
                {
                    samples.completedFieldName =
                        "done_evt_" + opDebugName(graph, opId) + "_" + std::to_string(opId.index);
                    model.eventFieldDecls.push_back("    bool " + samples.completedFieldName + " = false;");
                }
                model.eventSamplesByOp.insert_or_assign(opId, std::move(samples));
            };

            for (OperationId opId : graph.operations())
            {
                const Operation op = graph.getOperation(opId);
                switch (op.kind())
                {
                case OperationKind::kRegisterWritePort:
                case OperationKind::kLatchWritePort:
                case OperationKind::kMemoryWritePort:
                case OperationKind::kMemoryFillPort:
                case OperationKind::kSystemTask:
                case OperationKind::kDpicCall:
                    registerEventSamples(opId, op);
                    break;
                default:
                    break;
                }
            }
            model.activeIdBySupernode.assign(schedule.supernodeToOps.size(), kInvalidIndex);
            for (std::size_t topoIndex = 0; topoIndex < schedule.topoOrder.size(); ++topoIndex)
            {
                const uint32_t supernodeId = schedule.topoOrder[topoIndex];
                if (supernodeId < model.activeIdBySupernode.size())
                {
                    model.activeIdBySupernode[supernodeId] = topoIndex;
                }
            }
            model.computeSupernodeIds.clear();
            model.commitSupernodeIds.clear();
            model.supernodeHasComputePart.assign(schedule.supernodeToOps.size(), 0U);
            model.supernodeHasCommitPart.assign(schedule.supernodeToOps.size(), 0U);
            model.computeSupernodeIds.reserve(schedule.supernodeToOps.size());
            model.commitSupernodeIds.reserve(schedule.supernodeToOps.size());
            for (uint32_t supernodeId : schedule.topoOrder)
            {
                if (supernodeId >= schedule.supernodeToOps.size())
                {
                    continue;
                }
                bool hasCommitOp = false;
                bool hasComputeOp = false;
                if (schedule.supernodeKinds != nullptr &&
                    supernodeId < schedule.supernodeKinds->size())
                {
                    hasCommitOp =
                        (*schedule.supernodeKinds)[supernodeId] == ActivityScheduleSupernodeKind::Commit;
                    hasComputeOp = !hasCommitOp;
                }
                else
                {
                    for (OperationId opId : schedule.supernodeToOps[supernodeId])
                    {
                        const Operation op = graph.getOperation(opId);
                        if (isCommitPhaseOp(op))
                        {
                            hasCommitOp = true;
                        }
                        else
                        {
                            hasComputeOp = true;
                        }
                    }
                }
                model.supernodeHasComputePart[supernodeId] = hasComputeOp ? 1U : 0U;
                model.supernodeHasCommitPart[supernodeId] = hasCommitOp ? 1U : 0U;
                if (hasComputeOp && hasCommitOp)
                {
                    error = "activity-schedule produced a mixed compute/commit supernode: supernode=" +
                            std::to_string(supernodeId);
                    return false;
                }
                if (hasComputeOp)
                {
                    model.computeSupernodeIds.push_back(supernodeId);
                }
                if (hasCommitOp)
                {
                    model.commitSupernodeIds.push_back(supernodeId);
                }
            }

            for (ValueId valueId : graph.values())
            {
                if (valueId.index == 0 || valueId.index > schedule.valueFanout.size())
                {
                    continue;
                }
                const auto &succs = schedule.valueFanout[valueId.index - 1];
                if (!succs.empty())
                {
                    std::vector<uint32_t> activeIds;
                    activeIds.reserve(succs.size());
                    for (uint32_t supernodeId : succs)
                    {
                        if (isCommitSupernode(model, supernodeId))
                        {
                            continue;
                        }
                        if (supernodeId < model.activeIdBySupernode.size() &&
                            model.activeIdBySupernode[supernodeId] != kInvalidIndex)
                        {
                            activeIds.push_back(static_cast<uint32_t>(model.activeIdBySupernode[supernodeId]));
                        }
                    }
                    sortUniqueVector(activeIds);
                    if (!activeIds.empty())
                    {
                        if (model.inputFieldByValue.contains(valueId))
                        {
                            auto &inputHeads = model.inputHeadSupernodesByValue[valueId];
                            inputHeads.insert(inputHeads.end(), activeIds.begin(), activeIds.end());
                        }
                        else
                        {
                            model.boundaryFanoutByValue.emplace(valueId, std::move(activeIds));
                        }
                    }
                }
            }

            std::unordered_set<ValueId, ValueIdHash> regToMemIntentIndexValues;
            {
                constexpr uint32_t kNoSupernode = std::numeric_limits<uint32_t>::max();
                std::vector<uint32_t> opSupernode;
                if (!graph.operations().empty())
                {
                    opSupernode.assign(graph.operations().back().index + 1u, kNoSupernode);
                }
                for (uint32_t supernodeId = 0; supernodeId < schedule.supernodeToOps.size(); ++supernodeId)
                {
                    for (const OperationId opId : schedule.supernodeToOps[supernodeId])
                    {
                        if (opId.index >= opSupernode.size())
                        {
                            opSupernode.resize(opId.index + 1u, kNoSupernode);
                        }
                        opSupernode[opId.index] = supernodeId;
                    }
                }
                auto noteIntentIndexFanout = [&](ValueId valueId, uint32_t supernodeId) {
                    if (!valueId.valid() || !isComputeSupernode(model, supernodeId) ||
                        supernodeId >= model.activeIdBySupernode.size() ||
                        model.activeIdBySupernode[supernodeId] == kInvalidIndex)
                    {
                        return;
                    }
                    const auto activeId = static_cast<uint32_t>(model.activeIdBySupernode[supernodeId]);
                    if (model.inputFieldByValue.contains(valueId))
                    {
                        model.inputHeadSupernodesByValue[valueId].push_back(activeId);
                        return;
                    }
                    auto &fanout = model.boundaryFanoutByValue[valueId];
                    fanout.push_back(activeId);
                };
                for (uint32_t supernodeId = 0; supernodeId < schedule.supernodeToOps.size(); ++supernodeId)
                {
                    for (const OperationId opId : schedule.supernodeToOps[supernodeId])
                    {
                        const Operation op = graph.getOperation(opId);
                        const auto indexValue = regToMemIntentSliceIndexValue(graph, op);
                        if (!indexValue)
                        {
                            continue;
                        }
                        regToMemIntentIndexValues.insert(*indexValue);
                        const OperationId defOpId = graph.valueDef(*indexValue);
                        const uint32_t defSupernode =
                            defOpId.valid() && defOpId.index < opSupernode.size()
                                ? opSupernode[defOpId.index]
                                : kNoSupernode;
                        if (defSupernode != supernodeId)
                        {
                            noteIntentIndexFanout(*indexValue, supernodeId);
                        }
                    }
                }
                for (auto &[valueId, fanout] : model.boundaryFanoutByValue)
                {
                    (void)valueId;
                    sortUniqueVector(fanout);
                }
            }

            discoverPackedArrayLaneViews(graph, waveformValueIds, model);

            std::unordered_set<ValueId, ValueIdHash> persistentValues;
            persistentValues.reserve(graph.values().size());
            enum PersistentValueReason : uint32_t
            {
                kPersistentOutput = 1u << 0u,
                kPersistentInout = 1u << 1u,
                kPersistentWaveform = 1u << 2u,
                kPersistentEvent = 1u << 3u,
                kPersistentBoundaryFanout = 1u << 4u,
                kPersistentCommitOperand = 1u << 5u,
                kPersistentNoDef = 1u << 6u,
                kPersistentNonLogic = 1u << 7u,
                kPersistentSideEffectResult = 1u << 8u,
                kPersistentPhaseCrossing = 1u << 9u,
                kPersistentRegToMemIntentIndex = 1u << 10u,
            };
            std::unordered_map<ValueId, uint32_t, ValueIdHash> persistentReasonByValue;
            persistentReasonByValue.reserve(graph.values().size());
            std::unordered_set<OperationId, OperationIdHash> validOperationIds;
            validOperationIds.reserve(graph.operations().size());
            for (OperationId opId : graph.operations())
            {
                validOperationIds.insert(opId);
            }

            auto markPersistent = [&](ValueId valueId, uint32_t reason) {
                if (!valueId.valid() || model.inputFieldByValue.contains(valueId))
                {
                    return;
                }
                persistentValues.insert(valueId);
                persistentReasonByValue[valueId] |= reason;
            };

            for (const auto &port : graph.outputPorts())
            {
                markPersistent(port.value, kPersistentOutput);
            }
            for (const auto &port : graph.inoutPorts())
            {
                markPersistent(port.out, kPersistentInout);
                markPersistent(port.oe, kPersistentInout);
            }
            for (ValueId valueId : waveformValueIds)
            {
                markPersistent(valueId, kPersistentWaveform);
            }
            for (const auto &[valueId, _] : model.eventEdgeFieldByValue)
            {
                (void)_;
                markPersistent(valueId, kPersistentEvent);
            }
            for (const auto &[valueId, _] : model.boundaryFanoutByValue)
            {
                (void)_;
                markPersistent(valueId, kPersistentBoundaryFanout);
            }
            for (ValueId valueId : regToMemIntentIndexValues)
            {
                markPersistent(valueId, kPersistentRegToMemIntentIndex);
            }
            for (OperationId opId : graph.operations())
            {
                const Operation op = graph.getOperation(opId);
                if (!isCommitPhaseOp(op))
                {
                    continue;
                }
                for (ValueId operand : op.operands())
                {
                    markPersistent(operand, kPersistentCommitOperand);
                }
            }

            for (ValueId valueId : graph.values())
            {
                if (model.inputFieldByValue.find(valueId) != model.inputFieldByValue.end())
                {
                    continue;
                }

                const OperationId defOpId = graph.valueDef(valueId);
                if (!defOpId.valid())
                {
                    markPersistent(valueId, kPersistentNoDef);
                }
                if (graph.valueType(valueId) != ValueType::Logic)
                {
                    markPersistent(valueId, kPersistentNonLogic);
                }
                if (defOpId.valid())
                {
                    const OperationKind defKind = graph.getOperation(defOpId).kind();
                    if (defKind == OperationKind::kDpicCall || defKind == OperationKind::kSystemFunction)
                    {
                        markPersistent(valueId, kPersistentSideEffectResult);
                    }
                    const bool defCommitPhase = isCommitPhaseOp(graph.getOperation(defOpId));
                    const Value valueInfo = graph.getValue(valueId);
                    for (const auto &user : valueInfo.users())
                    {
                        const OperationId userOpId = user.operation;
                        if (!userOpId.valid() || !validOperationIds.contains(userOpId))
                        {
                            continue;
                        }
                        const bool userCommitPhase = isCommitPhaseOp(graph.getOperation(userOpId));
                        if (userCommitPhase != defCommitPhase)
                        {
                            markPersistent(valueId, kPersistentPhaseCrossing);
                            break;
                        }
                    }
                }
            }

            std::vector<ValueId> materializedValueOrder;
            materializedValueOrder.reserve(persistentValues.size());
            std::unordered_set<ValueId, ValueIdHash> queuedMaterializedValues;
            queuedMaterializedValues.reserve(persistentValues.size());

            auto queueMaterializedValue = [&](ValueId valueId) {
                if (!valueId.valid() || model.inputFieldByValue.contains(valueId) || !persistentValues.contains(valueId))
                {
                    return;
                }
                if (!queuedMaterializedValues.insert(valueId).second)
                {
                    return;
                }
                materializedValueOrder.push_back(valueId);
            };

            auto queueSupernodeValues = [&](uint32_t supernodeId) {
                if (supernodeId >= schedule.supernodeToOps.size())
                {
                    return;
                }
                for (const OperationId opId : schedule.supernodeToOps[supernodeId])
                {
                    const Operation op = graph.getOperation(opId);
                    for (const ValueId operand : op.operands())
                    {
                        queueMaterializedValue(operand);
                    }
                    for (const ValueId result : op.results())
                    {
                        queueMaterializedValue(result);
                    }
                }
            };

            for (uint32_t supernodeId : model.computeSupernodeIds)
            {
                queueSupernodeValues(supernodeId);
            }
            for (uint32_t supernodeId : model.commitSupernodeIds)
            {
                queueSupernodeValues(supernodeId);
            }

            for (ValueId valueId : graph.values())
            {
                if (model.inputFieldByValue.find(valueId) != model.inputFieldByValue.end())
                {
                    continue;
                }
                if (!persistentValues.contains(valueId))
                {
                    if (isPackedArrayLaneValue(model, valueId))
                    {
                        model.localPackedArrayLaneNameByValue.emplace(
                            valueId,
                            "packed_array_lanes_local_" + std::to_string(valueId.index) + "_" +
                                std::to_string(valueId.generation));
                    }
                    else
                    {
                        model.localValueNameByValue.emplace(valueId, localValueName(graph, valueId));
                    }
                    continue;
                }
                queueMaterializedValue(valueId);
            }

            for (ValueId valueId : materializedValueOrder)
            {
                model.materializedValues.insert(valueId);
            }
            collectRegToMemIntentBypassOps(graph, model);
            buildSameSupernodeStateReadSlotAliases(graph, schedule, waveformValueIds, model);
            if (emitMaterializedValueStatsEnabled())
            {
                std::map<std::string, std::size_t> reasonCounts;
                std::map<std::string, std::size_t> sourceKindCounts;
                std::size_t materializedBoundaryValues = 0;
                std::size_t materializedBoundaryEdges = 0;
                std::size_t materializedTrackedChangeValues = 0;
                std::size_t localValueCount = 0;
                std::size_t localScalarLogicValues = 0;
                std::size_t localWideLogicValues = 0;
                for (ValueId valueId : graph.values())
                {
                    if (model.inputFieldByValue.contains(valueId))
                    {
                        continue;
                    }
                    if (!persistentValues.contains(valueId))
                    {
                        ++localValueCount;
                        if (graph.valueType(valueId) == ValueType::Logic)
                        {
                            if (isWideLogicValue(graph, valueId))
                            {
                                ++localWideLogicValues;
                            }
                            else
                            {
                                ++localScalarLogicValues;
                            }
                        }
                        continue;
                    }
                    const uint32_t reasons = persistentReasonByValue[valueId];
                    ++reasonCounts[persistentReasonSummary(reasons)];
                    const OperationId defOpId = graph.valueDef(valueId);
                    const std::string sourceKind =
                        defOpId.valid() ? std::string(toString(graph.opKind(defOpId))) : std::string("<no_def>");
                    ++sourceKindCounts[sourceKind];
                    if ((reasons & kPersistentBoundaryFanout) != 0)
                    {
                        ++materializedBoundaryValues;
                        if (const auto it = model.boundaryFanoutByValue.find(valueId);
                            it != model.boundaryFanoutByValue.end())
                        {
                            materializedBoundaryEdges += it->second.size();
                        }
                    }
                    if (valueNeedsTrackedChange(model, valueId))
                    {
                        ++materializedTrackedChangeValues;
                    }
                }
                auto emitTopCounts = [](const char *label, const std::map<std::string, std::size_t> &counts) {
                    std::vector<std::pair<std::string, std::size_t>> ordered(counts.begin(), counts.end());
                    std::sort(ordered.begin(),
                              ordered.end(),
                              [](const auto &lhs, const auto &rhs)
                              {
                                  if (lhs.second != rhs.second)
                                  {
                                      return lhs.second > rhs.second;
                                  }
                                  return lhs.first < rhs.first;
                              });
                    const std::size_t limit = std::min<std::size_t>(ordered.size(), 16);
                    for (std::size_t i = 0; i < limit; ++i)
                    {
                        std::fprintf(stderr,
                                     "[GRHSIM_MATERIALIZED_VALUE_STATS] %s[%zu]=%s:%zu\n",
                                     label,
                                     i,
                                     ordered[i].first.c_str(),
                                     ordered[i].second);
                    }
                };
                std::fprintf(stderr,
                             "[GRHSIM_MATERIALIZED_VALUE_STATS] graph_values=%zu inputs=%zu materialized=%zu persistent=%zu local=%zu local_scalar_logic=%zu local_wide_logic=%zu boundary_values=%zu boundary_edges=%zu tracked_change=%zu\n",
                             graph.values().size(),
                             model.inputFieldByValue.size(),
                             materializedValueOrder.size(),
                             persistentValues.size(),
                             localValueCount,
                             localScalarLogicValues,
                             localWideLogicValues,
                             materializedBoundaryValues,
                             materializedBoundaryEdges,
                             materializedTrackedChangeValues);
                std::fprintf(stderr,
                             "[GRHSIM_MATERIALIZED_VALUE_STATS] same_supernode_state_read_slot_aliases=%zu groups=%zu\n",
                             model.sameSupernodeStateReadSlotAliasCount,
                             model.sameSupernodeStateReadSlotAliasGroupCount);
                emitTopCounts("reason", reasonCounts);
                emitTopCounts("source_kind", sourceKindCounts);
            }
            rebuildMaterializedValueStorage(graph, materializedValueOrder, model);

            for (const auto &[stateSymbol, supernodes] : schedule.stateReadSupernodes)
            {
                auto &dst = model.stateHeadSupernodesBySymbol[stateSymbol];
                for (uint32_t supernodeId : supernodes)
                {
                    if (!isComputeSupernode(model, supernodeId))
                    {
                        continue;
                    }
                    if (supernodeId < model.activeIdBySupernode.size() &&
                        model.activeIdBySupernode[supernodeId] != kInvalidIndex)
                    {
                        dst.push_back(static_cast<uint32_t>(model.activeIdBySupernode[supernodeId]));
                    }
                }
            }

            for (uint32_t supernodeId = 0; supernodeId < schedule.supernodeToOps.size(); ++supernodeId)
            {
                for (const auto opId : schedule.supernodeToOps[supernodeId])
                {
                    if (isCommitSupernode(model, supernodeId))
                    {
                        const Operation op = graph.getOperation(opId);
                        for (const ValueId operand : op.operands())
                        {
                            if (model.inputFieldByValue.find(operand) != model.inputFieldByValue.end())
                            {
                                model.commitInputValues.push_back(operand);
                            }
                        }
                        continue;
                    }
                    if (!isComputeSupernode(model, supernodeId))
                    {
                        continue;
                    }
                    const Operation op = graph.getOperation(opId);
                    for (const ValueId operand : op.operands())
                    {
                        if (model.inputFieldByValue.find(operand) != model.inputFieldByValue.end())
                        {
                            if (supernodeId < model.activeIdBySupernode.size() &&
                                model.activeIdBySupernode[supernodeId] != kInvalidIndex)
                            {
                                model.inputHeadSupernodesByValue[operand].push_back(
                                    static_cast<uint32_t>(model.activeIdBySupernode[supernodeId]));
                            }
                        }
                    }
                }
            }

            for (auto &[value, supernodes] : model.inputHeadSupernodesByValue)
            {
                (void)value;
                sortUniqueVector(supernodes);
            }
            for (auto &[symbol, supernodes] : model.stateHeadSupernodesBySymbol)
            {
                (void)symbol;
                sortUniqueVector(supernodes);
            }
            buildDirectSingleWriterStateReads(graph, schedule, waveformValueIds, model);

            struct MemoryReaderActivationCandidate
            {
                std::unordered_map<std::size_t, std::vector<uint32_t>> constantActiveIdsByRow;
                std::vector<uint32_t> dynamicActiveIds;
                std::vector<uint32_t> representedActiveIds;
            };
            std::unordered_map<std::string, MemoryReaderActivationCandidate> activationCandidates;
            for (uint32_t supernodeId = 0; supernodeId < schedule.supernodeToOps.size(); ++supernodeId)
            {
                if (!isComputeSupernode(model, supernodeId) ||
                    supernodeId >= model.activeIdBySupernode.size() ||
                    model.activeIdBySupernode[supernodeId] == kInvalidIndex)
                {
                    continue;
                }
                const uint32_t activeId = static_cast<uint32_t>(model.activeIdBySupernode[supernodeId]);
                for (OperationId opId : schedule.supernodeToOps[supernodeId])
                {
                    const Operation op = graph.getOperation(opId);
                    if (op.kind() != OperationKind::kMemoryReadPort || op.operands().empty())
                    {
                        continue;
                    }
                    const auto memSymbol = getAttribute<std::string>(op, "memSymbol");
                    if (!memSymbol)
                    {
                        continue;
                    }
                    const auto stateIt = model.stateBySymbol.find(*memSymbol);
                    if (stateIt == model.stateBySymbol.end() ||
                        stateIt->second.kind != StateDecl::Kind::Memory ||
                        stateIt->second.rowCount <= 0)
                    {
                        continue;
                    }

                    auto &candidate = activationCandidates[*memSymbol];
                    candidate.representedActiveIds.push_back(activeId);
                    const ValueId addrValue = op.operands().front();
                    const int32_t addrWidth = graph.valueWidth(addrValue);
                    const auto constAddr = constLogicValue(graph, addrValue, addrWidth);
                    if (!constAddr)
                    {
                        candidate.dynamicActiveIds.push_back(activeId);
                        continue;
                    }

                    const std::size_t rowCount = static_cast<std::size_t>(stateIt->second.rowCount);
                    const std::uint64_t *rawWords = constAddr->getRawPtr();
                    const std::size_t wordCount = logicWordCount(addrWidth);
                    const std::uint64_t lowWord = wordCount == 0 ? UINT64_C(0) : rawWords[0];
                    std::optional<std::size_t> row;
                    if (isPowerOfTwoU64(static_cast<std::uint64_t>(rowCount)))
                    {
                        row = static_cast<std::size_t>(lowWord & static_cast<std::uint64_t>(rowCount - 1u));
                    }
                    else
                    {
                        bool highWordsZero = true;
                        for (std::size_t word = 1; word < wordCount; ++word)
                        {
                            if (rawWords[word] != UINT64_C(0))
                            {
                                highWordsZero = false;
                                break;
                            }
                        }
                        if (highWordsZero && lowWord < static_cast<std::uint64_t>(rowCount))
                        {
                            row = static_cast<std::size_t>(lowWord);
                        }
                    }
                    if (row)
                    {
                        candidate.constantActiveIdsByRow[*row].push_back(activeId);
                    }
                }
            }

            for (const std::string &symbol : model.stateOrder)
            {
                const auto candidateIt = activationCandidates.find(symbol);
                if (candidateIt == activationCandidates.end())
                {
                    continue;
                }
                const StateDecl &state = model.stateBySymbol.at(symbol);
                const std::size_t rowCount = static_cast<std::size_t>(state.rowCount);
                auto &candidate = candidateIt->second;
                sortUniqueVector(candidate.dynamicActiveIds);
                sortUniqueVector(candidate.representedActiveIds);

                const auto fullReadersIt = model.stateHeadSupernodesBySymbol.find(symbol);
                if (fullReadersIt == model.stateHeadSupernodesBySymbol.end() ||
                    candidate.representedActiveIds != fullReadersIt->second ||
                    candidate.constantActiveIdsByRow.size() < kMemoryRowReaderActivationMinRows ||
                    candidate.constantActiveIdsByRow.size() * 2u < rowCount)
                {
                    continue;
                }

                std::vector<std::size_t> rowEntryOffsets;
                rowEntryOffsets.reserve(rowCount + 1u);
                std::vector<ActiveMaskEntry> rowEntries;
                std::vector<uint32_t> distinctConstantActiveIds;
                for (std::size_t row = 0; row < rowCount; ++row)
                {
                    rowEntryOffsets.push_back(rowEntries.size());
                    const auto rowIt = candidate.constantActiveIdsByRow.find(row);
                    if (rowIt == candidate.constantActiveIdsByRow.end())
                    {
                        continue;
                    }
                    auto &activeIds = rowIt->second;
                    sortUniqueVector(activeIds);
                    activeIds.erase(
                        std::remove_if(activeIds.begin(),
                                       activeIds.end(),
                                       [&](uint32_t activeId)
                                       {
                                           return std::binary_search(candidate.dynamicActiveIds.begin(),
                                                                     candidate.dynamicActiveIds.end(),
                                                                     activeId);
                                       }),
                        activeIds.end());
                    distinctConstantActiveIds.insert(
                        distinctConstantActiveIds.end(), activeIds.begin(), activeIds.end());
                    const auto entries = buildActiveMaskEntries(activeIds);
                    rowEntries.insert(rowEntries.end(), entries.begin(), entries.end());
                }
                rowEntryOffsets.push_back(rowEntries.size());
                sortUniqueVector(distinctConstantActiveIds);
                if (distinctConstantActiveIds.size() < 2)
                {
                    continue;
                }

                const std::size_t activationIndex = model.memoryRowReaderActivations.size();
                model.memoryRowReaderActivationBySymbol.emplace(symbol, activationIndex);
                model.memoryRowReaderActivations.push_back(MemoryRowReaderActivationDecl{
                    .symbol = symbol,
                    .methodName = "activate_memory_row_readers_" + std::to_string(activationIndex),
                    .rowEntryOffsets = std::move(rowEntryOffsets),
                    .rowEntries = std::move(rowEntries),
                    .dynamicReaderActiveIds = std::move(candidate.dynamicActiveIds),
                });
            }
            sortUniqueValueIds(model.commitInputValues);

            for (const auto &decl : model.dpiImports)
            {
                std::vector<std::string> args;
                const std::size_t argCount = decl.argsDirection.size();
                for (std::size_t i = 0; i < argCount; ++i)
                {
                    const std::string argType =
                        dpiDeclArgCppType(i < decl.argsType.size() ? std::string_view(decl.argsType[i]) : std::string_view("logic"),
                                          i < decl.argsWidth.size() ? decl.argsWidth[i] : 64,
                                          i < decl.argsSigned.size() ? decl.argsSigned[i] : false,
                                          decl.argsDirection[i]);
                    const std::string &direction = decl.argsDirection[i];
                    (void)direction;
                    args.push_back(argType + " " + sanitizeIdentifier(i < decl.argsName.size() ? decl.argsName[i] : ("arg" + std::to_string(i))));
                }
                const std::string returnType =
                    decl.hasReturn ? dpiBaseCppType(decl.returnType, decl.returnWidth, decl.returnSigned) : "void";
                model.dpiDecls.push_back("extern \"C\" " + returnType + " " + sanitizeIdentifier(decl.symbol) + "(" +
                                         joinStrings(args, ", ") + ");");
            }
            return true;
        }

        std::string valueRef(const EmitModel &model, ValueId value)
        {
            if (auto it = model.inputFieldByValue.find(value); it != model.inputFieldByValue.end())
            {
                return it->second;
            }
            if (auto it = model.staticConstStringFieldByValue.find(value);
                it != model.staticConstStringFieldByValue.end())
            {
                return it->second;
            }
            if (auto it = model.valueFieldByValue.find(value); it != model.valueFieldByValue.end())
            {
                return it->second;
            }
            if (auto it = model.packedArrayLaneFieldByValue.find(value);
                it != model.packedArrayLaneFieldByValue.end())
            {
                return it->second;
            }
            if (auto it = model.localValueNameByValue.find(value); it != model.localValueNameByValue.end())
            {
                return it->second;
            }
            if (auto it = model.localPackedArrayLaneNameByValue.find(value);
                it != model.localPackedArrayLaneNameByValue.end())
            {
                return it->second;
            }
            return "/*missing_value_ref*/";
        }

        const SupernodeLocalExpr *findSupernodeLocalExpr(const SupernodeLocalExprContext *context,
                                                         ValueId value) noexcept
        {
            if (context == nullptr)
            {
                return nullptr;
            }
            const auto it = context->byValue.find(value);
            if (it == context->byValue.end())
            {
                return nullptr;
            }
            return &it->second;
        }

        std::string resolvedScheduleValueExpr(const EmitModel &model,
                                              ValueId value,
                                              const SupernodeLocalExprContext *context = nullptr)
        {
            if (const auto directIt = model.directStateReadSymbolByValue.find(value);
                directIt != model.directStateReadSymbolByValue.end())
            {
                if (const auto stateIt = model.stateBySymbol.find(directIt->second);
                    stateIt != model.stateBySymbol.end())
                {
                    return resolvedStateRefExpr(stateIt->second, context);
                }
            }
            if (context != nullptr)
            {
                const auto storedIt = context->storedValueRefByValue.find(value);
                if (storedIt != context->storedValueRefByValue.end())
                {
                    return storedIt->second;
                }
                const ValueId canonicalValue = canonicalMaterializedStorageValue(model, value);
                const auto canonicalStoredIt = context->storedValueRefByValue.find(canonicalValue);
                if (canonicalStoredIt != context->storedValueRefByValue.end())
                {
                    return canonicalStoredIt->second;
                }
            }
            if (const auto *expr = findSupernodeLocalExpr(context, value); expr != nullptr)
            {
                return "(" + expr->expr + ")";
            }
            return valueRef(model, value);
        }

        std::string resolvedStoredValueRefExpr(const EmitModel &model,
                                               ValueId value,
                                               const SupernodeLocalExprContext *context = nullptr)
        {
            if (context != nullptr)
            {
                const auto it = context->storedValueRefByValue.find(value);
                if (it != context->storedValueRefByValue.end())
                {
                    return it->second;
                }
                const ValueId canonicalValue = canonicalMaterializedStorageValue(model, value);
                const auto canonicalIt = context->storedValueRefByValue.find(canonicalValue);
                if (canonicalIt != context->storedValueRefByValue.end())
                {
                    return canonicalIt->second;
                }
            }
            return valueRef(model, value);
        }

        std::optional<std::string> pureExprForValue(
            const Graph &graph,
            const EmitModel &model,
            ValueId value,
            std::unordered_map<ValueId, std::optional<std::string>, ValueIdHash> &cache,
            std::unordered_map<ValueId, std::size_t, ValueIdHash> &costCache,
            std::size_t &totalOps,
            std::size_t opBudget);

        std::string resolvedRegToMemIntentIndexExpr(const Graph &graph,
                                                    const EmitModel &model,
                                                    ValueId value,
                                                    const SupernodeLocalExprContext *context = nullptr)
        {
            if (context != nullptr)
            {
                const auto storedIt = context->storedValueRefByValue.find(value);
                if (storedIt != context->storedValueRefByValue.end())
                {
                    return storedIt->second;
                }
            }
            if (const auto *expr = findSupernodeLocalExpr(context, value); expr != nullptr)
            {
                return "(" + expr->expr + ")";
            }
            if (auto inputIt = model.inputFieldByValue.find(value); inputIt != model.inputFieldByValue.end())
            {
                return inputIt->second;
            }

            const OperationId defOpId = graph.valueDef(value);
            if (defOpId.valid())
            {
                const Operation defOp = graph.getOperation(defOpId);
                if (defOp.kind() == OperationKind::kConstant)
                {
                    if (auto expr = constantExpr(graph, defOp, value))
                    {
                        return *expr;
                    }
                }
                if (defOp.kind() == OperationKind::kRegisterReadPort ||
                    defOp.kind() == OperationKind::kLatchReadPort)
                {
                    const char *symbolAttr =
                        defOp.kind() == OperationKind::kRegisterReadPort ? "regSymbol" : "latchSymbol";
                    if (auto symbol = getAttribute<std::string>(defOp, symbolAttr))
                    {
                        if (auto stateIt = model.stateBySymbol.find(*symbol); stateIt != model.stateBySymbol.end())
                        {
                            return resolvedStateRefExpr(stateIt->second, context);
                        }
                    }
                }
            }

            std::unordered_map<ValueId, std::optional<std::string>, ValueIdHash> exprCache;
            std::unordered_map<ValueId, std::size_t, ValueIdHash> costCache;
            std::size_t totalOps = 0;
            if (auto pureExpr = pureExprForValue(
                    graph,
                    model,
                    value,
                    exprCache,
                    costCache,
                    totalOps,
                    kRegToMemIntentIndexInlineOpLimit))
            {
                return *pureExpr;
            }

            return resolvedScheduleValueExpr(model, value, context);
        }

        bool isCheapScalarInlineExpr(std::string_view expr) noexcept
        {
            if (expr.size() > 1024)
            {
                return false;
            }
            constexpr std::array<std::string_view, 8> expensivePatterns = {
                "_words(",
                "grhsim_udiv_",
                "grhsim_umod_",
                "grhsim_sdiv_",
                "grhsim_smod_",
                "grhsim_compare_signed_",
                "grhsim_clog2_",
                "grhsim_concat_loop_",
            };
            for (const std::string_view pattern : expensivePatterns)
            {
                if (expr.find(pattern) != std::string_view::npos)
                {
                    return false;
                }
            }
            return true;
        }

        bool canInlineSingleUserLocalValue(const Graph &graph,
                                           const EmitModel &model,
                                           ValueId value,
                                           std::string_view expr,
                                           SupernodeLocalExprKind kind,
                                           const SupernodeLocalExprContext *context = nullptr)
        {
            if (isMaterializedValue(model, value))
            {
                return false;
            }
            std::size_t useCount = graph.getValue(value).users().size();
            if (context != nullptr)
            {
                if (auto it = context->useCountByValue.find(value); it != context->useCountByValue.end())
                {
                    useCount = it->second;
                }
            }
            if (useCount != 1)
            {
                return false;
            }
            if (kind != SupernodeLocalExprKind::kScalarInline)
            {
                return false;
            }
            return isCheapScalarInlineExpr(expr);
        }

        std::string valueDebugText(const Graph &graph, const EmitModel &model, ValueId value)
        {
            const Value info = graph.getValue(value);
            std::ostringstream out;
            out << "value ";
            if (!info.symbolText().empty())
            {
                out << sanitizeCommentText(info.symbolText());
            }
            else
            {
                out << "<unnamed>";
            }
            out << " -> " << valueRef(model, value);
            out << " [value_id=" << value.index << ":" << value.generation << "]";
            return out.str();
        }

        void emitValueAssignmentComment(std::ostream &stream,
                                        const Graph &graph,
                                        const EmitModel &model,
                                        ValueId value,
                                        std::string_view indent)
        {
            if (!isMaterializedValue(model, value))
            {
                return;
            }
            stream << indent << "// " << valueDebugText(graph, model, value) << "\n";
        }

        std::string formatSrcLocText(const std::optional<wolvrix::lib::grh::SrcLoc> &srcLoc)
        {
            if (!srcLoc)
            {
                return "<none>";
            }

            std::ostringstream out;
            if (!srcLoc->file.empty())
            {
                out << srcLoc->file;
            }
            else
            {
                out << "<unknown-file>";
            }
            if (srcLoc->line != 0)
            {
                out << ":" << srcLoc->line;
                if (srcLoc->column != 0)
                {
                    out << ":" << srcLoc->column;
                }
            }
            if (!srcLoc->origin.empty())
            {
                out << " origin=" << srcLoc->origin;
            }
            if (!srcLoc->pass.empty())
            {
                out << " pass=" << srcLoc->pass;
            }
            if (!srcLoc->note.empty())
            {
                out << " note=" << sanitizeCommentText(srcLoc->note);
            }
            return out.str();
        }

        std::string formatValueIdText(ValueId value)
        {
            std::ostringstream out;
            out << value.index << ":" << value.generation;
            return out.str();
        }

        std::string formatOperationIdText(OperationId op)
        {
            std::ostringstream out;
            out << op.index << ":" << op.generation;
            return out.str();
        }

        std::string valueSymbolOrUnnamed(const Graph &graph, ValueId value)
        {
            const std::string_view symbol = graph.symbolText(graph.valueSymbol(value));
            if (!symbol.empty())
            {
                return std::string(symbol);
            }
            return "<unnamed>";
        }

        std::string opSymbolOrUnnamed(const Graph &graph, OperationId opId)
        {
            const Operation op = graph.getOperation(opId);
            if (!op.symbolText().empty())
            {
                return std::string(op.symbolText());
            }
            return "<unnamed-op>";
        }

        bool isReadRootOpKind(OperationKind kind) noexcept
        {
            return kind == OperationKind::kRegisterReadPort ||
                   kind == OperationKind::kLatchReadPort ||
                   kind == OperationKind::kMemoryReadPort;
        }

        std::string readRootText(const Graph &graph, const Operation &op)
        {
            std::ostringstream out;
            switch (op.kind())
            {
            case OperationKind::kRegisterReadPort:
                out << "read.register";
                if (auto regSymbol = getAttribute<std::string>(op, "regSymbol"))
                {
                    out << " state=" << *regSymbol;
                }
                break;
            case OperationKind::kLatchReadPort:
                out << "read.latch";
                if (auto latchSymbol = getAttribute<std::string>(op, "latchSymbol"))
                {
                    out << " state=" << *latchSymbol;
                }
                break;
            case OperationKind::kMemoryReadPort:
                out << "read.memory";
                if (auto memSymbol = getAttribute<std::string>(op, "memSymbol"))
                {
                    out << " state=" << *memSymbol;
                }
                break;
            default:
                out << "op kind=" << toString(op.kind());
                break;
            }
            out << " op=" << opSymbolOrUnnamed(graph, op.id());
            out << " op_id=" << formatOperationIdText(op.id());
            return out.str();
        }

        std::string dependencyOperandText(const Graph &graph, const EmitModel &model, ValueId operand)
        {
            std::ostringstream out;
            out << valueSymbolOrUnnamed(graph, operand);
            out << " value_id=" << formatValueIdText(operand);
            if (model.inputFieldByValue.contains(operand))
            {
                out << " kind=input";
                return out.str();
            }

            const OperationId defOpId = graph.valueDef(operand);
            if (!defOpId.valid())
            {
                out << " kind=nodef";
                return out.str();
            }

            const Operation defOp = graph.getOperation(defOpId);
            if (isReadRootOpKind(defOp.kind()))
            {
                out << " kind=" << readRootText(graph, defOp);
                return out.str();
            }

            out << " kind=internal";
            out << " def_kind=" << toString(defOp.kind());
            out << " def_op=" << opSymbolOrUnnamed(graph, defOpId);
            out << " def_op_id=" << formatOperationIdText(defOpId);
            return out.str();
        }

        using DependencyRootCache = std::unordered_map<ValueId, std::vector<std::string>, ValueIdHash>;

        std::vector<std::string> collectCombinationalRootsForValue(const Graph &graph,
                                                                   const EmitModel &model,
                                                                   ValueId value,
                                                                   DependencyRootCache &cache,
                                                                   std::unordered_set<ValueId, ValueIdHash> &visiting)
        {
            if (const auto it = cache.find(value); it != cache.end())
            {
                return it->second;
            }

            std::vector<std::string> roots;
            if (!visiting.insert(value).second)
            {
                return roots;
            }

            if (model.inputFieldByValue.contains(value))
            {
                roots.push_back("input " + valueSymbolOrUnnamed(graph, value) + " value_id=" + formatValueIdText(value));
            }
            else
            {
                const OperationId defOpId = graph.valueDef(value);
                if (defOpId.valid())
                {
                    const Operation defOp = graph.getOperation(defOpId);
                    if (isReadRootOpKind(defOp.kind()))
                    {
                        roots.push_back(readRootText(graph, defOp));
                    }
                    else if (defOp.kind() != OperationKind::kConstant)
                    {
                        for (const ValueId operand : defOp.operands())
                        {
                            std::vector<std::string> operandRoots =
                                collectCombinationalRootsForValue(graph, model, operand, cache, visiting);
                            roots.insert(roots.end(), operandRoots.begin(), operandRoots.end());
                        }
                    }
                }
            }

            visiting.erase(value);
            sortUniqueVector(roots);
            cache.emplace(value, roots);
            return roots;
        }

        bool emitDeclaredValueIndexFile(const Graph &graph,
                                        const EmitModel &model,
                                        const ScheduleRefs &schedule,
                                        const std::vector<ScheduleBatch> &scheduleBatches,
                                        const std::vector<std::filesystem::path> &schedPaths,
                                        const std::filesystem::path &indexPath,
                                        std::string &error)
        {
            std::unordered_map<OperationId, uint32_t, OperationIdHash> supernodeByOp;
            supernodeByOp.reserve(graph.operations().size());
            for (uint32_t supernodeId = 0; supernodeId < schedule.supernodeToOps.size(); ++supernodeId)
            {
                for (OperationId opId : schedule.supernodeToOps[supernodeId])
                {
                    supernodeByOp.emplace(opId, supernodeId);
                }
            }

            std::vector<std::size_t> batchBySupernode(schedule.supernodeToOps.size(), kInvalidIndex);
            for (std::size_t batchIndex = 0; batchIndex < scheduleBatches.size(); ++batchIndex)
            {
                for (uint32_t supernodeId : scheduleBatches[batchIndex].supernodeIds)
                {
                    if (supernodeId < batchBySupernode.size())
                    {
                        batchBySupernode[supernodeId] = batchIndex;
                    }
                }
            }

            if (auto dirError = ensureOutputDirectory(indexPath))
            {
                error = *dirError;
                return false;
            }

            std::ofstream stream(indexPath, std::ios::out | std::ios::trunc);
            if (!stream.is_open())
            {
                error = "failed to open output file";
                return false;
            }

            stream << "# grhsim declared value index\n";
            stream << "# graph=" << graph.symbol() << "\n";
            stream << "# schedule_supernodes=" << schedule.supernodeToOps.size() << "\n";
            stream << "# schedule_batches=" << scheduleBatches.size() << "\n";

            std::unordered_set<std::string> seenSymbols;
            seenSymbols.reserve(graph.declaredSymbols().size());
            DependencyRootCache rootCache;
            rootCache.reserve(graph.values().size());

            std::size_t emittedValueCount = 0;
            std::size_t skippedDeclaredNonValueCount = 0;
            for (const auto sym : graph.declaredSymbols())
            {
                const std::string symbol(graph.symbolText(sym));
                if (symbol.empty() || !seenSymbols.insert(symbol).second)
                {
                    continue;
                }

                const ValueId valueId = graph.findValue(sym);
                if (!valueId.valid())
                {
                    ++skippedDeclaredNonValueCount;
                    continue;
                }

                const Value value = graph.getValue(valueId);
                const OperationId defOpId = graph.valueDef(valueId);
                const bool hasDefOp = defOpId.valid();

                std::string valueRefText = valueRef(model, valueId);
                uint32_t supernodeId = 0;
                bool hasSupernode = false;
                std::size_t batchIndex = kInvalidIndex;
                std::string schedFileName = "<none>";
                if (hasDefOp)
                {
                    if (const auto it = supernodeByOp.find(defOpId); it != supernodeByOp.end())
                    {
                        hasSupernode = true;
                        supernodeId = it->second;
                        if (supernodeId < batchBySupernode.size())
                        {
                            batchIndex = batchBySupernode[supernodeId];
                            if (batchIndex != kInvalidIndex && batchIndex < schedPaths.size())
                            {
                                schedFileName = schedPaths[batchIndex].filename().string();
                            }
                        }
                    }
                }

                std::vector<std::string> directOperands;
                if (hasDefOp)
                {
                    const Operation defOp = graph.getOperation(defOpId);
                    directOperands.reserve(defOp.operands().size());
                    for (ValueId operand : defOp.operands())
                    {
                        directOperands.push_back(dependencyOperandText(graph, model, operand));
                    }
                }

                std::unordered_set<ValueId, ValueIdHash> visiting;
                std::vector<std::string> combRoots =
                    collectCombinationalRootsForValue(graph, model, valueId, rootCache, visiting);

                stream << "\n";
                stream << "symbol=" << symbol << "\n";
                stream << "value_id=" << formatValueIdText(valueId) << "\n";
                stream << "value_ref=" << valueRefText << "\n";
                stream << "value_type=" << toString(value.type()) << "\n";
                stream << "value_width=" << value.width() << "\n";
                stream << "value_signed=" << (value.isSigned() ? 1 : 0) << "\n";
                stream << "value_src_loc=" << formatSrcLocText(value.srcLoc()) << "\n";
                stream << "value_is_input=" << (model.inputFieldByValue.contains(valueId) ? 1 : 0) << "\n";

                if (hasDefOp)
                {
                    const Operation defOp = graph.getOperation(defOpId);
                    stream << "def_op=" << opSymbolOrUnnamed(graph, defOpId) << "\n";
                    stream << "def_op_id=" << formatOperationIdText(defOpId) << "\n";
                    stream << "def_kind=" << toString(defOp.kind()) << "\n";
                    stream << "def_src_loc=" << formatSrcLocText(defOp.srcLoc()) << "\n";
                }
                else
                {
                    stream << "def_op=<none>\n";
                    stream << "def_op_id=<none>\n";
                    stream << "def_kind=<none>\n";
                    stream << "def_src_loc=<none>\n";
                }

                if (hasSupernode)
                {
                    stream << "supernode=" << supernodeId << "\n";
                    stream << "sched_batch=" << batchIndex << "\n";
                    stream << "sched_cpp=" << schedFileName << "\n";
                }
                else
                {
                    stream << "supernode=<none>\n";
                    stream << "sched_batch=<none>\n";
                    stream << "sched_cpp=<none>\n";
                }

                stream << "direct_operand_count=" << directOperands.size() << "\n";
                for (std::size_t i = 0; i < directOperands.size(); ++i)
                {
                    stream << "direct_operand[" << i << "]=" << directOperands[i] << "\n";
                }

                stream << "comb_root_count=" << combRoots.size() << "\n";
                for (std::size_t i = 0; i < combRoots.size(); ++i)
                {
                    stream << "comb_root[" << i << "]=" << combRoots[i] << "\n";
                }
                stream << "---\n";
                ++emittedValueCount;
            }

            stream << "\n";
            stream << "# emitted_declared_values=" << emittedValueCount << "\n";
            stream << "# skipped_declared_non_value_symbols=" << skippedDeclaredNonValueCount << "\n";

            stream.flush();
            stream.close();
            if (!stream)
            {
                error = "failed to write output file";
                return false;
            }
            return true;
        }

        std::string sanitizeTsvField(std::string_view text)
        {
            std::string out(text);
            for (char &ch : out)
            {
                if (ch == '\t' || ch == '\n' || ch == '\r')
                {
                    ch = ' ';
                }
            }
            return out;
        }

        bool emitStateReadLocalityStatsFile(const Graph &graph,
                                            const EmitModel &model,
                                            const ScheduleRefs &schedule,
                                            const std::vector<ScheduleBatch> &scheduleBatches,
                                            const std::filesystem::path &path,
                                            std::string &error)
        {
            constexpr uint32_t kNoSupernode = std::numeric_limits<uint32_t>::max();
            std::vector<uint32_t> supernodeByOp;
            if (!graph.operations().empty())
            {
                supernodeByOp.assign(graph.operations().back().index + 1u, kNoSupernode);
            }
            std::vector<std::size_t> batchBySupernode(schedule.supernodeToOps.size(), kInvalidIndex);
            std::vector<std::size_t> readOpsBySupernode(schedule.supernodeToOps.size(), 0);
            for (std::size_t batchIndex = 0; batchIndex < scheduleBatches.size(); ++batchIndex)
            {
                for (uint32_t supernodeId : scheduleBatches[batchIndex].supernodeIds)
                {
                    if (supernodeId < batchBySupernode.size())
                    {
                        batchBySupernode[supernodeId] = batchIndex;
                    }
                }
            }
            for (uint32_t supernodeId = 0; supernodeId < schedule.supernodeToOps.size(); ++supernodeId)
            {
                for (OperationId opId : schedule.supernodeToOps[supernodeId])
                {
                    if (opId.index >= supernodeByOp.size())
                    {
                        supernodeByOp.resize(opId.index + 1u, kNoSupernode);
                    }
                    supernodeByOp[opId.index] = supernodeId;
                    const OperationKind kind = graph.opKind(opId);
                    if (kind == OperationKind::kRegisterReadPort || kind == OperationKind::kLatchReadPort)
                    {
                        ++readOpsBySupernode[supernodeId];
                    }
                }
            }

            if (auto dirError = ensureOutputDirectory(path))
            {
                error = *dirError;
                return false;
            }
            std::ofstream stream(path, std::ios::out | std::ios::trunc);
            if (!stream.is_open())
            {
                error = "failed to open output file";
                return false;
            }
            stream << "op_id\tvalue_id\tkind\tstate_prefix\tstate_symbol\twidth\tscalar"
                      "\tsource_supernode\tsource_batch\tsupernode_ops\tsupernode_read_ops"
                      "\tsupernode_only_state_reads\tmaterialized\talias\tcanonical_value_id"
                      "\ttracked_change\tboundary_fanout\tgraph_user_edges\tsame_supernode_user_edges"
                      "\tsame_batch_user_edges\tcross_batch_user_edges\tunscheduled_user_edges"
                      "\tunique_user_supernodes\tunique_user_batches\n";

            const auto indexText = [](std::size_t index) {
                return index == kInvalidIndex ? std::string("-1") : std::to_string(index);
            };
            std::size_t rowCount = 0;
            std::size_t scalarRowCount = 0;
            std::size_t materializedRowCount = 0;
            std::size_t aliasRowCount = 0;
            std::size_t pureSupernodeRowCount = 0;
            std::unordered_set<uint32_t> pureSupernodes;
            for (uint32_t supernodeId = 0; supernodeId < schedule.supernodeToOps.size(); ++supernodeId)
            {
                const auto &supernodeOps = schedule.supernodeToOps[supernodeId];
                const bool onlyStateReads =
                    !supernodeOps.empty() && readOpsBySupernode[supernodeId] == supernodeOps.size();
                for (OperationId opId : supernodeOps)
                {
                    const Operation op = graph.getOperation(opId);
                    if ((op.kind() != OperationKind::kRegisterReadPort &&
                         op.kind() != OperationKind::kLatchReadPort) ||
                        op.results().size() != 1)
                    {
                        continue;
                    }
                    const ValueId valueId = op.results().front();
                    const char *symbolAttr =
                        op.kind() == OperationKind::kRegisterReadPort ? "regSymbol" : "latchSymbol";
                    const std::string stateSymbol = getAttribute<std::string>(op, symbolAttr).value_or(std::string());
                    const std::size_t separator = stateSymbol.find('$');
                    const std::string statePrefix =
                        separator == std::string::npos ? stateSymbol : stateSymbol.substr(0, separator);
                    const bool scalar =
                        graph.valueType(valueId) == ValueType::Logic && !isWideLogicValue(graph, valueId);
                    const bool materialized = isMaterializedValue(model, valueId);
                    const bool alias = model.materializedValueAliasByValue.contains(valueId);
                    const ValueId canonicalValue = canonicalMaterializedStorageValue(model, valueId);
                    const auto boundaryIt = model.boundaryFanoutByValue.find(valueId);
                    const std::size_t boundaryFanout =
                        boundaryIt == model.boundaryFanoutByValue.end() ? 0 : boundaryIt->second.size();
                    const std::size_t sourceBatch =
                        supernodeId < batchBySupernode.size() ? batchBySupernode[supernodeId] : kInvalidIndex;

                    std::size_t graphUserEdges = 0;
                    std::size_t sameSupernodeUserEdges = 0;
                    std::size_t sameBatchUserEdges = 0;
                    std::size_t crossBatchUserEdges = 0;
                    std::size_t unscheduledUserEdges = 0;
                    std::unordered_set<uint32_t> userSupernodes;
                    std::unordered_set<std::size_t> userBatches;
                    for (const auto &user : graph.getValue(valueId).users())
                    {
                        ++graphUserEdges;
                        const OperationId userOpId = user.operation;
                        const uint32_t userSupernode =
                            userOpId.valid() && userOpId.index < supernodeByOp.size()
                                ? supernodeByOp[userOpId.index]
                                : kNoSupernode;
                        if (userSupernode == kNoSupernode || userSupernode >= batchBySupernode.size())
                        {
                            ++unscheduledUserEdges;
                            continue;
                        }
                        const std::size_t userBatch = batchBySupernode[userSupernode];
                        userSupernodes.insert(userSupernode);
                        if (userBatch != kInvalidIndex)
                        {
                            userBatches.insert(userBatch);
                        }
                        if (userSupernode == supernodeId)
                        {
                            ++sameSupernodeUserEdges;
                        }
                        else if (sourceBatch != kInvalidIndex && userBatch == sourceBatch)
                        {
                            ++sameBatchUserEdges;
                        }
                        else
                        {
                            ++crossBatchUserEdges;
                        }
                    }

                    stream << opId.index << '\t'
                           << valueId.index << '\t'
                           << toString(op.kind()) << '\t'
                           << sanitizeTsvField(statePrefix) << '\t'
                           << sanitizeTsvField(stateSymbol) << '\t'
                           << graph.valueWidth(valueId) << '\t'
                           << (scalar ? 1 : 0) << '\t'
                           << supernodeId << '\t'
                           << indexText(sourceBatch) << '\t'
                           << supernodeOps.size() << '\t'
                           << readOpsBySupernode[supernodeId] << '\t'
                           << (onlyStateReads ? 1 : 0) << '\t'
                           << (materialized ? 1 : 0) << '\t'
                           << (alias ? 1 : 0) << '\t'
                           << canonicalValue.index << '\t'
                           << (valueNeedsTrackedChange(model, valueId) ? 1 : 0) << '\t'
                           << boundaryFanout << '\t'
                           << graphUserEdges << '\t'
                           << sameSupernodeUserEdges << '\t'
                           << sameBatchUserEdges << '\t'
                           << crossBatchUserEdges << '\t'
                           << unscheduledUserEdges << '\t'
                           << userSupernodes.size() << '\t'
                           << userBatches.size() << '\n';
                    ++rowCount;
                    scalarRowCount += scalar ? 1u : 0u;
                    materializedRowCount += materialized ? 1u : 0u;
                    aliasRowCount += alias ? 1u : 0u;
                    if (onlyStateReads)
                    {
                        ++pureSupernodeRowCount;
                        pureSupernodes.insert(supernodeId);
                    }
                }
            }
            if (!stream.good())
            {
                error = "failed while writing output file";
                return false;
            }
            std::fprintf(stderr,
                         "[GRHSIM_STATE_READ_LOCALITY] path=%s rows=%zu scalar=%zu materialized=%zu aliases=%zu pure_supernodes=%zu pure_rows=%zu\n",
                         path.string().c_str(),
                         rowCount,
                         scalarRowCount,
                         materializedRowCount,
                         aliasRowCount,
                         pureSupernodes.size(),
                         pureSupernodeRowCount);
            return true;
        }

        bool emitMaterializedScalarReadLocalityStatsFile(
            const Graph &graph,
            const EmitModel &model,
            const ScheduleRefs &schedule,
            const std::vector<ScheduleBatch> &scheduleBatches,
            const std::filesystem::path &path,
            std::string &error)
        {
            struct TouchInfo
            {
                std::size_t operandTouches = 0;
                std::size_t resultWrites = 0;
                std::size_t firstTouchOrder = kInvalidIndex;
                std::unordered_set<ValueId, ValueIdHash> operandValues;
                std::unordered_set<OperationId, OperationIdHash> useOps;
            };
            struct Row
            {
                uint32_t supernodeId = 0;
                std::size_t batchIndex = kInvalidIndex;
                ValueId value{};
                ValueSlotScalarKind scalarKind = ValueSlotScalarKind::kBool;
                std::size_t slotIndex = 0;
                std::size_t operandTouches = 0;
                std::size_t distinctOperandValues = 0;
                std::size_t useOps = 0;
                std::size_t resultWrites = 0;
                std::size_t supernodeOps = 0;
                std::size_t emittedComputeOps = 0;
                std::size_t firstTouchOrder = kInvalidIndex;
                bool candidate = false;
            };

            std::vector<Row> rows;
            std::unordered_set<uint32_t> visitedSupernodes;
            std::size_t scannedSupernodes = 0;
            std::size_t scalarOperandTouches = 0;
            std::size_t directStateReadOperandTouches = 0;
            std::size_t candidateOperandTouches = 0;
            std::size_t loadsSavedPerFire = 0;

            for (const ScheduleBatch &batch : scheduleBatches)
            {
                if (batch.phase != ScheduleBatch::Phase::kCompute)
                {
                    continue;
                }
                for (uint32_t supernodeId : batch.supernodeIds)
                {
                    if (supernodeId >= schedule.supernodeToOps.size() ||
                        !visitedSupernodes.insert(supernodeId).second)
                    {
                        continue;
                    }
                    ++scannedSupernodes;
                    const auto &supernodeOps = schedule.supernodeToOps[supernodeId];
                    std::unordered_map<ValueId, TouchInfo, ValueIdHash> touchesByValue;
                    std::size_t emittedComputeOps = 0;
                    std::size_t nextTouchOrder = 0;

                    for (OperationId opId : supernodeOps)
                    {
                        const Operation op = graph.getOperation(opId);
                        if (isCommitPhaseOp(op) || isRegToMemIntentBypassOp(model, opId))
                        {
                            continue;
                        }
                        ++emittedComputeOps;
                        for (ValueId operand : op.operands())
                        {
                            if (model.directStateReadSymbolByValue.contains(operand))
                            {
                                ++directStateReadOperandTouches;
                                continue;
                            }
                            const ValueId canonicalValue = canonicalMaterializedStorageValue(model, operand);
                            const auto slotIt = model.valueScalarSlotByValue.find(canonicalValue);
                            if (slotIt == model.valueScalarSlotByValue.end() ||
                                !isMaterializedValue(model, canonicalValue))
                            {
                                continue;
                            }
                            TouchInfo &touch = touchesByValue[canonicalValue];
                            if (touch.firstTouchOrder == kInvalidIndex)
                            {
                                touch.firstTouchOrder = nextTouchOrder++;
                            }
                            ++touch.operandTouches;
                            touch.operandValues.insert(operand);
                            touch.useOps.insert(opId);
                            ++scalarOperandTouches;
                        }
                        for (ValueId result : op.results())
                        {
                            if (model.directStateReadSymbolByValue.contains(result))
                            {
                                continue;
                            }
                            const ValueId canonicalValue = canonicalMaterializedStorageValue(model, result);
                            if (!model.valueScalarSlotByValue.contains(canonicalValue) ||
                                !isMaterializedValue(model, canonicalValue))
                            {
                                continue;
                            }
                            ++touchesByValue[canonicalValue].resultWrites;
                        }
                    }

                    for (const auto &[value, touch] : touchesByValue)
                    {
                        if (touch.operandTouches == 0)
                        {
                            continue;
                        }
                        const ValueScalarSlotRef &slot = model.valueScalarSlotByValue.at(value);
                        const bool candidate = touch.operandTouches >= 2 && touch.resultWrites == 0;
                        rows.push_back(Row{
                            .supernodeId = supernodeId,
                            .batchIndex = batch.index,
                            .value = value,
                            .scalarKind = slot.kind,
                            .slotIndex = slot.slotIndex,
                            .operandTouches = touch.operandTouches,
                            .distinctOperandValues = touch.operandValues.size(),
                            .useOps = touch.useOps.size(),
                            .resultWrites = touch.resultWrites,
                            .supernodeOps = supernodeOps.size(),
                            .emittedComputeOps = emittedComputeOps,
                            .firstTouchOrder = touch.firstTouchOrder,
                            .candidate = candidate,
                        });
                        if (candidate)
                        {
                            candidateOperandTouches += touch.operandTouches;
                            loadsSavedPerFire += touch.operandTouches - 1u;
                        }
                    }
                }
            }

            std::sort(rows.begin(),
                      rows.end(),
                      [](const Row &lhs, const Row &rhs) {
                          if (lhs.batchIndex != rhs.batchIndex)
                          {
                              return lhs.batchIndex < rhs.batchIndex;
                          }
                          if (lhs.supernodeId != rhs.supernodeId)
                          {
                              return lhs.supernodeId < rhs.supernodeId;
                          }
                          if (lhs.firstTouchOrder != rhs.firstTouchOrder)
                          {
                              return lhs.firstTouchOrder < rhs.firstTouchOrder;
                          }
                          if (lhs.value.index != rhs.value.index)
                          {
                              return lhs.value.index < rhs.value.index;
                          }
                          return lhs.value.generation < rhs.value.generation;
                      });

            if (auto dirError = ensureOutputDirectory(path))
            {
                error = *dirError;
                return false;
            }
            std::ofstream stream(path, std::ios::out | std::ios::trunc);
            if (!stream.is_open())
            {
                error = "failed to open output file";
                return false;
            }
            stream << "supernode_id\tphase\tbatch_id\tcanonical_value_id\tcanonical_value_generation"
                      "\tvalue_name\twidth\tscalar_kind\tslot_index\toperand_touches"
                      "\tdistinct_operand_values\tuse_ops\tresult_writes\tsupernode_ops"
                      "\temitted_compute_ops\tcandidate\tloads_saved_per_fire\n";
            for (const Row &row : rows)
            {
                stream << row.supernodeId << "\tcompute\t"
                       << row.batchIndex << '\t'
                       << row.value.index << '\t'
                       << row.value.generation << '\t'
                       << sanitizeTsvField(valueSymbolOrUnnamed(graph, row.value)) << '\t'
                       << graph.valueWidth(row.value) << '\t'
                       << valueSlotScalarKindName(row.scalarKind) << '\t'
                       << row.slotIndex << '\t'
                       << row.operandTouches << '\t'
                       << row.distinctOperandValues << '\t'
                       << row.useOps << '\t'
                       << row.resultWrites << '\t'
                       << row.supernodeOps << '\t'
                       << row.emittedComputeOps << '\t'
                       << (row.candidate ? 1 : 0) << '\t'
                       << (row.candidate ? row.operandTouches - 1u : 0u) << '\n';
            }
            if (!stream.good())
            {
                error = "failed while writing output file";
                return false;
            }
            std::fprintf(stderr,
                         "[GRHSIM_MATERIALIZED_SCALAR_READ_LOCALITY] path=%s supernodes=%zu read_rows=%zu scalar_operand_touches=%zu direct_state_read_operand_touches=%zu candidate_rows=%zu candidate_touches=%zu loads_saved_per_fire=%zu\n",
                         path.string().c_str(),
                         scannedSupernodes,
                         rows.size(),
                         scalarOperandTouches,
                         directStateReadOperandTouches,
                         static_cast<std::size_t>(std::count_if(rows.begin(), rows.end(), [](const Row &row) {
                             return row.candidate;
                         })),
                         candidateOperandTouches,
                         loadsSavedPerFire);
            return true;
        }

        bool collectDeclaredSymbolWaveformSignals(const Graph &graph,
                                                  const EmitModel &model,
                                                  std::vector<WaveformSignalDecl> &outSignals)
        {
            outSignals.clear();
            std::unordered_set<std::string> seenSymbols;
            seenSymbols.reserve(graph.declaredSymbols().size());

            for (const auto sym : graph.declaredSymbols())
            {
                const std::string symbol(graph.symbolText(sym));
                if (symbol.empty() || !seenSymbols.insert(symbol).second)
                {
                    continue;
                }

                if (const ValueId valueId = graph.findValue(sym); valueId.valid())
                {
                    const std::string ref = valueRef(model, valueId);
                    if (ref == "/*missing_value_ref*/")
                    {
                        continue;
                    }
                    WaveformSignalDecl signal;
                    signal.sourceKind = WaveformSignalDecl::SourceKind::kValue;
                    signal.symbol = symbol;
                    signal.escapedSymbol = escapeCppString(symbol);
                    signal.type = graph.valueType(valueId);
                    signal.width = graph.valueWidth(valueId);
                    signal.isSigned = graph.valueSigned(valueId);
                    signal.value = valueId;
                    outSignals.push_back(std::move(signal));
                    continue;
                }

                auto stateIt = model.stateBySymbol.find(symbol);
                if (stateIt == model.stateBySymbol.end())
                {
                    continue;
                }
                const StateDecl &state = stateIt->second;
                if (state.kind == StateDecl::Kind::Memory)
                {
                    continue;
                }
                WaveformSignalDecl signal;
                signal.sourceKind = WaveformSignalDecl::SourceKind::kState;
                signal.symbol = symbol;
                signal.escapedSymbol = escapeCppString(symbol);
                signal.type = ValueType::Logic;
                signal.width = state.width;
                signal.isSigned = state.isSigned;
                signal.stateSymbol = state.symbol;
                outSignals.push_back(std::move(signal));
            }

            return true;
        }

        void assignWaveformPrevStorageLayout(EmitModel &model)
        {
            std::size_t logicStorageOffset = 0;
            model.waveformPrevRealCount = 0;
            model.waveformPrevStringCount = 0;
            for (auto &signal : model.waveformSignals)
            {
                switch (signal.type)
                {
                case ValueType::Real:
                    signal.waveformPrevRealIndex = model.waveformPrevRealCount++;
                    break;
                case ValueType::String:
                    signal.waveformPrevStringIndex = model.waveformPrevStringCount++;
                    break;
                case ValueType::Logic:
                default:
                {
                    const int32_t width = signal.width <= 0 ? 1 : signal.width;
                    if (isWideLogicWidth(width))
                    {
                        logicStorageOffset = alignTo(logicStorageOffset, alignof(std::uint64_t));
                        signal.waveformPrevStorageOffset = logicStorageOffset;
                        signal.waveformPrevWordCount = logicWordCount(width);
                        logicStorageOffset += signal.waveformPrevWordCount * sizeof(std::uint64_t);
                    }
                    else
                    {
                        signal.waveformPrevScalarKind = valueScalarSlotKindForWidth(width);
                        logicStorageOffset =
                            alignTo(logicStorageOffset, valuePackedScalarSlotAlignment(signal.waveformPrevScalarKind));
                        signal.waveformPrevStorageOffset = logicStorageOffset;
                        logicStorageOffset += valuePackedScalarSlotByteSize(signal.waveformPrevScalarKind);
                    }
                    break;
                }
                }
            }
            model.waveformPrevLogicStorageBytes = logicStorageOffset;
        }

        std::unordered_set<ValueId, ValueIdHash> collectDeclaredSymbolWaveformValueIds(const Graph &graph)
        {
            std::unordered_set<ValueId, ValueIdHash> valueIds;
            valueIds.reserve(graph.declaredSymbols().size());
            std::unordered_set<std::string> seenSymbols;
            seenSymbols.reserve(graph.declaredSymbols().size());

            for (const auto sym : graph.declaredSymbols())
            {
                const std::string symbol(graph.symbolText(sym));
                if (symbol.empty() || !seenSymbols.insert(symbol).second)
                {
                    continue;
                }
                const ValueId valueId = graph.findValue(sym);
                if (!valueId.valid())
                {
                    continue;
                }
                valueIds.insert(valueId);
            }

            return valueIds;
        }

        std::pair<std::size_t, std::size_t> waveformSignalRangeForBatch(std::size_t signalCount,
                                                                         std::size_t batchCount,
                                                                         std::size_t batchIndex) noexcept
        {
            if (signalCount == 0 || batchCount == 0 || batchIndex >= batchCount)
            {
                return {0, 0};
            }
            const std::size_t begin = (signalCount * batchIndex) / batchCount;
            const std::size_t end = (signalCount * (batchIndex + 1)) / batchCount;
            return {begin, end};
        }

        void emitWaveformSignalWrite(std::ostream &stream,
                                     const Graph &graph,
                                     const EmitModel &model,
                                     const WaveformSignalDecl &signal,
                                     std::size_t signalIndex,
                                     std::string_view indent)
        {
            std::string expr;
            if (signal.sourceKind == WaveformSignalDecl::SourceKind::kState)
            {
                expr = stateRef(model.stateBySymbol.at(signal.stateSymbol));
            }
            else
            {
                expr = valueRef(model, signal.value);
            }

            switch (signal.type)
            {
            case ValueType::Real:
                stream << indent << "{\n";
                stream << indent << "    const double curr_value = static_cast<double>(" << expr << ");\n";
                stream << indent << "    auto &prev_value = waveform_prev_real_slots_[" << signal.waveformPrevRealIndex
                       << "];\n";
                stream << indent << "    if (force || prev_value != curr_value) {\n";
                stream << indent << "        waveform_writer_->emit_real(waveform_handles_[" << signalIndex
                       << "], curr_value);\n";
                stream << indent << "        prev_value = curr_value;\n";
                stream << indent << "    }\n";
                stream << indent << "}\n";
                break;
            case ValueType::String:
                stream << indent << "{\n";
                stream << indent << "    const std::string curr_value = " << expr << ";\n";
                stream << indent << "    auto &prev_value = waveform_prev_string_slots_["
                       << signal.waveformPrevStringIndex << "];\n";
                stream << indent << "    if (force || prev_value != curr_value) {\n";
                stream << indent << "        waveform_writer_->emit_string(waveform_handles_[" << signalIndex
                       << "], curr_value);\n";
                stream << indent << "        prev_value = curr_value;\n";
                stream << indent << "    }\n";
                stream << indent << "}\n";
                break;
            case ValueType::Logic:
            default:
                if (isWideLogicWidth(signal.width))
                {
                    stream << indent << "{\n";
                    stream << indent << "    auto &prev_value = "
                           << packedWideStorageDirectRefExpr("waveform_prev_logic_storage_",
                                                             signal.waveformPrevWordCount,
                                                             std::to_string(signal.waveformPrevStorageOffset))
                           << ";\n";
                    stream << indent << "    if (force) {\n";
                    stream << indent << "        "
                           << assignWordsInlineExpr(
                                  "prev_value",
                                  waveformWideExprForSignal(graph, model, signal),
                                  (signal.width <= 0 ? 1 : signal.width))
                           << ";\n";
                    stream << indent << "        waveform_writer_->emit_logic_words(waveform_handles_["
                           << signalIndex << "], " << (signal.width <= 0 ? 1 : signal.width)
                           << "u, prev_value);\n";
                    stream << indent << "    } else if ("
                           << assignWordsInlineExpr(
                                  "prev_value",
                                  waveformWideExprForSignal(graph, model, signal),
                                  (signal.width <= 0 ? 1 : signal.width))
                           << ") {\n";
                    stream << indent << "        waveform_writer_->emit_logic_words(waveform_handles_["
                           << signalIndex << "], " << (signal.width <= 0 ? 1 : signal.width)
                           << "u, prev_value);\n";
                    stream << indent << "    }\n";
                    stream << indent << "}\n";
                }
                else
                {
                    stream << indent << "{\n";
                    if (signal.waveformPrevScalarKind == ValueSlotScalarKind::kBool)
                    {
                        stream << indent << "    const std::uint8_t curr_value = static_cast<std::uint8_t>((" << expr
                               << ") ? 1u : 0u);\n";
                    }
                    else
                    {
                        stream << indent << "    const auto curr_value = static_cast<"
                               << scalarLogicSlotCppType(signal.waveformPrevScalarKind)
                               << ">(grhsim_trunc_u64(static_cast<std::uint64_t>(" << expr << "), "
                               << (signal.width <= 0 ? 1 : signal.width) << "u));\n";
                    }
                    stream << indent << "    auto &prev_value = "
                           << packedScalarStorageDirectRefExpr("waveform_prev_logic_storage_",
                                                               signal.waveformPrevScalarKind,
                                                               std::to_string(signal.waveformPrevStorageOffset))
                           << ";\n";
                    stream << indent << "    if (force || prev_value != curr_value) {\n";
                    stream << indent << "        waveform_writer_->emit_logic_u64(waveform_handles_["
                           << signalIndex << "], " << (signal.width <= 0 ? 1 : signal.width)
                           << "u, static_cast<std::uint64_t>(curr_value));\n";
                    stream << indent << "        prev_value = curr_value;\n";
                    stream << indent << "    }\n";
                    stream << indent << "}\n";
                }
                break;
            }
        }

        void emitWaveformSignalRegistrationBatch(std::ostream &stream,
                                                 std::span<const WaveformSignalDecl> signals,
                                                 std::string_view indent)
        {
            if (signals.empty())
            {
                return;
            }

            stream << indent << "enum class waveform_signal_kind : std::uint8_t {\n";
            stream << indent << "    logic,\n";
            stream << indent << "    real,\n";
            stream << indent << "    string,\n";
            stream << indent << "};\n";
            stream << indent << "struct waveform_signal_decl {\n";
            stream << indent << "    const char *name;\n";
            stream << indent << "    std::uint32_t width;\n";
            stream << indent << "    waveform_signal_kind kind;\n";
            stream << indent << "};\n";
            stream << indent << "static constexpr waveform_signal_decl kWaveformSignals[] = {";
            for (std::size_t i = 0; i < signals.size(); ++i)
            {
                const auto &signal = signals[i];
                if ((i % 4u) == 0u)
                {
                    stream << "\n" << indent << "    ";
                }
                stream << "{\"" << signal.escapedSymbol << "\", " << (signal.width <= 0 ? 1 : signal.width) << "u, ";
                switch (signal.type)
                {
                case ValueType::Real:
                    stream << "waveform_signal_kind::real}";
                    break;
                case ValueType::String:
                    stream << "waveform_signal_kind::string}";
                    break;
                case ValueType::Logic:
                default:
                    stream << "waveform_signal_kind::logic}";
                    break;
                }
                if (i + 1u != signals.size())
                {
                    stream << ", ";
                }
            }
            stream << "\n" << indent << "};\n";
            stream << indent << "for (const auto &signal : kWaveformSignals) {\n";
            stream << indent << "    switch (signal.kind) {\n";
            stream << indent << "    case waveform_signal_kind::real:\n";
            stream << indent << "        waveform_handles_.push_back(writer.register_real(signal.name));\n";
            stream << indent << "        break;\n";
            stream << indent << "    case waveform_signal_kind::string:\n";
            stream << indent << "        waveform_handles_.push_back(writer.register_string(signal.name));\n";
            stream << indent << "        break;\n";
            stream << indent << "    case waveform_signal_kind::logic:\n";
            stream << indent << "    default:\n";
            stream << indent << "        waveform_handles_.push_back(writer.register_logic(signal.name, signal.width));\n";
            stream << indent << "        break;\n";
            stream << indent << "    }\n";
            stream << indent << "}\n";
        }

        std::string stateShadowTouchedRef(const StateShadowDecl &shadow)
        {
            return "state_shadow_touched_slots_[" + std::to_string(shadow.touchedIndex) + "]";
        }

        std::string stateShadowDataRef(const StateShadowDecl &shadow, const StateDecl &state)
        {
            return logicSlotRefExpr("state_shadow_",
                                    "state_shadow_",
                                    shadow.scalarKind,
                                    shadow.wordCount,
                                    shadow.dataIndex,
                                    isWideLogicWidth(state.width));
        }

        std::string memoryWriteTouchedRef(const WriteDecl &write)
        {
            return "memory_write_touched_slots_[" + std::to_string(write.shadowTouchedIndex) + "]";
        }

        std::string memoryWriteAddrRef(const WriteDecl &write)
        {
            return "memory_write_addr_slots_[" + std::to_string(write.shadowAddrIndex) + "]";
        }

        std::string memoryWriteDataRef(const WriteDecl &write, const StateDecl &state)
        {
            return logicSlotRefExpr("memory_write_data_",
                                    "memory_write_data_",
                                    write.shadowScalarKind,
                                    write.shadowWordCount,
                                    write.shadowDataIndex,
                                    isWideLogicWidth(state.width));
        }

        std::string memoryWriteMaskRef(const WriteDecl &write, const StateDecl &state)
        {
            return logicSlotRefExpr("memory_write_mask_",
                                    "memory_write_mask_",
                                    write.shadowScalarKind,
                                    write.shadowWordCount,
                                    write.shadowMaskIndex,
                                    isWideLogicWidth(state.width));
        }

        std::optional<std::string> stableValueExpr(const Graph &graph, const EmitModel &model, ValueId value)
        {
            const OperationId defOpId = graph.valueDef(value);
            if (defOpId.valid())
            {
                const Operation defOp = graph.getOperation(defOpId);
                if (defOp.kind() == OperationKind::kConstant)
                {
                    if (auto expr = constantExpr(graph, defOp, value))
                    {
                        return expr;
                    }
                }
            }
            if (auto it = model.inputFieldByValue.find(value); it != model.inputFieldByValue.end())
            {
                return it->second;
            }
            if (auto it = model.valueFieldByValue.find(value); it != model.valueFieldByValue.end())
            {
                return it->second;
            }
            return std::nullopt;
        }

        std::string waveformWideExprForSignal(const Graph &graph,
                                              const EmitModel &model,
                                              const WaveformSignalDecl &signal)
        {
            if (signal.sourceKind == WaveformSignalDecl::SourceKind::kState)
            {
                return stateRef(model.stateBySymbol.at(signal.stateSymbol));
            }
            (void)graph;
            return valueRef(model, signal.value);
        }

        std::string truthyLogicValueExpr(const Graph &graph,
                                         const EmitModel &model,
                                         ValueId value,
                                         const SupernodeLocalExprContext *context)
        {
            if (isWideLogicValue(graph, value))
            {
                return "grhsim_any_bits_words(" + resolvedScheduleValueExpr(model, value, context) + ", " +
                       std::to_string(graph.valueWidth(value)) + ")";
            }
            return "(" + resolvedScheduleValueExpr(model, value, context) + ") != 0";
        }

        std::string truthyLogicValueExpr(const Graph &graph, const EmitModel &model, ValueId value)
        {
            return truthyLogicValueExpr(graph, model, value, nullptr);
        }

        std::string stableTruthyLogicValueExpr(const Graph &graph, const EmitModel &model, ValueId value)
        {
            const std::string ref =
                stableValueExpr(graph, model, value).value_or(std::string("/*missing_stable_truthy_value*/"));
            if (isWideLogicValue(graph, value))
            {
                return "grhsim_any_bits_words(" + ref + ", " + std::to_string(graph.valueWidth(value)) + ")";
            }
            return "(" + ref + ") != 0";
        }

        std::string stableSystemTaskArgExpr(const Graph &graph,
                                            const EmitModel &model,
                                            ValueId value)
        {
            const std::string ref =
                stableValueExpr(graph, model, value).value_or(std::string("/*missing_stable_system_task_arg*/"));
            const std::string signedText = graph.valueSigned(value) ? "true" : "false";
            switch (graph.valueType(value))
            {
            case ValueType::String:
                return "grhsim_make_task_arg(" + ref + ")";
            case ValueType::Real:
                return "grhsim_make_task_arg(static_cast<double>(" + ref + "))";
            case ValueType::Logic:
            default:
                break;
            }
            if (isWideLogicValue(graph, value))
            {
                std::ostringstream out;
                out << "grhsim_make_task_arg(" << ref << ", "
                    << graph.valueWidth(value) << ", "
                    << signedText << ")";
                return out.str();
            }
            std::ostringstream out;
            out << "grhsim_make_task_arg(static_cast<std::uint64_t>(" << ref << "), "
                << graph.valueWidth(value) << ", "
                << signedText << ")";
            return out.str();
        }

        std::string stableScalarSystemTaskArgExpr(const Graph &graph,
                                                  const EmitModel &model,
                                                  ValueId value)
        {
            const std::string ref =
                stableValueExpr(graph, model, value).value_or(std::string("/*missing_stable_scalar_system_task_arg*/"));
            std::ostringstream out;
            out << "grhsim_scalar_task_arg{static_cast<std::uint64_t>(" << ref << "), "
                << graph.valueWidth(value) << "u, "
                << (graph.valueSigned(value) ? "true" : "false") << "}";
            return out.str();
        }

        std::string stableScalarSystemTaskDirectArgExpr(const Graph &graph,
                                                        const EmitModel &model,
                                                        ValueId value)
        {
            const std::string ref =
                stableValueExpr(graph, model, value).value_or(std::string("/*missing_stable_scalar_system_task_arg*/"));
            std::ostringstream out;
            out << "static_cast<unsigned>(" << graph.valueWidth(value) << "u"
                << (graph.valueSigned(value) ? " | 0x80000000u" : "") << "), "
                << "static_cast<std::uint64_t>(" << ref << ")";
            return out.str();
        }

        void emitStableScalarFormatSystemTaskCall(std::ostream &stream,
                                                  const Graph &graph,
                                                  const EmitModel &model,
                                                  std::string_view indent,
                                                  std::string_view name,
                                                  std::span<const ValueId> args)
        {
            const bool usesHandle = name == "fdisplay" || name == "fwrite";
            const std::size_t formatIndex = usesHandle ? 1u : 0u;
            const std::string handleExpr =
                usesHandle
                    ? ("static_cast<std::uint64_t>(" +
                       stableValueExpr(graph, model, args.front()).value_or(std::string("UINT64_C(0)")) + ")")
                    : "UINT64_C(0)";
            const std::string formatExpr = model.staticConstStringFieldByValue.at(args[formatIndex]);
            emitScalarFormatSystemTaskCall(stream,
                                           indent,
                                           name,
                                           handleExpr,
                                           formatExpr,
                                           args.size() - formatIndex - 1u,
                                           [&](std::size_t argIndex)
                                           {
                                               return stableScalarSystemTaskArgExpr(graph,
                                                                                   model,
                                                                                   args[formatIndex + 1u + argIndex]);
                                           });
        }

        void emitStableDirectScalarFormatSystemTaskCall(std::ostream &stream,
                                                        const Graph &graph,
                                                        const EmitModel &model,
                                                        std::string_view indent,
                                                        std::string_view name,
                                                        std::span<const ValueId> args)
        {
            const bool usesHandle = name == "fdisplay" || name == "fwrite";
            const bool newline = name == "display" || name == "fdisplay";
            const std::size_t formatIndex = usesHandle ? 1u : 0u;
            const std::string handleExpr =
                usesHandle
                    ? ("static_cast<std::uint64_t>(" +
                       stableValueExpr(graph, model, args.front()).value_or(std::string("UINT64_C(0)")) + ")")
                    : "UINT64_C(0)";
            const std::string formatExpr = model.staticConstStringFieldByValue.at(args[formatIndex]);
            emitDirectScalarFormatSystemTaskCall(stream,
                                                 indent,
                                                 usesHandle,
                                                 newline,
                                                 handleExpr,
                                                 formatExpr,
                                                 args.size() - formatIndex - 1u,
                                                 [&](std::size_t argIndex)
                                                 {
                                                     return stableScalarSystemTaskDirectArgExpr(
                                                         graph,
                                                         model,
                                                         args[formatIndex + 1u + argIndex]);
                                                 });
        }

        std::string boolLiteral(bool value)
        {
            return value ? "true" : "false";
        }

        std::string wordsArrayTypeForWidth(int32_t width)
        {
            std::ostringstream out;
            out << "std::array<std::uint64_t, " << logicWordCount(width) << ">";
            return out.str();
        }

        bool canUseFullWidthWordsHelper(int32_t width)
        {
            return width > 0 &&
                   (static_cast<std::uint32_t>(width) % 64u) == 0u &&
                   logicWordCount(width) >= 3u;
        }

        bool isFullWidthBinaryWordsHelper(std::string_view helperName)
        {
            return helperName == "grhsim_and_words" ||
                   helperName == "grhsim_or_words" ||
                   helperName == "grhsim_xor_words" ||
                   helperName == "grhsim_xnor_words";
        }

        bool isFullWidthUnaryWordsHelper(std::string_view helperName)
        {
            return helperName == "grhsim_not_words";
        }

        void appendWordsTailTruncation(std::ostringstream &out,
                                       std::string_view arrayExpr,
                                       int32_t width)
        {
            if (width <= 0)
            {
                return;
            }
            const std::size_t wordCount = logicWordCount(width);
            if (wordCount == 0)
            {
                return;
            }
            const std::size_t tailWidth = static_cast<std::size_t>(width) - (wordCount - 1u) * 64u;
            if (tailWidth >= 64u)
            {
                return;
            }
            out << arrayExpr << "[" << (wordCount - 1u) << "] &= " << scalarMaskExpr(tailWidth) << "; ";
        }

        void emitWordsTailTruncationStatements(std::ostream &stream,
                                               std::string_view indent,
                                               std::string_view arrayExpr,
                                               int32_t width)
        {
            if (width <= 0)
            {
                return;
            }
            const std::size_t wordCount = logicWordCount(width);
            if (wordCount == 0)
            {
                return;
            }
            const std::size_t tailWidth = static_cast<std::size_t>(width) - (wordCount - 1u) * 64u;
            if (tailWidth >= 64u)
            {
                return;
            }
            stream << indent << arrayExpr << "[" << (wordCount - 1u) << "] &= " << scalarMaskExpr(tailWidth)
                   << ";\n";
        }

        std::string castScalarWordsInlineExpr(const std::string &expr,
                                              int32_t srcWidth,
                                              int32_t destWidth,
                                              bool srcSigned)
        {
            const std::size_t destWords = logicWordCount(destWidth);
            std::ostringstream out;
            out << "grhsim_cast_words<" << destWords << ">((" << expr << "), "
                << srcWidth << ", "
                << destWidth << ", "
                << boolLiteral(srcSigned) << ")";
            return out.str();
        }

        std::string castWideWordsInlineExpr(const std::string &expr,
                                            int32_t srcWidth,
                                            int32_t destWidth,
                                            bool srcSigned)
        {
            const std::size_t destWords = logicWordCount(destWidth);
            std::ostringstream out;
            out << "grhsim_cast_words<" << destWords << ">((" << expr << "), "
                << srcWidth << ", "
                << destWidth << ", "
                << boolLiteral(srcSigned) << ")";
            return out.str();
        }

        std::string addWordsInlineExpr(const std::string &lhsExpr,
                                       const std::string &rhsExpr,
                                       int32_t resultWidth)
        {
            if (logicWordCount(resultWidth) == 2)
            {
                return "grhsim_add_words_2<" + std::to_string(resultWidth) + ">((" + lhsExpr + "), (" + rhsExpr + "))";
            }
            return "grhsim_add_words((" + lhsExpr + "), (" + rhsExpr + "), " + std::to_string(resultWidth) + ")";
        }

        std::string concatTwoWordsInlineExpr(const std::string &lhsExpr,
                                             int32_t lhsWidth,
                                             const std::string &rhsExpr,
                                             int32_t rhsWidth,
                                             int32_t resultWidth)
        {
            const std::size_t destWords = logicWordCount(resultWidth);
            const std::size_t lhsWords = logicWordCount(lhsWidth);
            const std::size_t rhsWords = logicWordCount(rhsWidth);
            if (destWords == 2 && lhsWords == 1 && rhsWords == 1)
            {
                std::ostringstream out;
                out << "grhsim_concat_words_2_1_1<" << lhsWidth << ", "
                    << rhsWidth << ", "
                    << resultWidth << ">((" << lhsExpr << "), ("
                    << rhsExpr << "))";
                return out.str();
            }
            if (destWords == 2 && lhsWords == 1 && rhsWords == 2)
            {
                std::ostringstream out;
                out << "grhsim_concat_words_2_1_2<" << lhsWidth << ", "
                    << rhsWidth << ", "
                    << resultWidth << ">((" << lhsExpr << "), ("
                    << rhsExpr << "))";
                return out.str();
            }
            std::ostringstream out;
            out << "grhsim_concat_words<" << destWords << ">((" << lhsExpr << "), "
                << lhsWidth << ", "
                << "(" << rhsExpr << "), "
                << rhsWidth << ", "
                << resultWidth << ")";
            return out.str();
        }

        std::string assignWordsInlineExpr(const std::string &lhsExpr,
                                          const std::string &rhsExpr,
                                          int32_t width)
        {
            if (logicWordCount(width) == 2)
            {
                return "grhsim_assign_words_2<" + std::to_string(width) + ">(" + lhsExpr + ", " + rhsExpr + ")";
            }
            if (canUseFullWidthWordsHelper(width))
            {
                return "grhsim_assign_words_full<" + std::to_string(logicWordCount(width)) + ">(" +
                       lhsExpr + ", " + rhsExpr + ")";
            }
            return "grhsim_assign_words(" + lhsExpr + ", " + rhsExpr + ", " + std::to_string(width) + ")";
        }

        std::size_t estimateChangedValueEffectLines(const ActivityScheduleValueFanout &valueFanout,
                                                    ValueId resultValue) noexcept
        {
            if (!resultValue.valid() || resultValue.index == 0 || resultValue.index > valueFanout.size())
            {
                return 0;
            }
            return valueFanout[resultValue.index - 1].size();
        }

        std::size_t estimateCommitWriteEmitLines(const Graph &graph,
                                                 const EmitModel &model,
                                                 uint32_t supernodeId,
                                                 OperationId opId,
                                                 const Operation &op)
        {
            (void)graph;
            (void)op;
            const auto writeIt = model.writeByOp.find(opId);
            if (writeIt == model.writeByOp.end())
            {
                return 24;
            }
            const WriteDecl &write = writeIt->second;
            const auto stateIt = model.stateBySymbol.find(write.symbol);
            if (stateIt == model.stateBySymbol.end())
            {
                return 24;
            }
            const StateDecl &state = stateIt->second;

            std::size_t total = 6;
            if (write.kind == StateDecl::Kind::Memory)
            {
                total += 3;
                if (write.isMemoryFill)
                {
                    total += isWideLogicWidth(state.width) ? 6 : 8;
                }
                else if (write.memoryMaskMode == WriteDecl::MemoryMaskMode::kConstZero)
                {
                    total += 1;
                }
                else if (write.memoryMaskMode == WriteDecl::MemoryMaskMode::kConstAllOnes)
                {
                    total += isWideLogicWidth(state.width) ? 4 : 6;
                }
                else
                {
                    total += isWideLogicWidth(state.width) ? 4 : 7;
                }
                total += 1;
            }
            else
            {
                total += isWideLogicWidth(state.width) ? 4 : 5;
            }

            const auto headIt = model.stateHeadSupernodesBySymbol.find(write.symbol);
            if (headIt == model.stateHeadSupernodesBySymbol.end() || headIt->second.empty())
            {
                return total;
            }

            const std::size_t currentActiveId =
                supernodeId < model.activeIdBySupernode.size() ? model.activeIdBySupernode[supernodeId] : kInvalidIndex;
            const ActivationEmitContext activationContext{
                .currentWordIndex = currentActiveId == kInvalidIndex ? 0u : currentActiveId / kActiveFlagBitsPerWord,
                .currentActiveId = currentActiveId,
                .localActiveExpr = "activeWordFlags"};
            total += 2 + estimateActivationEmitLines(headIt->second, &activationContext);
            return total;
        }

        std::size_t estimateOperationEmitLines(const Graph &graph,
                                               const EmitModel &model,
                                               const ActivityScheduleValueFanout &valueFanout,
                                               uint32_t supernodeId,
                                               OperationId opId,
                                               const Operation &op)
        {
            if (op.kind() == OperationKind::kRegisterReadPort && op.results().size() == 1 &&
                model.directStateReadSymbolByValue.contains(op.results().front()))
            {
                return 1;
            }
            if (isCommitPhaseOp(op) &&
                (op.kind() == OperationKind::kRegisterWritePort ||
                 op.kind() == OperationKind::kLatchWritePort ||
                 op.kind() == OperationKind::kMemoryWritePort))
            {
                return estimateCommitWriteEmitLines(graph, model, supernodeId, opId, op);
            }

            std::size_t changedValueEffectLines = 0;
            if (!op.results().empty())
            {
                changedValueEffectLines = estimateChangedValueEffectLines(valueFanout, op.results().front());
            }
            switch (op.kind())
            {
            case OperationKind::kConstant:
            case OperationKind::kRegisterReadPort:
            case OperationKind::kLatchReadPort:
                return 4 + changedValueEffectLines;
            case OperationKind::kMemoryReadPort:
                return 6 + changedValueEffectLines;
            case OperationKind::kRegisterWritePort:
            case OperationKind::kLatchWritePort:
            case OperationKind::kMemoryWritePort:
                return 7;
            case OperationKind::kSystemTask:
            case OperationKind::kDpicCall:
                return 10;
            case OperationKind::kAssign:
            case OperationKind::kAdd:
            case OperationKind::kSub:
            case OperationKind::kMul:
            case OperationKind::kDiv:
            case OperationKind::kMod:
            case OperationKind::kAnd:
            case OperationKind::kOr:
            case OperationKind::kXor:
            case OperationKind::kXnor:
            case OperationKind::kNot:
            case OperationKind::kEq:
            case OperationKind::kNe:
            case OperationKind::kCaseEq:
            case OperationKind::kCaseNe:
            case OperationKind::kWildcardEq:
            case OperationKind::kWildcardNe:
            case OperationKind::kLt:
            case OperationKind::kLe:
            case OperationKind::kGt:
            case OperationKind::kGe:
            case OperationKind::kLogicAnd:
            case OperationKind::kLogicOr:
            case OperationKind::kLogicNot:
            case OperationKind::kReduceAnd:
            case OperationKind::kReduceNand:
            case OperationKind::kReduceOr:
            case OperationKind::kReduceNor:
            case OperationKind::kReduceXor:
            case OperationKind::kReduceXnor:
            case OperationKind::kShl:
            case OperationKind::kLShr:
            case OperationKind::kAShr:
            case OperationKind::kMux:
            case OperationKind::kConcat:
            case OperationKind::kReplicate:
            case OperationKind::kSliceStatic:
            case OperationKind::kSliceDynamic:
            case OperationKind::kSliceArray:
            case OperationKind::kSystemFunction:
                return (opNeedsWordLogicEmit(graph, op) ? 8 : 5) + changedValueEffectLines;
            default:
                return 2;
            }
        }

        std::size_t estimateSupernodeEmitLines(const Graph &graph,
                                               const EmitModel &model,
                                               const ActivityScheduleValueFanout &valueFanout,
                                               const ActivityScheduleSupernodeToOps &supernodeToOps,
                                               uint32_t supernodeId)
        {
            std::size_t total = 8;
            if (supernodeId >= supernodeToOps.size())
            {
                return total;
            }
            for (OperationId opId : supernodeToOps[supernodeId])
            {
                total += estimateOperationEmitLines(
                    graph, model, valueFanout, supernodeId, opId, graph.getOperation(opId));
            }
            return total;
        }

        std::vector<ScheduleBatch> buildScheduleBatches(const Graph &graph,
                                                        const EmitModel &model,
                                                        const ScheduleRefs &schedule,
                                                        const std::vector<uint32_t> &orderedSupernodeIds,
                                                        const std::vector<std::size_t> &activeIdBySupernode,
                                                        ScheduleBatch::Phase phase,
                                                        std::size_t batchMaxOps,
                                                        std::size_t batchMaxEstimatedLines,
                                                        std::size_t targetBatchCount)
        {
            struct ActiveWordSummary
            {
                std::size_t activeFlagWordIndex = 0;
                std::size_t estimatedLines = 0;
                std::size_t opCount = 0;
                std::vector<uint32_t> supernodeIds;
            };

            std::vector<ActiveWordSummary> activeWords;
            activeWords.reserve((orderedSupernodeIds.size() + kActiveFlagBitsPerWord - 1u) / kActiveFlagBitsPerWord);
            for (uint32_t supernodeId : orderedSupernodeIds)
            {
                if (supernodeId >= activeIdBySupernode.size() || activeIdBySupernode[supernodeId] == kInvalidIndex)
                {
                    continue;
                }
                const std::size_t activeWordIndex = activeIdBySupernode[supernodeId] / kActiveFlagBitsPerWord;
                const std::size_t supernodeOps =
                    supernodeId < schedule.supernodeToOps.size() ? schedule.supernodeToOps[supernodeId].size() : 0;
                const std::size_t supernodeLines =
                    estimateSupernodeEmitLines(graph, model, schedule.valueFanout, schedule.supernodeToOps, supernodeId);
                if (phase == ScheduleBatch::Phase::kCommit ||
                    activeWords.empty() ||
                    activeWords.back().activeFlagWordIndex != activeWordIndex)
                {
                    activeWords.push_back(ActiveWordSummary{.activeFlagWordIndex = activeWordIndex});
                }
                auto &word = activeWords.back();
                word.supernodeIds.push_back(supernodeId);
                word.opCount += supernodeOps;
                word.estimatedLines += supernodeLines;
            }

            std::size_t effectiveMaxOps = batchMaxOps;
            std::size_t effectiveMaxLines = batchMaxEstimatedLines;
            if (targetBatchCount > 0 && !activeWords.empty())
            {
                std::size_t totalOps = 0;
                std::size_t totalLines = 0;
                for (const auto &word : activeWords)
                {
                    totalOps += word.opCount;
                    totalLines += word.estimatedLines;
                }
                const std::size_t dynamicMaxOps = totalOps / targetBatchCount;
                const std::size_t dynamicMaxLines = totalLines / targetBatchCount;
                effectiveMaxOps = std::max(effectiveMaxOps, dynamicMaxOps);
                effectiveMaxLines = std::max(effectiveMaxLines, dynamicMaxLines);
            }

            std::vector<ScheduleBatch> batches;
            ScheduleBatch current;
            current.phase = phase;
            auto flushCurrent = [&]()
            {
                if (current.words.empty())
                {
                    return;
                }
                current.index = batches.size();
                batches.push_back(std::move(current));
                current = ScheduleBatch{};
                current.phase = phase;
            };

            for (const auto &word : activeWords)
            {
                const bool exceedsMaxOps =
                    effectiveMaxOps != 0u && !current.words.empty() && (current.opCount + word.opCount) > effectiveMaxOps;
                const bool exceedsMaxEstimatedLines =
                    effectiveMaxLines != 0u && !current.words.empty() &&
                    (current.estimatedLines + word.estimatedLines) > effectiveMaxLines;
                if (exceedsMaxOps || exceedsMaxEstimatedLines)
                {
                    flushCurrent();
                }
                current.words.push_back(
                    ScheduleBatch::Word{.activeFlagWordIndex = word.activeFlagWordIndex,
                                        .estimatedLines = word.estimatedLines,
                                        .opCount = word.opCount,
                                        .supernodeIds = word.supernodeIds});
                current.supernodeIds.insert(
                    current.supernodeIds.end(), word.supernodeIds.begin(), word.supernodeIds.end());
                current.opCount += word.opCount;
                current.estimatedLines += word.estimatedLines;
            }
            flushCurrent();
            return batches;
        }

        void appendSupernodePatternValueSignature(
            std::ostringstream &out,
            const Graph &graph,
            ValueId value,
            const std::unordered_map<ValueId, std::size_t, ValueIdHash> &localValueOrdinal)
        {
            const auto appendValueShape = [&]()
            {
                switch (graph.valueType(value))
                {
                case ValueType::Logic:
                    out << "logic:" << graph.valueWidth(value) << ':' << (graph.valueSigned(value) ? 's' : 'u');
                    break;
                case ValueType::Real:
                    out << "real";
                    break;
                case ValueType::String:
                    out << "string";
                    break;
                }
            };

            appendValueShape();
            if (const auto it = localValueOrdinal.find(value); it != localValueOrdinal.end())
            {
                out << "@local:" << it->second;
                return;
            }

            const OperationId defOpId = graph.valueDef(value);
            if (!defOpId.valid())
            {
                out << "@input";
                return;
            }

            const Operation defOp = graph.getOperation(defOpId);
            if (defOp.kind() == OperationKind::kConstant)
            {
                out << "@const";
                if (const auto literal = getAttribute<std::string>(defOp, "constValue"))
                {
                    out << ':' << *literal;
                }
                return;
            }
            if (isReadRootOpKind(defOp.kind()))
            {
                out << "@root:" << readRootText(graph, defOp);
                return;
            }
            out << "@ext:" << toString(defOp.kind());
        }

        std::string buildSupernodePatternSignature(const Graph &graph,
                                                   const ActivityScheduleValueFanout &valueFanout,
                                                   const ActivityScheduleSupernodeToOps &supernodeToOps,
                                                   uint32_t supernodeId)
        {
            if (supernodeId >= supernodeToOps.size())
            {
                return "invalid-supernode";
            }

            std::ostringstream out;
            out << "ops=" << supernodeToOps[supernodeId].size();
            std::unordered_map<ValueId, std::size_t, ValueIdHash> localValueOrdinal;
            std::size_t nextLocalValueOrdinal = 0;
            for (OperationId opId : supernodeToOps[supernodeId])
            {
                const Operation op = graph.getOperation(opId);
                out << "|op:" << toString(op.kind());
                out << ":in=" << op.operands().size();
                for (ValueId operand : op.operands())
                {
                    out << '[';
                    appendSupernodePatternValueSignature(out, graph, operand, localValueOrdinal);
                    out << ']';
                }
                out << ":out=" << op.results().size();
                for (ValueId result : op.results())
                {
                    const std::size_t fanout =
                        result.valid() && result.index > 0u && (result.index - 1u) < valueFanout.size()
                            ? valueFanout[result.index - 1u].size()
                            : 0u;
                    out << '[';
                    switch (graph.valueType(result))
                    {
                    case ValueType::Logic:
                        out << "logic:" << graph.valueWidth(result) << ':'
                            << (graph.valueSigned(result) ? 's' : 'u');
                        break;
                    case ValueType::Real:
                        out << "real";
                        break;
                    case ValueType::String:
                        out << "string";
                        break;
                    }
                    out << ":fanout=" << fanout;
                    out << ']';
                    localValueOrdinal.emplace(result, nextLocalValueOrdinal++);
                }
            }
            return out.str();
        }

        void markRepeatedPatternScheduleBatches(const Graph &graph,
                                                const EmitModel &model,
                                                const ScheduleRefs &schedule,
                                                std::vector<ScheduleBatch> &scheduleBatches)
        {
            (void)model;
            (void)graph;
            (void)schedule;
            (void)scheduleBatches;
        }

        bool opNeedsWordLogicEmit(const Graph &graph, const Operation &op) noexcept
        {
            for (ValueId value : op.operands())
            {
                if (isWideLogicValue(graph, value))
                {
                    return true;
                }
            }
            for (ValueId value : op.results())
            {
                if (isWideLogicValue(graph, value))
                {
                    return true;
                }
            }
            return false;
        }

        std::string castWordsExprForValue(const Graph &graph,
                                          ValueId value,
                                          const std::string &expr,
                                          int32_t destWidth)
        {
            const int32_t srcWidth = graph.valueWidth(value);
            if (graph.valueType(value) == ValueType::Logic &&
                isWideLogicValue(graph, value) &&
                srcWidth == destWidth)
            {
                return expr;
            }

            const std::size_t destWords = logicWordCount(destWidth);
            if (graph.valueType(value) == ValueType::Logic && isWideLogicValue(graph, value))
            {
                (void)destWords;
                return castWideWordsInlineExpr(expr, srcWidth, destWidth, graph.valueSigned(value));
            }
            (void)destWords;
            return castScalarWordsInlineExpr(expr, srcWidth, destWidth, graph.valueSigned(value));
        }

        std::string wordsExprForValue(const Graph &graph,
                                      const EmitModel &model,
                                      ValueId value,
                                      int32_t destWidth)
        {
            return castWordsExprForValue(graph, value, valueRef(model, value), destWidth);
        }

        std::string wordsExprForValue(const Graph &graph,
                                      const EmitModel &model,
                                      ValueId value,
                                      int32_t destWidth,
                                      const SupernodeLocalExprContext *context)
        {
            return castWordsExprForValue(graph, value, resolvedScheduleValueExpr(model, value, context), destWidth);
        }

        std::string sliceWordsExpr(const std::string &srcExpr,
                                   int32_t srcWidth,
                                   const std::string &startExpr,
                                   int32_t resultWidth)
        {
            const std::size_t destWords = logicWordCount(resultWidth);
            (void)srcWidth;
            std::ostringstream out;
            out << "grhsim_slice_words<" << destWords << ">((" << srcExpr << "), "
                << "static_cast<std::size_t>(" << startExpr << "), "
                << resultWidth << ")";
            return out.str();
        }

        std::string unaryWordsBufferOpExpr(const std::string &valueExpr,
                                           int32_t resultWidth,
                                           std::string_view helperName)
        {
            std::ostringstream out;
            if (canUseFullWidthWordsHelper(resultWidth) && isFullWidthUnaryWordsHelper(helperName))
            {
                out << helperName << "_full<" << logicWordCount(resultWidth) << ">(" << valueExpr << ")";
            }
            else
            {
                out << helperName << "(" << valueExpr << ", " << resultWidth << ")";
            }
            return out.str();
        }

        std::string binaryWordsBufferOpExpr(const std::string &lhsExpr,
                                            const std::string &rhsExpr,
                                            int32_t resultWidth,
                                            std::string_view helperName)
        {
            std::ostringstream out;
            if (canUseFullWidthWordsHelper(resultWidth) && isFullWidthBinaryWordsHelper(helperName))
            {
                out << helperName << "_full<" << logicWordCount(resultWidth) << ">("
                    << lhsExpr << ", " << rhsExpr << ")";
            }
            else
            {
                out << helperName << "(" << lhsExpr << ", " << rhsExpr << ", " << resultWidth << ")";
            }
            return out.str();
        }

        std::string shiftWordsBufferOpExpr(const std::string &valueExpr,
                                           const std::string &shiftExpr,
                                           int32_t resultWidth,
                                           std::string_view helperName)
        {
            std::ostringstream out;
            out << helperName << "(" << valueExpr << ", " << shiftExpr << ", " << resultWidth << ")";
            return out.str();
        }

        std::string muxWordsExpr(const std::string &condExpr,
                                 const std::string &trueExpr,
                                 const std::string &falseExpr,
                                 int32_t resultWidth)
        {
            const std::size_t destWords = logicWordCount(resultWidth);
            std::ostringstream out;
            out << "grhsim_mux_words<" << destWords << ">(static_cast<std::uint64_t>(" << condExpr << "), "
                << trueExpr << ", " << falseExpr << ", " << resultWidth << ")";
            return out.str();
        }

        std::string unaryWordsBoolExpr(const std::string &valueExpr,
                                       int32_t width,
                                       std::string_view helperName)
        {
            return std::string(helperName) + "(" + valueExpr + ", " + std::to_string(width) + ")";
        }

        std::string binaryWordsCompareExpr(const std::string &lhsExpr,
                                           const std::string &rhsExpr,
                                           std::string_view helperName)
        {
            return std::string(helperName) + "(" + lhsExpr + ", " + rhsExpr + ")";
        }

        std::string binaryWordsSignedCompareExpr(const std::string &lhsExpr,
                                                 const std::string &rhsExpr,
                                                 int32_t width)
        {
            return "grhsim_compare_signed_words(" + lhsExpr + ", " + rhsExpr + ", " + std::to_string(width) + ")";
        }

        std::string concatWordsExpr(const std::vector<std::string> &operandWordExprs,
                                    const std::vector<int32_t> &operandWidths,
                                    int32_t resultWidth)
        {
            if (operandWordExprs.empty())
            {
                return wordsArrayTypeForWidth(resultWidth) + "{}";
            }
            std::string expr = operandWordExprs.back();
            int32_t accumWidth = operandWidths.back();
            for (std::size_t i = operandWordExprs.size() - 1; i-- > 0;)
            {
                const int32_t operandWidth = operandWidths[i];
                expr = concatTwoWordsInlineExpr(
                    operandWordExprs[i], operandWidth, expr, accumWidth, operandWidth + accumWidth);
                accumWidth += operandWidth;
            }
            return expr;
        }

        std::string replicateWordsExpr(const std::string &valueExpr,
                                       int32_t operandWidth,
                                       int32_t resultWidth,
            std::size_t rep)
        {
            if (operandWidth == 1 && resultWidth > 0 && rep == static_cast<std::size_t>(resultWidth))
            {
                std::ostringstream out;
                out << "grhsim_replicate_bit_words<" << logicWordCount(resultWidth) << ", "
                    << resultWidth << ">(" << valueExpr << ")";
                return out.str();
            }
            if (logicWordCount(resultWidth) == 2 && logicWordCount(operandWidth) == 1)
            {
                std::ostringstream out;
                out << "grhsim_replicate_words_2_1<" << operandWidth << ", "
                    << rep << ", "
                    << resultWidth << ">(" << valueExpr << ")";
                return out.str();
            }
            std::ostringstream out;
            out << "grhsim_replicate_words<" << logicWordCount(resultWidth) << ">("
                << valueExpr << ", "
                << operandWidth << ", "
                << rep << ", "
                << resultWidth << ")";
            return out.str();
        }

        bool tryRecordSupernodeInlineExpr(const Graph &graph,
                                          const EmitModel &model,
                                          ValueId resultValue,
                                          const std::string &expr,
                                          SupernodeLocalExprKind kind,
                                          SupernodeLocalExprContext *context)
        {
            if (context == nullptr || !canInlineSingleUserLocalValue(graph, model, resultValue, expr, kind, context))
            {
                return false;
            }
            context->byValue[resultValue] = SupernodeLocalExpr{
                .expr = expr,
                .kind = kind,
                .width = graph.valueWidth(resultValue),
            };
            return true;
        }

        void recordSupernodeLocalExprRef(const Graph &graph,
                                         ValueId resultValue,
                                         const std::string &expr,
                                         SupernodeLocalExprKind kind,
                                         SupernodeLocalExprContext *context)
        {
            if (context == nullptr)
            {
                return;
            }
            context->byValue[resultValue] = SupernodeLocalExpr{
                .expr = expr,
                .kind = kind,
                .width = graph.valueWidth(resultValue),
            };
        }

        void emitLogicAssignFromWordsExpr(std::ostream &stream,
                                          const Graph &graph,
                                          const EmitModel &model,
                                          ValueId resultValue,
                                          const std::string &wordsExpr,
                                          const SupernodeLocalExprContext *context = nullptr,
                                          const ActivationEmitContext *activationContext = nullptr,
                                          DeferredActivationEmitContext *deferredContext = nullptr)
        {
            const std::string lhs = resolvedStoredValueRefExpr(model, resultValue, context);
            const int32_t resultWidth = graph.valueWidth(resultValue);
            const bool materialized = isMaterializedValue(model, resultValue);
            const bool needChangeDetect = valueNeedsTrackedChange(model, resultValue);
            if (!materialized)
            {
                emitValueAssignmentComment(stream, graph, model, resultValue, "        ");
                if (isWideLogicValue(graph, resultValue))
                {
                    stream << "        const auto " << lhs << " = " << wordsExpr << ";\n";
                }
                else
                {
                    const std::string wordsName = lhs + "_words";
                    stream << "        const auto " << wordsName << " = " << wordsExpr << ";\n";
                    stream << "        const auto " << lhs << " = static_cast<" << cppTypeForValue(graph, resultValue)
                           << ">(grhsim_trunc_u64(" << wordsName << "[0], " << resultWidth << "));\n";
                }
                return;
            }
            emitValueAssignmentComment(stream, graph, model, resultValue, "        ");
            stream << "        {\n";
            stream << "            const auto next_words = " << wordsExpr << ";\n";
            if (isWideLogicValue(graph, resultValue))
            {
                if (needChangeDetect)
                {
                    stream << "            if (" << assignWordsInlineExpr(lhs, "next_words", resultWidth) << ") {\n";
                    emitChangedValuePropagation(stream, model, resultValue, "                ", activationContext);
                    stream << "            }\n";
                }
                else
                {
                    stream << "            " << lhs << " = next_words;\n";
                }
            }
            else
            {
                stream << "            const auto next_value = static_cast<" << cppTypeForValue(graph, resultValue)
                       << ">(grhsim_trunc_u64(next_words[0], " << resultWidth << "));\n";
                if (needChangeDetect)
                {
                    emitScalarChangedValueAssign(
                        stream, model, resultValue, lhs, "next_value", "            ", activationContext, deferredContext);
                }
                else
                {
                    stream << "            " << lhs << " = next_value;\n";
                }
            }
            stream << "        }\n";
        }

        void emitLogicAssignFromWideWordsExpr(std::ostream &stream,
                                             const Graph &graph,
                                             const EmitModel &model,
                                             ValueId resultValue,
                                             const std::string &wordsExpr,
                                             SupernodeLocalExprContext *context,
                                             const ActivationEmitContext *activationContext = nullptr,
                                             DeferredActivationEmitContext *deferredContext = nullptr)
        {
            if (!isMaterializedValue(model, resultValue))
            {
                const std::string lhs = valueRef(model, resultValue);
                if (tryRecordSupernodeInlineExpr(
                        graph, model, resultValue, "(" + wordsExpr + ")", SupernodeLocalExprKind::kWideWords, context))
                {
                    return;
                }
                emitValueAssignmentComment(stream, graph, model, resultValue, "        ");
                stream << "        const auto " << lhs << " = " << wordsExpr << ";\n";
                recordSupernodeLocalExprRef(graph, resultValue, lhs, SupernodeLocalExprKind::kWideWords, context);
                return;
            }
            emitLogicAssignFromWordsExpr(
                stream, graph, model, resultValue, wordsExpr, context, activationContext, deferredContext);
        }

        void emitLogicAssignFromBoolExpr(std::ostream &stream,
                                         const Graph &graph,
                                         const EmitModel &model,
                                         ValueId resultValue,
                                         const std::string &boolExpr,
                                         SupernodeLocalExprContext *context = nullptr,
                                         const ActivationEmitContext *activationContext = nullptr,
                                         DeferredActivationEmitContext *deferredContext = nullptr)
        {
            const std::string lhs = resolvedStoredValueRefExpr(model, resultValue, context);
            if (!isMaterializedValue(model, resultValue))
            {
                if (tryRecordSupernodeInlineExpr(graph,
                                                 model,
                                                 resultValue,
                                                 "static_cast<" + cppTypeForValue(graph, resultValue) + ">(" + boolExpr + ")",
                                                 SupernodeLocalExprKind::kScalarInline,
                                                 context))
                {
                    return;
                }
                emitValueAssignmentComment(stream, graph, model, resultValue, "        ");
                stream << "        const auto " << lhs << " = static_cast<" << cppTypeForValue(graph, resultValue)
                       << ">(" << boolExpr << ");\n";
                return;
            }
            const bool needChangeDetect = valueNeedsTrackedChange(model, resultValue);
            emitValueAssignmentComment(stream, graph, model, resultValue, "        ");
            stream << "        {\n";
            stream << "            const auto next_value = static_cast<" << cppTypeForValue(graph, resultValue)
                   << ">(" << boolExpr << ");\n";
            if (needChangeDetect)
            {
                emitScalarChangedValueAssign(
                    stream, model, resultValue, lhs, "next_value", "            ", activationContext, deferredContext);
            }
            else
            {
                stream << "            " << lhs << " = next_value;\n";
            }
            stream << "        }\n";
        }

        void emitLogicAssignFromScalarExpr(std::ostream &stream,
                                           const Graph &graph,
                                           const EmitModel &model,
                                           ValueId resultValue,
                                           const std::string &expr,
                                           bool alreadyBoundedToResultWidth,
                                           SupernodeLocalExprContext *context = nullptr,
                                           const ActivationEmitContext *activationContext = nullptr,
                                           DeferredActivationEmitContext *deferredContext = nullptr,
                                           bool byteBitResult = false)
        {
            const std::string lhs = resolvedStoredValueRefExpr(model, resultValue, context);
            const std::string assignedExpr =
                renderScalarAssignedExpr(graph, resultValue, expr, alreadyBoundedToResultWidth, byteBitResult);
            const std::string cppType = byteBitResult ? "std::uint8_t" : cppTypeForValue(graph, resultValue);
            const std::string initializerExpr = scalarTypedInitializerExpr(graph, resultValue, assignedExpr);
            const bool materialized = isMaterializedValue(model, resultValue);
            if (!materialized)
            {
                if (tryRecordSupernodeInlineExpr(graph,
                                                 model,
                                                 resultValue,
                                                 assignedExpr,
                                                 SupernodeLocalExprKind::kScalarInline,
                                                 context))
                {
                    return;
                }
                emitValueAssignmentComment(stream, graph, model, resultValue, "        ");
                stream << "        const " << cppType << " " << lhs << " = " << initializerExpr << ";\n";
                return;
            }

            const bool needChangeDetect = valueNeedsTrackedChange(model, resultValue);
            emitValueAssignmentComment(stream, graph, model, resultValue, "        ");
            stream << "        {\n";
            stream << "            const " << cppType << " next_value = " << initializerExpr << ";\n";
            if (needChangeDetect)
            {
                emitScalarChangedValueAssign(
                    stream, model, resultValue, lhs, "next_value", "            ", activationContext, deferredContext);
            }
            else
            {
                stream << "            " << lhs << " = next_value;\n";
            }
            stream << "        }\n";
        }

        bool concatAllOperandsAreOneBit(const Graph &graph, const Operation &op)
        {
            if (op.operands().empty())
            {
                return false;
            }
            for (ValueId operand : op.operands())
            {
                if (graph.valueWidth(operand) != 1)
                {
                    return false;
                }
            }
            return true;
        }

        bool concatAllOperandsAreScalarLogic(const Graph &graph, const Operation &op)
        {
            if (op.kind() != OperationKind::kConcat || op.operands().empty())
            {
                return false;
            }
            for (ValueId operand : op.operands())
            {
                if (!isScalarLogicValue(graph, operand))
                {
                    return false;
                }
            }
            return true;
        }

        std::optional<int32_t> concatUniformOperandWidth(const Graph &graph, const Operation &op)
        {
            if (op.operands().empty())
            {
                return std::nullopt;
            }
            const int32_t width = graph.valueWidth(op.operands().front());
            for (ValueId operand : op.operands())
            {
                if (graph.valueWidth(operand) != width)
                {
                    return std::nullopt;
                }
            }
            return width;
        }

        bool preferLoopedScalarConcatEmit(const Graph &graph, const Operation &op)
        {
            return concatAllOperandsAreScalarLogic(graph, op) && op.operands().size() >= 4;
        }

        std::string scalarConcatValueArrayExpr(const std::vector<std::string> &operands)
        {
            std::vector<std::string> items;
            items.reserve(operands.size());
            for (const auto &operand : operands)
            {
                items.push_back(scalarCastOperandExpr(operand));
            }
            return "std::array<std::uint64_t, " + std::to_string(operands.size()) + ">{" +
                   joinStrings(items, ", ") + "}";
        }

        std::string scalarConcatWidthArrayExpr(const Graph &graph, const Operation &op)
        {
            std::vector<std::string> items;
            items.reserve(op.operands().size());
            for (ValueId operand : op.operands())
            {
                items.push_back(std::to_string(graph.valueWidth(operand)));
            }
            return "std::array<std::size_t, " + std::to_string(op.operands().size()) + ">{" +
                   joinStrings(items, ", ") + "}";
        }

        std::string scalarDirectConcatExpr(const Graph &graph,
                                           const Operation &op,
                                           const std::vector<std::string> &operands)
        {
            if (operands.empty())
            {
                return "UINT64_C(0)";
            }
            std::vector<std::string> terms;
            terms.reserve(operands.size());
            std::size_t lsbOffset = 0;
            for (std::size_t i = 0; i < operands.size(); ++i)
            {
                const std::size_t operandIndex = operands.size() - i - 1;
                const std::size_t width = static_cast<std::size_t>(graph.valueWidth(op.operands()[operandIndex]));
                if (width == 0)
                {
                    continue;
                }
                std::string term = scalarTruncExpr(maskedScalarBitsExpr(operands[operandIndex]), width);
                if (lsbOffset != 0)
                {
                    term = "((" + scalarCastOperandExpr(term) + ") << " + std::to_string(lsbOffset) + ")";
                }
                lsbOffset += width;
                terms.push_back(std::move(term));
            }
            std::reverse(terms.begin(), terms.end());
            if (terms.empty())
            {
                return "UINT64_C(0)";
            }
            return "(" + joinStrings(terms, " | ") + ")";
        }

        std::uint64_t scalarRepeatPattern(std::size_t elemWidth, std::size_t rep)
        {
            if (elemWidth == 0 || rep == 0)
            {
                return 0;
            }
            std::uint64_t pattern = 0;
            for (std::size_t i = 0; i < rep; ++i)
            {
                const std::size_t shift = i * elemWidth;
                if (shift >= 64)
                {
                    break;
                }
                pattern |= (UINT64_C(1) << shift);
            }
            return pattern;
        }

        std::string scalarDirectReplicateExpr(const std::string &operand,
                                              std::size_t elemWidth,
                                              std::size_t rep,
                                              std::size_t resultWidth)
        {
            if (elemWidth == 0 || rep == 0 || resultWidth == 0)
            {
                return "UINT64_C(0)";
            }
            const std::string elem = scalarTruncExpr(maskedScalarBitsExpr(operand), elemWidth);
            if (elemWidth == 1)
            {
                return "((" + elem + ") ? " + scalarMaskExpr(resultWidth) + " : UINT64_C(0))";
            }
            const std::uint64_t pattern = scalarRepeatPattern(elemWidth, rep);
            return scalarTruncExpr("((" + elem + ") * UINT64_C(" + std::to_string(pattern) + "))", resultWidth);
        }

        std::string scalarWideConcatLoopExpr(const Graph &graph,
                                             const Operation &op,
                                             const std::vector<std::string> &operands)
        {
            const std::string valuesExpr = scalarConcatValueArrayExpr(operands);
            const auto uniformWidth = concatUniformOperandWidth(graph, op);
            const int32_t resultWidth =
                op.results().empty() ? 0 : graph.valueWidth(op.results().front());
            if (uniformWidth)
            {
                std::ostringstream out;
                out << "grhsim_concat_uniform_scalars_words<" << logicWordCount(resultWidth) << ">("
                    << valuesExpr << ", "
                    << *uniformWidth << ", "
                    << resultWidth << ")";
                return out.str();
            }
            const std::string widthsExpr = scalarConcatWidthArrayExpr(graph, op);
            std::ostringstream out;
            out << "grhsim_concat_scalars_words<" << logicWordCount(resultWidth) << ">("
                << valuesExpr << ", "
                << widthsExpr << ", "
                << resultWidth << ")";
            return out.str();
        }

        bool shouldEmitDirectWideConcatFastPath(const Graph &graph,
                                                const EmitModel &model,
                                                const Operation &op,
                                                ValueId resultValue)
        {
            if (op.kind() != OperationKind::kConcat || !isWideLogicValue(graph, resultValue))
            {
                return false;
            }
            if (isEventValue(model, resultValue))
            {
                return false;
            }
            return graph.valueWidth(resultValue) >= 96 && op.operands().size() >= 4;
        }

        void emitWideConcatInsertStatements(std::ostream &stream,
                                            const Graph &graph,
                                            ValueId operandValue,
                                            const std::string &operandExpr,
                                            std::string_view indent,
                                            std::string_view dstName,
                                            int32_t operandWidth,
                                            std::size_t lsbOffset,
                                            std::size_t operandIndex,
                                            std::size_t tempScopeId)
        {
            if (operandWidth <= 0)
            {
                return;
            }

            const std::size_t baseWord = lsbOffset / 64u;
            const std::size_t bitShift = lsbOffset & 63u;
            if (isWideLogicValue(graph, operandValue))
            {
                const std::size_t srcWords = logicWordCount(operandWidth);
                const std::string namePrefix =
                    "concat_" + std::to_string(tempScopeId) + "_" + std::to_string(operandIndex);
                const std::string srcName = namePrefix + "_src";
                stream << indent << "const auto &" << srcName << " = " << operandExpr << ";\n";
                for (std::size_t wordIndex = 0; wordIndex < srcWords; ++wordIndex)
                {
                    const std::size_t wordLsb = wordIndex * 64u;
                    const std::size_t remainingBits = static_cast<std::size_t>(operandWidth) > wordLsb
                                                          ? static_cast<std::size_t>(operandWidth) - wordLsb
                                                          : 0u;
                    if (remainingBits == 0u)
                    {
                        break;
                    }
                    const std::size_t wordWidth = std::min<std::size_t>(remainingBits, 64u);
                    const std::string bitsName = namePrefix + "_bits_" + std::to_string(wordIndex);
                    stream << indent << "const std::uint64_t " << bitsName << " = ";
                    if (wordWidth >= 64u)
                    {
                        stream << srcName << "[" << wordIndex << "]";
                    }
                    else
                    {
                        stream << scalarTruncExpr(srcName + "[" + std::to_string(wordIndex) + "]", wordWidth);
                    }
                    stream << ";\n";
                    stream << indent << dstName << "[" << (baseWord + wordIndex) << "] |= ";
                    if (bitShift == 0u)
                    {
                        stream << bitsName;
                    }
                    else
                    {
                        stream << "(" << bitsName << " << " << bitShift << "u)";
                    }
                    stream << ";\n";
                    if (bitShift != 0u && wordWidth + bitShift > 64u)
                    {
                        stream << indent << dstName << "[" << (baseWord + wordIndex + 1u) << "] |= (" << bitsName
                               << " >> " << (64u - bitShift) << "u);\n";
                    }
                }
                return;
            }

            const std::string bitsName =
                "concat_" + std::to_string(tempScopeId) + "_" + std::to_string(operandIndex) + "_bits_0";
            stream << indent << "const std::uint64_t " << bitsName << " = "
                   << scalarTruncExpr(scalarCastOperandExpr(operandExpr), static_cast<std::size_t>(operandWidth))
                   << ";\n";
            stream << indent << dstName << "[" << baseWord << "] |= ";
            if (bitShift == 0u)
            {
                stream << bitsName;
            }
            else
            {
                stream << "(" << bitsName << " << " << bitShift << "u)";
            }
            stream << ";\n";
            if (bitShift != 0u && static_cast<std::size_t>(operandWidth) + bitShift > 64u)
            {
                stream << indent << dstName << "[" << (baseWord + 1u) << "] |= (" << bitsName << " >> "
                       << (64u - bitShift) << "u);\n";
            }
        }

        bool emitDirectWideConcatOperation(std::ostream &stream,
                                           const Graph &graph,
                                           const EmitModel &model,
                                           const Operation &op,
                                           SupernodeLocalExprContext *context = nullptr,
                                           const ActivationEmitContext *activationContext = nullptr,
                                           DeferredActivationEmitContext *deferredContext = nullptr)
        {
            if (op.results().empty())
            {
                return true;
            }
            const ValueId resultValue = op.results().front();
            if (!shouldEmitDirectWideConcatFastPath(graph, model, op, resultValue))
            {
                return false;
            }

            const int32_t resultWidth = graph.valueWidth(resultValue);
            const std::size_t tempScopeId = resultValue.index;
            const std::string lhs = resolvedStoredValueRefExpr(model, resultValue, context);
            const bool materialized = isMaterializedValue(model, resultValue);
            const bool needsActivation = valueNeedsChangeDetect(model, resultValue);
            const auto operands = op.operands();
            std::vector<std::string> operandExprs;
            operandExprs.reserve(operands.size());
            for (ValueId operand : operands)
            {
                operandExprs.push_back(resolvedScheduleValueExpr(model, operand, context));
            }

            emitValueAssignmentComment(stream, graph, model, resultValue, "        ");
            if (!materialized)
            {
                stream << "        " << wordsArrayTypeForWidth(resultWidth) << " " << lhs << "{};\n";
            }
            else
            {
                stream << "        " << lhs << " = " << wordsArrayTypeForWidth(resultWidth) << "{};\n";
            }
            std::size_t cursor = static_cast<std::size_t>(resultWidth);
            for (std::size_t operandIndex = 0; operandIndex < operands.size(); ++operandIndex)
            {
                const int32_t operandWidth = graph.valueWidth(operands[operandIndex]);
                if (operandWidth <= 0)
                {
                    continue;
                }
                if (static_cast<std::size_t>(operandWidth) > cursor)
                {
                    cursor = 0u;
                    continue;
                }
                cursor -= static_cast<std::size_t>(operandWidth);
                emitWideConcatInsertStatements(stream,
                                               graph,
                                               operands[operandIndex],
                                               operandExprs[operandIndex],
                                               "        ",
                                               lhs,
                                               operandWidth,
                                               cursor,
                                               operandIndex,
                                               tempScopeId);
            }
            emitWordsTailTruncationStatements(stream, "        ", lhs, resultWidth);
            if (materialized)
            {
                if (needsActivation)
                {
                    emitChangedValuePropagation(stream, model, resultValue, "        ", activationContext);
                }
            }
            else
            {
                recordSupernodeLocalExprRef(graph, resultValue, lhs, SupernodeLocalExprKind::kWideWords, context);
            }
            return true;
        }

        std::string packedArrayLaneRefExpr(const EmitModel &model,
                                           const PackedArrayLaneView &view,
                                           const SupernodeLocalExprContext *context = nullptr)
        {
            return resolvedStoredValueRefExpr(model, view.value, context);
        }

        bool emitPackedArrayLaneConcatOperation(std::ostream &stream,
                                                const Graph &graph,
                                                const EmitModel &model,
                                                const Operation &op,
                                                SupernodeLocalExprContext *context = nullptr,
                                                const ActivationEmitContext *activationContext = nullptr)
        {
            if (op.results().empty())
            {
                return false;
            }
            const ValueId sourceValue = op.results().front();
            const PackedArrayLaneView *view = packedArrayLaneViewForSourceValue(model, sourceValue);
            if (view == nullptr || view->concatOp != graph.valueDef(sourceValue) || op.kind() != OperationKind::kConcat)
            {
                return false;
            }

            const bool materialized = isMaterializedValue(model, view->value);
            const std::string lanes = packedArrayLaneRefExpr(model, *view, context);
            const std::string storageType = packedArrayLaneStorageType(*view);
            const std::string laneType = packedArrayLaneCppType(*view);
            emitValueAssignmentComment(stream, graph, model, view->value, "        ");
            if (!materialized)
            {
                stream << "        " << storageType << " " << lanes << "{};\n";
            }
            else
            {
                stream << "        " << lanes << " = " << storageType << "{};\n";
            }

            const auto operands = op.operands();
            for (std::size_t operandIndex = 0; operandIndex < operands.size(); ++operandIndex)
            {
                const ValueId operand = operands[operandIndex];
                const std::string operandExpr = resolvedScheduleValueExpr(model, operand, context);
                const std::size_t laneIndex = view->laneByOperand[operandIndex];
                stream << "        " << lanes << "[" << laneIndex << "] = static_cast<" << laneType << ">("
                       << scalarTruncExpr(scalarCastOperandExpr(operandExpr),
                                          static_cast<std::size_t>(view->elementWidth))
                       << ");\n";
            }
            if (materialized && view->sourceValue == view->value && valueNeedsChangeDetect(model, view->value))
            {
                emitChangedValuePropagation(stream, model, view->value, "        ", activationContext);
            }
            return true;
        }

        bool emitPackedArrayLaneAssignOperation(std::ostream &stream,
                                                const Graph &graph,
                                                const EmitModel &model,
                                                const Operation &op,
                                                SupernodeLocalExprContext *context = nullptr,
                                                const ActivationEmitContext *activationContext = nullptr)
        {
            if (op.kind() != OperationKind::kAssign || op.results().empty())
            {
                return false;
            }
            const ValueId resultValue = op.results().front();
            const PackedArrayLaneView *view = packedArrayLaneViewForValue(model, resultValue);
            if (view == nullptr || view->defOp != graph.valueDef(resultValue))
            {
                return false;
            }
            (void)stream;
            (void)context;
            if (isMaterializedValue(model, resultValue) && valueNeedsChangeDetect(model, resultValue))
            {
                emitChangedValuePropagation(stream, model, resultValue, "        ", activationContext);
            }
            return true;
        }

        std::optional<std::string> packedArrayLaneSliceExpr(const Graph &graph,
                                                            const EmitModel &model,
                                                            const Operation &op,
                                                            const PackedArrayLaneView &view,
                                                            const std::string &indexExpr,
                                                            const SupernodeLocalExprContext *context = nullptr)
        {
            if (!sliceArrayUsesPackedArrayLaneView(graph, view, op))
            {
                return std::nullopt;
            }
            const ValueId resultValue = op.results().front();
            const std::string cppType = cppTypeForValue(graph, resultValue);
            const std::string lanes = packedArrayLaneRefExpr(model, view, context);
            const std::string rawIndex = indexExpr;
            return "((" + rawIndex + " < " + std::to_string(view.elementCount) +
                   "u) ? " + lanes + "[" + rawIndex + "] : " + cppType + "{})";
        }

        bool emitPackedArrayLaneSliceOperation(std::ostream &stream,
                                               const Graph &graph,
                                               const EmitModel &model,
                                               const Operation &op,
                                               SupernodeLocalExprContext *context = nullptr,
                                               const ActivationEmitContext *activationContext = nullptr,
                                               DeferredActivationEmitContext *deferredContext = nullptr)
        {
            if (op.kind() != OperationKind::kSliceArray || op.operands().size() != 2 || op.results().empty())
            {
                return false;
            }
            const ValueId baseValue = op.operands().front();
            const PackedArrayLaneView *view = packedArrayLaneViewForValue(model, baseValue);
            if (view == nullptr)
            {
                return false;
            }
            const ValueId resultValue = op.results().front();
            const std::string indexName = "packed_array_idx_" + std::to_string(resultValue.index);
            const std::string indexExpr = resolvedScheduleValueExpr(model, op.operands()[1], context);
            const auto expr = packedArrayLaneSliceExpr(graph, model, op, *view, indexName, context);
            if (!expr)
            {
                return false;
            }
            stream << "        const std::size_t " << indexName << " = static_cast<std::size_t>(" << indexExpr << ");\n";
            emitLogicAssignFromScalarExpr(stream,
                                          graph,
                                          model,
                                          resultValue,
                                          *expr,
                                          false,
                                          context,
                                          activationContext,
                                          deferredContext);
            return true;
        }

        struct ScalarConcatPrefixCacheKey
        {
            ValueId lhs;
            int32_t lhsWidth = 0;
            int32_t rhsWidth = 0;

            friend bool operator==(const ScalarConcatPrefixCacheKey &lhsKey,
                                   const ScalarConcatPrefixCacheKey &rhsKey) noexcept
            {
                return lhsKey.lhs == rhsKey.lhs &&
                       lhsKey.lhsWidth == rhsKey.lhsWidth &&
                       lhsKey.rhsWidth == rhsKey.rhsWidth;
            }
        };

        struct ScalarConcatPrefixCacheKeyHash
        {
            std::size_t operator()(const ScalarConcatPrefixCacheKey &key) const noexcept
            {
                std::size_t seed = ValueIdHash{}(key.lhs);
                seed = seed * 1315423911u + static_cast<std::size_t>(key.lhsWidth);
                seed = seed * 1315423911u + static_cast<std::size_t>(key.rhsWidth);
                return seed;
            }
        };

        struct ScalarConcatPrefixCacheDecl
        {
            ScalarConcatPrefixCacheKey key;
            int32_t totalWidth = 0;
            std::size_t firstUseIndex = 0;
            std::size_t useCount = 0;
            std::string tempName;
        };

        bool scalarConcatPrefixCacheable(const Graph &graph, const Operation &op)
        {
            (void)graph;
            (void)op;
            // <=64-bit scalar concat is emitted as direct bitwise code now.
            return false;
        }

        std::vector<ScalarConcatPrefixCacheDecl> collectScalarConcatPrefixCaches(
            const Graph &graph,
            const std::vector<OperationId> &opIds)
        {
            std::unordered_map<ScalarConcatPrefixCacheKey, ScalarConcatPrefixCacheDecl, ScalarConcatPrefixCacheKeyHash>
                declsByKey;
            for (std::size_t opIndex = 0; opIndex < opIds.size(); ++opIndex)
            {
                const Operation op = graph.getOperation(opIds[opIndex]);
                if (!scalarConcatPrefixCacheable(graph, op))
                {
                    continue;
                }
                const auto operands = op.operands();
                const ScalarConcatPrefixCacheKey key{
                    .lhs = operands[0],
                    .lhsWidth = graph.valueWidth(operands[0]),
                    .rhsWidth = graph.valueWidth(operands[1]),
                };
                auto [it, inserted] = declsByKey.emplace(
                    key,
                    ScalarConcatPrefixCacheDecl{
                        .key = key,
                        .totalWidth = graph.valueWidth(op.results().front()),
                        .firstUseIndex = opIndex,
                        .useCount = 0,
                        .tempName = {},
                    });
                if (inserted)
                {
                    it->second.firstUseIndex = opIndex;
                }
                it->second.useCount += 1;
            }

            std::vector<ScalarConcatPrefixCacheDecl> decls;
            decls.reserve(declsByKey.size());
            for (auto &[key, decl] : declsByKey)
            {
                if (decl.useCount >= 4)
                {
                    decls.push_back(decl);
                }
            }
            std::sort(decls.begin(),
                      decls.end(),
                      [](const ScalarConcatPrefixCacheDecl &lhs, const ScalarConcatPrefixCacheDecl &rhs) {
                          if (lhs.firstUseIndex != rhs.firstUseIndex)
                          {
                              return lhs.firstUseIndex < rhs.firstUseIndex;
                          }
                          const std::size_t lhsIdHash = ValueIdHash{}(lhs.key.lhs);
                          const std::size_t rhsIdHash = ValueIdHash{}(rhs.key.lhs);
                          if (lhsIdHash != rhsIdHash)
                          {
                              return lhsIdHash < rhsIdHash;
                          }
                          if (lhs.key.lhsWidth != rhs.key.lhsWidth)
                          {
                              return lhs.key.lhsWidth < rhs.key.lhsWidth;
                          }
                          return lhs.key.rhsWidth < rhs.key.rhsWidth;
                      });
            for (std::size_t i = 0; i < decls.size(); ++i)
            {
                decls[i].tempName = "catp_" + std::to_string(i);
            }
            return decls;
        }

        ScalarLogicExpr scalarAssignmentExpr(OperationKind kind,
                                             const std::vector<std::string> &operands,
                                             const Operation &op,
                                             const Graph &graph,
                                             const std::unordered_map<ScalarConcatPrefixCacheKey,
                                                                      std::string,
                                                                      ScalarConcatPrefixCacheKeyHash> *concatPrefixTemps = nullptr,
                                             bool oneBitBitwiseBytes = false);
        std::optional<std::string> eventWordLogicExprForOp(const Graph &graph,
                                                           const EmitModel &model,
                                                           const Operation &op,
                                                           ValueId resultValue,
                                                           const std::vector<std::string> &operandExprs);

        bool emitWordLogicOperation(std::ostream &stream,
                                    const Graph &graph,
                                    const EmitModel &model,
                                    const Operation &op,
                                    std::string &error,
                                    SupernodeLocalExprContext *context = nullptr,
                                    const ActivationEmitContext *activationContext = nullptr,
                                    DeferredActivationEmitContext *deferredContext = nullptr)
        {
            if (op.results().empty())
            {
                return true;
            }
            if (emitPackedArrayLaneConcatOperation(stream, graph, model, op, context, activationContext))
            {
                return true;
            }
            if (emitPackedArrayLaneAssignOperation(stream, graph, model, op, context, activationContext))
            {
                return true;
            }
            if (emitPackedArrayLaneSliceOperation(stream, graph, model, op, context, activationContext, deferredContext))
            {
                return true;
            }
            if (emitDirectWideConcatOperation(stream, graph, model, op, context, activationContext, deferredContext))
            {
                return true;
            }
            const auto operands = op.operands();
            const ValueId resultValue = op.results().front();
            std::vector<std::string> operandExprs;
            operandExprs.reserve(operands.size());
            for (ValueId operand : operands)
            {
                operandExprs.push_back(resolvedScheduleValueExpr(model, operand, context));
            }
            const auto expr = eventWordLogicExprForOp(graph, model, op, resultValue, operandExprs);
            if (!expr)
            {
                error = "unsupported wide logic emit op: " + std::string(op.symbolText());
                return false;
            }
            if (isWideLogicValue(graph, resultValue))
            {
                emitLogicAssignFromWideWordsExpr(
                    stream, graph, model, resultValue, *expr, context, activationContext, deferredContext);
            }
            else
            {
                emitLogicAssignFromScalarExpr(
                    stream, graph, model, resultValue, *expr, true, context, activationContext, deferredContext);
            }
            return true;
        }

        std::string eventLogicExprFromWordsExpr(const Graph &graph,
                                                ValueId resultValue,
                                                const std::string &wordsExpr)
        {
            if (isWideLogicValue(graph, resultValue))
            {
                return wordsExpr;
            }
            std::ostringstream out;
            out << "static_cast<" << cppTypeForValue(graph, resultValue) << ">("
                << scalarTruncExpr("(" + wordsExpr + ")[0]",
                                   static_cast<std::size_t>(graph.valueWidth(resultValue)))
                << ")";
            return out.str();
        }

        std::optional<std::string> eventWordLogicExprForOp(const Graph &graph,
                                                           const EmitModel &model,
                                                           const Operation &op,
                                                           ValueId resultValue,
                                                           const std::vector<std::string> &operandExprs)
        {
            const auto operands = op.operands();
            const int32_t resultWidth = graph.valueWidth(resultValue);
            auto operandWords = [&](std::size_t index, int32_t width) -> std::string
            {
                const ValueId value = operands[index];
                return castWordsExprForValue(graph, value, operandExprs[index], width);
            };
            auto compareWidth = [&]() -> int32_t
            {
                int32_t width = 1;
                for (ValueId value : operands)
                {
                    width = std::max(width, graph.valueWidth(value));
                }
                return width;
            };
            auto logicBoolExpr = [&](const std::string &expr) -> std::string
            {
                return "static_cast<" + cppTypeForValue(graph, resultValue) + ">(" + expr + ")";
            };

            switch (op.kind())
            {
            case OperationKind::kAssign:
                return eventLogicExprFromWordsExpr(graph, resultValue, operandWords(0, resultWidth));
            case OperationKind::kAdd:
                return eventLogicExprFromWordsExpr(graph,
                                                   resultValue,
                                                   addWordsInlineExpr(operandWords(0, resultWidth),
                                                                      operandWords(1, resultWidth),
                                                                      resultWidth));
            case OperationKind::kSub:
                return eventLogicExprFromWordsExpr(
                    graph, resultValue,
                    binaryWordsBufferOpExpr(operandWords(0, resultWidth),
                                            operandWords(1, resultWidth),
                                            resultWidth,
                                            "grhsim_sub_words"));
            case OperationKind::kMul:
                return eventLogicExprFromWordsExpr(
                    graph, resultValue,
                    "grhsim_mul_words(" + operandWords(0, resultWidth) + ", " + operandWords(1, resultWidth) + ", " +
                        std::to_string(resultWidth) + ")");
            case OperationKind::kDiv:
            {
                const bool signedMode = graph.valueSigned(operands[0]) && graph.valueSigned(operands[1]);
                const std::string helper = signedMode ? "grhsim_sdiv_words" : "grhsim_udiv_words";
                return eventLogicExprFromWordsExpr(graph, resultValue,
                                                   helper + "(" + operandWords(0, resultWidth) + ", " +
                                                       operandWords(1, resultWidth) + ", " +
                                                       std::to_string(resultWidth) + ")");
            }
            case OperationKind::kMod:
            {
                const bool signedMode = graph.valueSigned(operands[0]) && graph.valueSigned(operands[1]);
                const std::string helper = signedMode ? "grhsim_smod_words" : "grhsim_umod_words";
                return eventLogicExprFromWordsExpr(graph, resultValue,
                                                   helper + "(" + operandWords(0, resultWidth) + ", " +
                                                       operandWords(1, resultWidth) + ", " +
                                                       std::to_string(resultWidth) + ")");
            }
            case OperationKind::kAnd:
                return eventLogicExprFromWordsExpr(
                    graph, resultValue,
                    binaryWordsBufferOpExpr(operandWords(0, resultWidth),
                                            operandWords(1, resultWidth),
                                            resultWidth,
                                            "grhsim_and_words"));
            case OperationKind::kOr:
                return eventLogicExprFromWordsExpr(
                    graph, resultValue,
                    binaryWordsBufferOpExpr(operandWords(0, resultWidth),
                                            operandWords(1, resultWidth),
                                            resultWidth,
                                            "grhsim_or_words"));
            case OperationKind::kXor:
                return eventLogicExprFromWordsExpr(
                    graph, resultValue,
                    binaryWordsBufferOpExpr(operandWords(0, resultWidth),
                                            operandWords(1, resultWidth),
                                            resultWidth,
                                            "grhsim_xor_words"));
            case OperationKind::kXnor:
                return eventLogicExprFromWordsExpr(
                    graph, resultValue,
                    binaryWordsBufferOpExpr(operandWords(0, resultWidth),
                                            operandWords(1, resultWidth),
                                            resultWidth,
                                            "grhsim_xnor_words"));
            case OperationKind::kNot:
                return eventLogicExprFromWordsExpr(
                    graph, resultValue,
                    unaryWordsBufferOpExpr(operandWords(0, resultWidth),
                                           resultWidth,
                                           "grhsim_not_words"));
            case OperationKind::kEq:
            case OperationKind::kCaseEq:
            case OperationKind::kWildcardEq:
            {
                const int32_t width = compareWidth();
                return logicBoolExpr(binaryWordsCompareExpr(operandWords(0, width),
                                                            operandWords(1, width),
                                                            "grhsim_compare_unsigned_words") + " == 0");
            }
            case OperationKind::kNe:
            case OperationKind::kCaseNe:
            case OperationKind::kWildcardNe:
            {
                const int32_t width = compareWidth();
                return logicBoolExpr(binaryWordsCompareExpr(operandWords(0, width),
                                                            operandWords(1, width),
                                                            "grhsim_compare_unsigned_words") + " != 0");
            }
            case OperationKind::kLt:
            case OperationKind::kLe:
            case OperationKind::kGt:
            case OperationKind::kGe:
            {
                const int32_t width = compareWidth();
                const bool signedMode = graph.valueSigned(operands[0]) && graph.valueSigned(operands[1]);
                const std::string cmpExpr = signedMode
                                                ? binaryWordsSignedCompareExpr(operandWords(0, width),
                                                                               operandWords(1, width),
                                                                               width)
                                                : binaryWordsCompareExpr(operandWords(0, width),
                                                                        operandWords(1, width),
                                                                        "grhsim_compare_unsigned_words");
                if (op.kind() == OperationKind::kLt)
                {
                    return logicBoolExpr(cmpExpr + " < 0");
                }
                if (op.kind() == OperationKind::kLe)
                {
                    return logicBoolExpr(cmpExpr + " <= 0");
                }
                if (op.kind() == OperationKind::kGt)
                {
                    return logicBoolExpr(cmpExpr + " > 0");
                }
                return logicBoolExpr(cmpExpr + " >= 0");
            }
            case OperationKind::kLogicAnd:
                return logicBoolExpr(unaryWordsBoolExpr(operandWords(0, graph.valueWidth(operands[0])),
                                                        graph.valueWidth(operands[0]),
                                                        "grhsim_any_bits_words") +
                                     " && " +
                                     unaryWordsBoolExpr(operandWords(1, graph.valueWidth(operands[1])),
                                                        graph.valueWidth(operands[1]),
                                                        "grhsim_any_bits_words"));
            case OperationKind::kLogicOr:
                return logicBoolExpr(unaryWordsBoolExpr(operandWords(0, graph.valueWidth(operands[0])),
                                                        graph.valueWidth(operands[0]),
                                                        "grhsim_any_bits_words") +
                                     " || " +
                                     unaryWordsBoolExpr(operandWords(1, graph.valueWidth(operands[1])),
                                                        graph.valueWidth(operands[1]),
                                                        "grhsim_any_bits_words"));
            case OperationKind::kLogicNot:
                return logicBoolExpr("!" + unaryWordsBoolExpr(operandWords(0, graph.valueWidth(operands[0])),
                                                              graph.valueWidth(operands[0]),
                                                              "grhsim_any_bits_words"));
            case OperationKind::kReduceAnd:
                return logicBoolExpr(unaryWordsBoolExpr(operandWords(0, graph.valueWidth(operands[0])),
                                                        graph.valueWidth(operands[0]),
                                                        "grhsim_reduce_and_words"));
            case OperationKind::kReduceNand:
                return logicBoolExpr(unaryWordsBoolExpr(operandWords(0, graph.valueWidth(operands[0])),
                                                        graph.valueWidth(operands[0]),
                                                        "grhsim_reduce_nand_words"));
            case OperationKind::kReduceOr:
                return logicBoolExpr(unaryWordsBoolExpr(operandWords(0, graph.valueWidth(operands[0])),
                                                        graph.valueWidth(operands[0]),
                                                        "grhsim_reduce_or_words"));
            case OperationKind::kReduceNor:
                return logicBoolExpr(unaryWordsBoolExpr(operandWords(0, graph.valueWidth(operands[0])),
                                                        graph.valueWidth(operands[0]),
                                                        "grhsim_reduce_nor_words"));
            case OperationKind::kReduceXor:
                return logicBoolExpr(unaryWordsBoolExpr(operandWords(0, graph.valueWidth(operands[0])),
                                                        graph.valueWidth(operands[0]),
                                                        "grhsim_reduce_xor_words"));
            case OperationKind::kReduceXnor:
                return logicBoolExpr(unaryWordsBoolExpr(operandWords(0, graph.valueWidth(operands[0])),
                                                        graph.valueWidth(operands[0]),
                                                        "grhsim_reduce_xnor_words"));
            case OperationKind::kShl:
                return eventLogicExprFromWordsExpr(graph,
                                                   resultValue,
                                                   shiftWordsBufferOpExpr(operandWords(0, resultWidth),
                                                                          operandExprs[1],
                                                                          resultWidth,
                                                                          "grhsim_shl_words"));
            case OperationKind::kLShr:
                return eventLogicExprFromWordsExpr(graph,
                                                   resultValue,
                                                   shiftWordsBufferOpExpr(operandWords(0, resultWidth),
                                                                          operandExprs[1],
                                                                          resultWidth,
                                                                          "grhsim_lshr_words"));
            case OperationKind::kAShr:
                return eventLogicExprFromWordsExpr(graph,
                                                   resultValue,
                                                   shiftWordsBufferOpExpr(operandWords(0, resultWidth),
                                                                          operandExprs[1],
                                                                          resultWidth,
                                                                          "grhsim_ashr_words"));
            case OperationKind::kMux:
            {
                const ValueId condValue = operands[0];
                const std::string condExpr =
                    isWideLogicValue(graph, condValue)
                        ? ("grhsim_any_bits_words(" + operandWords(0, graph.valueWidth(condValue)) + ", " +
                           std::to_string(graph.valueWidth(condValue)) + ")")
                        : ("(" + operandExprs[0] + ") != 0");
                return eventLogicExprFromWordsExpr(graph, resultValue,
                                                   muxWordsExpr(condExpr,
                                                                operandWords(1, resultWidth),
                                                                operandWords(2, resultWidth),
                                                                resultWidth));
            }
            case OperationKind::kConcat:
            {
                if (resultWidth <= 64)
                {
                    return logicBoolExpr(scalarDirectConcatExpr(graph, op, operandExprs));
                }
                if (preferLoopedScalarConcatEmit(graph, op))
                {
                    return eventLogicExprFromWordsExpr(graph, resultValue,
                                                       scalarWideConcatLoopExpr(graph, op, operandExprs));
                }
                std::vector<std::string> concatOperandWords;
                std::vector<int32_t> concatOperandWidths;
                concatOperandWords.reserve(operands.size());
                concatOperandWidths.reserve(operands.size());
                for (std::size_t operandIndex = 0; operandIndex < operands.size(); ++operandIndex)
                {
                    const int32_t operandWidth = graph.valueWidth(operands[operandIndex]);
                    concatOperandWords.push_back(operandWords(operandIndex, operandWidth));
                    concatOperandWidths.push_back(operandWidth);
                }
                return eventLogicExprFromWordsExpr(
                    graph, resultValue, concatWordsExpr(concatOperandWords, concatOperandWidths, resultWidth));
            }
            case OperationKind::kReplicate:
            {
                const auto rep = getAttribute<int64_t>(op, "rep").value_or(1);
                const std::size_t repCount = rep <= 0 ? 0u : static_cast<std::size_t>(rep);
                if (resultWidth <= 64)
                {
                    return logicBoolExpr(scalarDirectReplicateExpr(operandExprs[0],
                                                                   static_cast<std::size_t>(graph.valueWidth(operands[0])),
                                                                   repCount,
                                                                   static_cast<std::size_t>(resultWidth)));
                }
                const int32_t operandWidth = graph.valueWidth(operands[0]);
                return eventLogicExprFromWordsExpr(
                    graph,
                    resultValue,
                    replicateWordsExpr(operandWords(0, operandWidth), operandWidth, resultWidth, repCount));
            }
            case OperationKind::kSliceStatic:
            {
                const auto sliceStart = getAttribute<int64_t>(op, "sliceStart").value_or(0);
                if (!isWideLogicValue(graph, resultValue) && resultWidth == 1)
                {
                    return logicBoolExpr("grhsim_get_bit_words(" +
                                         operandWords(0, graph.valueWidth(operands[0])) + ", " +
                                         std::to_string(sliceStart) + ")");
                }
                return eventLogicExprFromWordsExpr(
                    graph,
                    resultValue,
                    sliceWordsExpr(operandWords(0, graph.valueWidth(operands[0])),
                                   graph.valueWidth(operands[0]),
                                   std::to_string(sliceStart),
                                   resultWidth));
            }
            case OperationKind::kSliceDynamic:
            {
                if (const auto constStart = constLogicIndexValue(graph, operands[1], static_cast<std::size_t>(graph.valueWidth(operands[0]))))
                {
                    if (!isWideLogicValue(graph, resultValue) && resultWidth == 1)
                    {
                        return logicBoolExpr("grhsim_get_bit_words(" +
                                             operandWords(0, graph.valueWidth(operands[0])) + ", " +
                                             std::to_string(*constStart) + ")");
                    }
                    return eventLogicExprFromWordsExpr(
                        graph,
                        resultValue,
                        sliceWordsExpr(operandWords(0, graph.valueWidth(operands[0])),
                                       graph.valueWidth(operands[0]),
                                       std::to_string(*constStart),
                                       resultWidth));
                }
                return eventLogicExprFromWordsExpr(
                    graph,
                    resultValue,
                    sliceWordsExpr(operandWords(0, graph.valueWidth(operands[0])),
                                   graph.valueWidth(operands[0]),
                                   "grhsim_index_words(" + operandExprs[1] + ", " +
                                       std::to_string(graph.valueWidth(operands[0])) + ")",
                                   resultWidth));
            }
            case OperationKind::kSliceArray:
            {
                const auto sliceWidth = getAttribute<int64_t>(op, "sliceWidth");
                if (!sliceWidth)
                {
                    return std::nullopt;
                }
                return eventLogicExprFromWordsExpr(
                    graph,
                    resultValue,
                    sliceWordsExpr(operandWords(0, graph.valueWidth(operands[0])),
                                   graph.valueWidth(operands[0]),
                                   "((" + operandExprs[1] + ") * " + std::to_string(*sliceWidth) + ")",
                                   resultWidth));
            }
            case OperationKind::kSystemFunction:
            {
                const auto name = getAttribute<std::string>(op, "name");
                if (!name || *name != "clog2" || operands.size() != 1)
                {
                    return std::nullopt;
                }
                return logicBoolExpr("grhsim_clog2_words(" +
                                     operandWords(0, graph.valueWidth(operands[0])) + ", " +
                                     std::to_string(graph.valueWidth(operands[0])) + ")");
            }
            default:
                break;
            }
            return std::nullopt;
        }

        bool eventExprTopoCollect(const Graph &graph,
                                  ValueId value,
                                  std::unordered_set<ValueId, ValueIdHash> &visiting,
                                  std::unordered_set<ValueId, ValueIdHash> &visited,
                                  std::vector<ValueId> &ordered)
        {
            if (visited.contains(value))
            {
                return true;
            }
            if (visiting.contains(value))
            {
                return false;
            }
            visiting.insert(value);

            bool ok = true;
            const OperationId defOpId = graph.valueDef(value);
            if (defOpId.valid())
            {
                const Operation op = graph.getOperation(defOpId);
                switch (op.kind())
                {
                case OperationKind::kConstant:
                case OperationKind::kRegisterReadPort:
                case OperationKind::kLatchReadPort:
                    break;
                case OperationKind::kMemoryReadPort:
                case OperationKind::kAssign:
                case OperationKind::kAdd:
                case OperationKind::kSub:
                case OperationKind::kMul:
                case OperationKind::kDiv:
                case OperationKind::kMod:
                case OperationKind::kAnd:
                case OperationKind::kOr:
                case OperationKind::kXor:
                case OperationKind::kXnor:
                case OperationKind::kEq:
                case OperationKind::kNe:
                case OperationKind::kCaseEq:
                case OperationKind::kCaseNe:
                case OperationKind::kWildcardEq:
                case OperationKind::kWildcardNe:
                case OperationKind::kLt:
                case OperationKind::kLe:
                case OperationKind::kGt:
                case OperationKind::kGe:
                case OperationKind::kLogicAnd:
                case OperationKind::kLogicOr:
                case OperationKind::kNot:
                case OperationKind::kLogicNot:
                case OperationKind::kReduceAnd:
                case OperationKind::kReduceNand:
                case OperationKind::kReduceOr:
                case OperationKind::kReduceNor:
                case OperationKind::kReduceXor:
                case OperationKind::kReduceXnor:
                case OperationKind::kShl:
                case OperationKind::kLShr:
                case OperationKind::kAShr:
                case OperationKind::kMux:
                case OperationKind::kConcat:
                case OperationKind::kReplicate:
                case OperationKind::kSliceStatic:
                case OperationKind::kSliceDynamic:
                case OperationKind::kSliceArray:
                case OperationKind::kSystemFunction:
                    for (ValueId operand : op.operands())
                    {
                        if (!eventExprTopoCollect(graph, operand, visiting, visited, ordered))
                        {
                            ok = false;
                            break;
                        }
                    }
                    if (ok)
                    {
                        ordered.push_back(value);
                    }
                    break;
                default:
                    ok = false;
                    break;
                }
            }

            visiting.erase(value);
            if (ok)
            {
                visited.insert(value);
            }
            return ok;
        }

        std::optional<std::string> eventExprLeafRefForValue(const Graph &graph,
                                                            const EmitModel &model,
                                                            ValueId value)
        {
            if (auto it = model.inputFieldByValue.find(value); it != model.inputFieldByValue.end())
            {
                return it->second;
            }
            const OperationId defOpId = graph.valueDef(value);
            if (!defOpId.valid())
            {
                return valueRef(model, value);
            }
            const Operation op = graph.getOperation(defOpId);
            switch (op.kind())
            {
            case OperationKind::kConstant:
                return constantExpr(graph, op, value);
            case OperationKind::kRegisterReadPort:
            {
                auto regSymbol = getAttribute<std::string>(op, "regSymbol");
                if (!regSymbol)
                {
                    return std::nullopt;
                }
                auto it = model.stateBySymbol.find(*regSymbol);
                if (it == model.stateBySymbol.end())
                {
                    return std::nullopt;
                }
                return stateRef(it->second);
            }
            case OperationKind::kLatchReadPort:
            {
                auto latchSymbol = getAttribute<std::string>(op, "latchSymbol");
                if (!latchSymbol)
                {
                    return std::nullopt;
                }
                auto it = model.stateBySymbol.find(*latchSymbol);
                if (it == model.stateBySymbol.end())
                {
                    return std::nullopt;
                }
                return stateRef(it->second);
            }
            default:
                break;
            }
            return std::nullopt;
        }

        std::optional<std::string> eventExprRefForValue(const Graph &graph,
                                                        const EmitModel &model,
                                                        ValueId value,
                                                        const std::unordered_map<ValueId, std::string, ValueIdHash> &materializedRefs)
        {
            if (auto it = materializedRefs.find(value); it != materializedRefs.end())
            {
                return it->second;
            }
            return eventExprLeafRefForValue(graph, model, value);
        }

        struct MemoryRowAccessExpr
        {
            std::string rowExpr;
            std::string inRangeExpr;
            bool alwaysInRange = false;
        };

        MemoryRowAccessExpr memoryRowAccessExpr(const Graph &graph,
                                                ValueId addrValue,
                                                std::string_view addrExpr,
                                                std::size_t rowCount)
        {
            MemoryRowAccessExpr result;
            if (rowCount == 0)
            {
                result.rowExpr = "0u";
                result.inRangeExpr = "false";
                return result;
            }

            const int32_t addrWidth = graph.valueWidth(addrValue);
            const std::string rowCountExpr = std::to_string(rowCount) + "u";
            const std::string scalarAddrExpr = "static_cast<std::uint64_t>(" + std::string(addrExpr) + ")";
            if (isPowerOfTwoU64(static_cast<std::uint64_t>(rowCount)))
            {
                const std::string maskExpr = std::to_string(rowCount - 1u) + "u";
                if (isWideLogicWidth(addrWidth))
                {
                    result.rowExpr =
                        "(static_cast<std::size_t>((" + std::string(addrExpr) + ")[0]) & " + maskExpr + ")";
                }
                else
                {
                    result.rowExpr = "(static_cast<std::size_t>(" + scalarAddrExpr + ") & " + maskExpr + ")";
                }
                result.alwaysInRange = true;
                result.inRangeExpr = "true";
                return result;
            }

            if (addrWidth > 0 && addrWidth < 64 &&
                (UINT64_C(1) << static_cast<std::size_t>(addrWidth)) <= static_cast<std::uint64_t>(rowCount))
            {
                result.rowExpr = "static_cast<std::size_t>(" + scalarAddrExpr + ")";
                result.alwaysInRange = true;
                result.inRangeExpr = "true";
                return result;
            }

            if (isWideLogicWidth(addrWidth))
            {
                const std::size_t wordCount = logicWordCount(addrWidth);
                result.rowExpr = "static_cast<std::size_t>((" + std::string(addrExpr) + ")[0])";
                std::ostringstream cond;
                cond << "(";
                for (std::size_t i = 1; i < wordCount; ++i)
                {
                    if (i != 1)
                    {
                        cond << " && ";
                    }
                    cond << "((" << addrExpr << ")[" << i << "] == UINT64_C(0))";
                }
                if (wordCount > 1)
                {
                    cond << " && ";
                }
                cond << "((" << addrExpr << ")[0] < " << rowCountExpr << "))";
                result.inRangeExpr = cond.str();
                return result;
            }

            result.rowExpr = "static_cast<std::size_t>(" + scalarAddrExpr + ")";
            result.inRangeExpr = "(" + scalarAddrExpr + " < " + rowCountExpr + ")";
            return result;
        }

        struct RegToMemIntentRowAccessExpr
        {
            std::string rowExpr;
            std::string inRangeExpr;
            bool alwaysInRange = false;
        };

        std::optional<ValueId> regToMemIntentSliceDynamicIndexValue(const Graph &graph,
                                                                    const Operation &op,
                                                                    int64_t elementWidth)
        {
            (void)elementWidth;
            if (op.kind() != OperationKind::kSliceDynamic)
            {
                return std::nullopt;
            }
            return regToMemIntentSliceIndexValue(graph, op);
        }

        std::optional<RegToMemIntentRowAccessExpr>
        regToMemIntentRowAccessExpr(const Graph &graph,
                                    const EmitModel &model,
                                    const Operation &op,
                                    ValueId indexValue,
                                    std::string_view indexExpr)
        {
            if ((op.kind() != OperationKind::kSliceArray && op.kind() != OperationKind::kSliceDynamic) ||
                op.operands().size() != 2 || op.results().empty() || !indexValue.valid())
            {
                return std::nullopt;
            }
            const auto group = getAttribute<std::string>(op, "regToMem.intent.group");
            const auto mode = getAttribute<std::string>(op, "regToMem.intent.mode");
            const auto elementWidth = getAttribute<int64_t>(op, "regToMem.intent.elementWidth");
            const auto elementCount = getAttribute<int64_t>(op, "regToMem.intent.elementCount");
            const auto storageGroupAttr = getAttribute<std::string>(op, "regToMem.intent.storageGroup");
            const auto storageElementCountAttr = getAttribute<int64_t>(op, "regToMem.intent.storageElementCount");
            const auto storageRowOffsetAttr = getAttribute<int64_t>(op, "regToMem.intent.storageRowOffset");
            const auto sliceWidth = getAttribute<int64_t>(op, "sliceWidth");
            if (!group || mode.value_or(std::string()) != "array-index" ||
                !elementWidth || !elementCount || !sliceWidth ||
                *elementWidth <= 0 || *elementCount <= 0 ||
                *sliceWidth != *elementWidth ||
                graph.valueWidth(op.results().front()) != *elementWidth)
            {
                return std::nullopt;
            }
            const std::string storageGroup = storageGroupAttr.value_or(*group);
            const int64_t storageElementCount = storageElementCountAttr.value_or(*elementCount);
            const int64_t storageRowOffset = storageRowOffsetAttr.value_or(0);
            if (storageGroup.empty() ||
                storageElementCount < *elementCount ||
                storageRowOffset < 0 ||
                storageRowOffset > storageElementCount ||
                storageElementCount - storageRowOffset < *elementCount)
            {
                return std::nullopt;
            }
            const auto storageIt = model.regToMemIntentStorageByGroup.find(storageGroup);
            if (storageIt == model.regToMemIntentStorageByGroup.end())
            {
                return std::nullopt;
            }
            const RegToMemIntentStorageDecl &storage = storageIt->second;
            if (storage.elementWidth != *elementWidth ||
                storage.elementCount != static_cast<std::size_t>(storageElementCount))
            {
                return std::nullopt;
            }
            const int32_t indexWidth = graph.valueWidth(indexValue);
            RegToMemIntentRowAccessExpr access;
            const auto storageIndexExpr = [&](std::string baseExpr) {
                if (storageRowOffset == 0)
                {
                    return baseExpr;
                }
                return "(" + std::move(baseExpr) + " + " + std::to_string(storageRowOffset) + "u)";
            };
            if (isWideLogicWidth(indexWidth))
            {
                const std::size_t wordCount = logicWordCount(indexWidth);
                access.rowExpr =
                    storage.fieldName + "[static_cast<std::size_t>(" +
                    storageIndexExpr("(" + std::string(indexExpr) + ")[0]") + ")]";
                std::ostringstream cond;
                cond << "(";
                for (std::size_t i = 1; i < wordCount; ++i)
                {
                    if (i != 1)
                    {
                        cond << " && ";
                    }
                    cond << "((" << indexExpr << ")[" << i << "] == UINT64_C(0))";
                }
                if (wordCount > 1)
                {
                    cond << " && ";
                }
                cond << "((" << indexExpr << ")[0] < " << *elementCount << "u))";
                access.inRangeExpr = cond.str();
                access.alwaysInRange = false;
                return access;
            }
            const std::string scalarIndexExpr =
                "static_cast<std::uint64_t>(" + std::string(indexExpr) + ")";
            if (indexWidth > 0 && indexWidth < 64 &&
                (UINT64_C(1) << static_cast<std::size_t>(indexWidth)) <=
                    static_cast<std::uint64_t>(*elementCount))
            {
                access.rowExpr = storage.fieldName + "[static_cast<std::size_t>(" +
                                 storageIndexExpr(scalarIndexExpr) + ")]";
                access.inRangeExpr = "true";
                access.alwaysInRange = true;
                return access;
            }
            access.rowExpr = storage.fieldName + "[static_cast<std::size_t>(" +
                             storageIndexExpr(scalarIndexExpr) + ")]";
            access.inRangeExpr = "(" + scalarIndexExpr + " < " + std::to_string(*elementCount) + "u)";
            access.alwaysInRange = false;
            return access;
        }

        std::optional<std::string> regToMemIntentSliceExpr(const Graph &graph,
                                                           const EmitModel &model,
                                                           const Operation &op,
                                                           ValueId resultValue,
                                                           ValueId indexValue,
                                                           std::string_view indexExpr)
        {
            auto access = regToMemIntentRowAccessExpr(graph, model, op, indexValue, indexExpr);
            if (!access)
            {
                return std::nullopt;
            }
            if (isWideLogicValue(graph, resultValue))
            {
                if (access->alwaysInRange)
                {
                    return access->rowExpr;
                }
                return "((" + access->inRangeExpr + ") ? " + access->rowExpr + " : " +
                       wordsArrayTypeForWidth(graph.valueWidth(resultValue)) + "{})";
            }
            const std::string rowExpr =
                "static_cast<" + cppTypeForValue(graph, resultValue) + ">(" + access->rowExpr + ")";
            if (access->alwaysInRange)
            {
                return rowExpr;
            }
            return "((" + access->inRangeExpr + ") ? " + rowExpr + " : " +
                   defaultInitExprForLogicWidth(graph.valueWidth(resultValue)) + ")";
        }

        std::optional<std::string> eventExprMaterializedBodyForValue(
            const Graph &graph,
            const EmitModel &model,
            ValueId value,
            const std::unordered_map<ValueId, std::string, ValueIdHash> &materializedRefs)
        {
            if (auto leaf = eventExprLeafRefForValue(graph, model, value))
            {
                return leaf;
            }

            const OperationId defOpId = graph.valueDef(value);
            if (!defOpId.valid())
            {
                return valueRef(model, value);
            }
            const Operation op = graph.getOperation(defOpId);
            const auto operands = op.operands();
            std::vector<std::string> operandExprs;
            operandExprs.reserve(operands.size());
            for (ValueId operand : operands)
            {
                auto operandExpr = eventExprRefForValue(graph, model, operand, materializedRefs);
                if (!operandExpr)
                {
                    return std::nullopt;
                }
                operandExprs.push_back(*operandExpr);
            }

            if (op.kind() == OperationKind::kMemoryReadPort)
            {
                auto memSymbol = getAttribute<std::string>(op, "memSymbol");
                if (!memSymbol || operandExprs.empty() || graph.valueType(value) != ValueType::Logic)
                {
                    return std::nullopt;
                }
                auto stateIt = model.stateBySymbol.find(*memSymbol);
                if (stateIt == model.stateBySymbol.end())
                {
                    return std::nullopt;
                }
                const MemoryRowAccessExpr rowAccess =
                    memoryRowAccessExpr(graph, operands[0], operandExprs[0], stateIt->second.rowCount);
                const std::string rowExpr = stateRef(stateIt->second) + "[" + rowAccess.rowExpr + "]";
                if (isWideLogicValue(graph, value))
                {
                    if (rowAccess.alwaysInRange)
                    {
                        return rowExpr;
                    }
                    return "((" + rowAccess.inRangeExpr + ") ? " + rowExpr + " : " +
                           wordsArrayTypeForWidth(graph.valueWidth(value)) + "{})";
                }
                const std::string castRowExpr =
                    "static_cast<" + cppTypeForValue(graph, value) + ">(" + rowExpr + ")";
                if (rowAccess.alwaysInRange)
                {
                    return castRowExpr;
                }
                return "((" + rowAccess.inRangeExpr + ") ? " + castRowExpr + " : " +
                       defaultInitExprForLogicWidth(graph.valueWidth(value)) + ")";
            }

            if (graph.valueType(value) != ValueType::Logic)
            {
                return std::nullopt;
            }
            if (opNeedsWordLogicEmit(graph, op))
            {
                return eventWordLogicExprForOp(graph, model, op, value, operandExprs);
            }
            const ScalarLogicExpr rhs =
                scalarAssignmentExpr(op.kind(), operandExprs, op, graph, nullptr, model.oneBitBitwiseBytes);
            if (rhs.expr.empty())
            {
                return std::nullopt;
            }
            return renderScalarLogicExpr(graph, value, rhs);
        }

        std::optional<std::string> pureExprForValue(const Graph &graph,
                                                    const EmitModel &model,
                                                    ValueId value,
                                                    std::unordered_map<ValueId, std::optional<std::string>, ValueIdHash> &cache,
                                                    std::unordered_map<ValueId, std::size_t, ValueIdHash> &costCache,
                                                    std::size_t &totalOps,
                                                    std::size_t opBudget)
        {
            if (auto it = cache.find(value); it != cache.end())
            {
                const std::size_t cachedCost = costCache[value];
                if (cachedCost > opBudget || totalOps > opBudget - cachedCost)
                {
                    return std::nullopt;
                }
                totalOps += cachedCost;
                return it->second;
            }

            std::optional<std::string> expr;
            std::size_t cost = 0;
            if (auto inputIt = model.inputFieldByValue.find(value); inputIt != model.inputFieldByValue.end())
            {
                expr = inputIt->second;
            }
            else
            {
                const Value val = graph.getValue(value);
                const OperationId defOpId = val.definingOp();
                if (!defOpId.valid())
                {
                    expr = valueRef(model, value);
                }
                else
                {
                    const Operation op = graph.getOperation(defOpId);
                    switch (op.kind())
                    {
                    case OperationKind::kConstant:
                        expr = constantExpr(graph, op, value);
                        break;
                    case OperationKind::kRegisterReadPort:
                    {
                        auto regSymbol = getAttribute<std::string>(op, "regSymbol");
                        if (regSymbol)
                        {
                            if (auto it = model.stateBySymbol.find(*regSymbol); it != model.stateBySymbol.end())
                            {
                                expr = stateRef(it->second);
                            }
                        }
                        break;
                    }
                    case OperationKind::kLatchReadPort:
                    {
                        auto latchSymbol = getAttribute<std::string>(op, "latchSymbol");
                        if (latchSymbol)
                        {
                            if (auto it = model.stateBySymbol.find(*latchSymbol); it != model.stateBySymbol.end())
                            {
                                expr = stateRef(it->second);
                            }
                        }
                        break;
                    }
                    case OperationKind::kMemoryReadPort:
                    {
                        const auto memSymbol = getAttribute<std::string>(op, "memSymbol");
                        const auto operands = op.operands();
                        if (!memSymbol || operands.empty() || graph.valueType(value) != ValueType::Logic)
                        {
                            break;
                        }
                        auto stateIt = model.stateBySymbol.find(*memSymbol);
                        if (stateIt == model.stateBySymbol.end())
                        {
                            break;
                        }
                        std::size_t operandCost = 0;
                        auto addrExpr =
                            pureExprForValue(graph, model, operands[0], cache, costCache, operandCost, opBudget);
                        if (!addrExpr)
                        {
                            break;
                        }
                        if (operandCost + 1u > opBudget)
                        {
                            break;
                        }
                        cost += operandCost + 1u;
                        const MemoryRowAccessExpr rowAccess =
                            memoryRowAccessExpr(graph, operands[0], *addrExpr, stateIt->second.rowCount);
                        const std::string rowExpr = stateRef(stateIt->second) + "[" + rowAccess.rowExpr + "]";
                        if (isWideLogicValue(graph, value))
                        {
                            expr = rowAccess.alwaysInRange
                                       ? rowExpr
                                       : "((" + rowAccess.inRangeExpr + ") ? " + rowExpr + " : " +
                                             wordsArrayTypeForWidth(graph.valueWidth(value)) + "{})";
                        }
                        else
                        {
                            const std::string castRowExpr =
                                "static_cast<" + cppTypeForValue(graph, value) + ">(" + rowExpr + ")";
                            expr = rowAccess.alwaysInRange
                                       ? castRowExpr
                                       : "((" + rowAccess.inRangeExpr + ") ? " + castRowExpr + " : " +
                                             defaultInitExprForLogicWidth(graph.valueWidth(value)) + ")";
                        }
                        break;
                    }
                    case OperationKind::kAssign:
                    case OperationKind::kAdd:
                    case OperationKind::kSub:
                    case OperationKind::kMul:
                    case OperationKind::kDiv:
                    case OperationKind::kMod:
                    case OperationKind::kAnd:
                    case OperationKind::kOr:
                    case OperationKind::kXor:
                    case OperationKind::kXnor:
                    case OperationKind::kEq:
                    case OperationKind::kNe:
                    case OperationKind::kCaseEq:
                    case OperationKind::kCaseNe:
                    case OperationKind::kWildcardEq:
                    case OperationKind::kWildcardNe:
                    case OperationKind::kLt:
                    case OperationKind::kLe:
                    case OperationKind::kGt:
                    case OperationKind::kGe:
                    case OperationKind::kLogicAnd:
                    case OperationKind::kLogicOr:
                    case OperationKind::kNot:
                    case OperationKind::kLogicNot:
                    case OperationKind::kReduceAnd:
                    case OperationKind::kReduceNand:
                    case OperationKind::kReduceOr:
                    case OperationKind::kReduceNor:
                    case OperationKind::kReduceXor:
                    case OperationKind::kReduceXnor:
                    case OperationKind::kShl:
                    case OperationKind::kLShr:
                    case OperationKind::kAShr:
                    case OperationKind::kMux:
                    case OperationKind::kConcat:
                    case OperationKind::kReplicate:
                    case OperationKind::kSliceStatic:
                    case OperationKind::kSliceDynamic:
                    case OperationKind::kSliceArray:
                    case OperationKind::kSystemFunction:
                    {
                        if (graph.valueType(value) != ValueType::Logic)
                        {
                            break;
                        }
                        const auto operands = op.operands();
                        std::vector<std::string> operandExprs;
                        operandExprs.reserve(operands.size());
                        for (ValueId operand : operands)
                        {
                            std::size_t operandCost = 0;
                            auto operandExpr = pureExprForValue(
                                graph,
                                model,
                                operand,
                                cache,
                                costCache,
                                operandCost,
                                cost >= opBudget ? 0u : opBudget - cost);
                            if (!operandExpr)
                            {
                                operandExprs.clear();
                                break;
                            }
                            if (operandCost > opBudget - cost)
                            {
                                operandExprs.clear();
                                break;
                            }
                            cost += operandCost;
                            operandExprs.push_back(*operandExpr);
                        }
                        if (operandExprs.size() != operands.size())
                        {
                            break;
                        }
                        if (cost + 1u > opBudget)
                        {
                            break;
                        }
                        cost += 1u;
                        if (opNeedsWordLogicEmit(graph, op))
                        {
                            expr = eventWordLogicExprForOp(graph, model, op, value, operandExprs);
                        }
                        else
                        {
                            const ScalarLogicExpr rhs =
                                scalarAssignmentExpr(op.kind(), operandExprs, op, graph, nullptr, model.oneBitBitwiseBytes);
                            if (!rhs.expr.empty())
                            {
                                expr = renderScalarLogicExpr(graph, value, rhs);
                            }
                        }
                        if (expr && expr->empty())
                        {
                            expr.reset();
                        }
                        break;
                    }
                    default:
                        break;
                    }
                }
            }

            cache.emplace(value, expr);
            costCache.emplace(value, cost);
            totalOps += cost;
            return expr;
        }

        ScalarLogicExpr scalarAssignmentExpr(OperationKind kind,
                                             const std::vector<std::string> &operands,
                                             const Operation &op,
                                             const Graph &graph,
                                             const std::unordered_map<ScalarConcatPrefixCacheKey,
                                                                      std::string,
                                                                      ScalarConcatPrefixCacheKeyHash> *concatPrefixTemps,
                                             bool oneBitBitwiseBytes)
        {
            const auto resultWidth =
                op.results().empty() ? 64 : static_cast<std::size_t>(graph.valueWidth(op.results().front()));
            const bool byteBitResult = oneBitBitwiseBytes &&
                                       (op.kind() == OperationKind::kAnd || op.kind() == OperationKind::kOr) &&
                                       resultWidth == 1u &&
                                       std::ranges::all_of(op.operands(), [&](ValueId value) {
                                           return graph.valueType(value) == ValueType::Logic &&
                                                  graph.valueWidth(value) == 1;
                                       });
            auto byteBitOperandExpr = [&](std::size_t index) -> std::string
            {
                std::string expr = stripRedundantOuterParens(operands[index]);
                while (true)
                {
                    const std::string previous = expr;
                    expr = stripOuterCastToType(std::move(expr), "bool");
                    expr = stripRedundantUint64Cast(expr);
                    expr = stripRedundantOuterParens(std::move(expr));
                    if (expr == previous)
                    {
                        break;
                    }
                }
                if (expr.starts_with("grhsim_assume_bit_u8(") && expr.ends_with(")"))
                {
                    return expr;
                }
                return "grhsim_assume_bit_u8(static_cast<std::uint8_t>(" + expr + "))";
            };
            auto operandExpr = [&](std::size_t index, std::size_t width) -> std::string
            {
                const ValueId value = op.operands()[index];
                const std::size_t srcWidth = static_cast<std::size_t>(graph.valueWidth(value));
                if (srcWidth == width)
                {
                    if (width == 1)
                    {
                        return operands[index];
                    }
                    return scalarValueBitsExpr(graph, value, operands[index]);
                }
                return "grhsim_cast_u64(" + scalarValueBitsExpr(graph, value, operands[index]) + ", " +
                       std::to_string(srcWidth) + ", " + std::to_string(width) + ", " +
                       boolLiteral(graph.valueSigned(value)) + ")";
            };
            auto compareWidth = [&]() -> std::size_t
            {
                std::size_t width = 1;
                for (ValueId value : op.operands())
                {
                    width = std::max(width, static_cast<std::size_t>(graph.valueWidth(value)));
                }
                return width;
            };
            switch (kind)
            {
            case OperationKind::kAssign:
                return ScalarLogicExpr{operandExpr(0, resultWidth), true};
            case OperationKind::kAdd:
                return ScalarLogicExpr{"(" + operandExpr(0, resultWidth) + " + " + operandExpr(1, resultWidth) + ")", false};
            case OperationKind::kSub:
                return ScalarLogicExpr{"(" + operandExpr(0, resultWidth) + " - " + operandExpr(1, resultWidth) + ")", false};
            case OperationKind::kMul:
                return ScalarLogicExpr{"(" + operandExpr(0, resultWidth) + " * " + operandExpr(1, resultWidth) + ")", false};
            case OperationKind::kDiv:
            {
                const bool signedMode =
                    graph.valueSigned(op.operands()[0]) && graph.valueSigned(op.operands()[1]);
                return ScalarLogicExpr{
                    std::string(signedMode ? "grhsim_sdiv_u64(" : "grhsim_udiv_u64(") +
                        operandExpr(0, resultWidth) + ", " + operandExpr(1, resultWidth) + ", " +
                        std::to_string(resultWidth) + ")",
                    true};
            }
            case OperationKind::kMod:
            {
                const bool signedMode =
                    graph.valueSigned(op.operands()[0]) && graph.valueSigned(op.operands()[1]);
                return ScalarLogicExpr{
                    std::string(signedMode ? "grhsim_smod_u64(" : "grhsim_umod_u64(") +
                        operandExpr(0, resultWidth) + ", " + operandExpr(1, resultWidth) + ", " +
                        std::to_string(resultWidth) + ")",
                    true};
            }
            case OperationKind::kAnd:
                if (byteBitResult)
                {
                    return ScalarLogicExpr{"(" + byteBitOperandExpr(0) + " & " + byteBitOperandExpr(1) + ")",
                                           true,
                                           true};
                }
                return ScalarLogicExpr{"(" + operandExpr(0, resultWidth) + " & " + operandExpr(1, resultWidth) + ")", true};
            case OperationKind::kOr:
                if (byteBitResult)
                {
                    return ScalarLogicExpr{"(" + byteBitOperandExpr(0) + " | " + byteBitOperandExpr(1) + ")",
                                           true,
                                           true};
                }
                return ScalarLogicExpr{"(" + operandExpr(0, resultWidth) + " | " + operandExpr(1, resultWidth) + ")", true};
            case OperationKind::kXor:
                return ScalarLogicExpr{"(" + operandExpr(0, resultWidth) + " ^ " + operandExpr(1, resultWidth) + ")", true};
            case OperationKind::kXnor:
                return ScalarLogicExpr{"(~(" + operandExpr(0, resultWidth) + " ^ " + operandExpr(1, resultWidth) + "))", false};
            case OperationKind::kNot:
                return ScalarLogicExpr{"(~(" + operandExpr(0, resultWidth) + "))", false};
            case OperationKind::kEq:
            case OperationKind::kCaseEq:
            case OperationKind::kWildcardEq:
            {
                const std::size_t width = compareWidth();
                return ScalarLogicExpr{"((" + operandExpr(0, width) + ") == (" + operandExpr(1, width) + "))", true};
            }
            case OperationKind::kNe:
            case OperationKind::kCaseNe:
            case OperationKind::kWildcardNe:
            {
                const std::size_t width = compareWidth();
                return ScalarLogicExpr{"((" + operandExpr(0, width) + ") != (" + operandExpr(1, width) + "))", true};
            }
            case OperationKind::kLt:
            case OperationKind::kLe:
            case OperationKind::kGt:
            case OperationKind::kGe:
            {
                const std::size_t width = compareWidth();
                const bool signedMode =
                    graph.valueSigned(op.operands()[0]) && graph.valueSigned(op.operands()[1]);
                if (!signedMode && width <= 64u)
                {
                    const std::string lhs = operandExpr(0, width);
                    const std::string rhs = operandExpr(1, width);
                    switch (kind)
                    {
                    case OperationKind::kLt:
                        return ScalarLogicExpr{"((" + lhs + ") < (" + rhs + "))", true};
                    case OperationKind::kLe:
                        return ScalarLogicExpr{"((" + lhs + ") <= (" + rhs + "))", true};
                    case OperationKind::kGt:
                        return ScalarLogicExpr{"((" + lhs + ") > (" + rhs + "))", true};
                    case OperationKind::kGe:
                        return ScalarLogicExpr{"((" + lhs + ") >= (" + rhs + "))", true};
                    default:
                        break;
                    }
                }
                const std::string cmpExpr = signedMode
                                                ? "grhsim_compare_signed_u64(" + operandExpr(0, width) + ", " +
                                                      operandExpr(1, width) + ", " + std::to_string(width) + ")"
                                                : "grhsim_compare_unsigned_u64(" + operandExpr(0, width) + ", " +
                                                      operandExpr(1, width) + ", " + std::to_string(width) + ")";
                switch (kind)
                {
                case OperationKind::kLt:
                    return ScalarLogicExpr{"(" + cmpExpr + " < 0)", true};
                case OperationKind::kLe:
                    return ScalarLogicExpr{"(" + cmpExpr + " <= 0)", true};
                case OperationKind::kGt:
                    return ScalarLogicExpr{"(" + cmpExpr + " > 0)", true};
                case OperationKind::kGe:
                    return ScalarLogicExpr{"(" + cmpExpr + " >= 0)", true};
                default:
                    break;
                }
                return ScalarLogicExpr{};
            }
            case OperationKind::kLogicAnd:
                return ScalarLogicExpr{"((" + operands[0] + ") && (" + operands[1] + "))", true};
            case OperationKind::kLogicOr:
                return ScalarLogicExpr{"((" + operands[0] + ") || (" + operands[1] + "))", true};
            case OperationKind::kLogicNot:
                return ScalarLogicExpr{"(!(" + operands[0] + "))", true};
            case OperationKind::kReduceAnd:
                return ScalarLogicExpr{"grhsim_reduce_and_u64(" + operands[0] + ", " + std::to_string(graph.valueWidth(op.operands()[0])) + ")", true};
            case OperationKind::kReduceNand:
                return ScalarLogicExpr{"grhsim_reduce_nand_u64(" + operands[0] + ", " + std::to_string(graph.valueWidth(op.operands()[0])) + ")", true};
            case OperationKind::kReduceOr:
                return ScalarLogicExpr{"grhsim_reduce_or_u64(" + operands[0] + ", " + std::to_string(graph.valueWidth(op.operands()[0])) + ")", true};
            case OperationKind::kReduceNor:
                return ScalarLogicExpr{"grhsim_reduce_nor_u64(" + operands[0] + ", " + std::to_string(graph.valueWidth(op.operands()[0])) + ")", true};
            case OperationKind::kReduceXor:
                return ScalarLogicExpr{"grhsim_reduce_xor_u64(" + operands[0] + ", " + std::to_string(graph.valueWidth(op.operands()[0])) + ")", true};
            case OperationKind::kReduceXnor:
                return ScalarLogicExpr{"grhsim_reduce_xnor_u64(" + operands[0] + ", " + std::to_string(graph.valueWidth(op.operands()[0])) + ")", true};
            case OperationKind::kShl:
                return ScalarLogicExpr{
                    scalarShlExpr(operandExpr(0, resultWidth),
                                  operands[1],
                                  static_cast<std::size_t>(resultWidth),
                                  static_cast<std::size_t>(graph.valueWidth(op.operands()[1]))),
                    true};
            case OperationKind::kLShr:
                return ScalarLogicExpr{
                    scalarLShrExpr(operandExpr(0, resultWidth),
                                   operands[1],
                                   static_cast<std::size_t>(resultWidth),
                                   static_cast<std::size_t>(graph.valueWidth(op.operands()[1]))),
                    true};
            case OperationKind::kAShr:
                return ScalarLogicExpr{"grhsim_ashr_u64(" + operandExpr(0, resultWidth) + ", " + operands[1] + ", " + std::to_string(resultWidth) + ")", true};
            case OperationKind::kMux:
                return ScalarLogicExpr{
                    "grhsim_mux_u64(static_cast<std::uint64_t>(" + operands[0] + "), " +
                        operandExpr(1, resultWidth) + ", " + operandExpr(2, resultWidth) + ")",
                    true};
            case OperationKind::kConcat:
            {
                if (resultWidth <= 64)
                {
                    return ScalarLogicExpr{scalarDirectConcatExpr(graph, op, operands), true};
                }
                if (op.operands().size() == 2)
                {
                    const int32_t lhsWidth = graph.valueWidth(op.operands()[0]);
                    const int32_t rhsWidth = graph.valueWidth(op.operands()[1]);
                    if (concatPrefixTemps != nullptr)
                    {
                        const ScalarConcatPrefixCacheKey key{
                            .lhs = op.operands()[0],
                            .lhsWidth = lhsWidth,
                            .rhsWidth = rhsWidth,
                        };
                        if (auto it = concatPrefixTemps->find(key); it != concatPrefixTemps->end())
                        {
                            return ScalarLogicExpr{
                                "grhsim_cat_rhs(" + it->second + ", " + operands[1] + ", " +
                                    std::to_string(resultWidth) + ", " + std::to_string(rhsWidth) + ")",
                                true};
                        }
                    }
                    return ScalarLogicExpr{
                        "grhsim_cat(" + operands[0] + ", " + std::to_string(lhsWidth) + ", " + operands[1] + ", " +
                            std::to_string(rhsWidth) + ")",
                        true};
                }
                if (operands.empty())
                {
                    return ScalarLogicExpr{};
                }
                std::string expr = operands[0];
                int32_t accumWidth = graph.valueWidth(op.operands()[0]);
                for (std::size_t i = 1; i < operands.size(); ++i)
                {
                    expr = "grhsim_concat_u64(" + expr + ", " + std::to_string(accumWidth) + ", " +
                           operands[i] + ", " + std::to_string(graph.valueWidth(op.operands()[i])) + ")";
                    accumWidth += graph.valueWidth(op.operands()[i]);
                }
                return ScalarLogicExpr{expr, true};
            }
            case OperationKind::kReplicate:
            {
                const auto rep = getAttribute<int64_t>(op, "rep").value_or(1);
                const std::size_t repCount = rep <= 0 ? 0u : static_cast<std::size_t>(rep);
                if (resultWidth <= 64)
                {
                    return ScalarLogicExpr{
                        scalarDirectReplicateExpr(operands[0],
                                                  static_cast<std::size_t>(graph.valueWidth(op.operands()[0])),
                                                  repCount,
                                                  resultWidth),
                        true};
                }
                return ScalarLogicExpr{};
            }
            case OperationKind::kSliceStatic:
            {
                const auto sliceStart = getAttribute<int64_t>(op, "sliceStart").value_or(0);
                const auto sliceEnd = getAttribute<int64_t>(op, "sliceEnd").value_or(sliceStart);
                const int64_t width = sliceEnd - sliceStart + 1;
                if (width >= 64)
                {
                    return ScalarLogicExpr{"((" + operands[0] + ") >> " + std::to_string(sliceStart) + ")", true};
                }
                std::uint64_t mask = width <= 0 ? 0u : ((UINT64_C(1) << width) - 1u);
                return ScalarLogicExpr{"(((" + operands[0] + ") >> " + std::to_string(sliceStart) + ") & UINT64_C(" + std::to_string(mask) + "))",
                                       true};
            }
            case OperationKind::kSliceDynamic:
            {
                const auto sliceWidth = getAttribute<int64_t>(op, "sliceWidth").value_or(1);
                if (const auto constStart =
                        constLogicIndexValue(graph, op.operands()[1], static_cast<std::size_t>(graph.valueWidth(op.operands()[0]))))
                {
                    if (sliceWidth >= 64)
                    {
                        return ScalarLogicExpr{"((" + operands[0] + ") >> " + std::to_string(*constStart) + ")", true};
                    }
                    const std::uint64_t mask = sliceWidth <= 0 ? UINT64_C(0) : ((UINT64_C(1) << sliceWidth) - 1u);
                    return ScalarLogicExpr{
                        "(((" + operands[0] + ") >> " + std::to_string(*constStart) + ") & UINT64_C(" +
                            std::to_string(mask) + "))",
                        true};
                }
                return ScalarLogicExpr{
                    scalarSliceDynamicExpr(operands[0],
                                           static_cast<std::size_t>(graph.valueWidth(op.operands()[0])),
                                           operands[1],
                                           static_cast<std::size_t>(sliceWidth),
                                           static_cast<std::size_t>(graph.valueWidth(op.operands()[1]))),
                    true};
            }
            case OperationKind::kSliceArray:
            {
                const auto sliceWidth = getAttribute<int64_t>(op, "sliceWidth");
                if (!sliceWidth)
                {
                    return ScalarLogicExpr{};
                }
                return ScalarLogicExpr{
                    scalarSliceArrayExpr(operands[0],
                                         static_cast<std::size_t>(graph.valueWidth(op.operands()[0])),
                                         operands[1],
                                         static_cast<std::size_t>(*sliceWidth)),
                    true};
            }
            case OperationKind::kSystemFunction:
            {
                const auto name = getAttribute<std::string>(op, "name");
                if (!name || *name != "clog2" || operands.size() != 1)
                {
                    return ScalarLogicExpr{};
                }
                return ScalarLogicExpr{"grhsim_clog2_u64(" + operands[0] + ", " +
                                           std::to_string(graph.valueWidth(op.operands()[0])) + ")",
                                       false};
            }
            default:
                break;
            }
            return ScalarLogicExpr{};
        }

        std::optional<std::string> exactEventExpr(const Graph &graph,
                                                  const EmitModel &model,
                                                  OperationId opId,
                                                  const Operation &op)
        {
            const auto sampleIt = model.eventSamplesByOp.find(opId);
            if (sampleIt == model.eventSamplesByOp.end() || sampleIt->second.values.empty())
            {
                return std::string("true");
            }

            const EventSampleDecl &samples = sampleIt->second;
            std::vector<std::string> parts;
            for (std::size_t i = 0; i < samples.values.size(); ++i)
            {
                const ValueId value = samples.values[i];
                const std::string &edgeField = model.eventEdgeFieldByValue.at(value);
                const std::string &edge = samples.edges[i];
                if (edge.empty())
                {
                    parts.push_back(edgeField + " != grhsim_event_edge_kind::none");
                }
                else if (edge == "posedge")
                {
                    parts.push_back(edgeField + " == grhsim_event_edge_kind::posedge");
                }
                else if (edge == "negedge")
                {
                    parts.push_back(edgeField + " == grhsim_event_edge_kind::negedge");
                }
                else
                {
                    parts.push_back(edgeField + " != grhsim_event_edge_kind::none");
                }
            }
            if (parts.empty())
            {
                return std::string("true");
            }
            return joinStrings(parts, " || ");
        }

        bool isWritePortKind(OperationKind kind) noexcept
        {
            switch (kind)
            {
            case OperationKind::kRegisterWritePort:
            case OperationKind::kLatchWritePort:
            case OperationKind::kMemoryWritePort:
            case OperationKind::kMemoryFillPort:
                return true;
            default:
                return false;
            }
        }

        std::string scalarStateWriteHelperName(ValueSlotScalarKind kind)
        {
            switch (kind)
            {
            case ValueSlotScalarKind::kBool:
                return "apply_scalar_state_write_bool";
            case ValueSlotScalarKind::kU8:
                return "apply_scalar_state_write_u8";
            case ValueSlotScalarKind::kU16:
                return "apply_scalar_state_write_u16";
            case ValueSlotScalarKind::kU32:
                return "apply_scalar_state_write_u32";
            case ValueSlotScalarKind::kU64:
                return "apply_scalar_state_write_u64";
            case ValueSlotScalarKind::kCount:
                break;
            }
            return "apply_scalar_state_write_u64";
        }

        struct WritePortGuardKey
        {
            std::string condExpr;
            std::string eventExpr;

            bool operator==(const WritePortGuardKey &) const = default;
        };

        struct CommitWriteGuardGroup
        {
            std::string condExpr;
            std::vector<std::size_t> runIndices;
        };

        struct OrderedMemoryWriteSlotIndices
        {
            std::uint32_t cond = 0;
            std::uint32_t addr = 0;
            std::uint32_t data = 0;
        };

        struct OrderedMemoryWriteAffineRange
        {
            OrderedMemoryWriteSlotIndices first;
            std::int64_t condStep = 0;
            std::int64_t addrStep = 0;
            std::int64_t dataStep = 0;
            std::size_t count = 0;
        };

        struct OrderedMemoryWriteAffineGroup
        {
            std::string priorityGroup;
            std::string stateSymbol;
            std::size_t firstGuardGroupIndex = 0;
            std::vector<OperationId> opIds;
            std::vector<OrderedMemoryWriteAffineRange> ranges;
        };

        struct TableCompressibleScalarStateWriteDesc
        {
            ValueSlotScalarKind kind = ValueSlotScalarKind::kBool;
            std::uint32_t condIndex = 0;
            std::uint32_t touchedIndex = 0;
            std::uint32_t shadowDataIndex = 0;
            std::uint32_t stateDataIndex = 0;
            std::uint32_t nextIndex = 0;
            std::uint32_t maskIndex = 0;
            std::uint32_t shadowIndex = 0;
        };

        struct ScalarStateWriteRangeStep
        {
            std::int32_t cond = 0;
            std::int32_t touched = 0;
            std::int32_t shadowData = 0;
            std::int32_t stateData = 0;
            std::int32_t next = 0;
            std::int32_t mask = 0;
            std::int32_t shadow = 0;

            bool operator==(const ScalarStateWriteRangeStep &) const = default;
        };

        struct DirectCommitScalarStateWriteDesc
        {
            ValueSlotScalarKind kind = ValueSlotScalarKind::kBool;
            std::uint32_t condIndex = 0;
            std::uint32_t stateDataIndex = 0;
            std::uint32_t nextIndex = 0;
            std::uint32_t maskIndex = 0;
            std::vector<ActiveMaskEntry> activationEntries;
        };

        struct DirectCommitScalarStateWriteRangeStep
        {
            std::int32_t cond = 0;
            std::int32_t stateData = 0;
            std::int32_t next = 0;
            std::int32_t mask = 0;

            bool operator==(const DirectCommitScalarStateWriteRangeStep &) const = default;
        };

        std::optional<WritePortGuardKey> writePortGuardKey(const Graph &graph,
                                                           const EmitModel &model,
                                                           OperationId opId,
                                                           const Operation &op,
                                                           const SupernodeLocalExprContext *context = nullptr)
        {
            const auto operands = op.operands();
            const std::string condExpr =
                operands.empty() ? "true" : truthyLogicValueExpr(graph, model, operands[0], context);
            const auto eventExpr = exactEventExpr(graph, model, opId, op);
            if (!eventExpr)
            {
                return std::nullopt;
            }
            return WritePortGuardKey{
                .condExpr = condExpr,
                .eventExpr = *eventExpr,
            };
        }

        std::vector<CommitWriteGuardGroup> buildCommitWriteGuardGroups(
            std::span<const WritePortGuardKey> guardKeys)
        {
            std::vector<CommitWriteGuardGroup> groups;
            groups.reserve(guardKeys.size());
            for (std::size_t keyIndex = 0; keyIndex < guardKeys.size(); ++keyIndex)
            {
                auto groupIt = std::find_if(groups.begin(),
                                            groups.end(),
                                            [&](const CommitWriteGuardGroup &group)
                                            {
                                                return group.condExpr == guardKeys[keyIndex].condExpr;
                                            });
                if (groupIt == groups.end())
                {
                    groups.push_back(CommitWriteGuardGroup{
                        .condExpr = guardKeys[keyIndex].condExpr,
                        .runIndices = {keyIndex},
                    });
                    continue;
                }
                groupIt->runIndices.push_back(keyIndex);
            }
            return groups;
        }

        std::vector<OrderedMemoryWriteAffineRange> buildOrderedMemoryWriteAffineRanges(
            std::span<const OrderedMemoryWriteSlotIndices> entries)
        {
            std::vector<OrderedMemoryWriteAffineRange> ranges;
            std::size_t start = 0;
            while (start < entries.size())
            {
                std::size_t end = start + 1u;
                std::int64_t condStep = 0;
                std::int64_t addrStep = 0;
                std::int64_t dataStep = 0;
                if (end < entries.size())
                {
                    condStep = static_cast<std::int64_t>(entries[end].cond) - entries[start].cond;
                    addrStep = static_cast<std::int64_t>(entries[end].addr) - entries[start].addr;
                    dataStep = static_cast<std::int64_t>(entries[end].data) - entries[start].data;
                    ++end;
                    while (end < entries.size())
                    {
                        const auto &lhs = entries[end - 1u];
                        const auto &rhs = entries[end];
                        if (static_cast<std::int64_t>(rhs.cond) - lhs.cond != condStep ||
                            static_cast<std::int64_t>(rhs.addr) - lhs.addr != addrStep ||
                            static_cast<std::int64_t>(rhs.data) - lhs.data != dataStep)
                        {
                            break;
                        }
                        ++end;
                    }
                }
                ranges.push_back(OrderedMemoryWriteAffineRange{
                    .first = entries[start],
                    .condStep = condStep,
                    .addrStep = addrStep,
                    .dataStep = dataStep,
                    .count = end - start,
                });
                start = end;
            }
            return ranges;
        }

        std::vector<OrderedMemoryWriteAffineGroup> buildOrderedMemoryWriteAffineGroups(
            const Graph &graph,
            const EmitModel &model,
            std::span<const OperationId> runOpIds,
            std::span<const CommitWriteGuardGroup> guardGroups)
        {
            std::vector<OrderedMemoryWriteAffineGroup> groups;
            std::size_t runIndex = 0;
            while (runIndex < runOpIds.size())
            {
                const Operation firstOp = graph.getOperation(runOpIds[runIndex]);
                const auto priorityGroup = getAttribute<std::string>(
                    firstOp, wolvrix::lib::grh::kMemoryWritePriorityGroupAttr);
                if (!priorityGroup)
                {
                    ++runIndex;
                    continue;
                }

                const std::size_t firstRunIndex = runIndex;
                while (runIndex < runOpIds.size())
                {
                    const Operation candidateOp = graph.getOperation(runOpIds[runIndex]);
                    const auto candidateGroup = getAttribute<std::string>(
                        candidateOp, wolvrix::lib::grh::kMemoryWritePriorityGroupAttr);
                    if (!candidateGroup || *candidateGroup != *priorityGroup)
                    {
                        break;
                    }
                    ++runIndex;
                }
                const std::size_t writeCount = runIndex - firstRunIndex;
                if (writeCount < kOrderedMemoryWriteAffineMinWrites)
                {
                    continue;
                }

                bool valid = true;
                for (std::size_t otherIndex = 0; otherIndex < runOpIds.size(); ++otherIndex)
                {
                    if (otherIndex >= firstRunIndex && otherIndex < runIndex)
                    {
                        continue;
                    }
                    const Operation otherOp = graph.getOperation(runOpIds[otherIndex]);
                    const auto otherGroup = getAttribute<std::string>(
                        otherOp, wolvrix::lib::grh::kMemoryWritePriorityGroupAttr);
                    if (otherGroup && *otherGroup == *priorityGroup)
                    {
                        valid = false;
                        break;
                    }
                }
                if (!valid)
                {
                    continue;
                }

                std::string stateSymbol;
                std::vector<OperationId> opIds;
                std::vector<OrderedMemoryWriteSlotIndices> entries;
                opIds.reserve(writeCount);
                entries.reserve(writeCount);
                for (std::size_t offset = 0; offset < writeCount; ++offset)
                {
                    const OperationId opId = runOpIds[firstRunIndex + offset];
                    const Operation op = graph.getOperation(opId);
                    const auto priority = getAttribute<int64_t>(
                        op, wolvrix::lib::grh::kMemoryWritePriorityAttr);
                    if (op.kind() != OperationKind::kMemoryWritePort || !priority ||
                        *priority != static_cast<int64_t>(writeCount - 1u - offset))
                    {
                        valid = false;
                        break;
                    }
                    const auto writeIt = model.writeByOp.find(opId);
                    if (writeIt == model.writeByOp.end() ||
                        writeIt->second.kind != StateDecl::Kind::Memory ||
                        writeIt->second.isMemoryFill ||
                        writeIt->second.memoryMaskMode != WriteDecl::MemoryMaskMode::kConstAllOnes)
                    {
                        valid = false;
                        break;
                    }
                    const WriteDecl &write = writeIt->second;
                    if (offset == 0)
                    {
                        stateSymbol = write.symbol;
                    }
                    else if (write.symbol != stateSymbol)
                    {
                        valid = false;
                        break;
                    }
                    const auto stateIt = model.stateBySymbol.find(write.symbol);
                    if (stateIt == model.stateBySymbol.end())
                    {
                        valid = false;
                        break;
                    }
                    const StateDecl &state = stateIt->second;
                    if (state.kind != StateDecl::Kind::Memory || state.width <= 0 || state.width > 8 ||
                        state.scalarKind != ValueSlotScalarKind::kU8 || state.rowCount <= 0 ||
                        state.rowCount > 64 || !isPowerOfTwoU64(static_cast<std::uint64_t>(state.rowCount)))
                    {
                        valid = false;
                        break;
                    }
                    const auto operands = op.operands();
                    if (operands.size() < 4 || graph.valueWidth(operands[0]) != 1 ||
                        graph.valueWidth(operands[1]) <= 0 || graph.valueWidth(operands[1]) > 8 ||
                        graph.valueWidth(operands[2]) != state.width)
                    {
                        valid = false;
                        break;
                    }
                    const auto condIt = model.valueScalarSlotByValue.find(operands[0]);
                    const auto addrIt = model.valueScalarSlotByValue.find(operands[1]);
                    const auto dataIt = model.valueScalarSlotByValue.find(operands[2]);
                    if (condIt == model.valueScalarSlotByValue.end() ||
                        condIt->second.kind != ValueSlotScalarKind::kBool ||
                        addrIt == model.valueScalarSlotByValue.end() ||
                        addrIt->second.kind != ValueSlotScalarKind::kU8 ||
                        dataIt == model.valueScalarSlotByValue.end() ||
                        dataIt->second.kind != ValueSlotScalarKind::kU8 ||
                        condIt->second.slotIndex > std::numeric_limits<std::uint32_t>::max() ||
                        addrIt->second.slotIndex > std::numeric_limits<std::uint32_t>::max() ||
                        dataIt->second.slotIndex > std::numeric_limits<std::uint32_t>::max())
                    {
                        valid = false;
                        break;
                    }
                    opIds.push_back(opId);
                    entries.push_back(OrderedMemoryWriteSlotIndices{
                        .cond = static_cast<std::uint32_t>(condIt->second.slotIndex),
                        .addr = static_cast<std::uint32_t>(addrIt->second.slotIndex),
                        .data = static_cast<std::uint32_t>(dataIt->second.slotIndex),
                    });
                }
                if (!valid)
                {
                    continue;
                }

                std::size_t firstGuardGroupIndex = kInvalidIndex;
                for (std::size_t guardIndex = 0; guardIndex < guardGroups.size(); ++guardIndex)
                {
                    if (guardGroups[guardIndex].runIndices.size() == 1u &&
                        guardGroups[guardIndex].runIndices.front() == firstRunIndex)
                    {
                        firstGuardGroupIndex = guardIndex;
                        break;
                    }
                }
                if (firstGuardGroupIndex == kInvalidIndex ||
                    firstGuardGroupIndex + writeCount > guardGroups.size())
                {
                    continue;
                }
                for (std::size_t offset = 0; offset < writeCount; ++offset)
                {
                    const CommitWriteGuardGroup &guardGroup = guardGroups[firstGuardGroupIndex + offset];
                    if (guardGroup.runIndices.size() != 1u ||
                        guardGroup.runIndices.front() != firstRunIndex + offset)
                    {
                        valid = false;
                        break;
                    }
                }
                if (!valid)
                {
                    continue;
                }

                std::vector<OrderedMemoryWriteAffineRange> ranges =
                    buildOrderedMemoryWriteAffineRanges(entries);
                if (ranges.size() * 4u > writeCount)
                {
                    continue;
                }
                groups.push_back(OrderedMemoryWriteAffineGroup{
                    .priorityGroup = *priorityGroup,
                    .stateSymbol = std::move(stateSymbol),
                    .firstGuardGroupIndex = firstGuardGroupIndex,
                    .opIds = std::move(opIds),
                    .ranges = std::move(ranges),
                });
            }
            return groups;
        }

        struct CommitEventClusterInfo
        {
            bool homogeneous = false;
            std::string eventExpr = "true";
            std::string dispatchExpr = "true";
            std::vector<std::string> eventExprs;
        };

        std::optional<CommitEventClusterInfo> analyzeCommitSupernodeEvent(const Graph &graph,
                                                                          const EmitModel &model,
                                                                          const ActivityScheduleSupernodeToOps &supernodeToOps,
                                                                          uint32_t supernodeId)
        {
            CommitEventClusterInfo info;
            if (supernodeId >= supernodeToOps.size())
            {
                info.homogeneous = true;
                info.eventExprs.push_back(info.eventExpr);
                return info;
            }

            info.homogeneous = true;
            bool sawCommitOp = false;
            for (const OperationId opId : supernodeToOps[supernodeId])
            {
                const Operation op = graph.getOperation(opId);
                if (!isCommitPhaseOp(op))
                {
                    continue;
                }
                const auto eventExpr = exactEventExpr(graph, model, opId, op);
                if (!eventExpr)
                {
                    return std::nullopt;
                }
                if (std::find(info.eventExprs.begin(), info.eventExprs.end(), *eventExpr) ==
                    info.eventExprs.end())
                {
                    info.eventExprs.push_back(*eventExpr);
                }
                if (!sawCommitOp)
                {
                    info.eventExpr = *eventExpr;
                    sawCommitOp = true;
                    continue;
                }
                if (info.eventExpr != *eventExpr)
                {
                    info.homogeneous = false;
                }
            }

            if (!sawCommitOp)
            {
                info.eventExpr = "true";
                info.eventExprs.push_back(info.eventExpr);
            }
            if (std::find(info.eventExprs.begin(), info.eventExprs.end(), std::string("true")) !=
                info.eventExprs.end())
            {
                info.dispatchExpr = "true";
            }
            else
            {
                if (info.eventExprs.size() == 1u)
                {
                    info.dispatchExpr = info.eventExprs.front();
                }
                else
                {
                    std::vector<std::string> parts;
                    parts.reserve(info.eventExprs.size());
                    for (const auto &expr : info.eventExprs)
                    {
                        parts.push_back("(" + expr + ")");
                    }
                    info.dispatchExpr = parts.empty() ? std::string("true") : joinStrings(parts, " || ");
                }
            }
            return info;
        }

        bool isPureEventComputeProducerKind(OperationKind kind) noexcept
        {
            switch (kind)
            {
            case OperationKind::kConstant:
            case OperationKind::kAdd:
            case OperationKind::kSub:
            case OperationKind::kMul:
            case OperationKind::kDiv:
            case OperationKind::kMod:
            case OperationKind::kEq:
            case OperationKind::kNe:
            case OperationKind::kCaseEq:
            case OperationKind::kCaseNe:
            case OperationKind::kWildcardEq:
            case OperationKind::kWildcardNe:
            case OperationKind::kLt:
            case OperationKind::kLe:
            case OperationKind::kGt:
            case OperationKind::kGe:
            case OperationKind::kAnd:
            case OperationKind::kOr:
            case OperationKind::kXor:
            case OperationKind::kXnor:
            case OperationKind::kNot:
            case OperationKind::kLogicAnd:
            case OperationKind::kLogicOr:
            case OperationKind::kLogicNot:
            case OperationKind::kReduceAnd:
            case OperationKind::kReduceOr:
            case OperationKind::kReduceXor:
            case OperationKind::kReduceNor:
            case OperationKind::kReduceNand:
            case OperationKind::kReduceXnor:
            case OperationKind::kShl:
            case OperationKind::kLShr:
            case OperationKind::kAShr:
            case OperationKind::kMux:
            case OperationKind::kAssign:
            case OperationKind::kConcat:
            case OperationKind::kReplicate:
            case OperationKind::kSliceStatic:
            case OperationKind::kSliceDynamic:
            case OperationKind::kSliceArray:
            case OperationKind::kLatchReadPort:
            case OperationKind::kRegisterReadPort:
            case OperationKind::kMemoryReadPort:
                return true;
            default:
                return false;
            }
        }

        std::optional<std::string> analyzePureEventComputeSupernode(
            const Graph &graph,
            const EmitModel &model,
            const ActivityScheduleSupernodeToOps &supernodeToOps,
            uint32_t supernodeId)
        {
            if (supernodeId >= supernodeToOps.size())
            {
                return std::nullopt;
            }

            bool sawSideEffect = false;
            std::optional<std::string> commonEventExpr;
            for (OperationId opId : supernodeToOps[supernodeId])
            {
                const Operation op = graph.getOperation(opId);
                if (isCommitPhaseOp(op) || isRegToMemIntentBypassOp(model, opId))
                {
                    return std::nullopt;
                }
                if (op.kind() == OperationKind::kSystemTask || op.kind() == OperationKind::kDpicCall)
                {
                    if (op.operands().empty() || !op.results().empty() ||
                        (op.kind() == OperationKind::kSystemTask && systemTaskIsFinal(op)))
                    {
                        return std::nullopt;
                    }
                    const auto sampleIt = model.eventSamplesByOp.find(opId);
                    if (sampleIt == model.eventSamplesByOp.end() || sampleIt->second.values.size() != 1u ||
                        sampleIt->second.edges.size() != 1u || !sampleIt->second.completedFieldName.empty())
                    {
                        return std::nullopt;
                    }
                    const std::string &edge = sampleIt->second.edges.front();
                    if (edge != "posedge" && edge != "negedge")
                    {
                        return std::nullopt;
                    }
                    const auto eventExpr = exactEventExpr(graph, model, opId, op);
                    if (!eventExpr || *eventExpr == "true")
                    {
                        return std::nullopt;
                    }
                    if (commonEventExpr && *commonEventExpr != *eventExpr)
                    {
                        return std::nullopt;
                    }
                    commonEventExpr = *eventExpr;
                    sawSideEffect = true;
                    continue;
                }

                if (!isPureEventComputeProducerKind(op.kind()) ||
                    getAttribute<bool>(op, "hasSideEffects").value_or(false))
                {
                    return std::nullopt;
                }
                if (op.kind() == OperationKind::kConstant)
                {
                    continue;
                }
                if (op.results().empty())
                {
                    return std::nullopt;
                }
                for (ValueId result : op.results())
                {
                    if (isMaterializedValue(model, result) || valueNeedsTrackedChange(model, result))
                    {
                        return std::nullopt;
                    }
                }
            }
            if (!sawSideEffect || !commonEventExpr)
            {
                return std::nullopt;
            }
            return commonEventExpr;
        }

        std::optional<std::string> analyzePureEventComputeWord(
            const Graph &graph,
            const EmitModel &model,
            const ActivityScheduleSupernodeToOps &supernodeToOps,
            const ScheduleBatch::Word &word)
        {
            std::optional<std::string> commonEventExpr;
            for (uint32_t supernodeId : word.supernodeIds)
            {
                const auto eventExpr =
                    analyzePureEventComputeSupernode(graph, model, supernodeToOps, supernodeId);
                if (!eventExpr)
                {
                    return std::nullopt;
                }
                if (commonEventExpr && *commonEventExpr != *eventExpr)
                {
                    return std::nullopt;
                }
                commonEventExpr = *eventExpr;
            }
            return commonEventExpr;
        }

        std::optional<std::string> eligiblePureEventComputeWordExpr(
            const Graph &graph,
            const EmitModel &model,
            const ScheduleRefs &schedule,
            const ScheduleBatch &batch,
            const ScheduleBatch::Word &word,
            bool allowed)
        {
            if (!allowed || batch.phase != ScheduleBatch::Phase::kCompute)
            {
                return std::nullopt;
            }
            const std::uint8_t dispatchMask = scheduleBatchWordDispatchMask(model, word);
            const std::uint8_t clearMask = scheduleBatchWordClearMask(model, batch, word);
            const bool consumeFullActiveWord =
                model.fullActiveWordConsume && dispatchMask == UINT8_C(0xff);
            if (consumeFullActiveWord || dispatchMask == UINT8_C(0) || dispatchMask != clearMask)
            {
                return std::nullopt;
            }
            return analyzePureEventComputeWord(graph, model, schedule.supernodeToOps, word);
        }

        std::size_t ratioPpm(std::size_t numerator, std::size_t denominator) noexcept
        {
            if (denominator == 0u)
            {
                return numerator == 0u ? 0u : std::numeric_limits<std::size_t>::max();
            }
            return static_cast<std::size_t>(
                (static_cast<unsigned __int128>(numerator) * 1000000u) / denominator);
        }

        bool withinPpmBudget(std::size_t numerator,
                             std::size_t denominator,
                             std::size_t maxPpm) noexcept
        {
            if (denominator == 0u)
            {
                return numerator == 0u;
            }
            return static_cast<unsigned __int128>(numerator) * 1000000u <=
                   static_cast<unsigned __int128>(denominator) * maxPpm;
        }

        bool buildActivityScheduleKahnLevels(const ActivityScheduleDag &dag,
                                             std::size_t supernodeCount,
                                             std::vector<std::size_t> &levelBySupernode,
                                             std::size_t &levelCount,
                                             std::string &error)
        {
            if (dag.size() != supernodeCount)
            {
                error = "activity-schedule dag size mismatch: dag=" + std::to_string(dag.size()) +
                        " supernodes=" + std::to_string(supernodeCount);
                return false;
            }

            std::vector<std::size_t> indegree(supernodeCount, 0u);
            for (std::size_t supernodeId = 0; supernodeId < dag.size(); ++supernodeId)
            {
                for (uint32_t succ : dag[supernodeId])
                {
                    if (succ >= supernodeCount)
                    {
                        error = "activity-schedule dag contains out-of-range edge: " +
                                std::to_string(supernodeId) + "->" + std::to_string(succ);
                        return false;
                    }
                    ++indegree[succ];
                }
            }

            std::vector<uint32_t> frontier;
            frontier.reserve(supernodeCount);
            for (std::size_t supernodeId = 0; supernodeId < supernodeCount; ++supernodeId)
            {
                if (indegree[supernodeId] == 0u)
                {
                    frontier.push_back(static_cast<uint32_t>(supernodeId));
                }
            }
            std::sort(frontier.begin(), frontier.end());

            levelBySupernode.assign(supernodeCount, kInvalidIndex);
            std::size_t visited = 0u;
            levelCount = 0u;
            while (!frontier.empty())
            {
                std::vector<uint32_t> next;
                for (uint32_t supernodeId : frontier)
                {
                    levelBySupernode[supernodeId] = levelCount;
                    ++visited;
                    for (uint32_t succ : dag[supernodeId])
                    {
                        if (--indegree[succ] == 0u)
                        {
                            next.push_back(succ);
                        }
                    }
                }
                std::sort(next.begin(), next.end());
                frontier = std::move(next);
                ++levelCount;
            }
            if (visited != supernodeCount)
            {
                error = "activity-schedule dag contains a cycle: visited=" + std::to_string(visited) +
                        " supernodes=" + std::to_string(supernodeCount);
                return false;
            }
            return true;
        }

        bool validateActivityScheduleTopo(const ActivityScheduleDag &dag,
                                          const ActivityScheduleTopoOrder &topoOrder,
                                          std::vector<std::size_t> &positionBySupernode,
                                          std::string &error)
        {
            if (topoOrder.size() != dag.size())
            {
                error = "activity-schedule topo size mismatch: topo=" + std::to_string(topoOrder.size()) +
                        " dag=" + std::to_string(dag.size());
                return false;
            }
            positionBySupernode.assign(dag.size(), kInvalidIndex);
            for (std::size_t position = 0; position < topoOrder.size(); ++position)
            {
                const uint32_t supernodeId = topoOrder[position];
                if (supernodeId >= dag.size() || positionBySupernode[supernodeId] != kInvalidIndex)
                {
                    error = "activity-schedule topo is not a strict supernode permutation at position=" +
                            std::to_string(position) + " supernode=" + std::to_string(supernodeId);
                    return false;
                }
                positionBySupernode[supernodeId] = position;
            }
            for (std::size_t supernodeId = 0; supernodeId < dag.size(); ++supernodeId)
            {
                for (uint32_t succ : dag[supernodeId])
                {
                    if (succ >= dag.size() ||
                        positionBySupernode[supernodeId] >= positionBySupernode[succ])
                    {
                        error = "activity-schedule topo violates dag edge: " +
                                std::to_string(supernodeId) + "->" + std::to_string(succ);
                        return false;
                    }
                }
            }
            return true;
        }

        bool buildTargetedPureEventWordPack(
            const Graph &graph,
            const EmitModel &baselineModel,
            const ScheduleRefs &schedule,
            const std::vector<ScheduleBatch> &baselineBatches,
            PureEventWordPackStats &stats,
            ActivityScheduleTopoOrder &candidateTopoOrder,
            std::string &error)
        {
            if (schedule.dag == nullptr)
            {
                error = "missing activity-schedule dag for pure-event word packing";
                return false;
            }
            const ActivityScheduleDag &dag = *schedule.dag;
            const std::size_t supernodeCount = schedule.supernodeToOps.size();
            stats.supernodeCount = supernodeCount;
            stats.computeSupernodeCount = baselineModel.computeSupernodeIds.size();
            stats.batchCount = baselineBatches.size();

            std::vector<std::size_t> levelBySupernode;
            if (!buildActivityScheduleKahnLevels(
                    dag, supernodeCount, levelBySupernode, stats.kahnLevelCount, error))
            {
                return false;
            }
            std::vector<std::size_t> baselinePosition;
            if (!validateActivityScheduleTopo(dag, schedule.topoOrder, baselinePosition, error))
            {
                return false;
            }

            std::vector<std::size_t> batchBySupernode(supernodeCount, kInvalidIndex);
            std::set<std::size_t> computeActiveWords;
            for (const ScheduleBatch &batch : baselineBatches)
            {
                for (uint32_t supernodeId : batch.supernodeIds)
                {
                    if (supernodeId >= supernodeCount || batchBySupernode[supernodeId] != kInvalidIndex)
                    {
                        error = "baseline schedule batches do not form a strict supernode partition";
                        return false;
                    }
                    batchBySupernode[supernodeId] = batch.index;
                }
                if (batch.phase == ScheduleBatch::Phase::kCompute)
                {
                    for (const ScheduleBatch::Word &word : batch.words)
                    {
                        computeActiveWords.insert(word.activeFlagWordIndex);
                    }
                }
            }
            for (uint32_t supernodeId : schedule.topoOrder)
            {
                if (supernodeId >= supernodeCount || batchBySupernode[supernodeId] == kInvalidIndex)
                {
                    error = "baseline schedule batches omit supernode=" + std::to_string(supernodeId);
                    return false;
                }
            }
            stats.computeActiveWordCount = computeActiveWords.size();

            using Group = std::pair<std::size_t, std::size_t>;
            std::map<Group, std::vector<std::size_t>> wordsByGroup;
            std::map<std::size_t, std::string> baselinePureExprByWord;
            std::map<std::size_t, std::vector<uint32_t>> baselinePureNodesByWord;
            for (const ScheduleBatch &batch : baselineBatches)
            {
                if (batch.phase != ScheduleBatch::Phase::kCompute)
                {
                    continue;
                }
                for (const ScheduleBatch::Word &word : batch.words)
                {
                    if (word.supernodeIds.size() != kActiveFlagBitsPerWord)
                    {
                        continue;
                    }
                    std::vector<std::size_t> activeIds;
                    activeIds.reserve(word.supernodeIds.size());
                    bool allCompute = true;
                    for (uint32_t supernodeId : word.supernodeIds)
                    {
                        allCompute = allCompute && isComputeSupernode(baselineModel, supernodeId) &&
                                     !isCommitSupernode(baselineModel, supernodeId);
                        if (supernodeId >= baselineModel.activeIdBySupernode.size())
                        {
                            allCompute = false;
                            break;
                        }
                        activeIds.push_back(baselineModel.activeIdBySupernode[supernodeId]);
                    }
                    std::sort(activeIds.begin(), activeIds.end());
                    const std::size_t wordBegin = word.activeFlagWordIndex * kActiveFlagBitsPerWord;
                    for (std::size_t bit = 0; allCompute && bit < kActiveFlagBitsPerWord; ++bit)
                    {
                        allCompute = activeIds[bit] == wordBegin + bit;
                    }
                    if (!allCompute)
                    {
                        continue;
                    }

                    if (const auto expr = eligiblePureEventComputeWordExpr(
                            graph, baselineModel, schedule, batch, word, true))
                    {
                        baselinePureExprByWord.emplace(word.activeFlagWordIndex, *expr);
                        baselinePureNodesByWord.emplace(word.activeFlagWordIndex, word.supernodeIds);
                    }

                    const std::uint8_t dispatchMask =
                        scheduleBatchWordDispatchMask(baselineModel, word);
                    const std::uint8_t clearMask =
                        scheduleBatchWordClearMask(baselineModel, batch, word);
                    const bool consumeFullActiveWord =
                        baselineModel.fullActiveWordConsume && dispatchMask == UINT8_C(0xff);
                    if (consumeFullActiveWord || dispatchMask == UINT8_C(0) ||
                        dispatchMask != clearMask)
                    {
                        continue;
                    }

                    const std::size_t firstLevel = levelBySupernode[word.supernodeIds.front()];
                    const bool sameLevel = std::all_of(
                        word.supernodeIds.begin(),
                        word.supernodeIds.end(),
                        [&](uint32_t supernodeId) { return levelBySupernode[supernodeId] == firstLevel; });
                    if (!sameLevel)
                    {
                        continue;
                    }
                    wordsByGroup[{firstLevel, batch.index}].push_back(word.activeFlagWordIndex);
                    ++stats.eligibleFullComputeWordCount;
                }
            }
            stats.baselinePureWordCount = baselinePureExprByWord.size();

            candidateTopoOrder = schedule.topoOrder;
            for (auto &[group, words] : wordsByGroup)
            {
                (void)group;
                std::sort(words.begin(), words.end());
                std::map<std::string, std::vector<uint32_t>> nodesByKey;
                for (std::size_t wordIndex : words)
                {
                    const std::size_t begin = wordIndex * kActiveFlagBitsPerWord;
                    for (std::size_t bit = 0; bit < kActiveFlagBitsPerWord; ++bit)
                    {
                        const uint32_t supernodeId = schedule.topoOrder[begin + bit];
                        if (const auto expr = analyzePureEventComputeSupernode(
                                graph, baselineModel, schedule.supernodeToOps, supernodeId))
                        {
                            nodesByKey[*expr].push_back(supernodeId);
                        }
                    }
                }

                std::map<std::size_t, std::string> assignedWord;
                std::map<std::string, std::vector<std::size_t>> assignedWordsByKey;
                for (std::size_t wordIndex : words)
                {
                    const auto pureIt = baselinePureExprByWord.find(wordIndex);
                    if (pureIt == baselinePureExprByWord.end())
                    {
                        continue;
                    }
                    assignedWord.emplace(wordIndex, pureIt->second);
                    assignedWordsByKey[pureIt->second].push_back(wordIndex);
                }

                std::map<std::string, std::size_t> demandByKey;
                for (const auto &[key, nodes] : nodesByKey)
                {
                    const std::size_t assigned = assignedWordsByKey[key].size();
                    const std::size_t capacity = nodes.size() / kActiveFlagBitsPerWord;
                    if (assigned > capacity)
                    {
                        error = "pure-event word pack assigned-word demand underflow";
                        return false;
                    }
                    demandByKey.emplace(key, capacity - assigned);
                }

                std::set<std::size_t> freeWords(words.begin(), words.end());
                for (const auto &[wordIndex, key] : assignedWord)
                {
                    (void)key;
                    freeWords.erase(wordIndex);
                }
                struct WordChoice
                {
                    std::size_t matches = 0;
                    std::size_t wordIndex = 0;
                    std::string key;
                };
                std::vector<WordChoice> choices;
                choices.reserve(nodesByKey.size() * freeWords.size());
                for (const auto &[key, nodes] : nodesByKey)
                {
                    (void)nodes;
                    for (std::size_t wordIndex : freeWords)
                    {
                        std::size_t matches = 0u;
                        const std::size_t begin = wordIndex * kActiveFlagBitsPerWord;
                        for (std::size_t bit = 0; bit < kActiveFlagBitsPerWord; ++bit)
                        {
                            const uint32_t supernodeId = schedule.topoOrder[begin + bit];
                            const auto expr = analyzePureEventComputeSupernode(
                                graph, baselineModel, schedule.supernodeToOps, supernodeId);
                            matches += expr && *expr == key ? 1u : 0u;
                        }
                        choices.push_back(WordChoice{.matches = matches,
                                                     .wordIndex = wordIndex,
                                                     .key = key});
                    }
                }
                std::sort(choices.begin(),
                          choices.end(),
                          [](const WordChoice &lhs, const WordChoice &rhs)
                          {
                              if (lhs.matches != rhs.matches)
                              {
                                  return lhs.matches > rhs.matches;
                              }
                              if (lhs.wordIndex != rhs.wordIndex)
                              {
                                  return lhs.wordIndex < rhs.wordIndex;
                              }
                              return lhs.key < rhs.key;
                          });
                for (const WordChoice &choice : choices)
                {
                    auto demandIt = demandByKey.find(choice.key);
                    if (!freeWords.contains(choice.wordIndex) ||
                        demandIt == demandByKey.end() || demandIt->second == 0u)
                    {
                        continue;
                    }
                    assignedWord.emplace(choice.wordIndex, choice.key);
                    assignedWordsByKey[choice.key].push_back(choice.wordIndex);
                    freeWords.erase(choice.wordIndex);
                    --demandIt->second;
                }
                for (auto &[key, demand] : demandByKey)
                {
                    while (demand != 0u)
                    {
                        if (freeWords.empty())
                        {
                            error = "not enough complete words for targeted pure-event packing";
                            return false;
                        }
                        const std::size_t wordIndex = *freeWords.begin();
                        assignedWord.emplace(wordIndex, key);
                        assignedWordsByKey[key].push_back(wordIndex);
                        freeWords.erase(freeWords.begin());
                        --demand;
                    }
                }

                std::set<uint32_t> usedNodes;
                std::set<std::size_t> targetPositions;
                for (auto &[key, assignedWords] : assignedWordsByKey)
                {
                    std::sort(assignedWords.begin(), assignedWords.end());
                    std::vector<std::size_t> keyPositions;
                    for (std::size_t wordIndex : assignedWords)
                    {
                        for (std::size_t bit = 0; bit < kActiveFlagBitsPerWord; ++bit)
                        {
                            keyPositions.push_back(wordIndex * kActiveFlagBitsPerWord + bit);
                        }
                    }
                    targetPositions.insert(keyPositions.begin(), keyPositions.end());

                    const std::vector<uint32_t> &available = nodesByKey.at(key);
                    std::set<uint32_t> availableSet(available.begin(), available.end());
                    std::vector<std::size_t> emptyPositions;
                    for (std::size_t position : keyPositions)
                    {
                        const uint32_t supernodeId = schedule.topoOrder[position];
                        if (availableSet.erase(supernodeId) != 0u)
                        {
                            candidateTopoOrder[position] = supernodeId;
                            usedNodes.insert(supernodeId);
                        }
                        else
                        {
                            emptyPositions.push_back(position);
                        }
                    }
                    std::vector<uint32_t> remaining;
                    for (uint32_t supernodeId : available)
                    {
                        if (availableSet.contains(supernodeId))
                        {
                            remaining.push_back(supernodeId);
                        }
                    }
                    if (remaining.size() < emptyPositions.size())
                    {
                        error = "targeted pure-event packing key fill mismatch";
                        return false;
                    }
                    for (std::size_t index = 0; index < emptyPositions.size(); ++index)
                    {
                        candidateTopoOrder[emptyPositions[index]] = remaining[index];
                        usedNodes.insert(remaining[index]);
                    }
                }

                std::vector<std::size_t> emptyPositions;
                std::vector<std::size_t> groupPositions;
                groupPositions.reserve(words.size() * kActiveFlagBitsPerWord);
                for (std::size_t wordIndex : words)
                {
                    for (std::size_t bit = 0; bit < kActiveFlagBitsPerWord; ++bit)
                    {
                        const std::size_t position = wordIndex * kActiveFlagBitsPerWord + bit;
                        groupPositions.push_back(position);
                        if (targetPositions.contains(position))
                        {
                            continue;
                        }
                        const uint32_t supernodeId = schedule.topoOrder[position];
                        if (!usedNodes.contains(supernodeId))
                        {
                            candidateTopoOrder[position] = supernodeId;
                            usedNodes.insert(supernodeId);
                        }
                        else
                        {
                            emptyPositions.push_back(position);
                        }
                    }
                }
                std::vector<uint32_t> unusedNodes;
                for (std::size_t position : groupPositions)
                {
                    const uint32_t supernodeId = schedule.topoOrder[position];
                    if (!usedNodes.contains(supernodeId))
                    {
                        unusedNodes.push_back(supernodeId);
                    }
                }
                if (emptyPositions.size() != unusedNodes.size())
                {
                    error = "targeted pure-event packing residual mismatch";
                    return false;
                }
                for (std::size_t index = 0; index < emptyPositions.size(); ++index)
                {
                    candidateTopoOrder[emptyPositions[index]] = unusedNodes[index];
                    usedNodes.insert(unusedNodes[index]);
                }
                if (usedNodes.size() != groupPositions.size())
                {
                    error = "targeted pure-event packing lost supernodes";
                    return false;
                }
            }

            std::vector<std::size_t> candidatePosition;
            if (!validateActivityScheduleTopo(dag, candidateTopoOrder, candidatePosition, error))
            {
                return false;
            }
            for (std::size_t position = 0; position < schedule.topoOrder.size(); ++position)
            {
                const uint32_t baselineSupernode = schedule.topoOrder[position];
                const uint32_t candidateSupernode = candidateTopoOrder[position];
                if (baselineSupernode == candidateSupernode)
                {
                    continue;
                }
                if (isCommitSupernode(baselineModel, baselineSupernode) ||
                    isCommitSupernode(baselineModel, candidateSupernode))
                {
                    error = "targeted pure-event packing moved a commit supernode";
                    return false;
                }
                if (levelBySupernode[baselineSupernode] != levelBySupernode[candidateSupernode] ||
                    batchBySupernode[baselineSupernode] != batchBySupernode[candidateSupernode])
                {
                    error = "targeted pure-event packing crossed a Kahn level or frozen batch";
                    return false;
                }
                ++stats.movedSupernodeCount;
                if (analyzePureEventComputeSupernode(
                        graph, baselineModel, schedule.supernodeToOps, baselineSupernode))
                {
                    ++stats.movedEventSupernodeCount;
                }
            }
            for (uint32_t supernodeId : baselineModel.computeSupernodeIds)
            {
                stats.maxActiveIdDisplacement = std::max(
                    stats.maxActiveIdDisplacement,
                    baselinePosition[supernodeId] > candidatePosition[supernodeId]
                        ? baselinePosition[supernodeId] - candidatePosition[supernodeId]
                        : candidatePosition[supernodeId] - baselinePosition[supernodeId]);
            }
            stats.movedSupernodePpm = ratioPpm(stats.movedSupernodeCount, stats.computeSupernodeCount);

            for (std::size_t wordIndex : computeActiveWords)
            {
                const std::size_t begin = wordIndex * kActiveFlagBitsPerWord;
                const std::size_t end = std::min(begin + kActiveFlagBitsPerWord, schedule.topoOrder.size());
                if (!std::equal(schedule.topoOrder.begin() + static_cast<std::ptrdiff_t>(begin),
                                schedule.topoOrder.begin() + static_cast<std::ptrdiff_t>(end),
                                candidateTopoOrder.begin() + static_cast<std::ptrdiff_t>(begin)))
                {
                    ++stats.changedWordCount;
                }
            }
            stats.changedWordPpm = ratioPpm(stats.changedWordCount, stats.computeActiveWordCount);
            if (!withinPpmBudget(stats.movedSupernodeCount,
                                 stats.computeSupernodeCount,
                                 stats.maxMovedSupernodePpm))
            {
                error = "targeted pure-event word pack exceeds moved-supernode budget: moved=" +
                        std::to_string(stats.movedSupernodeCount) + " compute=" +
                        std::to_string(stats.computeSupernodeCount) + " max_ppm=" +
                        std::to_string(stats.maxMovedSupernodePpm);
                return false;
            }
            if (!withinPpmBudget(stats.changedWordCount,
                                 stats.computeActiveWordCount,
                                 stats.maxChangedWordPpm))
            {
                error = "targeted pure-event word pack exceeds changed-word budget: changed=" +
                        std::to_string(stats.changedWordCount) + " compute_words=" +
                        std::to_string(stats.computeActiveWordCount) + " max_ppm=" +
                        std::to_string(stats.maxChangedWordPpm);
                return false;
            }

            std::size_t candidatePureWords = 0u;
            for (std::size_t wordIndex : computeActiveWords)
            {
                const std::size_t begin = wordIndex * kActiveFlagBitsPerWord;
                if (begin + kActiveFlagBitsPerWord > candidateTopoOrder.size())
                {
                    continue;
                }
                const std::span<const uint32_t> nodes(candidateTopoOrder.data() + begin,
                                                      kActiveFlagBitsPerWord);
                if (!std::all_of(nodes.begin(),
                                 nodes.end(),
                                 [&](uint32_t supernodeId)
                                 {
                                     return isComputeSupernode(baselineModel, supernodeId) &&
                                            !isCommitSupernode(baselineModel, supernodeId);
                                 }))
                {
                    continue;
                }
                ScheduleBatch candidateBatch;
                candidateBatch.phase = ScheduleBatch::Phase::kCompute;
                candidateBatch.index = batchBySupernode[nodes.front()];
                ScheduleBatch::Word candidateWord;
                candidateWord.activeFlagWordIndex = wordIndex;
                candidateWord.supernodeIds.assign(nodes.begin(), nodes.end());
                const bool sameBatch = std::all_of(
                    nodes.begin(),
                    nodes.end(),
                    [&](uint32_t supernodeId)
                    {
                        return batchBySupernode[supernodeId] == candidateBatch.index;
                    });
                // A complete all-compute candidate word has dispatchMask == clearMask == 0xff.
                // Event purity and materialization do not depend on active IDs, so avoid copying
                // the full model merely to repeat those two mask computations.
                const auto expr = sameBatch && !baselineModel.fullActiveWordConsume
                                      ? analyzePureEventComputeWord(
                                            graph,
                                            baselineModel,
                                            schedule.supernodeToOps,
                                            candidateWord)
                                      : std::optional<std::string>{};
                if (expr)
                {
                    ++candidatePureWords;
                }
                const auto baselinePureIt = baselinePureExprByWord.find(wordIndex);
                if (baselinePureIt == baselinePureExprByWord.end())
                {
                    continue;
                }
                std::vector<uint32_t> candidateNodes(nodes.begin(), nodes.end());
                std::vector<uint32_t> baselineNodes = baselinePureNodesByWord.at(wordIndex);
                std::sort(candidateNodes.begin(), candidateNodes.end());
                std::sort(baselineNodes.begin(), baselineNodes.end());
                if (!expr || *expr != baselinePureIt->second || candidateNodes != baselineNodes)
                {
                    error = "targeted pure-event packing changed an existing pure word: word=" +
                            std::to_string(wordIndex);
                    return false;
                }
            }
            stats.candidatePureWordCount = candidatePureWords;
            if (candidatePureWords < stats.baselinePureWordCount)
            {
                stats.lostPureWordCount = stats.baselinePureWordCount - candidatePureWords;
                error = "targeted pure-event packing lost existing pure words";
                return false;
            }
            stats.addedPureWordCount = candidatePureWords - stats.baselinePureWordCount;
            stats.validationPassed = true;
            return true;
        }

        bool rebuildFrozenScheduleBatches(const Graph &graph,
                                          const EmitModel &model,
                                          const ScheduleRefs &schedule,
                                          const std::vector<ScheduleBatch> &baselineBatches,
                                          PureEventWordPackStats &stats,
                                          std::vector<ScheduleBatch> &rebuiltBatches,
                                          std::string &error)
        {
            const std::size_t supernodeCount = schedule.supernodeToOps.size();
            std::vector<std::size_t> batchBySupernode(supernodeCount, kInvalidIndex);
            for (const ScheduleBatch &batch : baselineBatches)
            {
                for (uint32_t supernodeId : batch.supernodeIds)
                {
                    if (supernodeId >= supernodeCount || batchBySupernode[supernodeId] != kInvalidIndex)
                    {
                        error = "baseline frozen batches are not a strict supernode partition";
                        return false;
                    }
                    batchBySupernode[supernodeId] = batch.index;
                }
            }

            rebuiltBatches.clear();
            rebuiltBatches.reserve(baselineBatches.size());
            for (const ScheduleBatch &baseline : baselineBatches)
            {
                ScheduleBatch rebuilt;
                rebuilt.index = baseline.index;
                rebuilt.phase = baseline.phase;
                auto appendWord = [&](uint32_t supernodeId)
                {
                    const std::size_t activeWordIndex = model.activeIdBySupernode[supernodeId] /
                                                        kActiveFlagBitsPerWord;
                    if (rebuilt.phase == ScheduleBatch::Phase::kCommit ||
                        rebuilt.words.empty() ||
                        rebuilt.words.back().activeFlagWordIndex != activeWordIndex)
                    {
                        rebuilt.words.push_back(
                            ScheduleBatch::Word{.activeFlagWordIndex = activeWordIndex});
                    }
                    ScheduleBatch::Word &word = rebuilt.words.back();
                    const std::size_t opCount = schedule.supernodeToOps[supernodeId].size();
                    const std::size_t estimatedLines = estimateSupernodeEmitLines(
                        graph, model, schedule.valueFanout, schedule.supernodeToOps, supernodeId);
                    word.supernodeIds.push_back(supernodeId);
                    word.opCount += opCount;
                    word.estimatedLines += estimatedLines;
                    rebuilt.supernodeIds.push_back(supernodeId);
                    rebuilt.opCount += opCount;
                    rebuilt.estimatedLines += estimatedLines;
                };
                for (uint32_t supernodeId : schedule.topoOrder)
                {
                    if (supernodeId >= supernodeCount || batchBySupernode[supernodeId] != baseline.index)
                    {
                        continue;
                    }
                    const bool correctPhase = rebuilt.phase == ScheduleBatch::Phase::kCompute
                                                  ? isComputeSupernode(model, supernodeId)
                                                  : isCommitSupernode(model, supernodeId);
                    if (!correctPhase || model.activeIdBySupernode[supernodeId] == kInvalidIndex)
                    {
                        error = "frozen batch rebuild encountered a phase or active-id mismatch";
                        return false;
                    }
                    appendWord(supernodeId);
                }
                rebuiltBatches.push_back(std::move(rebuilt));
            }

            if (rebuiltBatches.size() != baselineBatches.size())
            {
                error = "frozen batch rebuild changed batch count";
                return false;
            }
            stats.frozenBatchBaselineEstimatedLines = 0u;
            stats.frozenBatchRebuiltEstimatedLines = 0u;
            stats.frozenBatchEstimatedLineChangedBatchCount = 0u;
            stats.frozenBatchMaxAbsEstimatedLineDelta = 0u;
            for (std::size_t batchIndex = 0; batchIndex < baselineBatches.size(); ++batchIndex)
            {
                const ScheduleBatch &baseline = baselineBatches[batchIndex];
                const ScheduleBatch &rebuilt = rebuiltBatches[batchIndex];
                stats.frozenBatchBaselineEstimatedLines += baseline.estimatedLines;
                stats.frozenBatchRebuiltEstimatedLines += rebuilt.estimatedLines;
                if (baseline.estimatedLines != rebuilt.estimatedLines)
                {
                    ++stats.frozenBatchEstimatedLineChangedBatchCount;
                    const std::size_t delta = baseline.estimatedLines > rebuilt.estimatedLines
                                                  ? baseline.estimatedLines - rebuilt.estimatedLines
                                                  : rebuilt.estimatedLines - baseline.estimatedLines;
                    stats.frozenBatchMaxAbsEstimatedLineDelta =
                        std::max(stats.frozenBatchMaxAbsEstimatedLineDelta, delta);
                }
                if (baseline.index != rebuilt.index || baseline.phase != rebuilt.phase ||
                    baseline.opCount != rebuilt.opCount)
                {
                    error = "frozen batch rebuild changed batch metadata: batch=" +
                            std::to_string(batchIndex) + " baseline_index=" +
                            std::to_string(baseline.index) + " rebuilt_index=" +
                            std::to_string(rebuilt.index) + " baseline_phase=" +
                            std::string(scheduleBatchPhaseName(baseline.phase)) + " rebuilt_phase=" +
                            std::string(scheduleBatchPhaseName(rebuilt.phase)) + " baseline_ops=" +
                            std::to_string(baseline.opCount) + " rebuilt_ops=" +
                            std::to_string(rebuilt.opCount) + " baseline_lines=" +
                            std::to_string(baseline.estimatedLines) + " rebuilt_lines=" +
                            std::to_string(rebuilt.estimatedLines) + " baseline_words=" +
                            std::to_string(baseline.words.size()) + " rebuilt_words=" +
                            std::to_string(rebuilt.words.size()) + " baseline_members=" +
                            std::to_string(baseline.supernodeIds.size()) + " rebuilt_members=" +
                            std::to_string(rebuilt.supernodeIds.size());
                    return false;
                }
                std::vector<uint32_t> baselineMembers = baseline.supernodeIds;
                std::vector<uint32_t> rebuiltMembers = rebuilt.supernodeIds;
                std::sort(baselineMembers.begin(), baselineMembers.end());
                std::sort(rebuiltMembers.begin(), rebuiltMembers.end());
                if (baselineMembers != rebuiltMembers)
                {
                    error = "frozen batch rebuild changed batch membership: batch=" +
                            std::to_string(batchIndex);
                    return false;
                }
                std::vector<std::size_t> baselineWords;
                std::vector<std::size_t> rebuiltWords;
                for (const ScheduleBatch::Word &word : baseline.words)
                {
                    baselineWords.push_back(word.activeFlagWordIndex);
                }
                for (const ScheduleBatch::Word &word : rebuilt.words)
                {
                    rebuiltWords.push_back(word.activeFlagWordIndex);
                }
                std::sort(baselineWords.begin(), baselineWords.end());
                std::sort(rebuiltWords.begin(), rebuiltWords.end());
                if (baselineWords != rebuiltWords)
                {
                    error = "frozen batch rebuild changed active-word slots: batch=" +
                            std::to_string(batchIndex);
                    return false;
                }
                if (baseline.phase == ScheduleBatch::Phase::kCommit &&
                    baseline.supernodeIds != rebuilt.supernodeIds)
                {
                    error = "frozen batch rebuild changed commit order: batch=" +
                            std::to_string(batchIndex);
                    return false;
                }
            }
            return true;
        }

        bool validateRebuiltActiveIdVectors(const EmitModel &model,
                                            std::size_t supernodeCount,
                                            std::string &error)
        {
            const auto validateIds = [&](const std::vector<uint32_t> &activeIds,
                                         std::string_view field) -> bool
            {
                if (!std::is_sorted(activeIds.begin(), activeIds.end()) ||
                    std::adjacent_find(activeIds.begin(), activeIds.end()) != activeIds.end() ||
                    std::any_of(activeIds.begin(),
                                activeIds.end(),
                                [&](uint32_t activeId) { return activeId >= supernodeCount; }))
                {
                    error = "rebuilt active-id vector is not sorted-unique/in-range: " +
                            std::string(field);
                    return false;
                }
                return true;
            };
            for (const auto &[value, activeIds] : model.boundaryFanoutByValue)
            {
                (void)value;
                if (!validateIds(activeIds, "boundary_fanout"))
                {
                    return false;
                }
            }
            for (const auto &[value, activeIds] : model.inputHeadSupernodesByValue)
            {
                (void)value;
                if (!validateIds(activeIds, "input_heads"))
                {
                    return false;
                }
            }
            for (const auto &[symbol, activeIds] : model.stateHeadSupernodesBySymbol)
            {
                (void)symbol;
                if (!validateIds(activeIds, "state_heads"))
                {
                    return false;
                }
            }
            const std::size_t activeWordCount =
                (supernodeCount + kActiveFlagBitsPerWord - 1u) / kActiveFlagBitsPerWord;
            for (const MemoryRowReaderActivationDecl &activation : model.memoryRowReaderActivations)
            {
                if (!validateIds(activation.dynamicReaderActiveIds, "memory_dynamic_readers") ||
                    activation.rowEntryOffsets.empty() || activation.rowEntryOffsets.front() != 0u ||
                    activation.rowEntryOffsets.back() != activation.rowEntries.size() ||
                    !std::is_sorted(activation.rowEntryOffsets.begin(), activation.rowEntryOffsets.end()))
                {
                    if (error.empty())
                    {
                        error = "rebuilt memory-row activation offsets are invalid";
                    }
                    return false;
                }
                for (std::size_t row = 1; row < activation.rowEntryOffsets.size(); ++row)
                {
                    std::size_t previousWord = kInvalidIndex;
                    for (std::size_t index = activation.rowEntryOffsets[row - 1];
                         index < activation.rowEntryOffsets[row];
                         ++index)
                    {
                        const ActiveMaskEntry &entry = activation.rowEntries[index];
                        if (entry.mask == UINT8_C(0) || entry.wordIndex >= activeWordCount ||
                            (previousWord != kInvalidIndex && entry.wordIndex <= previousWord))
                        {
                            error = "rebuilt memory-row activation entries are invalid";
                            return false;
                        }
                        previousWord = entry.wordIndex;
                    }
                }
            }
            return true;
        }

        bool isCompressibleScalarStateWrite(const EmitModel &model, OperationId opId)
        {
            (void)model;
            (void)opId;
            // The two-phase compute/commit runtime updates visible state directly in commit batches,
            // so the old shadow-table compression path is intentionally disabled.
            return false;
#if 0
            const auto writeIt = model.writeByOp.find(opId);
            if (writeIt == model.writeByOp.end())
            {
                return false;
            }
            const WriteDecl &write = writeIt->second;
            if (write.kind == StateDecl::Kind::Memory)
            {
                return false;
            }
            const auto stateIt = model.stateBySymbol.find(write.symbol);
            if (stateIt == model.stateBySymbol.end())
            {
                return false;
            }
            return !isWideLogicWidth(stateIt->second.width);
#endif
        }

        std::optional<TableCompressibleScalarStateWriteDesc>
        buildTableCompressibleScalarStateWriteDesc(const Graph &graph,
                                                  const EmitModel &model,
                                                  OperationId opId,
                                                  const Operation &op)
        {
            if (!isCompressibleScalarStateWrite(model, opId))
            {
                return std::nullopt;
            }
            const auto writeIt = model.writeByOp.find(opId);
            if (writeIt == model.writeByOp.end())
            {
                return std::nullopt;
            }
            const WriteDecl &write = writeIt->second;
            if (write.kind == StateDecl::Kind::Memory)
            {
                return std::nullopt;
            }
            const auto stateIt = model.stateBySymbol.find(write.symbol);
            if (stateIt == model.stateBySymbol.end())
            {
                return std::nullopt;
            }
            const StateDecl &state = stateIt->second;
            if (state.scalarKind != write.shadowScalarKind || state.slotIndex == kInvalidIndex)
            {
                return std::nullopt;
            }
            const auto operands = op.operands();
            if (operands.size() < 3 || graph.valueWidth(operands[0]) != 1)
            {
                return std::nullopt;
            }
            const auto condIt = model.valueScalarSlotByValue.find(operands[0]);
            if (condIt == model.valueScalarSlotByValue.end() ||
                condIt->second.kind != ValueSlotScalarKind::kBool)
            {
                return std::nullopt;
            }
            const auto nextIt = model.valueScalarSlotByValue.find(operands[1]);
            const auto maskIt = model.valueScalarSlotByValue.find(operands[2]);
            if (nextIt == model.valueScalarSlotByValue.end() ||
                maskIt == model.valueScalarSlotByValue.end() ||
                nextIt->second.kind != write.shadowScalarKind ||
                maskIt->second.kind != write.shadowScalarKind)
            {
                return std::nullopt;
            }
            const StateShadowDecl &shadow = model.stateShadows[write.shadowIndex];
            if (shadow.scalarKind != write.shadowScalarKind)
            {
                return std::nullopt;
            }
            return TableCompressibleScalarStateWriteDesc{
                .kind = write.shadowScalarKind,
                .condIndex = static_cast<std::uint32_t>(condIt->second.slotIndex),
                .touchedIndex = static_cast<std::uint32_t>(shadow.touchedIndex),
                .shadowDataIndex = static_cast<std::uint32_t>(shadow.dataIndex),
                .stateDataIndex = static_cast<std::uint32_t>(state.slotIndex),
                .nextIndex = static_cast<std::uint32_t>(nextIt->second.slotIndex),
                .maskIndex = static_cast<std::uint32_t>(maskIt->second.slotIndex),
                .shadowIndex = static_cast<std::uint32_t>(write.shadowIndex),
            };
        }

        std::optional<DirectCommitScalarStateWriteDesc>
        buildDirectCommitScalarStateWriteDesc(const Graph &graph,
                                              const EmitModel &model,
                                              OperationId opId,
                                              const Operation &op)
        {
            if (!isCommitPhaseOp(op) || !isWritePortKind(op.kind()))
            {
                return std::nullopt;
            }
            const auto writeIt = model.writeByOp.find(opId);
            if (writeIt == model.writeByOp.end())
            {
                return std::nullopt;
            }
            const WriteDecl &write = writeIt->second;
            if (write.kind == StateDecl::Kind::Memory)
            {
                return std::nullopt;
            }
            const auto stateIt = model.stateBySymbol.find(write.symbol);
            if (stateIt == model.stateBySymbol.end())
            {
                return std::nullopt;
            }
            const StateDecl &state = stateIt->second;
            if (state.regToMemIntentStorage || isWideLogicWidth(state.width) || state.slotIndex == kInvalidIndex)
            {
                return std::nullopt;
            }
            const auto operands = op.operands();
            if (operands.size() < 3)
            {
                return std::nullopt;
            }
            if (graph.valueWidth(operands[0]) != 1)
            {
                return std::nullopt;
            }
            const auto condIt = model.valueScalarSlotByValue.find(operands[0]);
            const auto nextIt = model.valueScalarSlotByValue.find(operands[1]);
            const auto maskIt = model.valueScalarSlotByValue.find(operands[2]);
            if (condIt == model.valueScalarSlotByValue.end() ||
                condIt->second.kind != ValueSlotScalarKind::kBool ||
                nextIt == model.valueScalarSlotByValue.end() ||
                maskIt == model.valueScalarSlotByValue.end() ||
                nextIt->second.kind != state.scalarKind ||
                maskIt->second.kind != state.scalarKind)
            {
                return std::nullopt;
            }

            std::vector<ActiveMaskEntry> activationEntries;
            const auto headIt = model.stateHeadSupernodesBySymbol.find(write.symbol);
            if (headIt != model.stateHeadSupernodesBySymbol.end() && !headIt->second.empty())
            {
                activationEntries = buildActiveMaskEntries(headIt->second);
            }

            (void)graph;
            return DirectCommitScalarStateWriteDesc{
                .kind = state.scalarKind,
                .condIndex = static_cast<std::uint32_t>(condIt->second.slotIndex),
                .stateDataIndex = static_cast<std::uint32_t>(state.slotIndex),
                .nextIndex = static_cast<std::uint32_t>(nextIt->second.slotIndex),
                .maskIndex = static_cast<std::uint32_t>(maskIt->second.slotIndex),
                .activationEntries = std::move(activationEntries),
            };
        }

        ScalarStateWriteRangeStep scalarStateWriteRangeStep(const TableCompressibleScalarStateWriteDesc &lhs,
                                                            const TableCompressibleScalarStateWriteDesc &rhs)
        {
            return ScalarStateWriteRangeStep{
                .cond = static_cast<std::int32_t>(rhs.condIndex) - static_cast<std::int32_t>(lhs.condIndex),
                .touched = static_cast<std::int32_t>(rhs.touchedIndex) - static_cast<std::int32_t>(lhs.touchedIndex),
                .shadowData =
                    static_cast<std::int32_t>(rhs.shadowDataIndex) - static_cast<std::int32_t>(lhs.shadowDataIndex),
                .stateData =
                    static_cast<std::int32_t>(rhs.stateDataIndex) - static_cast<std::int32_t>(lhs.stateDataIndex),
                .next = static_cast<std::int32_t>(rhs.nextIndex) - static_cast<std::int32_t>(lhs.nextIndex),
                .mask = static_cast<std::int32_t>(rhs.maskIndex) - static_cast<std::int32_t>(lhs.maskIndex),
                .shadow = static_cast<std::int32_t>(rhs.shadowIndex) - static_cast<std::int32_t>(lhs.shadowIndex),
            };
        }

        DirectCommitScalarStateWriteRangeStep
        directCommitScalarStateWriteRangeStep(const DirectCommitScalarStateWriteDesc &lhs,
                                              const DirectCommitScalarStateWriteDesc &rhs)
        {
            return DirectCommitScalarStateWriteRangeStep{
                .cond = static_cast<std::int32_t>(rhs.condIndex) - static_cast<std::int32_t>(lhs.condIndex),
                .stateData =
                    static_cast<std::int32_t>(rhs.stateDataIndex) - static_cast<std::int32_t>(lhs.stateDataIndex),
                .next = static_cast<std::int32_t>(rhs.nextIndex) - static_cast<std::int32_t>(lhs.nextIndex),
                .mask = static_cast<std::int32_t>(rhs.maskIndex) - static_cast<std::int32_t>(lhs.maskIndex),
            };
        }

        std::string scalarStateWriteRangeDescTypeName(ValueSlotScalarKind kind)
        {
            switch (kind)
            {
            case ValueSlotScalarKind::kBool:
                return "scalar_state_write_bool_range_desc";
            case ValueSlotScalarKind::kU8:
                return "scalar_state_write_u8_range_desc";
            case ValueSlotScalarKind::kU16:
                return "scalar_state_write_u16_range_desc";
            case ValueSlotScalarKind::kU32:
                return "scalar_state_write_u32_range_desc";
            case ValueSlotScalarKind::kU64:
                return "scalar_state_write_u64_range_desc";
            case ValueSlotScalarKind::kCount:
                break;
            }
            return "scalar_state_write_u64_range_desc";
        }

