                *stream << "    for (char ch : mode) {\n";
                *stream << "        switch (ch) {\n";
                *stream << "        case 'r':\n";
                *stream << "        case 'w':\n";
                *stream << "        case 'a':\n";
                *stream << "            if (base != '\\0') {\n";
                *stream << "                return false;\n";
