                *stream << "        case 'b':\n";
                *stream << "            binary = true;\n";
                *stream << "            break;\n";
                *stream << "        case '+':\n";
                *stream << "            plus = true;\n";
                *stream << "            break;\n";
                *stream << "        default:\n";
                *stream << "            return false;\n";
                *stream << "        }\n";
                *stream << "    }\n";
                *stream << "    switch (base) {\n";
                *stream << "    case 'r':\n";
                *stream << "        openMode = std::ios::in;\n";
                *stream << "        canRead = true;\n";
