                *stream << "        canRead = true;\n";
                *stream << "        canWrite = true;\n";
                *stream << "    }\n";
                *stream << "    if (binary) {\n";
                *stream << "        openMode |= std::ios::binary;\n";
                *stream << "    }\n";
